insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('2ch',36,1,'crampon1923','Le peuple du pays prit Joachaz, fils de Josias, et le fit roi à la place de son père, à Jérusalem.'),
('2ch',36,2,'crampon1923','Joachaz avait vingt-trois ans lorsqu''il devint roi, et il régna trois mois à Jérusalem.'),
('2ch',36,3,'crampon1923','Le roi d''Egypte le destitua à Jérusalem, et imposa au pays une contribution de cent talents d''argent et d''un talent d''or.'),
('2ch',36,4,'crampon1923','Et il établit roi sur Juda et sur Jérusalem Eliacim, frère de Joachaz, et il changea son nom en celui de Joakim. Néchao prit son frère Joachaz et l''emmena en Egypte.'),
('2ch',36,5,'crampon1923','Joakim avait vingt-cinq ans lorsqu''il devint roi, et il régna onze ans à Jérusalem. Il fit ce qui est mal aux yeux de Yahweh, son Dieu.'),
('2ch',36,6,'crampon1923','Nabuchodonosor, roi de Babylone, monta contre lui, et le lia avec une double chaîne d''airain, pour le conduire à Babylone.'),
('2ch',36,7,'crampon1923','Nabuchodonosor emporta à Babylone des ustensiles de la maison de Yahweh, et il les mit dans son temple à Babylone.'),
('2ch',36,8,'crampon1923','Le reste des actes de Joakim, les abominations qu''il commit, et ce qui se trouvait en lui, voici que cela est écrit dans le livre des rois de Juda et d''Israël. Joachin, son fils, régna à sa place.'),
('2ch',36,9,'crampon1923','Joachin avait huit ans lorsqu''il devint roi, et il régna trois mois et dix jours à Jérusalem. Il fit ce qui est mal aux yeux de Yahweh.'),
('2ch',36,10,'crampon1923','Au retour de l''année, le roi Nabuchodonosor le fit emmener à Babylone, avec les ustensiles précieux de la maison de Yahweh; et il établit roi sur Juda et sur Jérusalem Sédécias, frère de Joachin.'),
('2ch',36,11,'crampon1923','Sédécias avait vingt et un ans lorsqu''il devint roi, et il régna onze ans à Jérusalem.'),
('2ch',36,12,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, son Dieu, et il ne s''humilia point devant Jérémie, le prophète, qui lui parlait de la part de Yahweh.'),
('2ch',36,13,'crampon1923','Il se révolta même contre le roi Nabuchodonosor, qui l''avait fait jurer par Dieu; il raidit son cou et endurcit son cœur, pour ne pas revenir à Yahweh, le Dieu d''Israël.'),
('2ch',36,14,'crampon1923','Tous les chefs des prêtres et le peuple multiplièrent aussi les transgressions, selon toutes les abominations des nations, et ils profanèrent la maison de Yahweh, qu''il avait sanctifiée à Jérusalem.'),
('2ch',36,15,'crampon1923','Yahweh, le Dieu de leurs pères, leur avait envoyé des avertissements par l''organe de ses messagers, de bonne heure et à plusieurs reprises; car il avait compassion de son peuple et de sa propre demeure.'),
('2ch',36,16,'crampon1923','Mais ils se moquèrent des envoyés de Dieu, ils méprisèrent ses paroles et se raillèrent de ses prophètes, jusqu''à ce que la colère de Dieu s''élevât contre son peuple, et qu''il n''y eût plus de remède.'),
('2ch',36,17,'crampon1923','Alors Yahweh fit monter contre eux le roi des Chaldéens, qui tua par l''épée leurs jeunes gens dans la maison de leur sanctuaire, et n''épargna ni le jeune homme, ni la vierge, ni le vieillard, ni l''homme aux cheveux blancs; Yahweh livra tout entre ses mains.'),
('2ch',36,18,'crampon1923','Nabuchodonosor emporta à Babylone tous les ustensiles de la maison de Dieu, grands et petits, les trésors de la maison de Yahweh, et les trésors du roi et de ses chefs.'),
('2ch',36,19,'crampon1923','Ils brûlèrent la maison de Dieu, ils démolirent les murailles de Jérusalem, ils livrèrent au feu tous ses palais, et tous ses objets précieux furent livrés à la destruction.'),
('2ch',36,20,'crampon1923','Nabuchodonosor emmena captifs à Babylone ceux qui échappèrent à l''épée, et ils furent ses esclaves, à lui et à ses fils, jusqu''à la domination du royaume de Perse.'),
('2ch',36,21,'crampon1923','Ainsi s''accomplit la parole de Yahweh, qu''il avait dite par la bouche de Jérémie: Jusqu''à ce que le pays ait joui de ses sabbats; car il se reposa tout le temps de sa dévastation, — jusqu''à l''accomplissement de soixante-dix années.'),
('2ch',36,22,'crampon1923','La première année de Cyrus, roi de Perse, pour accomplir la parole de Yahweh, qu''il avait dite par la bouche de Jérémie, Yahweh excita l''esprit de Cyrus, roi de Perse, qui fit faire de vive voix et par écrit cette proclamation dans tout son royaume:'),
('2ch',36,23,'crampon1923','" Ainsi dit Cyrus, roi de Perse: Yahweh, le Dieu du ciel, m''a donné tous les royaumes de la terre, et il m''a dit de lui bâtir une maison à Jérusalem, qui est en Juda. Qui d''entre vous est de son peuple? Que Yahweh, son Dieu, soit avec lui, et qu''il monte!... "'),
('esd',1,1,'crampon1923','La première année de Cyrus, roi de Perse, pour accomplir la parole de Yahweh, qu''il avait dite par la bouche de Jérémie, Yahweh excita l''esprit de Cyrus, roi de Perse, qui fit faire de vive voix et par écrit cette proclamation dans tout son royaume:'),
('esd',1,2,'crampon1923','" Ainsi dit Cyrus, roi de Perse: Yahweh, le Dieu du ciel, m''a donné tous les royaumes de la terre, et il m''a dit de lui bâtir une maison à Jérusalem, qui est en Juda.'),
('esd',1,3,'crampon1923','Qui d''entre vous est de son peuple? Que son Dieu soit avec lui, et qu''il monte à Jérusalem, qui est en Juda, et bâtisse la maison de Yahweh, Dieu d''Israël! C''est le Dieu qui est à Jérusalem.'),
('esd',1,4,'crampon1923','Qu''à tous ceux qui restent de Juda, en tous les séjours où ils demeurent, les gens de ce séjour viennent en aide par de l''argent, de l''or, des effets et du bétail, avec des dons volontaires, pour la maison de Dieu qui est à Jérusalem. "'),
('esd',1,5,'crampon1923','Les chefs de famille de Juda et de Benjamin, les prêtres et les lévites, tous ceux dont Dieu excita l''esprit, se levèrent pour aller bâtir la maison de Yahweh, qui est à Jérusalem.'),
('esd',1,6,'crampon1923','Tous leurs voisins les aidèrent avec des objets d''argent, de l''or, des effets, du bétail et des choses précieuses, sans compter toutes les offrandes volontaires.'),
('esd',1,7,'crampon1923','Le roi Cyrus enleva les ustensiles de la maison de Yahweh, que Nabuchodonosor avait enlevés de Jérusalem et placés dans la maison de son dieu.'),
('esd',1,8,'crampon1923','Cyrus, roi de Perse, les confia aux mains de Mithridate, le trésorier, qui les transmit en les comptant à Sassabasar, le prince de Juda.'),
('esd',1,9,'crampon1923','En voici le nombre: trente bassins d''or, mille bassins d''argent, vingt-neuf couteaux,'),
('esd',1,10,'crampon1923','trente coupes d''or, quatre cent dix coupes d''argent de second ordre, et mille autres ustensiles.'),
('esd',1,11,'crampon1923','Tous les objets d''or et d''argent étaient au nombre de cinq mille quatre cents. Sassabasar emporta le tout, lorsque les exilés furent ramenée de Babylone à Jérusalem.'),
('esd',2,1,'crampon1923','Voici les gens de la province qui revinrent de l''exil, — ceux que Nabuchodonosor, roi de Babylone, avait emmenés captifs à Babylone, et qui retournèrent à Jérusalem et en Juda, chacun dans sa ville, —'),
('esd',2,2,'crampon1923','qui revinrent avec Zorobabel, Josué, Néhémie, Saraïas, Rahélaïas, Mardochée, Belsan, Mesphar, Béguaï, Réhum, Baana: Nombre des hommes du peuple d''Israël:'),
('esd',2,3,'crampon1923','les fils de Pharos, deux mille cent soixante-douze;'),
('esd',2,4,'crampon1923','les fils de Saphatias, trois cent soixante-douze;'),
('esd',2,5,'crampon1923','les fils d''Aréa, sept cent soixante-quinze;'),
('esd',2,6,'crampon1923','les fils de Phahath-Moab, des fils de Josué et de Joab, deux mille huit cent douze;'),
('esd',2,7,'crampon1923','les fils d''Elam, mille deux cent cinquante-quatre;'),
('esd',2,8,'crampon1923','les fils de Zéthua, neuf cent quarante-cinq;'),
('esd',2,9,'crampon1923','les fils de Zachaï, sept cent soixante;'),
('esd',2,10,'crampon1923','les fils de Bani, six cent quarante-deux;'),
('esd',2,11,'crampon1923','les fils de Bébaï, six cent vingt-trois;'),
('esd',2,12,'crampon1923','les fils d''Azgad, mille deux cent vingt-deux;'),
('esd',2,13,'crampon1923','les fils d''Adonicam, six cent soixante-six;'),
('esd',2,14,'crampon1923','les fils de Béguaï, deux mille cinquante-six;'),
('esd',2,15,'crampon1923','les fils d''Adin, quatre cent cinquante-quatre;'),
('esd',2,16,'crampon1923','les fils d''Ater, de la famille d''Ezéchias, quatre-vingt-dix-huit;'),
('esd',2,17,'crampon1923','les fils de Bésaï, trois cent vingt-trois;'),
('esd',2,18,'crampon1923','les fils de Jora, cent douze;'),
('esd',2,19,'crampon1923','les fils de Hasum, deux cent vingt-trois;'),
('esd',2,20,'crampon1923','les fils de Gebbar, quatre-vingt-quinze;'),
('esd',2,21,'crampon1923','les fils de Bethléem, cent vingt-trois;'),
('esd',2,22,'crampon1923','les gens de Nétopha, cinquante-six;'),
('esd',2,23,'crampon1923','les gens d''Anathoth, cent vingt-huit;'),
('esd',2,24,'crampon1923','les fils d''Azmaveth, quarante-deux;'),
('esd',2,25,'crampon1923','les fils de Cariathiarim, de Céphira et de Béroth, sept cent quarante-trois;'),
('esd',2,26,'crampon1923','les fils de Rama et de Gabaa, six cent vingt et un;'),
('esd',2,27,'crampon1923','les gens de Machmas, cent vingt-deux;'),
('esd',2,28,'crampon1923','les gens de Béthel et de Haï, deux cent vingt trois;'),
('esd',2,29,'crampon1923','les fils de Nébo, cinquante-deux;'),
('esd',2,30,'crampon1923','les fils de Megbis, cent cinquante-six;'),
('esd',2,31,'crampon1923','les fils de l''autre Elam, mille deux cent cinquante-quatre;'),
('esd',2,32,'crampon1923','les fils de Harim, trois cent vingt;'),
('esd',2,33,'crampon1923','les fils de Lod, de Hadid et d''Ono, sept cent vingt-cinq;'),
('esd',2,34,'crampon1923','les fils de Jéricho, trois cent quarante-cinq;'),
('esd',2,35,'crampon1923','les fils de Sénaa, trois mille six cent trente.'),
('esd',2,36,'crampon1923','Prêtres: les fils de Iadaïas, de la maison de Josué, neuf cent soixante-treize;'),
('esd',2,37,'crampon1923','les fils d''Emmer, mille cinquante-deux;'),
('esd',2,38,'crampon1923','les fils de Phashur, mille deux cent quarante sept;'),
('esd',2,39,'crampon1923','les fils de Harim, mille dix-sept.'),
('esd',2,40,'crampon1923','Lévites: les fils de Josué et de Cedmiel, des fils d''Oduïas, soixante-quatorze.'),
('esd',2,41,'crampon1923','Chantres: les fils d''Asaph, cent vingt-huit.'),
('esd',2,42,'crampon1923','Fils des portiers: les fils de Sellum, les fils d''Ater, les fils de Telmon, les fils d''Accub, les fils de Hatita, les fils de Sobaï, en tout cent trente-neuf.'),
('esd',2,43,'crampon1923','Nathinéens: les fils de Siha, les fils de Hasupha, les fils de Tabbaoth,'),
('esd',2,44,'crampon1923','les fils de Céros, les fils de Siaa, les fils de Phadon,'),
('esd',2,45,'crampon1923','les fils de Lébana, les fils de Hagaba, les fils d''Accub,'),
('esd',2,46,'crampon1923','les fils de Hagab, les fils de Selmaï, les fils de Hanan,'),
('esd',2,47,'crampon1923','les fils de Gaddel, les fils de Gaher, les fils du Raaïa,'),
('esd',2,48,'crampon1923','les fils de Rasin, les fils de Nécoda, les fils de Gazam,'),
('esd',2,49,'crampon1923','les fils d''Aza, les fils de Phaséa, les fils de Besée,'),
('esd',2,50,'crampon1923','les fils d''Azéna, les fils de Munim, les fils de Néphusim,'),
('esd',2,51,'crampon1923','les fils de Bacbuc, les fils de Hacupha, les fils de Harhur,'),
('esd',2,52,'crampon1923','les fils de Besluth, les fils de Mahida, les fils de Harsa,'),
('esd',2,53,'crampon1923','les fils de Bercos, les fils de Sisara, les fils de Théma,'),
('esd',2,54,'crampon1923','les fils de Nasia, les fils de Hatipha.'),
('esd',2,55,'crampon1923','Fils des serviteurs de Salomon: les fils de Sotaï, les fils de Sophéret, les fils de Pharuda,'),
('esd',2,56,'crampon1923','les fils de Jala, les fils de Dercon, les fils de Geddel,'),
('esd',2,57,'crampon1923','les fils de Saphatia, les fils de Hatil, les fils de Phochéreth-Asebaïm, les fils d''Ami.'),
('esd',2,58,'crampon1923','Total des Nathinéens et des fils des serviteurs de Salomon: trois cent quatre-vingt-douze.'),
('esd',2,59,'crampon1923','Voici ceux qui partirent de Thel-Méla, Thel-Harsa, Chérub, Addon, Emmer, et qui ne purent pas faire connaître leur maison paternelle et leur race, pour montrer qu''ils étaient d''Israël:'),
('esd',2,60,'crampon1923','les fils de Dalaïas, les fils de Tobie, les fils de Nécoda, six cent cinquante-deux.'),
('esd',2,61,'crampon1923','Et parmi les fils des prêtres: les fils de Hobia, les fils d''Accos, les fils de Berzellaï, qui avait pris pour femme une des filles de Berzellaï, le Galaadite, et fut appelé de leur nom.'),
('esd',2,62,'crampon1923','Ils cherchèrent leur titre attestant leurs généalogies, mais on ne le trouva point; ils furent déclarés impurs et exclus du sacerdoce,'),
('esd',2,63,'crampon1923','et le gouverneur leur interdit de manger des choses très saintes, jusqu''à ce qu''un prêtre se levât pour consulter Dieu par l''Urim et le Thummim.'),
('esd',2,64,'crampon1923','L''assemblée tout entière était de quarante-deux mille trois cent soixante personnes,'),
('esd',2,65,'crampon1923','sans compter leurs serviteurs et leurs servantes, qui étaient au nombre de sept mille trois cent trente-sept; parmi eux se trouvaient deux cents chanteurs et chanteuses.'),
('esd',2,66,'crampon1923','Ils avaient sept cent trente-six chevaux, deux cent quarante-cinq mulets,'),
('esd',2,67,'crampon1923','quatre cent trente-cinq chameaux et six mille sept cent vingt ânes.'),
('esd',2,68,'crampon1923','Plusieurs des chefs de famille, en arrivant à la maison de Yahweh, qui est à Jérusalem, firent des offrandes volontaires pour la maison de Dieu, afin qu''on la relevât à sa place.'),
('esd',2,69,'crampon1923','Ils donnèrent au trésor de l''œuvre, selon leurs moyens, soixante et un mille dariques d''or, cinq mille mines d''argent, et cent tuniques sacerdotales.'),
('esd',2,70,'crampon1923','C''est ainsi que les prêtres et les lévites, des gens du peuple, les chantres, les portiers et les Nathinéens s''établirent dans leurs villes; et tout Israël habita dans ses villes.'),
('esd',3,1,'crampon1923','Le septième mois étant arrivé, et les enfants d''Israël étant établis dans les villes, le peuple s''assembla comme un seul homme à Jérusalem.'),
('esd',3,2,'crampon1923','Josué, fils de Josédec, avec ses frères, les prêtres, et Zorobabel, fils de Salathiel, avec ses frères, se levèrent et bâtirent l''autel du Dieu d''Israël pour y offrir des holocaustes, selon ce qui est écrit dans la loi de Moïse, l''homme de Dieu.'),
('esd',3,3,'crampon1923','Ils établirent l''autel sur ses anciens fondements, car ils étaient dans la terreur devant les peuples du pays, et ils y offrirent des holocaustes à Yahweh, les holocaustes du matin et du soir.'),
('esd',3,4,'crampon1923','Ils célébrèrent la fête des Tabernacles, comme il est écrit, et ils offrirent jour par jour les holocaustes, selon le nombre prescrit par la loi pour chaque jour.'),
('esd',3,5,'crampon1923','Après cela, ils offrirent l''holocauste perpétuel, les holocaustes des néoménies et de toutes les fêtes consacrées à Yahweh, et ceux de quiconque faisait une offrande volontaire à Yahweh.'),
('esd',3,6,'crampon1923','Dès le premier jour du septième mois, ils avaient commencé à offrir des holocaustes à Yahweh, mais les fondements du temple de Yahweh n''étaient pas encore posés.'),
('esd',3,7,'crampon1923','On donna de l''argent aux tailleurs de pierres et aux charpentiers; on donna aussi des vivres, des boissons et de l''huile aux Sidoniens et aux Tyriens, pour qu''ils amenassent par mer jusqu''à Joppé des bois de cèdre du Liban, suivant l''autorisation qu''on avait eue de Cyrus, roi de Perse.'),
('esd',3,8,'crampon1923','La seconde année de leur arrivée à la maison de Dieu à Jérusalem, le second mois, Zorobabel, fils de Salathiel, et Josué, fils de Josédec, avec le reste de leurs frères, les prêtres et les lévites, et tous ceux qui étaient revenus de la captivité à Jérusalem, se mirent à l''œuvre et établirent les lévites de vingt ans et au-dessus pour diriger les travaux de la maison de Yahweh.'),
('esd',3,9,'crampon1923','Josué, avec ses fils et ses frères, Cedmiel, avec ses fils, fils de Juda, se disposèrent unanimement à diriger ceux qui travaillaient à l''œuvre, dans la maison du Dieu; de même les fils de Hénadad, avec leurs fils et leurs frères, c''étaient tous des lévites.'),
('esd',3,10,'crampon1923','Lorsque les ouvriers posèrent les fondements du temple de Yahweh, on fit assister les prêtres en costume, avec les trompettes, et les lévites, fils d''Asaph, avec les cymbales, pour célébrer Yahweh, d''après les ordonnances de David, roi d''Israël.'),
('esd',3,11,'crampon1923','Ils se mirent à célébrer et à louer Yahweh: " Car il est bon, car sa miséricorde pour Israël subsiste à jamais! " Et tout le peuple poussait de grands cris de joie pour célébrer Yahweh, parce qu''on posait les fondements de la maison de Yahweh.'),
('esd',3,12,'crampon1923','Beaucoup de prêtres et de lévites, et de chefs de famille âgés, qui avaient vu la première maison, pleuraient à haute voix, pendant qu''on posait sous leurs yeux les fondements de cette maison; et beaucoup poussaient des cris de joie et d''allégresse.'),
('esd',3,13,'crampon1923','Et le peuple ne pouvait distinguer le bruit des cris de joie d''avec celui des gémissements du peuple, car le peuple poussait de grands cris, dont le son s''entendait au loin.'),
('esd',4,1,'crampon1923','Lorsque les ennemis de Juda et de Benjamin apprirent que les fils de la captivité bâtissaient un temple à Yahweh, le Dieu d''Israël,'),
('esd',4,2,'crampon1923','ils vinrent auprès de Zorobabel et des chefs de famille, et leur dirent: " Laissez-nous bâtir avec vous; car, comme vous, nous honorons votre Dieu, et nous lui offrons des sacrifices depuis le temps d''Asarhaddon, roi d''Assyrie, qui nous a fait monter ici. "'),
('esd',4,3,'crampon1923','Mais Zorobabel, Josué et les autres chefs des familles d''Israël leur répondirent: " Il ne convient pas que vous et nous, nous bâtissions ensemble la maison de notre Dieu; mais nous la bâtirons nous seuls à Yahweh, le Dieu d''Israël, comme nous l''a ordonné le roi Cyrus, roi de Perse. "'),
('esd',4,4,'crampon1923','Alors le peuple du pays se mit à décourager le peuple de Juda, l''intimidant dans son travail.'),
('esd',4,5,'crampon1923','Il acheta contre lui des conseillers pour faire échouer son entreprise. Il en fut ainsi pendant toute la vie de Cyrus, roi de Perse, et jusqu''au règne de Darius, roi de Perse.'),
('esd',4,6,'crampon1923','Et sous le règne d''Assuérus, au commencement de son règne, ils écrivirent une lettre d''accusation contre les habitants de Juda et de Jérusalem.'),
('esd',4,7,'crampon1923','Et du temps d''Artaxerxès, Bésélam, Mithridate, Tabéel et le reste de leurs compagnons écrivirent à Artaxerxès, roi de Perse; le texte de la lettre fut écrit en caractère araméen et traduit en araméen.'),
('esd',4,8,'crampon1923','Réhum, gouverneur, et Samsaï, secrétaire, écrivirent à Artaxerxès, au sujet de Jérusalem, une lettre ainsi conçue:'),
('esd',4,9,'crampon1923','" Alors Réhum, gouverneur, Samsaï, secrétaire, et le reste de leurs compagnons, ceux de Din, d''Apharsathach, de Terphal, d''Apharsa, d''Erchua, de Babylone, de Suse, de Déha, d''Elam,'),
('esd',4,10,'crampon1923','et le reste des peuples que le grand et illustre Asnaphar a transportés et établis dans la ville de Samarie et autres lieux d''au delà du fleuve, etc. "'),
('esd',4,11,'crampon1923','Voici la copie de la lettre qu''ils envoyèrent au roi Artaxerxès: " Tes serviteurs, les gens d''au delà du fleuve, etc.'),
('esd',4,12,'crampon1923','" Que le roi sache que les Juifs qui sont montés de chez toi parmi nous sont venus à Jérusalem; ils rebâtissent la ville rebelle et méchante, en relèvent les murs et en restaurent les fondements.'),
('esd',4,13,'crampon1923','Que le roi sache donc que, si cette ville est rebâtie et si ses murs sont relevés, ils ne paieront ni impôt, ni tribut, ni droit de passage, ce qui causera un dommage aux rois.'),
('esd',4,14,'crampon1923','Or, comme nous mangeons le sel du palais et qu''il ne nous paraît pas convenable de voir mépriser le roi, nous envoyons au roi des informations à ce sujet.'),
('esd',4,15,'crampon1923','Qu''on fasse des recherches dans le livre des annales de tes pères, et tu trouveras dans le livre des annales et tu sauras que cette ville est une ville rebelle, causant des dommages aux rois et aux provinces, et qu''on s''y livre à la révolte depuis les temps anciens. C''est pour cela que cette ville a été détruite.'),
('esd',4,16,'crampon1923','Nous faisons savoir au roi que, si cette ville est rebâtie et si ses murs sont relevés, par cela même tu ne posséderas plus rien au delà du fleuve. "'),
('esd',4,17,'crampon1923','Le roi envoya cette réponse à Réhum, gouverneur, à Samsaï, secrétaire, et au reste de leurs compagnons, demeurant à Samarie et aux autres lieux d''au-delà du fleuve: " Salut, etc.'),
('esd',4,18,'crampon1923','" La lettre que vous nous avez envoyée a été lue distinctement devant moi.'),
('esd',4,19,'crampon1923','J''ai donné un ordre, et on a fait des recherches, et l''on a trouvé que, dès les temps anciens, cette ville s''est soulevée contre les rois et qu''on s''y est livré à la sédition et à la révolte.'),
('esd',4,20,'crampon1923','Il y eut à Jérusalem des rois puissants, maîtres de tout le pays d''au delà du fleuve; et on leur payait impôt, tribut et droit de passage.'),
('esd',4,21,'crampon1923','En conséquence, donnez ordre de faire cesser les travaux de ces gens, afin que cette ville ne se rebâtisse point, jusqu''à ce que je donne un ordre à ce sujet.'),
('esd',4,22,'crampon1923','Gardez-vous de mettre en cela de la négligence, de peur que le mal n''augmente au détriment des rois. "'),
('esd',4,23,'crampon1923','Alors, dès que la copie de la lettre du roi Artaxerxès eut été lue devant Réhum, Samsaï, secrétaire, et leurs compagnons, ils se rendirent avec hâte à Jérusalem vers les Juifs, et il leur firent cesser le travail par violence et par force.'),
('esd',4,24,'crampon1923','Alors s''arrêta l''ouvrage de la maison de Dieu à Jérusalem, et il fut interrompu jusqu''à la seconde année du règne de Darius, roi de Perse.'),
('esd',5,1,'crampon1923','Les prophètes Aggée, le prophète, et Zacharie, fils d''Addo prophétisèrent aux Juifs qui étaient en Juda et à Jérusalem, au nom du Dieu d''Israël, qui était sur eux.'),
('esd',5,2,'crampon1923','Alors Zorobabel, fils de Salathiel, et Josué, fils de Josédec, se levèrent et recommencèrent à bâtir la maison de Dieu à Jérusalem, et avec eux étaient les prophètes de Dieu qui les assistaient.'),
('esd',5,3,'crampon1923','Dans le même temps, Thathanaï, gouverneur d''au delà du fleuve, Stharbuzanaï et leurs compagnons vinrent les trouver et leur parlèrent ainsi: " Qui vous a donné l''autorisation de bâtir cette maison et de relever ces murs? "'),
('esd',5,4,'crampon1923','Alors nous leur parlâmes en leur disant les noms des hommes qui construisaient cet édifice.'),
('esd',5,5,'crampon1923','Mais l''œil de leur Dieu était sur les anciens des Juifs; et on ne leur fit pas cesser les travaux jusqu''à ce que le rapport fût parvenu à Darius et que revint une lettre à ce sujet.'),
('esd',5,6,'crampon1923','Copie de la lettre qu''envoyèrent au roi Darius Thathanaï, gouverneur d''au-delà du fleuve, Stharbuzanaï et leurs compagnons d''Arphasach, demeurant au delà du fleuve.'),
('esd',5,7,'crampon1923','Ils lui envoyèrent un rapport, et voici ce qui y était écrit: " Au roi Darius, salut parfait!'),
('esd',5,8,'crampon1923','Que le roi sache que nous sommes allés dans la province de Juda, à la maison du grand Dieu. Elle se construit en pierres énormes, et le bois se pose dans les murs; ce travail est poussé avec diligence et prospère sous leurs mains.'),
('esd',5,9,'crampon1923','Alors nous avons interrogé ces anciens et nous leur avons ainsi parlé: " Qui vous a donné l''autorisation de bâtir cette maison et de relever ces murs? "'),
('esd',5,10,'crampon1923','Nous leur avons aussi demandé leurs noms pour te les faire connaître, afin de mettre par écrit les noms des hommes qui sont à leur tête.'),
('esd',5,11,'crampon1923','Voici la réponse qu''ils nous ont faite: " Nous sommes les serviteurs du Dieu du ciel et de la terre, et nous rebâtissons la maison qui a été construite jadis, il y a bien des années, et qu''avait bâtie et achevée un grand roi d''Israël.'),
('esd',5,12,'crampon1923','Mais, après que nos pères eurent irrité le Dieu du ciel, il les livra entre les mains de Nabuchodonosor, roi de Babylone, le Chaldéen, qui détruisit cette maison et emmena le peuple captif à Babylone.'),
('esd',5,13,'crampon1923','Toutefois, la première année de Cyrus, roi de Babylone, le roi Cyrus rendit un décret permettant de rebâtir cette maison de Dieu.'),
('esd',5,14,'crampon1923','Et même le roi Cyrus retira du temple de Babylone les ustensiles d''or et d''argent de la maison de Dieu, que Nabuchodonosor avait enlevés du temple qui était à Jérusalem et transportés dans le temple de Babylone; ils furent remis au nommé Sassabasar, qu''il établit gouverneur.'),
('esd',5,15,'crampon1923','Et il lui dit: Prends ces ustensiles, va les déposer dans le temple qui est à Jérusalem, et que la maison de Dieu soit rebâtie sur son emplacement.'),
('esd',5,16,'crampon1923','Alors ce Sassabasar est venu, et il a posé les fondements de la maison de Dieu qui est à Jérusalem; depuis lors jusqu''à présent, elle se construit, et elle n''est pas achevée. "'),
('esd',5,17,'crampon1923','Maintenant, si le roi le trouve bon, que l''on fasse des recherches dans la maison des trésors du roi, là à Babylone, pour savoir s''il existe un décret rendu par le roi Cyrus, permettant de bâtir cette maison de Dieu à Jérusalem. Puis, que le roi nous transmette sa volonté à cet égard."'),
('esd',6,1,'crampon1923','Alors le roi Darius rendit un décret et l''on fit des recherches dans la maison des archives, où étaient déposés les trésors, à Babylone.'),
('esd',6,2,'crampon1923','Et l''on trouva à Ecbatane, la forteresse qui est en la province de Médie, un rouleau sur lequel était écrit le document suivant:'),
('esd',6,3,'crampon1923','" La première année du roi Cyrus, le roi Cyrus a donné cet ordre: que la maison de Dieu qui est à Jérusalem, que cette maison soit rebâtie pour être un lieu où l''on offre des sacrifices, et que les fondations soient solidement posées. Sa hauteur sera de soixante coudées et sa largeur de soixante coudées.'),
('esd',6,4,'crampon1923','Il y aura trois rangées de pierre de taille et une rangée de bois; la dépense sera payée par la maison du roi.'),
('esd',6,5,'crampon1923','En outre, on rendra les ustensiles d''or et d''argent de la maison de Dieu, que Nabuchodonosor avait enlevés du temple qui est à Jérusalem, et ils seront transportés au temple qui est à Jérusalem, à la place où ils étaient, et tu les déposeras dans la maison de Dieu. "'),
('esd',6,6,'crampon1923','"... Maintenant, Thathanaï, gouverneur d''au delà du fleuve, Stharbuzanaï et vos compagnons d''Apharsach, qui êtes au delà du fleuve, tenez-vous éloignés de là,'),
('esd',6,7,'crampon1923','et laissez continuer les travaux de cette maison de Dieu; que le gouverneur des Juifs et les anciens des Juifs rebâtissent cette maison de Dieu sur son ancien emplacement.'),
('esd',6,8,'crampon1923','Voici l''ordre que je donne touchant ce que vous devez faire avec ces anciens des Juifs pour rebâtir cette maison de Dieu: sur les biens du roi, provenant des impôts d''au delà du fleuve, la dépense sera exactement payée à ces hommes, afin qu''il n''y ait pas d''interruption.'),
('esd',6,9,'crampon1923','Ce qui sera nécessaire pour les holocaustes du Dieu du ciel, jeunes taureaux, béliers et agneaux, froment, sel, vin et huile, selon l''ordonnance des prêtres qui sont à Jérusalem, leur sera donné jour par jour, sans faute,'),
('esd',6,10,'crampon1923','afin qu''ils offrent des sacrifices d''agréable odeur au Dieu du ciel, et qu''ils prient pour la vie du roi et de ses fils.'),
('esd',6,11,'crampon1923','Je donne aussi cet ordre: Si quelqu''un change cette parole, qu''on arrache de sa maison une poutre, qu''il y soit suspendu et attaché, et qu''à cause de cela l''on fasse de sa maison un tas d''immondices.'),
('esd',6,12,'crampon1923','Que le Dieu qui fait résider là son nom renverse tout roi et tout peuple qui étendraient la main pour changer ce décret et détruire cette maison de Dieu qui est à Jérusalem! Moi, Darius, j''ai donné cet ordre: qu''il soit ponctuellement exécuté. "'),
('esd',6,13,'crampon1923','Alors Thathanaï, gouverneur d''au delà du fleuve, Stharbuzanaï et leurs compagnons se conformèrent ponctuellement à l''ordre que le roi Darius leur avait envoyé.'),
('esd',6,14,'crampon1923','Et les anciens d''Israël se mirent à bâtir et firent des progrès, soutenus par les prophéties d''Aggée, le prophète, et de Zacharie, fils d''Addo. Ils bâtirent et achevèrent, d''après l''ordre du Dieu d''Israël et d''après l''ordre de Cyrus, de Darius et d''Artaxerxès, roi de Perse.'),
('esd',6,15,'crampon1923','On acheva cette maison le troisième jour du mois d''Adar, dans la sixième année du règne du roi Darius.'),
('esd',6,16,'crampon1923','Les enfants d''Israël, les prêtres et les lévites, et le reste des fils de la captivité, firent avec joie la dédicace de cette maison de Dieu.'),
('esd',6,17,'crampon1923','Ils offrirent, pour la dédicace de cette maison de Dieu, cent taureaux, deux cents béliers, quatre cents agneaux, et, comme victimes pour le péché, en faveur de tout Israël, douze boucs, d''après le nombre des tribus d''Israël.'),
('esd',6,18,'crampon1923','Ils établirent les prêtres selon leurs divisions et les lévites selon leurs classes pour le service du Dieu qui est à Jérusalem, comme il est écrit dans le livre de Moïse.'),
('esd',6,19,'crampon1923','Les fils de la captivité célébrèrent la Pâque le quatorzième jour du premier mois.'),
('esd',6,20,'crampon1923','Car les prêtres et les lévites sans exception s''étaient purifiés; tous étaient purs; et ils immolèrent la Pâque pour tous les fils de la captivité, pour leurs frères les prêtres et pour eux-mêmes.'),
('esd',6,21,'crampon1923','Les enfants d''Israël revenus de la captivité mangèrent la Pâque, ainsi que tous ceux qui s''étaient séparés de l''impureté des nations du pays pour se joindre à eux afin de chercher Yahweh, le Dieu d''Israël.'),
('esd',6,22,'crampon1923','Ils célébrèrent avec joie pendant sept jours la fête des Azymes; car Yahweh les avait réjouis en tournant vers eux le cœur du roi d''Assyrie, pour soutenir leurs mains dans l''œuvre de la maison de Dieu, du Dieu d''Israël.'),
('esd',7,1,'crampon1923','Après ces événements, sous le règne d''Artaxerxès, roi de Perse, Esdras, fils de Saraïas, fils d''Azarias, fils d''Helcias,'),
('esd',7,2,'crampon1923','fils de Sellum, fils de Sadoc, fils d''Achitob,'),
('esd',7,3,'crampon1923','fils d''Amarias, fils d''Azarias, fils de Maraïoth,'),
('esd',7,4,'crampon1923','fils de Zarahias, fils d''Ozi, fils de Bocci,'),
('esd',7,5,'crampon1923','fils d''Abisué, fils de Phinées, fils d''Eléazar, fils d''Aaron, le grand prêtre, —'),
('esd',7,6,'crampon1923','cet Esdras monta de Babylone: c''était un scribe versé dans la loi de Moïse, qu''a donnée Yahweh, le Dieu d''Israël. Comme la main de Yahweh, son Dieu, était sur lui, le roi lui accorda tout ce qu''il avait demandé.'),
('esd',7,7,'crampon1923','Plusieurs des enfants d''Israël, des prêtres et des lévites, des chantres, des portiers et des Nathinéens montèrent aussi à Jérusalem, la septième année du roi Artaxerxès.'),
('esd',7,8,'crampon1923','Esdras arriva à Jérusalem le cinquième mois de la septième année du roi.'),
('esd',7,9,'crampon1923','C''est le premier jour du premier mois qu''il commença à monter de Babylone, et c''est le premier jour du cinquième mois qu''il arriva à Jérusalem, la main bienfaisante de son Dieu étant sur lui.'),
('esd',7,10,'crampon1923','Car Esdras avait appliqué son cœur à étudier la loi de Yahweh, à la mettre en pratique, et à enseigner en Israël les préceptes et les ordonnances.'),
('esd',7,11,'crampon1923','Voici la copie de la lettre que le roi Artaxerxès donna à Esdras, le prêtre et le scribe, scribe instruit des paroles de la loi de Yahweh et de ses préceptes, concernant Israël:'),
('esd',7,12,'crampon1923','" Artaxerxès, roi des rois, à Esdras, prêtre et scribe versé dans la loi du Dieu du ciel, etc.'),
('esd',7,13,'crampon1923','J''ai donné ordre pour que tous ceux du peuple d''Israël, de ses prêtres et de ses lévites, résidant dans mon royaume, qui désirent aller à Jérusalem, y aillent avec toi.'),
('esd',7,14,'crampon1923','Car tu es envoyé par le roi et ses sept conseillers pour inspecter Juda et Jérusalem d''après la loi de ton Dieu, laquelle est dans ta main,'),
('esd',7,15,'crampon1923','et pour porter l''argent et l''or que le roi et ses conseillers ont spontanément offerts au Dieu d''Israël, dont la demeure est à Jérusalem,'),
('esd',7,16,'crampon1923','ainsi que tout l''or et l''argent que tu trouveras dans toute la province de Babylone, avec les dons volontaires du peuple et des prêtres, librement offerts pour la maison de leur Dieu à Jérusalem.'),
('esd',7,17,'crampon1923','C''est pourquoi tu auras soin d''acheter avec cet argent des taureaux, des béliers, des agneaux, et ce qui est nécessaire pour les oblations et les libations qui les accompagnent, et tu les offriras sur l''autel de la maison de votre Dieu, qui est à Jérusalem.'),
('esd',7,18,'crampon1923','Vous ferez, avec le reste de l''argent et de l''or, ce qui vous paraîtra bon, à toi et à tes frères, en vous conformant à la volonté de votre Dieu.'),
('esd',7,19,'crampon1923','Dépose devant le Dieu de Jérusalem les ustensiles qui te sont donnés pour le service de la maison de ton Dieu.'),
('esd',7,20,'crampon1923','Et le reste de ce qui est nécessaire à la maison de ton Dieu, et que tu auras à fournir, tu le fourniras après l''avoir reçu de la maison des trésors du roi.'),
('esd',7,21,'crampon1923','Et moi, le roi Artaxerxès, je donne ordre à tous les trésoriers d''au delà du fleuve que tout ce qu''Esdras, prêtre et scribe, versé dans la loi du Dieu du ciel, vous demandera, soit exactement exécuté:'),
('esd',7,22,'crampon1923','jusqu''à cent talents d''argent, cent cors de froment, cent baths de vin, cent baths d''huile, et du sel à discrétion.'),
('esd',7,23,'crampon1923','Que tout ce qui est ordonné par le Dieu du ciel soit ponctuellement accompli pour la maison du Dieu du ciel, afin que sa colère ne vienne pas sur le royaume du roi et de ses fils.'),
('esd',7,24,'crampon1923','Nous vous faisons savoir aussi qu''en ce qui concerne tous les prêtres, lévites, chantres, portiers, Nathinéens et serviteurs quelconques de cette maison de Dieu, il n''est pas permis de lever sur eux ni impôt, ni tribut, ni droit de passage.'),
('esd',7,25,'crampon1923','Et toi, Esdras, selon la sagesse de ton Dieu, qui est dans ta main, établis des juges et des magistrats qui rendent la justice à tout le peuple d''au delà du fleuve, à tous ceux qui connaissent les lois de ton Dieu, et enseigne-les à ceux qui ne les connaissent pas.'),
('esd',7,26,'crampon1923','Quiconque n''exécutera pas la loi de ton Dieu et la loi du roi, qu''il soit fait de lui exacte justice, soit par la mort, soit par le bannissement, soit par une amende, soit par la prison. "'),
('esd',7,27,'crampon1923','Béni soit Yahweh, le Dieu de nos pères, qui a mis ainsi au cœur du roi de glorifier la maison de Yahweh qui est à Jérusalem,'),
('esd',7,28,'crampon1923','et qui a tourné sur moi la bienveillance du roi, de ses conseillers et de tous les plus puissants officiers du roi! Et je pris courage parce que la main de Yahweh mon Dieu était sur moi, et je rassemblai les chefs d''Israël, afin qu''ils partissent avec moi.'),
('esd',8,1,'crampon1923','Voici les chefs de famille — avec leur généalogie, — de ceux qui montèrent avec moi de Babylone, sous le règne du roi Artaxerxès.'),
('esd',8,2,'crampon1923','Des fils de Phinées, Gersom; des fils d''Ithamar, Daniel; des fils de David, Hattus,'),
('esd',8,3,'crampon1923','qui descendait de Séchénias; des fils de Pharos, Zacharie, et avec lui cent cinquante mâles inscrits dans le registre de famille.'),
('esd',8,4,'crampon1923','Des fils de Phahath-Moab, Elioénaï, fils de Zaréhias, et avec lui deux cents mâles;'),
('esd',8,5,'crampon1923','des fils de Séchénias, fils d''Ezéchiel, et avec lui trois cents mâles;'),
('esd',8,6,'crampon1923','des fils d''Adin, Abed, fils de Jonathan, et avec lui cinquante mâles;'),
('esd',8,7,'crampon1923','des fils d''Elam, Isaïe, fils d''Athalias, et avec lui soixante-dix mâles;'),
('esd',8,8,'crampon1923','des fils de Saphatias, Zébédias, fils de Michaël, et avec lui quatre-vingts mâles;'),
('esd',8,9,'crampon1923','des fils de Joab, Obédias, fils de Jéhiel, et avec lui deux cent dix-huit mâles;'),
('esd',8,10,'crampon1923','des fils de Selomith, fils de Joséphias, et avec lui cent soixante mâles;'),
('esd',8,11,'crampon1923','des fils de Bébaï, Zacharie, fils de Bébaï, et avec lui vingt-huit mâles;'),
('esd',8,12,'crampon1923','des fils d''Azgad, Johanan, fils d''Eccétan, et avec lui cent dix mâles;'),
('esd',8,13,'crampon1923','des fils d''Adonicam, les derniers, dont voici les noms: Eliphélet, Jéhiel et Samaïas, et avec eux soixante mâles;'),
('esd',8,14,'crampon1923','des fils de Béguaï, Uthaï et Zachur, et avec eux soixante-dix mâles.'),
('esd',8,15,'crampon1923','Je les rassemblai prés de la rivière qui coule vers Ahava, et nous campâmes là trois jours. Ayant porté mon attention sur le peuple et sur les prêtres, je ne trouvai là aucun des fils de Lévi.'),
('esd',8,16,'crampon1923','Alors je fis appeler les chefs Eliézer, Ariel, Séméïas, Elnathan, Jarib, un autre Elnathan, Nathan, Zacharie et Mosollam, ainsi que les docteurs Joïarib et Elnathan.'),
('esd',8,17,'crampon1923','Je les envoyai vers le chef Eddo, à l''endroit appelé Chasphia, et je mis dans leur bouche les paroles qu''ils devaient dire à Eddo et à ses frères les Nathinéens qui étaient à l''endroit appelé Chasphia, afin qu''ils nous amenassent des ministres pour la maison de notre Dieu.'),
('esd',8,18,'crampon1923','Et comme la main bienfaisante de notre Dieu était sur nous, ils nous amenèrent un homme intelligent, d''entre les fils de Moholi, fils de Lévi, fils d''Israël, savoir Sarabias, et avec lui ses fils et ses frères au nombre de dix-huit;'),
('esd',8,19,'crampon1923','Hasabias, et avec lui Isaie, d''entre les fils de Mérari,'),
('esd',8,20,'crampon1923','ses frères et leurs fils au nombre de vingt; et d''entre les Nathinéens, que David et les chefs avaient donnés pour le service des lévites, deux cent vingt Nathinéens, tous nominativement désignés.'),
('esd',8,21,'crampon1923','Je publiai là, près de la rivière d''Ahava, un jeûne pour nous affliger devant notre Dieu, afin d''implorer de lui un heureux voyage pour nous, pour nos enfants et pour tout ce qui nous appartenait.'),
('esd',8,22,'crampon1923','Car j''aurais eu honte de demander au roi une escorte et des cavaliers pour nous secourir contre l''ennemi pendant la route, parce que nous avions dit au roi: " La main de notre Dieu est pour leur bien sur tous ceux qui le cherchent, mais sa force et sa colère sont sur tous ceux qui l''abandonnent. "'),
('esd',8,23,'crampon1923','Et à cause de cela nous jeûnâmes et nous invoquâmes notre Dieu; et il nous exauça.'),
('esd',8,24,'crampon1923','Je choisis douze chefs des prêtres, Sarabias et Hasabias, et dix de leurs frères.'),
('esd',8,25,'crampon1923','Je pesai devant eux l''argent, l''or et les ustensiles, offrande qu''avaient prélevée pour la maison de notre Dieu le roi, ses conseillers et ses chefs, et tous ceux d''Israël qui se trouvaient là;'),
('esd',8,26,'crampon1923','et je pesai, en les remettant entre leurs mains, six cent cinquante talents d''argent, des ustensiles d''argent de la valeur de cent talents, cent talents d''or,'),
('esd',8,27,'crampon1923','vingt coupes d''or de la valeur de mille dariques, et deux vases d''un bel airain brillant, aussi précieux que l''or.'),
('esd',8,28,'crampon1923','Et je leur dis: " Vous êtes saints devant Yahweh, et ces ustensiles sont saints, cet argent et cet or sont une offrande volontaire à Yahweh, Dieu de vos pères.'),
('esd',8,29,'crampon1923','Soyez vigilants à les garder, jusqu''à ce que vous les pesiez devant les chefs des prêtres et des lévites, et devant les chefs de famille d''Israël, à Jérusalem, dans les chambres de la maison de Yahweh. "'),
('esd',8,30,'crampon1923','Et les prêtres et les lévites reçurent au poids l''argent, l''or et les ustensiles, pour les porter à Jérusalem dans la maison de notre Dieu.'),
('esd',8,31,'crampon1923','Nous partîmes de la rivière d''Ahava le douzième jour du premier mois, pour nous rendre à Jérusalem. La main de notre Dieu fut sur nous, et nous sauva des mains de l''ennemi et des embûches pendant la route.'),
('esd',8,32,'crampon1923','Arrivés à Jérusalem, nous nous y reposâmes trois jours.'),
('esd',8,33,'crampon1923','Le quatrième jour, l''argent, l''or et les ustensiles furent pesés, dans la maison de notre Dieu, entre les mains de Mérimuth, fils d''Urie, le prêtre; il y avait avec lui Eléazar, fils de Phinées et avec eux les lévites Jozabad, fils de Josué, et Noadias, fils de Bennui.'),
('esd',8,34,'crampon1923','Le tout fut livré selon le nombre et selon le poids; et le poids total fut mis par écrit en ce temps-là.'),
('esd',8,35,'crampon1923','Ceux qui revenaient de l''exil, les fils de la captivité, offrirent en holocauste au Dieu d''Israël douze taureaux pour tout Israël, quatre-vingt-seize béliers, soixante-dix-sept agneaux, douze boucs pour le péché, le tout en holocauste à Yahweh.'),
('esd',8,36,'crampon1923','Ils transmirent les ordres du roi aux satrapes du roi et aux gouverneurs d''au delà du fleuve, et ceux-ci soutinrent le peuple et la maison de Dieu.'),
('esd',9,1,'crampon1923','Quand ces choses furent achevées, les chefs s''approchèrent de moi, en disant: " Le peuple d''Israël, les prêtres et les lévites ne se sont point séparés des peuples de ces pays; ils imitent leurs abominations, celles des Chananéens, des Héthéens, des Phérézéens, des Jébuséens, des Ammonites, des Moabites, des Egyptiens et des Amorrhéens.'),
('esd',9,2,'crampon1923','Car ils ont pris de leurs filles pour eux et pour leurs fils, et la race sainte s''est alliée avec les peuples de ces pays; et la main des chefs et des magistrats a été la première dans cette transgression. "'),
('esd',9,3,'crampon1923','Lorsque j''appris cette affaire, je déchirai mes vêtements et mon manteau, je m''arrachai les cheveux de la tête et la barbe, et je m''assis consterné.'),
('esd',9,4,'crampon1923','Auprès de moi se réunirent tous ceux qui tremblaient à cause des paroles du Dieu d''Israël, à cause de la transgression des fils de la captivité; et moi, je restai assis, consterné, jusqu''à l''oblation du soir.'),
('esd',9,5,'crampon1923','Puis, au moment de l''oblation du soir, je me levai de mon affliction, avec mes vêtements et mon manteau déchirés, et, tombant à genoux, les mains étendues vers Yahweh, mon Dieu,'),
('esd',9,6,'crampon1923','je dis: " Mon Dieu, je suis trop chargé de honte et de confusion pour lever ma face vers vous, mon Dieu; car nos iniquités se sont multipliées par-dessus nos têtes, et notre faute est montée jusqu''au ciel.'),
('esd',9,7,'crampon1923','Depuis les jours de nos pères jusqu''à ce jour, nous avons été grandement coupables; et c''est à cause de nos iniquités que nous avons été livrés, nous, nos rois et nos prêtres, aux mains des rois des pays, à l''épée, à la captivité, au pillage et à la honte, comme nous le sommes encore aujourd''hui.'),
('esd',9,8,'crampon1923','Et maintenant, Yahweh, notre Dieu, nous a un moment témoigné sa miséricorde, en nous laissant un reste et en nous accordant un abri dans son lieu saint, afin que notre Dieu éclaire nos yeux et nous rende un peu de vie au milieu de notre servitude.'),
('esd',9,9,'crampon1923','Car nous sommes esclaves; mais notre Dieu ne nous a pas abandonnés dans notre servitude. Il a dirigé sur nous la bienveillance des rois de Perse, pour nous rendre la vie, afin que nous bâtissions la maison de notre Dieu et que nous relevions ses ruines, et pour nous donner une demeure close en Juda et à Jérusalem.'),
('esd',9,10,'crampon1923','Maintenant, ô notre Dieu, que dirons-nous après cela? Car nous avons abandonné vos commandements'),
('esd',9,11,'crampon1923','que vous nous aviez prescrits par l''organe de vos serviteurs les prophètes, en disant: Le pays dans lequel vous entrez pour en prendre possession est un pays d''impureté, souillé par les impuretés des peuples de ces contrées, par les abominations dont ils l''ont rempli d''un bout à l''autre avec leurs impuretés.'),
('esd',9,12,'crampon1923','Et maintenant, ne donnez point vos filles à leurs fils, et ne prenez point leurs filles pour vos fils, et n''ayez jamais souci de leur prospérité ni de leur bien-être, afin que vous deveniez forts, que vous mangiez les bons produits de ce pays, et que vous le transmettiez pour toujours en héritage à vos enfants...'),
('esd',9,13,'crampon1923','Après tout ce qui nous est arrivé à cause de nos mauvaises actions et de nos grandes fautes, — quoique vous nous ayez épargnés, ô notre Dieu, plus que ne le méritaient nos iniquités, et que vous nous ayez laissé un reste tel que celui-ci, —'),
('esd',9,14,'crampon1923','pourrions-nous violer de nouveau vos commandements et nous allier avec ces peuples si abominables? Ne vous irriteriez-vous pas contre nous jusqu''à nous détruire, sans laisser ni reste ni réchappés?'),
('esd',9,15,'crampon1923','Yahweh, Dieu d''Israël, vous êtes juste, car nous ne sommes aujourd''hui qu''un reste de réchappés; nous voici devant vous avec notre faute; car nous ne pouvons, à cause d''elle, subsister devant votre face. "'),
('esd',10,1,'crampon1923','Pendant qu''Esdras, pleurant et prosterné devant la maison de Dieu, faisait cette prière et cette confession, il s''était réuni auprès de lui une assemblée très nombreuse d''Israélites, hommes, femmes et enfants; car le peuple versait beaucoup de larmes.'),
('esd',10,2,'crampon1923','Alors Séchénias, fils de Jéhiel, d''entre les fils d''Elam, prit la parole et dit à Esdras: " Nous avons péché contre notre Dieu en établissant chez nous des femmes étrangères, appartenant à la population du pays. Et maintenant, il reste à cet égard à Israël une espérance.'),
('esd',10,3,'crampon1923','Concluons maintenant une alliance avec notre Dieu, en vue de renvoyer toutes les femmes et les enfants issus d''elles, selon le conseil de mon seigneur et de ceux qui craignent devant les commandements de notre Dieu. Et qu''il soit fait selon la Loi.'),
('esd',10,4,'crampon1923','Lève-toi, car c''est à toi de prendre en main cette affaire. Nous serons avec toi. Courage, et à l''œuvre! "'),
('esd',10,5,'crampon1923','Esdras se leva, et il fit jurer aux chefs des prêtres, des lévites et de tout Israël, de faire comme il venait d''être dit; et ils le jurèrent.'),
('esd',10,6,'crampon1923','Puis, s''étant retiré de devant la maison de Dieu, Esdras alla dans la chambre de Johanan, fils d''Eliasib; quand il y fut entré, il ne mangea pas de pain et ne but pas d''eau, parce qu''il était dans le deuil à cause du péché des fils de la captivité.'),
('esd',10,7,'crampon1923','On fit passer une proclamation dans Juda et à Jérusalem, pour que tous les fils de la captivité se réunissent à Jérusalem;'),
('esd',10,8,'crampon1923','et, d''après l''avis des chefs et des anciens, quiconque n''y serait pas arrivé dans trois jours, aurait tous ses biens confisqués et serait lui-même exclu de l''assemblée des fils de la captivité.'),
('esd',10,9,'crampon1923','Tous les hommes de Juda et de Benjamin se rassemblèrent à Jérusalem dans les trois jours; c''était le vingtième jour du neuvième mois. Tout le peuple se tenait sur la place de la maison de Dieu, tremblant à cause de la circonstance, et parce qu''il pleuvait.'),
('esd',10,10,'crampon1923','Esdras, le prêtre, se leva et leur dit: " Vous avez péché en établissant chez vous des femmes étrangères, ajoutant ainsi à la faute d''Israël.'),
('esd',10,11,'crampon1923','Et maintenant, confessez votre faute à Yahweh, le Dieu de vos pères, et faites sa volonté; séparez-vous des peuples du pays et des femmes étrangères. "'),
('esd',10,12,'crampon1923','Toute l''assemblée répondit, en disant d''une voix haute: " A nous d''agir comme tu l''as dit!'),
('esd',10,13,'crampon1923','Mais le peuple est nombreux, et c''est le temps des pluies, et il n''est pas possible de rester dehors; d''ailleurs, ce n''est pas l''affaire d''un jour ou deux, car nous avons commis un grave péché en cette matière.'),
('esd',10,14,'crampon1923','Que nos chefs restent donc pour toute l''assemblée; et que tous ceux qui, dans nos villes, ont établi chez eux des femmes étrangères, viennent aux jours qui leur seront fixés, avec les anciens de chaque ville et ses juges, jusqu''à ce qu''on ait détourné de nous le feu de la colère de notre Dieu au sujet de cette affaire. "'),
('esd',10,15,'crampon1923','Il n''y eut que Jonathan, fils d''Azahel, et Jaasias, fils de Thécuah, pour combattre cet avis; et Mosollam et Sebéthaï, le lévite, les appuyèrent.'),
('esd',10,16,'crampon1923','Mais les fils de la captivité firent comme il avait été dit. Esdras, le prêtre, et des hommes, chefs de familles selon leurs maisons, tous désignés par leurs noms, se mirent à part et siégèrent le premier jour du dixième mois pour examiner l''affaire.'),
('esd',10,17,'crampon1923','Ils en eurent fini le premier jour du premier mois avec tous les hommes qui avaient établi chez eux des femmes étrangères.'),
('esd',10,18,'crampon1923','Parmi les fils des prêtres, il s''en trouva qui avaient établi chez eux des femmes étrangères, savoir: des fils de Josué, fils de Josédec, et de ses frères: Maasias, Eliézer, Jarib et Godolias;'),
('esd',10,19,'crampon1923','ils donnèrent parole de renvoyer leurs femmes et, se déclarant coupables, d''offrir un bélier pour l''expiation de leur faute.'),
('esd',10,20,'crampon1923','Des fils d''Emmer: Hanani et Zébédias.'),
('esd',10,21,'crampon1923','Des fils de Harim: Maasias, Elie, Séméïas, Jéhiel et Ozias.'),
('esd',10,22,'crampon1923','Des fils de Phashur: Elioénaï, Maasias, Ismaël, Nathanaël, Jozabed et Elasa.'),
('esd',10,23,'crampon1923','— Parmi les lévites: Jozabed, Séméï, Célaïas, le même que Célita, Phataïas, Juda et Eliézer.'),
('esd',10,24,'crampon1923','— Parmi les chantres: Eliasib. — Parmi les portiers: Selum, Télem et Uri.'),
('esd',10,25,'crampon1923','Parmi ceux d''Israël: Des fils de Pharos: Réméïas, Jézias, Melchias, Miamin, Eliézer, Melchias et Banaïas;'),
('esd',10,26,'crampon1923','des fils d''Elam: Mathanias, Zacharie, Jéhiel, Abdi, Jérimoth et Elie;'),
('esd',10,27,'crampon1923','des fils de Zéthua: Elioénaï, Eliasib, Mathanias, Jérimoth, Zabad et Aziza;'),
('esd',10,28,'crampon1923','des fils de Bébaï: Johanan, Ananie, Zabbaï, Athalaï;'),
('esd',10,29,'crampon1923','des fils de Bani: Mosollam, Melluch, Adaïas, Jasub, Saal et Ramoth;'),
('esd',10,30,'crampon1923','des fils de Phahath-Moab: Edna, Chalal, Banaïas, Maasias, Mathanias, Béséléel, Bennui et Manassé;'),
('esd',10,31,'crampon1923','des fils de Harim: Eliézer, Jesias, Melchias, Séméïas, Siméon,'),
('esd',10,32,'crampon1923','Benjamin, Melluch, Samarias;'),
('esd',10,33,'crampon1923','des fils de Hasom: Mathanaï, Mathatha, Zabad, Eliphélet, Jermaï, Manassé, Séméï;'),
('esd',10,34,'crampon1923','des fils de Bani: Maaddi, Amram, Uel,'),
('esd',10,35,'crampon1923','Banaïas, Badaïas, Chéliaü,'),
('esd',10,36,'crampon1923','Vanias, Merimuth, Eliasib,'),
('esd',10,37,'crampon1923','Mathanias, Mathanai, Jasi,'),
('esd',10,38,'crampon1923','Bani, Bennui, Séméï,'),
('esd',10,39,'crampon1923','Salmias, Nathan, Adaïas,'),
('esd',10,40,'crampon1923','Mechnédébaï, Sisaï, Sarai,'),
('esd',10,41,'crampon1923','Ezrel, Sélémiaü, Sémérias,'),
('esd',10,42,'crampon1923','Sellum, Amarias, Joseph;'),
('esd',10,43,'crampon1923','des fils de Nébo: Jéhiel, Mathathias, Zabad, Zabina, Jeddu, Joël et Banaïas.'),
('esd',10,44,'crampon1923','Tous ces hommes avaient pris des femmes étrangères, et plusieurs d''entre eux en avaient eu des enfants.'),
('ne',1,1,'crampon1923','Paroles de Néhémie, fils de Helchias. Au mois de Casleu, la vingtième année, comme j''étais à Suse, dans le château,'),
('ne',1,2,'crampon1923','arriva Hanani, l''un de mes frères, avec des hommes de Juda. Je les questionnai au sujet des Juifs délivrés, qui avaient échappé à la captivité, et au sujet de Jérusalem.'),
('ne',1,3,'crampon1923','Ils me répondirent: " Les réchappés, ceux qui ont échappé à la captivité, là-bas dans la province, sont dans une grande misère et dans l''opprobre; les murailles de Jérusalem sont démolies et ses portes consumées par le feu. "'),
('ne',1,4,'crampon1923','Lorsque j''entendis ces choses, je m''assis et je pleurai, et je fus plusieurs jours dans le deuil. Je jeûnais et je priais devant le Dieu du ciel,'),
('ne',1,5,'crampon1923','en disant: " Ah! Yahweh, Dieu du ciel, Dieu grand et redoutable, vous qui gardez l''alliance et la miséricorde à l''égard de ceux qui vous aiment et qui observent vos commandements,'),
('ne',1,6,'crampon1923','que votre oreille soit attentive et que vos yeux soient ouverts, pour que vous entendiez la prière de votre serviteur, celle que je vous adresse maintenant, nuit et jour, pour vos serviteurs, les enfants d''Israël, en confessant les péchés des enfants d''Israël, ceux que nous avons commis contre vous; car moi et la maison de mon père, nous avons péché.'),
('ne',1,7,'crampon1923','Nous avons très mal agi envers vous, nous n''avons pas observé les commandements, les lois et les ordonnances que vous avez prescrits à Moïse, votre serviteur.'),
('ne',1,8,'crampon1923','Souvenez-vous de la parole que vous avez ordonné à Moïse, votre serviteur, de prononcer, en disant: Si vous transgressez mes préceptes, je vous disperserai parmi les peuples;'),
('ne',1,9,'crampon1923','mais si vous revenez à moi, et si vous observez mes commandements et les mettez en pratique, alors même que vos exilés seraient à l''extrémité du ciel, de là je les rassemblerai et je les ramènerai dans le lieu que j''ai choisi pour y faire habiter mon nom.'),
('ne',1,10,'crampon1923','Ils sont vos serviteurs et votre peuple, que vous avez rachetés par votre grande puissance et par votre main forte.'),
('ne',1,11,'crampon1923','Ah! Seigneur, que votre oreille soit attentive à la prière de votre serviteur et à la prière de vos serviteurs qui se plaisent à craindre votre nom! Daignez aujourd''hui donner le succès à votre serviteur, et faites-lui trouver grâce devant cet homme! " J''étais alors échanson du roi.'),
('ne',2,1,'crampon1923','Au mois de Nisan, la vingtième année du roi Artaxerxés, comme le vin était devant lui, je pris le vin et je l''offris au roi, et je tâchai de n''être pas triste en sa présence.'),
('ne',2,2,'crampon1923','Le roi me dit: " Pourquoi ton visage est-il triste, puisque tu n''es pas malade? Ce ne peut être qu''une tristesse de cœur. " Je fus très effrayé'),
('ne',2,3,'crampon1923','et je répondis au roi: " Que le roi vive éternellement! Comment mon visage ne serait-il pas triste, lorsque la ville où sont les sépulcres de mes pères est dévastée et que ses portes sont consumées par le feu? "'),
('ne',2,4,'crampon1923','Et le roi me dit: " Que veux-tu demander? " Je priai le Dieu du ciel,'),
('ne',2,5,'crampon1923','et je répondis au roi: " Si le roi le trouve bon, et si ton serviteur t''est agréable, je demande que tu m''envoies en Juda, vers la ville des sépulcres de mes pères, pour que je la rebâtisse. "'),
('ne',2,6,'crampon1923','Et le roi me dit, la reine étant assise prés de lui: " Jusqu''à quand durera ton voyage, et quand reviendras-tu? " Il plut au roi de m''envoyer et je lui fixai un temps.'),
('ne',2,7,'crampon1923','Puis je dis au roi: " Si le roi le trouve bon, qu''on me donne des lettres pour les gouverneurs d''au delà du fleuve, afin qu''ils me laissent passer jusqu''à ce que j''arrive en Juda,'),
('ne',2,8,'crampon1923','et une lettre pour Asaph, garde de la forêt qui appartient au roi, afin qu''il me fournisse du bois pour mettre des poutres aux portes de la forteresse qui est proche du temple, pour la muraille de la ville et pour la maison où je me retirerai. " Et le roi me donna ces lettres, car la main favorable de mon Dieu était sur moi.'),
('ne',2,9,'crampon1923','Je me rendis donc auprès des gouverneurs d''au delà du fleuve, et je leur remis les lettres du roi; or le roi avait envoyé avec moi des chefs militaires et des cavaliers.'),
('ne',2,10,'crampon1923','Quand Sanaballat, le Horonite, et Tobie, le serviteur ammonite, furent au courant, il leur parut très mauvais qu''un homme vint pour procurer le bien des enfants d''Israël.'),
('ne',2,11,'crampon1923','J''arrivai à Jérusalem et, après y avoir passé trois jours,'),
('ne',2,12,'crampon1923','je me levai pendant la nuit, avec un petit nombre d''hommes. Je ne communiquai à personne ce que mon Dieu m''avait mis au cœur de faire pour Jérusalem. Je n''avais avec moi d''autre bête de somme que ma propre monture.'),
('ne',2,13,'crampon1923','Je sortis de nuit par la porte de la Vallée, me dirigeant vers la source du Dragon et la porte du Fumier; et je considérai les murailles démolies de Jérusalem et ses portes consumées par le feu.'),
('ne',2,14,'crampon1923','Je continuai vers la porte de la Source et l''étang du Roi, et il n''y avait pas de place pour que la monture pût passer sous moi.'),
('ne',2,15,'crampon1923','Je montai de nuit dans le ravin, et je considérai la muraille; puis je revins par la porte de la Vallée, et je rentrai.'),
('ne',2,16,'crampon1923','Les magistrats ignoraient où j''étais allé et ce que je voulais faire. Jusqu''à ce moment je n''avais fait part de rien aux Juifs, ni aux prêtres, ni aux grands, ni aux magistrats, ni au reste du peuple qui devait s''occuper des travaux.'),
('ne',2,17,'crampon1923','Je leur dis alors: " Vous voyez la misère dans laquelle nous sommes, Jérusalem est dévastée, et ses portes sont consumées par le feu. Venez, rebâtissons la muraille de Jérusalem, et nous ne serons plus un sujet d''opprobre. "'),
('ne',2,18,'crampon1923','Et je leur racontai comment la main favorable de mon Dieu avait été sur moi, et aussi quelles paroles le roi m''avaient adressées. Ils répondirent: " Levons-nous, et bâtissons! " Et ils mirent avec courage la main à cette bonne œuvre.'),
('ne',2,19,'crampon1923','Quand Sanaballat, le Horonite, Tobie, le serviteur ammonite, et Gosem, l''Arabe, l''eurent appris, ils se moquèrent de nous et nous méprisèrent. Ils disaient: " Que faites-vous là? Vous révoltez-vous contre le roi? "'),
('ne',2,20,'crampon1923','Je leur fis réponse et leur dis: " Le Dieu du ciel nous donnera le succès. Nous, ses serviteurs, nous allons nous mettre à rebâtir; quant à vous, vous n''avez ni part, ni droit, ni souvenir dans Jérusalem. "'),
('ne',3,1,'crampon1923','Eliasib, le grand prêtre, et ses frères les prêtres se mirent à bâtir la porte des Brebis; ils la consacrèrent et en posèrent les battants; ils réparèrent la muraille et la consacrèrent jusqu''à la tour de Méa et jusqu''à la tour de Hananéel.'),
('ne',3,2,'crampon1923','A côté bâtissaient les hommes de Jéricho; et à côté bâtissait Zachur, fils d''Amri.'),
('ne',3,3,'crampon1923','Les fils d''Asnaa bâtirent la porte des Poissons; ils y mirent des poutres et en posèrent les battants, les verrous et les barres;'),
('ne',3,4,'crampon1923','et à côté, réparait Marimuth, fils d''Urie, fils d''Accus; et à côté réparait Mosollam, fils de Barachie, fils de Mésézébel; et à côté réparait Sadoc, fils de Baana;'),
('ne',3,5,'crampon1923','et à côté réparaient les Thécuites: mais leurs chefs n''apportèrent pas leur concours à la besogne de leur Seigneur.'),
('ne',3,6,'crampon1923','Joïada, fils de Phaséa, et Mosollam, fils de Besodias, réparèrent la Vieille Porte; ils y mirent des poutres et en posèrent les battants, les verrous et les barres.'),
('ne',3,7,'crampon1923','Et à côté réparaient Meltias le Gabaonite, Jadon le Méronathite, et les hommes de Gabaon et de Maspha, près du tribunal du gouverneur d''au delà du fleuve;'),
('ne',3,8,'crampon1923','et à côté réparait Eziel, fils d''Araïas, chef des orfèvres; et à côté réparait Ananie, de la corporation des parfumeurs. Ils laissèrent Jérusalem jusqu''à la muraille large.'),
('ne',3,9,'crampon1923','A côté d''eux réparait Raphaïas, fils de Hur, chef de la moitié du district de Jérusalem.'),
('ne',3,10,'crampon1923','A côté réparait, vis-à-vis de sa maison, Jédaïas, fils de Haromaph; et à côté réparait Hattus, fils de Hasebonias.'),
('ne',3,11,'crampon1923','Melchias, fils de Herem, et Hasub, fils de Phahath-Moab, réparèrent une autre partie de la muraille et la tour des Fourneaux.'),
('ne',3,12,'crampon1923','A côté réparait, avec ses filles, Sellum, fils d''Alohès, chef de l''autre moitié du district de Jérusalem.'),
('ne',3,13,'crampon1923','Hanun et les habitants de Zanoé réparèrent la porte de la Vallée; ils la bâtirent et en posèrent les battants, les verrous et les barres; ils firent en outre mille coudées de mur jusqu''à la porte du Fumier.'),
('ne',3,14,'crampon1923','Melchias, fils de Réchab, chef du district de Bethacharam, répara la porte du Fumier; il la bâtit et en posa les battants, les verrous et les barres.'),
('ne',3,15,'crampon1923','Sellun, fils de Cholhoza, chef du district de Maspha, répara la porte de la Source; il la bâtit, la couvrit et en posa les battants, les verrous et les barres; il fit en outre les murs de l''étang de Siloé, près du jardin du Roi, jusqu''aux degrés qui descendent de la cité de David.'),
('ne',3,16,'crampon1923','Après lui, Néhémie, fils d''Azboc, chef de la moitié du district de Bethsur, répara jusque vis-à-vis des sépulcres de David, jusqu''au réservoir qui avait été construit, et jusqu''à la maison des Héros.'),
('ne',3,17,'crampon1923','Après lui réparaient les lévites, sous la conduite de Réhum, fils de Benni; à côté de lui réparait, pour son district, Hasébias, chef de la moitié du district de Céïla.'),
('ne',3,18,'crampon1923','Après lui réparaient leurs frères, sous la conduite de Bavaï, fils de Enadad, chef de l''autre moitié du district de Céïla.'),
('ne',3,19,'crampon1923','A côté, Azer, fils de Josué, chef de Maspha, répara une autre portion de la muraille, vis-à-vis de la montée de l''arsenal, à l''angle.'),
('ne',3,20,'crampon1923','Après lui, Baruch, fils de Zachaï, réparait avec ardeur une autre portion, depuis l''angle jusqu''à la porte de la maison d''Eliasib, le grand prêtre.'),
('ne',3,21,'crampon1923','Après lui, Mérimuth, fils d''Urie, fils de Haccus, réparait une autre portion, depuis la porte de la maison d''Eliasib, jusqu''à l''extrémité de la maison d''Eliasib.'),
('ne',3,22,'crampon1923','Après lui réparaient les prêtres, les hommes de la plaine du Jourdain.'),
('ne',3,23,'crampon1923','Après eux Benjamin et Hasub réparaient vis-à-vis de leur maison. Après eux, Azarias, fils de Maasias, fils d''Ananie, réparait à côté de sa maison.'),
('ne',3,24,'crampon1923','Après lui, Bennui, fils de Hénadad réparait une autre portion, depuis la maison d''Azarias jusqu''à l''angle et jusqu''au tournant.'),
('ne',3,25,'crampon1923','Phalel, fils d''Ozi, réparait vis-à-vis de l''angle et de la haute tour qui fait saillie en avant de la maison du roi, près de la cour de la prison. Après lui réparait Phadaïas, fils de Pharos.'),
('ne',3,26,'crampon1923','Les Nathinéens demeuraient sur Ophel, jusque vis-à-vis de la porte de l''Eau, à l''orient, et de la tour en saillie.'),
('ne',3,27,'crampon1923','Après lui, les Thécuites réparèrent une autre portion, vis-à-vis de la grande tour en saillie, jusqu''au mur d''Ophel.'),
('ne',3,28,'crampon1923','Au-dessus de la porte des Chevaux, réparaient les prêtres, chacun devant sa maison.'),
('ne',3,29,'crampon1923','Après lui, Sadoc, fils d''Emmer, réparait devant sa maison; après lui, réparait Sémaïas, fils de Séchénias, gardien de la porte orientale du temple.'),
('ne',3,30,'crampon1923','Après lui, Hananias, fils de Sélémias, et Hanun, le sixième fils de Séleph, réparaient une autre portion de la muraille. Après lui, réparait Mosollam, fils de Barachie, devant sa demeure.'),
('ne',3,31,'crampon1923','Après lui, réparait Melchias, de la corporation des orfèvres, jusqu''à l''habitation des Nathinéens et des marchands, devant la porte de Miphcad, et jusqu''à la chambre haute du tournant.'),
('ne',3,32,'crampon1923','Et, entre la chambre haute du tournant et la porte des Brebis, réparaient les orfèvres et les marchands.'),
('ne',3,33,'crampon1923','Lorsque Sanaballat apprit que nous rebâtissons la muraille, il se mit en colère et fut très irrité. Il se moqua des juifs.'),
('ne',3,34,'crampon1923','Il parla devant ses frères et devant les troupes de Samarie, et dit: " Qu''entreprennent les Juifs impuissants? Les laissera-t-on faire? Offriront-ils des sacrifices? Achèveront-ils en un jour? Feront-ils revivre les pierres ensevelies sous des monceaux de poussière et consumées par le feu? "'),
('ne',3,35,'crampon1923','Et Tobie, l''Ammonite, qui était à côté de lui, dit: " Qu''ils bâtissent seulement! Si un renard s''élance, il renversera leur muraille de pierre. "'),
('ne',3,36,'crampon1923','Ecoutez, ô notre Dieu, car nous sommes méprisés! Faites retomber leurs insultes sur leur tête, et livrez-les comme une proie dans un pays d''exil.'),
('ne',3,37,'crampon1923','Ne pardonnez pas leur iniquité et que leur péché ne soit pas effacé de devant votre face, car ils ont fait scandale devant ceux qui bâtissent.'),
('ne',3,38,'crampon1923','Nous rebâtîmes la muraille, et l''enceinte fut rétablie toute entière jusqu''à moitié de sa hauteur; car le peuple prit cœur à ce travail.'),
('ne',4,1,'crampon1923','Quand Sanaballat, Tobie, les Arabes, les Ammonites et les Azotiens, apprirent que la réparation des murs avançait et que les brèches commençaient à se fermer, ils furent très irrités.'),
('ne',4,2,'crampon1923','Ils se liguèrent tous ensemble pour venir attaquer Jérusalem et y causer du trouble.'),
('ne',4,3,'crampon1923','Nous priâmes notre Dieu et nous établîmes une garde contre eux, jour et nuit, pour nous protéger contre eux.'),
('ne',4,4,'crampon1923','Mais Juda disait: " Les forces manquent aux porteurs de fardeaux, et il y a quantité de décombres; nous ne pourrons pas bâtir la muraille. "'),
('ne',4,5,'crampon1923','Et nos ennemis disaient: " Ils ne sauront rien, ils ne verront rien, jusqu''à ce que nous arrivions au milieu d''eux; nous les massacrerons et nous ferons cesser l''ouvrage. "'),
('ne',4,6,'crampon1923','Or, quand venaient les Juifs qui habitaient près d''eux, ils nous avertirent dix fois de tous les lieux d''où nos adversaires revenaient contre nous.'),
('ne',4,7,'crampon1923','Alors je plaçai aux endroits les plus bas, derrière la muraille, en des endroits découverts, je plaçai le peuple par familles, tous avec leurs épées, leurs lances et leurs arcs.'),
('ne',4,8,'crampon1923','Ayant regardé, je me levai et je dis aux grands, aux magistrats et au reste du peuple: " Ne craignez pas devant eux! Souvenez-vous du Seigneur, grand et redoutable, et combattez pour vos frères, pour vos fils et vos filles, pour vos femmes et pour vos maisons! "'),
('ne',4,9,'crampon1923','Quand nos ennemis apprirent que nous étions avertis, et que Dieu avait anéanti leur projet nous retournâmes tous à la muraille, chacun à son ouvrage.'),
('ne',4,10,'crampon1923','Mais à partir de ce jour, la moitié de mes gens travaillait à l''œuvre, et l''autre moitié tenait des lances, des boucliers, des arcs et des cuirasses, et les chefs étaient derrière toute la maison de Juda.'),
('ne',4,11,'crampon1923','Parmi ceux qui bâtissaient la muraille, les uns, ceux qui portaient les fardeaux et s''en chargeaient, travaillaient d''une main à l''œuvre, pendant que l''autre tenait une arme;'),
('ne',4,12,'crampon1923','les autres, ceux qui bâtissaient, avaient chacun leur épée ceinte autour des reins, pendant qu''ils bâtissaient; celui qui sonnait de la trompette se tenait prés de moi.'),
('ne',4,13,'crampon1923','Et je dis aux grands, aux magistrats et au reste du peuple: " L''ouvrage est considérable et sur une vaste étendue; nous sommes dispersés sur la muraille, éloignés les uns des autres.'),
('ne',4,14,'crampon1923','De quelque endroit que vous entendiez le son de la trompette, rassemblez-vous auprès de nous; notre Dieu combattra pour nous. "'),
('ne',4,15,'crampon1923','Et nous travaillions à l''œuvre, la moitié d''entre nous tenant des lances depuis le lever de l''aurore jusqu''à l''apparition des étoiles.'),
('ne',4,16,'crampon1923','Dans ce même temps, je dis encore au peuple: " Que chacun, avec son serviteur, passe la nuit dans Jérusalem, pour nous servir de garde pendant la nuit, et travailler pendant le jour. "'),
('ne',4,17,'crampon1923','Mais ni moi, ni mes frères, ni mes gens, ni les hommes de garde qui me suivaient, ne quittions nos vêtements; chacun ne les ôtait que pour l''ablution.'),
('ne',5,1,'crampon1923','Et il s''éleva une grande plainte des gens du peuple et de leurs femmes contre leurs frères les Juifs.'),
('ne',5,2,'crampon1923','Il y en avait qui disaient: " Nous, nos fils et nos filles, nous sommes nombreux; recevons du blé, afin que nous mangions et que nous vivions. "'),
('ne',5,3,'crampon1923','Il y en avait qui disaient: " Nous engageons nos champs, nos vignes et nos maisons pour recevoir du blé durant la famine. "'),
('ne',5,4,'crampon1923','Il y en avait qui disaient: " Nous avons, pour payer le tribut du roi, emprunté de l''argent sur nos champs et nos vignes.'),
('ne',5,5,'crampon1923','Et maintenant, notre chair est comme la chair de nos frères, nos enfants sont comme leurs enfants; et voici que nous soumettons à la servitude nos fils et nos filles, et il y a de nos filles qui sont déjà servantes!... Et nous n''y pouvons rien, car nos champs et nos vignes sont à d''autres. "'),
('ne',5,6,'crampon1923','Je fus très irrité lorsque j''entendis leurs plaintes et ces paroles.'),
('ne',5,7,'crampon1923','Et, après avoir réfléchi en moi-même, j''adressai des réprimandes aux grands et aux magistrats, et je leur dis: " Vous prêtez donc à intérêt, chacun à votre frère! " Et, ayant réuni à cause d''eux une grande assemblée,'),
('ne',5,8,'crampon1923','je leur dis: " Nous avons racheté selon notre pouvoir nos frères les Juifs qui étaient vendus aux nations, et vous vendriez vous-mêmes vos frères, et c''est à nous qu''ils seraient vendus!... " Ils se turent, ne trouvant rien à répondre.'),
('ne',5,9,'crampon1923','J''ajoutai: " Ce n''est pas une bonne action que vous faites là! Ne devriez-vous pas marcher dans la crainte de notre Dieu, pour éviter l''insulte des nations, nos ennemies?'),
('ne',5,10,'crampon1923','Moi aussi, mes frères et mes serviteurs, nous leur avons prêté de l''argent et du blé. Faisons l''abandon de cette dette.'),
('ne',5,11,'crampon1923','Rendez-leur donc aujourd''hui leurs champs, leurs vignes, leurs oliviers et leurs maisons, et le centième de l''argent, du vin nouveau et de l''huile que vous avez exigé d''eux comme intérêt. "'),
('ne',5,12,'crampon1923','Ils répondirent: " Nous le rendrons, et nous ne leur demanderons plus rien; nous ferons ce que tu dis. " J''appelai alors les prêtres, et je leur fis jurer qu''ils agiraient selon cette parole.'),
('ne',5,13,'crampon1923','Et je secouai mon manteau, en disant: " Que Dieu secoue ainsi hors de sa maison et de ses biens tout homme qui n''aura pas tenu cette parole, et qu''ainsi cet homme soit secoué et laissé à vide! " Toute l''assemblée dit: " Amen! " et loua Yahweh; et le peuple agit selon cette parole.'),
('ne',5,14,'crampon1923','Depuis le jour où le roi me chargea d''être leur gouverneur dans le pays de Juda, savoir depuis la vingtième année jusqu''à la trente-deuxième année du roi Artaxerxès, pendant douze ans, ni moi ni mes frères n''avons mangé le pain du gouverneur.'),
('ne',5,15,'crampon1923','Les anciens gouverneurs qui m''avaient précédé accablaient le peuple et recevaient de lui du pain et du vin, outre quarante sicles d''argent; leurs serviteurs mêmes opprimaient le peuple; mais moi, je n''ai point agi de la sorte, par crainte de Dieu.'),
('ne',5,16,'crampon1923','Et même, je me suis appliqué à l''œuvre de cette muraille; nous n''avons acheté aucun champ, et tous mes gens étaient là rassemblés pour l''œuvre.'),
('ne',5,17,'crampon1923','J''avais à ma table cent cinquante hommes, Juifs et magistrats, outre ceux qui venaient à nous des nations d''alentour.'),
('ne',5,18,'crampon1923','Voici ce qu''on préparait pour chaque jour: un bœuf, six moutons choisis, de la volaille étaient préparés à mes frais, et, tous les dix jours, tout le vin nécessaire, en abondance. Malgré cela, je n''ai pas réclamé le pain du gouverneur, parce que les travaux pesaient lourdement sur ce peuple.'),
('ne',5,19,'crampon1923','Souvenez-vous en ma faveur, ô mon Dieu, de tout ce que j''ai fait pour ce peuple!'),
('ne',6,1,'crampon1923','Lorsqu''il fut connu de Sanaballat, de Tobie, de Gosem l''Arabe et du reste de nos ennemis que j''avais rebâti la muraille et qu''il n''y restait plus de brèche — jusqu''à cette date toutefois je n''avais pas mis les battants aux portes, —'),
('ne',6,2,'crampon1923','Sanaballat et Gosem m''envoyèrent dire: " Viens, et ayons ensemble une entrevue dans les villages, dans la vallée d''Ono. " Ils avaient le dessein de me faire du mal.'),
('ne',6,3,'crampon1923','Je leur envoyai des messagers pour leur dire: " J''exécute un grand travail, et je ne puis descendre. Pourquoi le travail serait-il interrompu, parce que je le quitterais pour descendre vers vous? "'),
('ne',6,4,'crampon1923','Ils m''adressèrent quatre fois la même proposition, et je leur fis la même réponse.'),
('ne',6,5,'crampon1923','Sanaballat m''envoya de la même manière une cinquième fois son serviteur, qui tenait à la main une lettre ouverte.'),
('ne',6,6,'crampon1923','Il y était écrit: " Le bruit se répand parmi les nations et Gosem affirme que toi et les Juifs, vous avez dessein de vous révolter, et que c''est pour cela que tu rebâtis la muraille; et, d''après ces rapports, tu veux devenir leur roi.'),
('ne',6,7,'crampon1923','Et même tu as établis des prophètes pour faire à ton propos cette proclamation dans Jérusalem: Il y a un roi en Juda. Maintenant, on va informer le roi de cette affaire. Viens donc, et consultons-nous ensemble. "'),
('ne',6,8,'crampon1923','Et je lui envoyai dire: " Rien n''est arrivé de pareil à ces choses que tu dis; c''est de ton cœur que tu les inventes. "'),
('ne',6,9,'crampon1923','Car tous voulaient nous effrayer, se disant: " Leurs mains affaiblies se détacheront de l''œuvre, et elle ne s''accomplira pas. " Maintenant, ô mon Dieu, donne force à mes mains!'),
('ne',6,10,'crampon1923','Je me rendis chez Sémaïas, fils de Dalaïas, fils de Métabéel. Il s''était enfermé, et il dit: " Allons ensemble dans la maison de Dieu, dans l''intérieur du temple et fermons les portes du temple; car on vient pour te tuer; c''est pendant la nuit qu''on viendra pour te tuer. "'),
('ne',6,11,'crampon1923','Je répondis: " Un homme comme moi prendre la fuite...! Et comment un homme comme moi pénétrerait-il dans le temple et demeurerait-il en vie? Je n''entrerai point. "'),
('ne',6,12,'crampon1923','Et je fis attention, et voici que ce n''était pas Dieu qui l''envoyait; il avait prononcé sur moi une prophétie parce que Tobie et Sanaballat l''avaient acheté.'),
('ne',6,13,'crampon1923','On l''avait acheté pour que j''aie peur, que j''agisse selon ses avis et que je pèche; et cela leur eut été un prétexte pour me faire un mauvais renom et me couvrir d''opprobre.'),
('ne',6,14,'crampon1923','Souvenez-vous, ô mon Dieu, de Tobie et de Sanaballat selon ces méfaits! Et aussi de Noadias le prophète, et des autres prophètes qui cherchaient à m''effrayer.'),
('ne',6,15,'crampon1923','La muraille fut achevée le vingt-cinquième jour du mois d''Elul, en cinquante-deux jours.'),
('ne',6,16,'crampon1923','Lorsque tous nos ennemis l''apprirent, toutes les nations qui étaient autour de nous furent dans la crainte; elles éprouvèrent un grand découragement et reconnurent que c''était par le secours de notre Dieu que cette œuvre s''était accomplie.'),
('ne',6,17,'crampon1923','Dans ce temps-là aussi, des grands de Juda multipliaient leurs lettres à l''adresse de Tobie, et celles de Tobie leur parvenaient.'),
('ne',6,18,'crampon1923','Car beaucoup de grands en Juda lui étaient liés par serment, parce qu''il était gendre de Séchénias, fils d''Aréa, et que son fils Johanan avait pris pour femme la fille de Mosollam, fils de Barachie.'),
('ne',6,19,'crampon1923','Ils disaient même ses bonnes qualités devant moi, et ils lui rapportaient mes paroles. Tobie envoyait des lettres pour m''effrayer.'),
('ne',7,1,'crampon1923','Lorsque la muraille fut rebâtie et que j''eus posé les battants des portes, les portiers, les chantres et les lévites furent chargés de la surveillance.'),
('ne',7,2,'crampon1923','Je donnai autorité sur Jérusalem à Hanani, mon frère, et à Ananie, commandant de la citadelle, car c''était un homme fidèle et craignant Dieu plus que beaucoup d''autres.'),
('ne',7,3,'crampon1923','Et je leur dis: " Que les portes de Jérusalem ne soient pas ouvertes avant que soit venue la chaleur du soleil; le soir, pendant que les gardes seront encore à leur poste, on fermera les portes et on mettra les barres; et, pendant la nuit, on établira des gardes pris parmi les habitants de Jérusalem, chacun à son poste, et chacun devant sa maison.'),
('ne',7,4,'crampon1923','Or la ville était spacieuse et grande, mais il n''y avait que peu d''habitants au milieu d''elle, et toutes les maisons n''étaient pas rebâties.'),
('ne',7,5,'crampon1923','Mon Dieu me mit au cœur d''assembler les grands, les magistrats et le peuple, pour en faire le dénombrement. Je trouvai un registre généalogique de ceux qui étaient montés les premiers, et j''y vis écrit ce qui suit:'),
('ne',7,6,'crampon1923','Voici les gens de la province qui revinrent de l''exil, — ceux que Nabuchodonosor, roi de Babylone, avait emmenés captifs, et qui retournèrent à Jérusalem et en Juda, chacun dans sa ville, —'),
('ne',7,7,'crampon1923','qui revinrent avec Zorobabel, Josué, Néhémie, Azarias, Raamias, Nahamani, Mardochée, Belsan, Mespharath, Bégoaî, Nahum, Baana: Nombre des hommes du peuple d''Israël:'),
('ne',7,8,'crampon1923','les fils de Pharsos, deux mille cent soixante-douze;'),
('ne',7,9,'crampon1923','les fils de Saphatias, trois cent soixante-douze;'),
('ne',7,10,'crampon1923','les fils d''Aréa, six cent cinquante-deux;'),
('ne',7,11,'crampon1923','les fils de Phahath-Moab, des fils de Josué et de Joab, deux mille huit cent dix-huit;'),
('ne',7,12,'crampon1923','les fils d''Elam, mille deux cent cinquante-quatre;'),
('ne',7,13,'crampon1923','les fils de Zethua, huit cent quarante-cinq;'),
('ne',7,14,'crampon1923','les fils de Zachaï, sept cent soixante;'),
('ne',7,15,'crampon1923','les fils de Bannui, six cent quarante-huit;'),
('ne',7,16,'crampon1923','les fils de Bébaï, six cent vingt-huit;'),
('ne',7,17,'crampon1923','les fils d''Azgad, deux mille trois cent vingt-deux;'),
('ne',7,18,'crampon1923','les fils d''Adonicam, six cent soixante-sept;'),
('ne',7,19,'crampon1923','les fils de Béguaï, deux mille soixante-sept;'),
('ne',7,20,'crampon1923','les fils d''Adin, six cent cinquante-cinq;'),
('ne',7,21,'crampon1923','les fils d''Ater, fils d''Ezéchias, quatre-vingt-dix-huit;'),
('ne',7,22,'crampon1923','les fils de Hasem, trois cent vingt-huit;'),
('ne',7,23,'crampon1923','les fils de Bésaï, trois cent vingt-quatre;'),
('ne',7,24,'crampon1923','les fils de Hareph, cent douze;'),
('ne',7,25,'crampon1923','les fils de Gabaon, quatre-vingt quinze;'),
('ne',7,26,'crampon1923','les gens de Bethléem et de Nétopha, cent quatre-vingt-huit;'),
('ne',7,27,'crampon1923','les gens d''Anathoth, cent vingt-huit;'),
('ne',7,28,'crampon1923','les gens de Beth-Azmoth, quarante-deux;'),
('ne',7,29,'crampon1923','les gens de Cariathiarim, de Céphira et de Béroth: sept cent quarante-trois;'),
('ne',7,30,'crampon1923','les gens de Rama et de Géba, six cent vingt et un;'),
('ne',7,31,'crampon1923','les gens de Machmas, cent vingt deux;'),
('ne',7,32,'crampon1923','les gens de Béthel et de Haï, cent vingt-trois;'),
('ne',7,33,'crampon1923','les gens de l''autre Nébo, cinquante-deux;'),
('ne',7,34,'crampon1923','les fils de l''autre Elam, mille deux cent cinquante-quatre;'),
('ne',7,35,'crampon1923','les fils de Harem, trois cent vingt;'),
('ne',7,36,'crampon1923','les fils de Jéricho, trois cent quarante cinq;'),
('ne',7,37,'crampon1923','les fils de Lod, de Hadid et d''Ono, sept cent vingt et un;'),
('ne',7,38,'crampon1923','les fils de Sénaa, trois mille neuf cent trente.'),
('ne',7,39,'crampon1923','Prêtres: les fils d''Idaïas, de la maison de Josué, neuf cent soixante-treize;'),
('ne',7,40,'crampon1923','les fils d''Emmer, mille cinquante-deux;'),
('ne',7,41,'crampon1923','les fils de Phashur, mille deux cent quarante-sept;'),
('ne',7,42,'crampon1923','les fils d''Arem, mille dix-sept.'),
('ne',7,43,'crampon1923','Lévites: les fils de Josué et de Cedmiel, des fils d''Oduïas; soixante-quatorze.'),
('ne',7,44,'crampon1923','Chantres: les fils d''Asaph: cent quarante-huit.'),
('ne',7,45,'crampon1923','Portiers: les fils de Sellum, les fils d''Ater, les fils de Telmon, les fils d''Accub, les fils de Hatita, les fils de Sobaï; cent trente-huit.'),
('ne',7,46,'crampon1923','Nathinéens: les fils de Soha, les fils de Hasupha, les fils de Tebbaoth,'),
('ne',7,47,'crampon1923','les fils de Céros, les fils de Siaa, les fils de Phadon,'),
('ne',7,48,'crampon1923','les fils de Lébana, les fils de Hagaba, les fils de Selmaï,'),
('ne',7,49,'crampon1923','les fils de Hanan, les fils de Géddel, les fils de Gaher,'),
('ne',7,50,'crampon1923','les fils de Raaïas, les fils de Rasin, les fils de Nécoda,'),
('ne',7,51,'crampon1923','les fils de Gézem, les fils d''Aza, les fils de Phaséa,'),
('ne',7,52,'crampon1923','les fils de Bésée, les fils de Munim, les fils de Néphusim,'),
('ne',7,53,'crampon1923','les fils de Bacbuc, les fils de Hacupha, les fils de Harhur,'),
('ne',7,54,'crampon1923','les fils de Besloth, les fils de Mahida, les fils de Harsa,'),
('ne',7,55,'crampon1923','les fils de Bercos, les fils de Sisara, les fils de Théma,'),
('ne',7,56,'crampon1923','les fils de Nasia, les fils de Hatipha.'),
('ne',7,57,'crampon1923','Fils des serviteurs de Salomon: les fils de Sothaï, les fils de Sophéreth, les fils de Pharida,'),
('ne',7,58,'crampon1923','les fils de Jahala, les fils de Darcon, les fils de Jeddel,'),
('ne',7,59,'crampon1923','les fils de Saphatias, les fils de Hatil, les fils de Phochéreth-Asebaïm, les fils d''Amon.'),
('ne',7,60,'crampon1923','Total des Nathinéens et des fils des serviteurs de Salomon: trois cent quatre-vingt-douze.'),
('ne',7,61,'crampon1923','Voici ceux qui partirent de Thel-Mêla, Thel-Harsa, Chérub, Addon et Emmer, et qui ne purent pas faire connaître leur maison paternelle et leur race, pour montrer qu''ils étaient d''Israël:'),
('ne',7,62,'crampon1923','les fils de Dalaïas, les fils de Tobie, les fils de Nécoda, six cent quarante-deux.'),
('ne',7,63,'crampon1923','Et parmi les prêtres: les fils de Habia, les fils d''Accos, les fils de Berzellaï, qui avait pris pour femme une des filles de Berzellaï, le Galaadite, et fut appelé de leur nom.'),
('ne',7,64,'crampon1923','Ils cherchèrent leur titre attestant leurs généalogies, mais on ne le trouva point. Ils furent déclarés impurs et exclus du sacerdoce,'),
('ne',7,65,'crampon1923','et le gouverneur leur interdit de manger des choses très saintes, jusqu''à ce que le prêtre se levât pour consulter Dieu par l''Urim et le Thummim.'),
('ne',7,66,'crampon1923','L''assemblée tout entière était de quarante-deux mille trois cent soixante personnes,'),
('ne',7,67,'crampon1923','sans compter leurs serviteurs et leurs servantes, qui étaient au nombre de sept mille trois cent trente-sept; parmi eux se trouvaient deux cent quarante cinq chanteurs et chanteuses.'),
('ne',7,68,'crampon1923','Ils avaient sept cent trente-six chevaux, deux cent quarante-cinq mulets,'),
('ne',7,69,'crampon1923','quatre cent trente cinq chameaux et six mille sept cent vingt ânes.'),
('ne',7,70,'crampon1923','Plusieurs des chefs de famille firent des dons pour l''œuvre. Le gouverneur donna au trésor mille dariques d''or, cinquante coupes, cinq cent trente tuniques sacerdotales.'),
('ne',7,71,'crampon1923','Plusieurs des chefs de famille donnèrent au trésor de l''œuvre vingt mille dariques d''or et deux mille deux cents mines d''argent.'),
('ne',7,72,'crampon1923','Ce que le reste du peuple donna fut de vingt mille dariques d''or, deux mille mines d''argent et soixante-sept tuniques sacerdotales.'),
('ne',7,73,'crampon1923','C''est ainsi que les prêtres et les lévites, les chantres, les portiers, des gens du peuple, les Nathinéens et tout Israël s''établirent dans leurs villes.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('ne',8,1,'crampon1923','Le septième mois étant arrivé, et les enfants d''Israël étant établis dans leurs villes, tout le peuple s''assembla comme un seul homme sur la place qui est devant la porte de l''Eau. Et ils dirent à Esdras, le scribe, d''apporter le livre de la loi de Moïse, que Yahweh a prescrite à Israël.'),
('ne',8,2,'crampon1923','Et le prêtre Esdras apporta la loi devant l''assemblée, les hommes et les femmes et tous ceux qui étaient assez intelligents pour l''entendre: c''était le premier jour du septième mois.'),
('ne',8,3,'crampon1923','Il lut dans le livre, depuis le matin jusqu''au milieu du jour, sur la place qui est devant la porte de l''Eau, en présence des hommes et des femmes et de ceux qui étaient assez intelligents pour l''entendre; tout le peuple prêtait l''oreille à la lecture du livre de la loi.'),
('ne',8,4,'crampon1923','Esdras le scribe se tenait sur une estrade de bois, dressée pour la circonstance; et à côté de lui se tenaient, à sa droite, Mathatias, Séméïas, Anias, Urie, Helcias et Maasias; et à sa gauche, Phadaïas, Misaël, Melchias, Hasum, Hasbadana, Zacharie et Mosollam.'),
('ne',8,5,'crampon1923','Esdras ouvrit le livre à la vue de tout le peuple, car il était élevé au-dessus de tout le peuple; et, lorsqu''il l''eut ouvert, tout le peuple se tint debout.'),
('ne',8,6,'crampon1923','Esdras bénit Yahweh, le grand Dieu, et tout le peuple répondit en levant les mains: " Amen! amen! " Et ils s''inclinèrent et se prosternèrent devant Yahweh, le visage contre terre.'),
('ne',8,7,'crampon1923','Et Josué, Bani, Sérébias, Jamin, Accub, Sépthaï, Odias, Maasias, Célita, Azarias, Jozabed, Hanan, Phalaïas et les lévites instruisaient le peuple de la loi, et chacun restait à sa place.'),
('ne',8,8,'crampon1923','Ils lisaient distinctement dans le livre, dans la loi de Dieu, et ils en donnaient le sens, et l''on comprenait ce qui était lu.'),
('ne',8,9,'crampon1923','Et Néhémie, le gouverneur, Esdras, le prêtre et le scribe, et les lévites qui instruisaient le peuple, dirent à tout le peuple: " Ce jour est saint pour Yahweh, votre Dieu; ne soyez pas dans le deuil et dans les larmes. " Car tout le peuple pleurait en entendant les paroles de la loi.'),
('ne',8,10,'crampon1923','Et Néhémie leur dit: " Allez, mangez des viandes grasses et buvez des liqueurs douces, et envoyez des portions à celui qui n''a rien de préparé, car ce jour est saint pour notre Seigneur; ne vous affligez pas, car la joie en Yahweh est votre force. "'),
('ne',8,11,'crampon1923','Les lévites calmaient tout le peuple, en disant: " Taisez-vous; car ce jour est saint; ne vous affligez pas. "'),
('ne',8,12,'crampon1923','Et tout le peuple s''en alla pour manger et boire, envoyer des portions et se livrer à de grandes réjouissances. Car ils avaient compris les paroles qu''on leur avait fait connaître.'),
('ne',8,13,'crampon1923','Le second jour, les chefs de famille de tout le peuple, les prêtres et les lévites s''assemblèrent auprès d''Esdras le scribe, afin de s''instruire plus complètement des paroles de la loi.'),
('ne',8,14,'crampon1923','Et ils trouvèrent écrit dans la loi que Yahweh avait prescrite par l''organe de Moïse, que les enfants d''Israël devaient habiter sous des tentes pendant la fête du septième mois,'),
('ne',8,15,'crampon1923','et qu''ils devaient faire entendre et publier une proclamation dans toutes leurs villes et à Jérusalem, en disant: " Allez à la montagne et rapportez des rameaux d''olivier, des rameaux d''olivier sauvage, des rameaux de myrte, des rameaux de palmier et des rameaux d''arbres touffus pour faire des tentes, selon qu''il est écrit. "'),
('ne',8,16,'crampon1923','Alors le peuple y alla, et ils rapportèrent des rameaux, et ils se firent des tentes chacun sur son toit, dans leurs cours, dans les parvis de la maison de Dieu, sur la place de la porte de l''Eau et sur la place de la porte d''Ephraïm.'),
('ne',8,17,'crampon1923','Toute l''assemblée de ceux qui étaient revenus de la captivité fit des tentes et habita sous les tentes. Depuis les jours de Josué, fils de Nun, jusqu''à ce jour, les enfants d''Israël n''avaient rien fait de pareil. Et il y eut de très grandes réjouissances.'),
('ne',8,18,'crampon1923','On lut dans le livre de la loi de Dieu chaque jour, depuis le premier jour jusqu''au dernier. On célébra la fête pendant sept jours, et le huitième jour il y eut une assemblée solennelle, selon le rite prescrit.'),
('ne',9,1,'crampon1923','Le vingt-quatrième jour du même mois, les enfants d''Israël s''assemblèrent pour un jeûne, revêtus de sacs, avec de la poussière sur la tête.'),
('ne',9,2,'crampon1923','Ceux qui étaient de la race d''Israël, s''étant séparés de tous les fils de l''étranger, se tinrent debout et confessèrent leurs péchés et les iniquités de leurs pères.'),
('ne',9,3,'crampon1923','Lorsqu''ils se furent levés à leur place, ils lurent dans le livre de la loi de Yahweh, leur Dieu, pendant un quart de la journée, et, pendant un autre quart, ils confessèrent leurs péchés et adorèrent Yahweh, leur Dieu.'),
('ne',9,4,'crampon1923','Josué, Bani, Cedmiel, Sabanias, Bonni, Sarébias, Bani et Chanani, étant montés sur l''estrade des lévites, crièrent à haute voix vers Yahweh, leur Dieu.'),
('ne',9,5,'crampon1923','Et les lévites Josué, Cedmiel, Bani, Hasebnias, Sérébias, Odaïas, Sébnias et Phathahias dirent: " Levez-vous, bénissez Yahweh, votre Dieu, d''éternité en éternité! Que l''on bénisse votre nom glorieux, qui est élevé au-dessus de toute bénédiction et de toute louange!'),
('ne',9,6,'crampon1923','C''est vous seul, Yahweh, vous, qui avez fait le ciel, le ciel des cieux et toute leur armée, la terre et tout ce qu''elle porte, la mer et tout ce qu''elle renferme; c''est vous qui donnez la vie à toutes ces choses, et l''armée du ciel vous adore.'),
('ne',9,7,'crampon1923','C''est vous, Yahweh, Dieu, qui avez choisi Abram, qui l''avez fait sortir d''Ur de Chaldée, et qui lui avez donné le nom d''Abraham.'),
('ne',9,8,'crampon1923','Vous avez trouvé son cœur fidèle devant vous et vous avez conclu avec lui l''alliance pour donner à sa postérité le pays des Chananéens, des Héthéens, des Amorhéens, des Phérézéens, des Jébuséens et des Gergeséens; et vous avez tenu votre parole, car vous êtes juste. "'),
('ne',9,9,'crampon1923','" Vous avez vu l''affliction de nos pères en Egypte, et vous avez entendu leurs cris prés de la Mer rouge.'),
('ne',9,10,'crampon1923','Vous avez opéré des signes et des prodiges contre Pharaon, contre tous ses serviteurs et contre tout le peuple de son pays, parce que vous saviez qu''ils avaient agi avec arrogance à l''égard de nos pères et vous vous êtes fait un nom, comme on le voit encore aujourd''hui.'),
('ne',9,11,'crampon1923','Vous avez fendu la mer devant eux, et ils ont passé à sec au milieu de la mer; mais vous avez précipité dans les abîmes, comme une pierre dans les grandes eaux, ceux qui les poursuivaient.'),
('ne',9,12,'crampon1923','Vous les avez guidés le jour par une colonne de nuée, et la nuit par une colonne de feu, pour éclairer devant eux la voie qu''ils devaient suivre.'),
('ne',9,13,'crampon1923','Vous êtes descendu sur la montagne du Sinaï, vous avez parlé avec eux du haut du ciel, et vous leur avez donné des ordonnances justes, des lois de vérité, des préceptes et des commandements excellents.'),
('ne',9,14,'crampon1923','Vous leur avez fait connaître votre saint sabbat, et vous leur avez prescrit par l''organe de Moïse, votre serviteur, des commandements, des préceptes et une loi.'),
('ne',9,15,'crampon1923','Vous leur avez donné du ciel le pain pour leur faim, et vous avez fait sortir du rocher l''eau pour leur soif. Et vous leur avez dit d''entrer en possession du pays que vous aviez juré de leur donner. "'),
('ne',9,16,'crampon1923','" Mais nos pères, eux, se livrèrent à l''orgueil, raidirent leur cou, et n''écoutèrent pas vos commandements.'),
('ne',9,17,'crampon1923','Ils refusèrent d''écouter, et ils ne se souvinrent pas de vos merveilles, que vous aviez faites en leur faveur. Ils raidirent leur cou et, dans leur opiniâtreté, ils se donnèrent un chef pour retourner à leur servitude. Mais vous êtes un Dieu prêt au pardon, clément et miséricordieux, lent à la colère et riche en bonté, et vous ne les avez pas abandonnés.'),
('ne',9,18,'crampon1923','Même lorsqu''ils se firent un veau en fonte et dirent: Voici ton Dieu qui t''a fait sortir d''Egypte, et qu''ils se livrèrent contre vous à de grands blasphèmes,'),
('ne',9,19,'crampon1923','selon votre grande miséricorde, vous ne les avez pas abandonnés dans le désert; et la colonne de nuée ne s''écarta point d''auprès d''eux, les guidant le jour dans leur chemin, ni la colonne de feu, les éclairant la nuit dans la route qu''ils devaient suivre.'),
('ne',9,20,'crampon1923','Vous leur avez donné votre bon esprit pour les rendre prudents; vous n''avez point refusé votre manne à leur bouche, et vous leur avez fourni de l''eau pour leur soif.'),
('ne',9,21,'crampon1923','Pendant quarante ans vous avez pourvu à leur entretien dans le désert, et ils ne manquèrent de rien; leurs vêtements ne s''usèrent point et leurs pieds ne s''enflèrent point. "'),
('ne',9,22,'crampon1923','" Vous leur avez livré des royaumes et des peuples, dont vous partageâtes entre eux les territoires; et ils possédèrent le pays de Séhon, le pays du roi d''Hésébon, et le pays d''Og, roi de Basan.'),
('ne',9,23,'crampon1923','Vous avez multiplié leurs fils comme les étoiles du ciel, et vous les avez amenés dans le pays dont vous aviez dit à leurs pères qu''ils y entreraient pour en prendre possession.'),
('ne',9,24,'crampon1923','Et leurs fils vinrent prendre possession du pays, et vous avez humilié devant eux les habitants du pays, les Chananéens, et vous les avez livrés entre leurs mains, ainsi que les rois et les peuples du pays, pour qu''ils les traitassent à leur gré.'),
('ne',9,25,'crampon1923','Ils s''emparèrent de villes fortifiées et de terres fertiles; ils possédèrent des maisons remplies de toutes sortes de biens, des citernes creusées, des vignes, des oliviers et des arbres fruitiers en abondance. Ils mangèrent, ils se rassasièrent, ils s''engraissèrent et vécurent dans les délices par votre grande bonté. "'),
('ne',9,26,'crampon1923','" Néanmoins ils furent rebelles et se révoltèrent contre vous. Ils jetèrent votre loi derrière leur dos, ils tuèrent vos prophètes qui rendaient témoignage contre eux, pour les ramener vers vous, et ils se livrèrent envers vous à de grands blasphèmes.'),
('ne',9,27,'crampon1923','Alors vous les abandonnâtes entre les mains de leurs oppresseurs, qui les opprimèrent. Mais, au temps de leur oppression, ils crièrent vers vous, et vous, vous les entendîtes du haut du ciel et, dans votre grande miséricorde, vous leur donnâtes des sauveurs qui les sauvèrent de la main de leurs oppresseurs.'),
('ne',9,28,'crampon1923','Quand ils eurent du repos, ils firent de nouveau le mal devant vous, et vous les abandonnâtes entre les mains de leurs ennemis, qui dominèrent sur eux. Mais ils crièrent encore vers vous, et vous, vous les entendîtes du haut du ciel et, dans votre grande miséricorde, vous les délivrâtes plusieurs fois.'),
('ne',9,29,'crampon1923','Vous rendîtes témoignage contre eux, pour les ramener à votre loi, et eux, persévérant dans l''orgueil, n''écoutèrent point vos commandements; ils transgressèrent vos ordonnances, bien que celui qui les met en pratique trouve en elles la vie; ils présentèrent une épaule rebelle, ils raidirent leur cou et ils n''écoutèrent point.'),
('ne',9,30,'crampon1923','Vous usâtes de patience envers eux pendant de nombreuses années; vous rendîtes témoignage contre eux par votre esprit, par l''organe de vos prophètes, et ils n''écoutèrent point. Alors vous les livrâtes entre les mains des peuples des pays.'),
('ne',9,31,'crampon1923','Mais, dans votre grande miséricorde, vous ne les avez pas anéantis et vous ne les avez pas délaissés, car vous êtes un Dieu clément et miséricordieux. "'),
('ne',9,32,'crampon1923','" Et maintenant, ô notre Dieu, Dieu grand, puissant et redoutable, vous qui maintenez l''alliance et la miséricorde, ne regardez pas comme peu de chose toutes les souffrances qui nous ont atteints, nous, nos rois, nos chefs, nos prêtres, nos prophètes, nos pères et tout votre peuple, depuis le temps des rois d''Assyrie jusqu''à ce jour.'),
('ne',9,33,'crampon1923','Vous avez été juste dans tout ce qui nous est arrivé, car vous avez agi avec fidélité; mais nous, nous avons fait le mal.'),
('ne',9,34,'crampon1923','Nos rois, nos chefs, nos prêtres et nos pères n''ont pas mis en pratique votre loi, et ils n''ont été attentifs ni à vos commandements ni aux témoignages que vous rendiez contre eux.'),
('ne',9,35,'crampon1923','Dans leur royaume, au milieu des nombreux bienfaits que vous leur accordiez, dans le pays vaste et fertile que vous leur aviez livré, ils ne vous ont pas servi, et ils ne se sont pas détournés de leurs œuvres mauvaises.'),
('ne',9,36,'crampon1923','Et voici qu''aujourd''hui nous sommes esclaves! Voici que nous sommes esclaves sur la terre que vous avez donnée à nos pères pour en manger les fruits et jouir de ses biens!'),
('ne',9,37,'crampon1923','Elle multiplie ses produits pour les rois que vous avez établis sur nous, à cause de nos péchés. Ils disposent à leur gré de nos corps et de notre bétail, et nous sommes dans une grande détresse. "'),
('ne',10,1,'crampon1923','En conséquence de tout cela, nous contractâmes un engagement sacré que nous mîmes par écrit, et nos chefs, nos lévites et nos prêtres y apposèrent leur sceau.'),
('ne',10,2,'crampon1923','Voici ceux qui apposèrent leur sceau: Néhémie, le gouverneur, fils de Helchias.'),
('ne',10,3,'crampon1923','— Sédécias, Saraïas, Azarias, Jérémie,'),
('ne',10,4,'crampon1923','Phashur, Amarias, Melchias,'),
('ne',10,5,'crampon1923','Hattus, Sébénias, Melluch,'),
('ne',10,6,'crampon1923','Harem, Mérimuth, Abdias,'),
('ne',10,7,'crampon1923','Daniel, Genthon, Baruch,'),
('ne',10,8,'crampon1923','Mosollam, Abias, Miamin,'),
('ne',10,9,'crampon1923','Maazias, Belgaï, Séméïas, prêtres.'),
('ne',10,10,'crampon1923','— Lévites: Josué, fils d''Azanias, Bennui des fils de Hénadad, Cedmiel,'),
('ne',10,11,'crampon1923','et leurs frères, Sébénias, Odaïas, Célita, Phalaïas, Hanan,'),
('ne',10,12,'crampon1923','Micha, Rohob, Hasébias,'),
('ne',10,13,'crampon1923','Zachur, Sérébias, Sabanias,'),
('ne',10,14,'crampon1923','Odaïas, Bani, Baninu.'),
('ne',10,15,'crampon1923','— Chefs du peuple: Pharos, Phahath-Moab, Elam, Zéthu, Bani,'),
('ne',10,16,'crampon1923','Bonni, Azgad, Bébaï,'),
('ne',10,17,'crampon1923','Adonias, Bégoai, Adin,'),
('ne',10,18,'crampon1923','Ater, Ezéchias, Azur,'),
('ne',10,19,'crampon1923','Odaïas, Hasum, Besaï,'),
('ne',10,20,'crampon1923','Hareph, Anathoth, Nébaï,'),
('ne',10,21,'crampon1923','Megphias, Mosollam, Hazir,'),
('ne',10,22,'crampon1923','Mésizabel, Sadoc, Jeddua,'),
('ne',10,23,'crampon1923','Pheltias, Hanan, Anaïas,'),
('ne',10,24,'crampon1923','Osée, Ananie, Hassub,'),
('ne',10,25,'crampon1923','Alohès, Phaléa, Sobec,'),
('ne',10,26,'crampon1923','Réhum, Hasebna, Maasias,'),
('ne',10,27,'crampon1923','Echias, Hanan, Anan,'),
('ne',10,28,'crampon1923','Melluch, Harim, Baana.'),
('ne',10,29,'crampon1923','Le reste du peuple, les prêtres, les lévites, les portiers, les chantres, les Nathinéens, et tous ceux qui s''étaient séparés des peuples des pays pour suivre la loi de Dieu, leurs femmes, leurs fils et leurs filles, tous ceux qui étaient capables de connaissance et d''intelligence,'),
('ne',10,30,'crampon1923','s''attachèrent à leurs frères, leurs nobles, promirent avec imprécation et serment de marcher dans la loi de Dieu, qui avait été donnée par l''organe de Moïse, serviteur de Dieu, d''observer et de mettre en pratique tous les commandements de Yahweh, notre Seigneur, ses ordonnances et ses lois.'),
('ne',10,31,'crampon1923','Nous promîmes, en particulier, que nous ne donnerions pas nos filles aux peuples du pays, et que nous ne prendrions pas leurs filles pour nos fils;'),
('ne',10,32,'crampon1923','que, si les peuples du pays apportaient à vendre, le jour du sabbat, des marchandises ou denrées quelconques, nous ne leur achèterions rien le jour du sabbat et les jours de fête; que nous laisserions reposer la terre la septième année, et que nous n''exigerions le paiement d''aucune dette.'),
('ne',10,33,'crampon1923','Nous nous imposâmes l''obligation de payer un tiers de sicle chaque année pour le service de la maison de Dieu,'),
('ne',10,34,'crampon1923','pour les pains de proposition, pour l''oblation perpétuelle, pour l''holocauste perpétuel, pour les sacrifices des sabbats, des néoménies, pour les fêtes, pour les choses consacrées, pour les sacrifices pour le péché, afin de faire expiation en faveur d''Israël, et pour tout ce qui se fait dans la maison de notre Dieu.'),
('ne',10,35,'crampon1923','Nous tirâmes au sort, prêtres, lévites et peuple, au sujet de l''offrande du bois, afin qu''on l''apportât à la maison de notre Dieu, chacune de nos familles à son tour, à des époques déterminées, d''année en année, pour qu''on le brûle sur l''autel de Yahweh, notre Dieu, comme il est écrit dans la loi.'),
('ne',10,36,'crampon1923','Nous prîmes l''engagement d''apporter chaque année à la maison de Yahweh les prémices de notre sol et les prémices de tous les fruits de tous les arbres;'),
('ne',10,37,'crampon1923','d''amener à la maison de notre Dieu, aux prêtres qui font le service dans la maison de notre Dieu, les premiers-nés de nos fils et de notre bétail, comme il est écrit dans la loi, et les premiers-nés de nos bœufs et de nos brebis.'),
('ne',10,38,'crampon1923','De même, que nous apporterions aux prêtres, dans les chambres de la maison de notre Dieu, les prémices de notre pâte, et nos offrandes prélevées, ainsi que des fruits de tous les arbres, du vin nouveau et de l''huile; et que nous livrerions la dîme de notre sol aux lévites. Et les lévites eux-mêmes lèveront la dîme dans toutes les villes voisines de nos cultures.'),
('ne',10,39,'crampon1923','Le prêtre, fils d''Aaron, sera avec les lévites quand les lévites lèveront la dîme, et les lévites apporteront la dîme de la dîme à la maison de notre Dieu, dans les chambres de la maison du trésor.'),
('ne',10,40,'crampon1923','Car les enfants d''Israël et les fils de Lévi apporteront dans les chambres l''offrande du blé, du vin nouveau et de l''huile; là sont les ustensiles du sanctuaire, et se tiennent les prêtres qui font le service, les portiers et les chantres. Ainsi nous ne négligerons pas la maison de notre Dieu.'),
('ne',11,1,'crampon1923','Les chefs du peuple s''établirent à Jérusalem. Le reste du peuple tira au sort, pour qu''un sur dix vînt habiter Jérusalem, la ville sainte, les neuf autres parties restant dans les autres villes.'),
('ne',11,2,'crampon1923','Le peuple bénit tous ceux qui se décidèrent d''eux-mêmes à résider à Jérusalem.'),
('ne',11,3,'crampon1923','Voici les chefs de famille de la province qui s''établirent à Jérusalem. Dans les villes de Juda, chacun s''établit dans sa propriété, dans sa ville: Israël, les prêtres et les lévites, les Nathinéens et les fils des serviteurs de Salomon:'),
('ne',11,4,'crampon1923','A Jérusalem s''établirent des fils de Juda et des fils de Benjamin. — Des fils de Juda: Athaïas, fils d''Aziam, fils de Zacharie, fils d''Amarias, fils de Saphatias, fils de Malaléel, des fils de Pharès;'),
('ne',11,5,'crampon1923','et Maasias, fils de Baruch, fils de Cholhoza, fils de Hazias, fils d''Adaïas, fils de Joïarib, fils de Zacharie, fils de Séla.'),
('ne',11,6,'crampon1923','Total des fils de Pharès qui s''établirent à Jérusalem: quatre cent soixante-huit hommes vaillants.'),
('ne',11,7,'crampon1923','— Voici les fils de Benjamin: Sellum, fils de Mosollam, fils de Joëd, fils de Phadaïas, fils de Colaïas, fils de Maasias, fils d''Ethéel, fils d''Isaïe,'),
('ne',11,8,'crampon1923','et après lui Gebbaï-Sellaï: neuf cent vingt-huit.'),
('ne',11,9,'crampon1923','Joël, fils de Zéchri, était leur chef, et Juda, fils de Sénua, était le second chef de la ville.'),
('ne',11,10,'crampon1923','Des prêtres: Idaïas, fils de Joïarib, Jachin,'),
('ne',11,11,'crampon1923','Saraïas, fils de Helcias, fils de Mosollam, fils de Sadoc, fils de Méraïoth, fils d''Achitob, prince de la maison de Dieu,'),
('ne',11,12,'crampon1923','et leurs frères qui faisaient le travail dans la maison: huit cent vingt-deux; Adaïas, fils de Jéroham, fils de Phéléias, fils d''Amsi, fils de Zacharie, fils de Phashur, fils de Melchias,'),
('ne',11,13,'crampon1923','et ses frères, chefs de famille: deux cent quarante-deux; et Amassaï, fils d''Azréel, fils d''Ahazi, fils de Mosollamoth, fils d''Emmer,'),
('ne',11,14,'crampon1923','et leurs frères, hommes vaillants: cent vingt-huit. Zabdiel, fils de Hagdolim, était leur chef.'),
('ne',11,15,'crampon1923','Des lévites: Séméïas, fils de Hasub, fils d''Azaricam, fils de Hasabias, fils de Boni;'),
('ne',11,16,'crampon1923','Sabathaï et Jozabed, chargés des affaires extérieures de la maison de Dieu, du nombre des chefs des lévites;'),
('ne',11,17,'crampon1923','Mathanias, fils de Micha, fils de Zébédéi, fils d''Asaph, le chef qui entonnait le chant de louange à la prière; Becbécias, le second parmi ses frères, et Abda, fils de Samua, fils de Galal, fils d''Idithun.'),
('ne',11,18,'crampon1923','Total des lévites dans la ville sainte: deux cent quatre-vingt-quatre.'),
('ne',11,19,'crampon1923','Et les portiers: Accub, Telmon et leurs frères, gardiens des portes: cent soixante-douze.'),
('ne',11,20,'crampon1923','Le reste d''Israël, les prêtres, les lévites, étaient dans toutes les autres villes de Juda, chacun dans sa propriété.'),
('ne',11,21,'crampon1923','Les Nathinéens, s''établirent dans le quartier d''Ophel; Siha et Gaspha étaient préposés aux Nathinéens.'),
('ne',11,22,'crampon1923','Le chef des lévites à Jérusalem était Azzi, fils de Bani, fils de Hasabias, fils de Mathanias, fils de Micha, d''entre les fils d''Asaph, les chantres chargés du service de la maison de Dieu.'),
('ne',11,23,'crampon1923','Car il y avait une ordonnance du roi à leur sujet, et un salaire déterminé était accordé aux chantres pour chaque jour.'),
('ne',11,24,'crampon1923','Phathahias, fils de Mésézébel, d''entre les fils de Zara, fils de Juda, était commissaire du roi pour toutes les affaires du peuple.'),
('ne',11,25,'crampon1923','Quant aux villages et à leurs territoires, des fils de Juda s''établirent: à Cariath-Arbé et dans les villes de sa dépendance, à Dibon et dans les villes de sa dépendance, à Cabséel et dans ses villages,'),
('ne',11,26,'crampon1923','à Jésué, à Molada, à Beth-Phalet,'),
('ne',11,27,'crampon1923','à Hasersual, à Bersabée et dans les villes de sa dépendance,'),
('ne',11,28,'crampon1923','à Siceleg, à Mochona, et dans les villes de sa dépendance,'),
('ne',11,29,'crampon1923','à En-Remmon, à Saraa, à Jérimuth,'),
('ne',11,30,'crampon1923','à Zanoé, à Odollam et dans leurs villages, à Lachis et dans son territoire, à Azéca et dans les villes de sa dépendance. Ils s''établirent depuis Bersabée jusqu''à la vallée d''Ennom.'),
('ne',11,31,'crampon1923','Des fils de Benjamin s''établirent depuis Geba, à Machmas, à Haï, à Béthel et dans les villes de sa dépendance,'),
('ne',11,32,'crampon1923','à Anathoth, à Nob, à Anania,'),
('ne',11,33,'crampon1923','à Asor, à Rama, à Géthaïm,'),
('ne',11,34,'crampon1923','à Hadid, à Séboïm, à Néballat,'),
('ne',11,35,'crampon1923','à Lod et à Ono, dans la Vallée des Ouvriers.'),
('ne',11,36,'crampon1923','Il y eut, parmi les lévites, des classes appartenant à Juda qui se joignirent à Benjamin.'),
('ne',12,1,'crampon1923','Voici les prêtres et les lévites qui revinrent avec Zorobabel, fils de Salathiel, et avec Josué: Saraïas, Jérémie, Esdras,'),
('ne',12,2,'crampon1923','Amarias, Melluch, Hattus,'),
('ne',12,3,'crampon1923','Sechénias, Réhum, Mérimuth,'),
('ne',12,4,'crampon1923','Addo, Genthon, Abias,'),
('ne',12,5,'crampon1923','Miamin, Maadias, Belga,'),
('ne',12,6,'crampon1923','Seméïas, Joïarib, Idaïas,'),
('ne',12,7,'crampon1923','Sellum, Amoc, Helcias, Idaïas. Ce furent là les chefs des prêtres et de leurs frères au temps de Josué.'),
('ne',12,8,'crampon1923','Lévites: Josué, Bennui, Cedmiel, Sarébias, Juda, Mathanias, qui était préposé, avec ses frères, au chant des louanges;'),
('ne',12,9,'crampon1923','Becbécias et Hanni, leurs frères, formaient dans le service le chœur opposé.'),
('ne',12,10,'crampon1923','Josué engendra Joakim, Joakim engendra Eliasib, Eliasib engendra Joïada,'),
('ne',12,11,'crampon1923','Joïada engendra Jonathan, et Jonathan engendra Jeddoa.'),
('ne',12,12,'crampon1923','Voici quels étaient, au temps de Joakim, les prêtres, chefs de famille: pour Saraïas, Maraïas; pour Jérémie, Ananie;'),
('ne',12,13,'crampon1923','pour Esdras, Mosollam; pour Amarias, Johanan;'),
('ne',12,14,'crampon1923','pour Milicho, Jonathan; pour Sébénias, Joseph;'),
('ne',12,15,'crampon1923','pour Haram, Edna; pour Maraïoth, Helci;'),
('ne',12,16,'crampon1923','pour Addo, Zacharie; pour Genthon, Mosollam;'),
('ne',12,17,'crampon1923','pour Abias, Zéchri; pour Miamin et Moadias, Phelti;'),
('ne',12,18,'crampon1923','pour Belga, Sammua; pour Séméias, Jonathan;'),
('ne',12,19,'crampon1923','pour Joïarib, Mathanaï; pour Jodaïas, Azzi;'),
('ne',12,20,'crampon1923','pour Sellaï, Célaï; pour Amoc, Héber;'),
('ne',12,21,'crampon1923','pour Helcias, Hasébias; pour Idaïas, Nathanaël.'),
('ne',12,22,'crampon1923','Au temps d''Eliasib, de Joiada, de Johanan et de Jeddoa, les lévites, chefs de famille, et les prêtres furent inscrits, sous le règne de Darius, le Perse.'),
('ne',12,23,'crampon1923','Les fils de Lévi, chefs de famille, furent inscrits dans le livre des Chroniques, jusqu''au temps de Johanan, fils d''Eliasib.'),
('ne',12,24,'crampon1923','Chefs des lévites: Hasébias, Sérébias et Josué, fils de Cedmiel, chargés, avec leurs frères en face d''eux, de célébrer et de louer Dieu, selon l''ordre de David, homme de Dieu, un groupe alternant avec l''autre groupe.'),
('ne',12,25,'crampon1923','Mathanias, Becbécias, Abdias, Mosollam, Telmon et Accub, portiers, faisaient la garde au seuil des portes.'),
('ne',12,26,'crampon1923','Ils vivaient au temps de Joakim, fils de Josué, fils de Josédec, et au temps de Néhémie, le gouverneur, et d''Esdras, le prêtre et le scribe.'),
('ne',12,27,'crampon1923','Lors de la dédicace des murailles de Jérusalem, on convoqua les lévites de tous les lieux qu''ils habitaient, pour les faire venir à Jérusalem, afin de célébrer la dédicace avec joie, avec des louanges et des chants, au son des cymbales, des cithares et des harpes.'),
('ne',12,28,'crampon1923','Les fils des chantres se rassemblèrent de la campagne environnant Jérusalem, des villages des Nétophatiens,'),
('ne',12,29,'crampon1923','de Beth-Galgal et du territoire de Géba et d''Azmaveth; car les chantres s''étaient bâti des villages aux alentours de Jérusalem.'),
('ne',12,30,'crampon1923','Les prêtres et les lévites, après s''être purifiés, purifièrent le peuple, les portes et la muraille.'),
('ne',12,31,'crampon1923','Je fis monter sur la muraille les princes de Juda, et je formai deux grands chœurs de procession. Le premier chœur se mit en marche vers le côté droit, sur la muraille, vers la porte du Fumier.'),
('ne',12,32,'crampon1923','Derrière eux marchaient Osaïas et la moitié des princes de Juda,'),
('ne',12,33,'crampon1923','Azarias, Esdras, Mosollam,'),
('ne',12,34,'crampon1923','Juda, Benjamin, Séméïas et Jérémie;'),
('ne',12,35,'crampon1923','des fils de prêtres avec des trompettes, Zacharie, fils de Jonathan, fils de Séméïas, fils de Mathanias, fils de Michée, fils de Zéchur, fils d''Asaph,'),
('ne',12,36,'crampon1923','et ses frères, Séméïas, Azaréel, Malalaï, Galalaï, Maaï, Nathanaël, Juda et Hanani, avec les instruments de musique de David, homme de Dieu. Esdras, le scribe, était devant eux.'),
('ne',12,37,'crampon1923','A la porte de la Source, ils montèrent vis-à-vis d''eux les degrés de la cité de David, par la montée de la muraille, au-dessus de la maison de David, jusqu''à la porte de l''Eau, vers l''orient.'),
('ne',12,38,'crampon1923','Le second chœur se mit en marche du côté opposé; j''étais derrière lui, avec l''autre moitié du peuple, sur la muraille. D''au-dessus de la tour des Fourneaux, on alla jusqu''à la muraille large;'),
('ne',12,39,'crampon1923','puis, d''au dessus de la porte d''Ephraïm, de la Vieille porte, de la porte des Poissons, de la tour de Hananéel et de la tour de Méa, jusqu''à la porte des Brebis; et l''on s''arrêta à la porte de la Prison.'),
('ne',12,40,'crampon1923','Les deux chœurs s''arrêtèrent dans la maison de Dieu, ainsi que moi et la moitié des magistrats qui étaient avec moi,'),
('ne',12,41,'crampon1923','et les prêtres Eliacim, Maasias, Miamin, Michée, Elioénaï, Zacharie, Ananie, avec des trompettes,'),
('ne',12,42,'crampon1923','et Maasias, Séméïas, Eléazar, Azzi, Johanan, Melchias, Elam et Ezer. Et les chantres se firent entendre, avec Jezraïas, leur chef.'),
('ne',12,43,'crampon1923','Ils offrirent ce jour-là de grands sacrifices et se livrèrent aux réjouissances, car Dieu leur avait donné un grand sujet de joie. Les femmes et les enfants se réjouirent aussi, et les cris de joie de Jérusalem furent entendus au loin.'),
('ne',12,44,'crampon1923','En ce temps-là, on établit des hommes préposés aux chambres qui servaient de magasins pour les offrandes prélevées, les prémices et les dîmes, et on les chargea d''y recueillir, du territoire des villes, les portions assignées par la loi aux prêtres et aux lévites; car Juda se réjouissait de voir à leur poste les prêtres et les lévites,'),
('ne',12,45,'crampon1923','observant le service de leur Dieu, et le service des purifications; et de même, les chantres et les portiers, selon l''ordonnance de David et de Salomon, son fils.'),
('ne',12,46,'crampon1923','Car autrefois, dans les jours de David et d''Asaph, le chef des chantres, il y avait des chants de louange et d''actions de grâces en l''honneur de Dieu.'),
('ne',12,47,'crampon1923','Tout Israël, dans les jours de Zorobabel et de Néhémie, donnait jour par jour les portions des chantres et des portiers; on donnait aux lévites les saintes offrandes, et les lévites en donnaient leur part aux fils d''Aaron.'),
('ne',13,1,'crampon1923','En ce temps-là, on lut aux oreilles du peuple dans le livre de Moïse, et l''on y trouva écrit que l''Ammonite et le Moabite ne devaient jamais entrer dans l''assemblée de Dieu,'),
('ne',13,2,'crampon1923','parce qu''ils n''étaient pas venus au-devant des enfants d''Israël avec du pain et de l''eau, et parce qu''ils avaient payé contre eux Balaam pour qu''il les maudit; mais notre Dieu avait changé la malédiction en bénédiction.'),
('ne',13,3,'crampon1923','Lorsqu''on eut entendu cette loi, on sépara d''Israël tous les étrangers.'),
('ne',13,4,'crampon1923','Avant cela, le prêtre Eliasib, qui avait l''intendance des chambres de la maison de notre Dieu et qui était allié de Tobie,'),
('ne',13,5,'crampon1923','avait disposé pour ce dernier une grande chambre où l''on mettait auparavant les offrandes, l''encens, les ustensiles, la dîme du blé, du vin nouveau et de l''huile, la taxe des lévites, des chantres et des portiers, et ce qui était prélevé pour les prêtres.'),
('ne',13,6,'crampon1923','Quand tout cela eut lieu, je n''étais point à Jérusalem; car, la trente deuxième année d''Artaxerxès, roi de Babylone, j''étais retourné près du roi. Au bout de quelque temps, j''obtins du roi la permission'),
('ne',13,7,'crampon1923','de revenir à Jérusalem, et je m''aperçus du mal qu''avait fait Eliasib, en faveur de Tobie, en arrangeant une chambre pour lui dans les parvis de la maison de Dieu.'),
('ne',13,8,'crampon1923','J''en éprouvai une grande douleur, et je jetai hors de la chambre tous les meubles de la demeure de Tobie.'),
('ne',13,9,'crampon1923','Puis j''ordonnai qu''on purifiât les chambres, et j''y replaçai les ustensiles de la maison de Dieu, les offrandes et l''encens.'),
('ne',13,10,'crampon1923','J''appris aussi que les portions des lévites n''avaient pas été livrées, et que les lévites et les chantres chargés du service s''étaient enfuis chacun dans ses terres.'),
('ne',13,11,'crampon1923','J''adressai des réprimandes aux magistrats, et je dis: " Pourquoi la maison de Dieu est-elle abandonnée? " Et je rassemblai les lévites et les chantres, et je les remis à leur poste.'),
('ne',13,12,'crampon1923','Alors tout Juda apporta dans les magasins la dîme du blé, du vin nouveau et de l''huile.'),
('ne',13,13,'crampon1923','Je confiai l''intendance des magasins à Sélémias, le prêtre, à Sadoc, le scribe, et à Phadaïas, l''un des lévites, et je leur adjoignis Hanan, fils de Zachur, fils de Mathanias, parce qu''ils étaient reconnus fidèles. C''était à eux de faire les distributions à leurs frères.'),
('ne',13,14,'crampon1923','Souvenez-vous de moi, ô mon Dieu, à cause de cela, et n''effacez pas de votre mémoire les actes de piété que j''ai faits pour la maison de Dieu et pour son service!'),
('ne',13,15,'crampon1923','En ce temps là, je vis en Juda des hommes qui foulaient au pressoir pendant le sabbat, qui rentraient des gerbes, chargeaient sur des ânes même du vin, des raisins, des figues et toutes sortes de fardeaux, et qui les amenaient à Jérusalem le jour du sabbat; et je leur donnai un avertissement lorsqu''ils vendaient leurs denrées.'),
('ne',13,16,'crampon1923','De même les Tyriens demeurant à Jérusalem, apportaient du poisson et toutes sortes de marchandises, et les vendaient, le jour du sabbat, aux fils de Juda et dans Jérusalem.'),
('ne',13,17,'crampon1923','J''adressai des réprimandes aux grands de Juda et je leur dis: " Quelle est cette mauvaise action que vous faites, en profanant le jour du sabbat?'),
('ne',13,18,'crampon1923','N''est-ce pas ainsi qu''ont agi vos pères, et n''est-ce pas à cause de cela que notre Dieu a fait venir tous ces malheurs sur nous et sur cette ville? Et vous, vous augmentez encore sa colère contre Israël en profanant le sabbat!... "'),
('ne',13,19,'crampon1923','Ensuite, dès qu''il fit sombre aux entrées de Jérusalem, avant le sabbat, j''ordonnai de fermer les portes, et j''ordonnai qu''on ne les ouvrit qu''après le sabbat. De plus, je plaçai aux portes quelques-uns de mes gens afin qu''aucun fardeau n''entrât le jour du sabbat.'),
('ne',13,20,'crampon1923','Alors les marchands et les vendeurs de toutes sortes de denrées passèrent la nuit une fois ou deux hors de Jérusalem.'),
('ne',13,21,'crampon1923','Je les avertis, et je leur dis: " Pourquoi passez-vous la nuit devant la muraille? Si vous le faites encore, je mettrai la main sur vous. " Depuis ce temps-là, ils ne vinrent plus pendant le sabbat.'),
('ne',13,22,'crampon1923','Et j''ordonnai aux lévites de se purifier et de venir garder les portes pour sanctifier le jour du sabbat. Souvenez-vous encore de moi, ô mon Dieu, à cause de cela, et épargnez-moi selon votre grande miséricorde!'),
('ne',13,23,'crampon1923','En ce même temps, je vis aussi des Juifs qui avaient établi chez eux des femmes azotiennes, ammonites, moabites.'),
('ne',13,24,'crampon1923','La moitié de leurs fils parlaient l''azotien sans pouvoir parler judéen; et de même pour la langue de tel et tel autre peuple.'),
('ne',13,25,'crampon1923','Je leur adressai des réprimandes et je les maudis; j''en frappai plusieurs, je leur arrachai les cheveux et je les adjurai au nom de Dieu, en disant: " Vous ne donnerez point vos filles à leurs fils et vous ne prendrez point de leurs filles pour vos fils ou pour vous.'),
('ne',13,26,'crampon1923','N''est-ce pas en cela qu''a péché Salomon, roi d''Israël? Il n''y avait pas de roi semblable à lui parmi la multitude des nations, il était aimé de son Dieu et Dieu l’avait établi roi sur tout Israël; mais les femmes étrangères l''entraînèrent, lui aussi, dans le péché.'),
('ne',13,27,'crampon1923','Fallait-il donc apprendre à votre sujet que vous commettez ce grand crime et que vous péchez contre notre Dieu, en établissant chez vous des femmes étrangères? "'),
('ne',13,28,'crampon1923','Un des fils de Joïada, fils d''Eliasib, le grand prêtre, était gendre de Sanaballat le Horonite; je le chassai loin de moi.'),
('ne',13,29,'crampon1923','Souvenez-vous d''eux, ô mon Dieu, à propos de cette profanation du sacerdoce et des obligations sacrées des prêtres et des lévites!'),
('ne',13,30,'crampon1923','Je les purifiai de tout ce qui était étranger, et je remis en vigueur les règlements concernent les prêtres et les lévites, chacun dans son ministère,'),
('ne',13,31,'crampon1923','et ce qui concernait l''offrande du bois à des époques déterminées, ainsi que les prémices. Souvenez-vous-en en ma faveur, ô mon Dieu, pour mon bien!'),
('tb',1,1,'crampon1923','Tobie, de la tribu et d''une ville de Nephthali, qui est dans la Galilée supérieure, au-dessus de Naasson, derrière le chemin qui va au couchant, ayant à gauche la ville de Séphet,'),
('tb',1,2,'crampon1923','fut emmené captif au temps de Salmanasar, roi des Assyriens; et, dans sa captivité même, il n''abandonna pas le chemin de la vérité.'),
('tb',1,3,'crampon1923','Tous les jours, il distribuait à ses frères, ceux de sa nation, captifs comme lui, tout ce dont il pouvait disposer.'),
('tb',1,4,'crampon1923','Et alors même qu''il était le plus jeune de ceux de la tribu de Nephthali, il n''y avait rien de juvénile en sa conduite.'),
('tb',1,5,'crampon1923','Aussi, tandis que tout le monde allait adorer les veaux d''or que Jéroboam, roi d''Israël, avait faits, lui seul fuyait la compagnie de tous,'),
('tb',1,6,'crampon1923','et il se rendait à Jérusalem, au temple du Seigneur où il adorait le Seigneur, Dieu d''Israël, offrant fidèlement les prémices et les dîmes de ses biens.'),
('tb',1,7,'crampon1923','Tous les trois ans, il distribuait aux prosélytes et aux étrangers toute sa dîme.'),
('tb',1,8,'crampon1923','Il observait ces choses et d''autres semblables, selon la loi de Dieu, dès son jeune âge.'),
('tb',1,9,'crampon1923','Parvenu à l''âge d''homme, il épousa une femme de sa tribu, nommée Anne; et il en eut un fils auquel il donna son nom,'),
('tb',1,10,'crampon1923','et qu''il instruisit dès l''enfance à craindre Dieu et à s''abstenir de tout péché.'),
('tb',1,11,'crampon1923','Lors donc qu''il fut arrivé comme captif, avec sa femme et son fils, en la ville de Ninive, où était toute sa tribu,'),
('tb',1,12,'crampon1923','bien que tous les autres mangeassent des mets des païens, il garda son âme pure, et jamais il ne se souilla par leurs viandes.'),
('tb',1,13,'crampon1923','Et parce qu''il se souvenait fidèlement du Seigneur, Dieu lui concilia la faveur du roi Salmanasar,'),
('tb',1,14,'crampon1923','qui lui donna pouvoir d''aller partout où il voudrait, avec liberté de faire ce qu''il lui plairait.'),
('tb',1,15,'crampon1923','Il allait donc visiter tous ceux qui étaient captifs et leur donnait des conseils salutaires.'),
('tb',1,16,'crampon1923','Etant une fois allé à Ragès, ville des Mèdes, avec dix talents, provenant des largesses dont le roi l''avait enrichi,'),
('tb',1,17,'crampon1923','il vit, parmi le grand nombre de ses compatriotes, un homme de sa tribu, nommé Gabélus, qui était dans le besoin, et il lui donna contre un reçu cette somme d''argent.'),
('tb',1,18,'crampon1923','Longtemps après, le roi Salmanasar étant mort, Sennachérib, son fils, régna à sa place. Comme ce prince avait une grande haine contre les enfants d''Israël,'),
('tb',1,19,'crampon1923','Tobie allait visiter chaque jour tous ceux de sa parenté; il les consolait et distribuait de ses biens à chacun, selon son pouvoir;'),
('tb',1,20,'crampon1923','il donnait à manger à ceux qui avaient faim, procurait des vêtements à ceux qui étaient nus et mettait un grand zèle à donner la sépulture à ceux qui étaient morts ou qui avaient été tués.'),
('tb',1,21,'crampon1923','Lorsque le roi Sennachérib, revenu de Judée en fugitif, après la défaite dont Dieu l''avait frappé pour ses blasphèmes, faisait mettre à mort, dans sa fureur, un grand nombre des enfants d''Israël, Tobie enterrait les cadavres.'),
('tb',1,22,'crampon1923','La nouvelle en ayant été apportée au roi, il ordonna de le mettre à mort et lui ôta tous ses biens. Mais Tobie prit la fuite avec son fils et sa femme, et, dépouillé de tout, il réussit à se cacher, parce qu''il avait beaucoup d''amis. Quarante-cinq jours après, le roi fut tué par ses propres fils. Alors Tobie revint dans sa maison, et tous ses biens lui furent rendus.'),
('tb',2,1,'crampon1923','Après cela, une fête du Seigneur étant venue, et un grand repas ayant été préparé dans la maison de Tobie,'),
('tb',2,2,'crampon1923','il dit à son fils: " Va et amène quelques hommes de notre tribu, craignant Dieu, afin qu''ils mangent avec nous. "'),
('tb',2,3,'crampon1923','Son fils partit; à son retour, il lui annonça qu''un des enfants d''Israël, qu''on avait assassiné, gisait dans la rue. A l''instant, Tobie se leva de table et, laissant là le repas sans avoir rien mangé, arriva au cadavre,'),
('tb',2,4,'crampon1923','le prit et le rapporta secrètement à sa maison, afin de l''inhumer avec précaution après le coucher du soleil.'),
('tb',2,5,'crampon1923','Lorsqu''il l''eut caché, il prit son repas avec larmes et tremblement,'),
('tb',2,6,'crampon1923','au souvenir de cette parole que le Seigneur avait dite par le prophète Amos: " Vos jours de fêtes seront changés en gémissements et en deuil. "'),
('tb',2,7,'crampon1923','Puis, quand le soleil fut couché, il sortit et mit le corps en terre.'),
('tb',2,8,'crampon1923','Tous ses voisins le blâmaient en disant: " On a déjà ordonné de te faire mourir pour ce sujet, et à peine as-tu échappé à cet arrêt de mort, que tu recommences à donner aux morts la sépulture! "'),
('tb',2,9,'crampon1923','Mais Tobie, craignant plus Dieu que le roi, enlevait les corps de ceux qui avaient été tués, les cachait dans sa maison et les inhumait pendant la nuit.'),
('tb',2,10,'crampon1923','Un jour qu''il s''était fatigué à donner la sépulture aux morts, étant rentré à sa maison, il se jeta au pied de la muraille et s''endormit.'),
('tb',2,11,'crampon1923','Pendant qu''il dormait, il tomba d''un nid d''hirondelles de la fiente chaude sur ses yeux, et il devint aveugle.'),
('tb',2,12,'crampon1923','Dieu permit que cette épreuve lui arrivât, afin que sa patience, comme celle du saint homme Job, fût donnée en exemple à la postérité.'),
('tb',2,13,'crampon1923','Car, ayant toujours craint Dieu dès son enfance et observé ses commandements, il ne s''attrista pas contre Dieu de ce que le malheur de la cécité l''avait atteint.'),
('tb',2,14,'crampon1923','Mais il resta inébranlable dans la crainte de Dieu, lui rendant grâces tous les jours de sa vie. De même que les chefs de tribu insultaient au bienheureux Job, ainsi les parents et les amis de Tobie raillaient sa conduite, en disant: " Qu''est devenue ton espérance, pour laquelle tu faisais des aumônes et donnais la sépulture aux morts? " Tobie les reprenait en disant: " Ne parlez pas ainsi; car nous sommes enfants des saints, et nous attendons cette vie que Dieu doit donner à ceux qui ne lui retirent jamais leur fidélité. " Anne, sa femme, allait tous les jours tisser de la toile et, par le travail de ses mains, elle rapportait, pour leur entretien, ce qu''elle pouvait gagner. Il arriva ainsi qu''ayant reçu un chevreau, elle l''apporta à la maison. Son mari, ayant entendu le bêlement du chevreau dit: " Voyez si ce chevreau n''aurait pas été dérobé, et rendez-le à son maître, car il ne nous est pas permis de rien manger qui provienne d''un vol, ni même d''y toucher. " Alors sa femme répondit avec colère: " Il est manifeste que ton espérance est devenue vaine; voilà ce que t''ont rapporté tes aumônes! " C''est par ces discours et d''autres semblables qu''elle l''injuriait.'),
('tb',3,1,'crampon1923','Alors Tobie, ayant poussé un soupir, commença à prier avec larmes,'),
('tb',3,2,'crampon1923','en disant: " Vous êtes juste, Seigneur; justes sont tous vos jugements, et toutes vos voies sont miséricorde, vérité et justice.'),
('tb',3,3,'crampon1923','Et maintenant, Seigneur, souvenez-vous de moi; ne tirez pas vengeance de mes péchés, et ne rappelez pas en votre mémoire mes offenses, ou celles de mes ancêtres.'),
('tb',3,4,'crampon1923','Car nous n''avons pas obéi à vos préceptes; c''est pourquoi nous avons été livrés au pillage, à la captivité, à la mort, à la risée et à l''opprobre parmi toutes les nations au sein desquelles vous nous avez dispersés.'),
('tb',3,5,'crampon1923','Et maintenant, Seigneur, vos châtiments sont grands, parce que nous n''avons pas agi selon vos préceptes et que nous n''avons pas marché sincèrement devant vous.'),
('tb',3,6,'crampon1923','Et maintenant, Seigneur, traitez-moi selon votre volonté, et commandez que mon esprit soit reçu en paix, car il est meilleur pour moi de mourir que de vivre. "'),
('tb',3,7,'crampon1923','Il arriva en ce même jour, à Ecbatane, ville des Mèdes, que Sara, fille de Raguel, entendit, elle aussi, les injures d''une des servantes de son père.'),
('tb',3,8,'crampon1923','Car elle avait été successivement donnée en mariage à sept maris, et un démon, nommé Asmodée, les avait fait mourir aussitôt qu''ils étaient venus auprès d''elle.'),
('tb',3,9,'crampon1923','Comme elle reprenait donc cette servante pour quelque faute, celle-ci lui répondit en disant: " Que jamais nous ne voyions sur la terre ni fils ni fille de toi, meurtrière de tes maris.!'),
('tb',3,10,'crampon1923','Veux-tu donc me donner aussi la mort, comme tu as déjà fait mourir sept maris? " A cette parole, Sara monta dans la chambre haute de sa maison et y resta trois jours et trois nuits, sans boire ni manger.'),
('tb',3,11,'crampon1923','Mais, persévérant dans la prière, elle suppliait Dieu avec larmes de la délivrer de cet opprobre.'),
('tb',3,12,'crampon1923','Le troisième jour, elle acheva sa prière et bénit le Seigneur,'),
('tb',3,13,'crampon1923','en disant: " Béni soit votre nom, ô Dieu de nos pères, qui, lors même que vous êtes irrité, faites miséricorde, et qui, au temps de la tribulation, pardonnez les péchés à ceux qui vous invoquent.'),
('tb',3,14,'crampon1923','Vers vous, Seigneur, je tourne mon visage, vers vous j''élève mes yeux.'),
('tb',3,15,'crampon1923','Je vous demande, Seigneur, de me délivrer des liens de cet opprobre; sinon, de me retirer de cette terre.'),
('tb',3,16,'crampon1923','Vous savez, Seigneur, que je n''ai jamais désiré un mari, et que j''ai conservé mon âme pure de toute concupiscence.'),
('tb',3,17,'crampon1923','Jamais je n''ai fréquenté les jeux folâtres et n''ai eu de commerce avec les hommes de conduite légère. C''est dans votre crainte, et non pour suivre ma passion, que j''ai consenti à prendre un mari. Ou bien je n''étais pas digne d''eux, ou bien peut-être n''étaient-ils pas dignes de moi, car il se pourrait que vous m''ayez conservée pour un autre époux. Il n''est pas au pouvoir de l''homme de pénétrer vos desseins. Mais quiconque vous honore tient pour assuré que sa vie, si elle a été dans l''épreuve, sera couronnée, que s''il a été dans la tribulation, il sera délivré, et que si le châtiment est venu sur lui, il pourra obtenir votre miséricorde. Car vous ne prenez point plaisir à notre perte, mais après la tempête vous ramenez le calme, et après les pleurs et les larmes vous répandez la joie. Que votre nom, Dieu d''Israël, soit béni dans tous les siècles! " Ces deux supplications furent exaucées en même temps devant la gloire du Dieu souverain; et le saint ange du Seigneur, Raphaël, fut envoyé pour guérir Tobie et Sara, dont les prières avaient été prononcées en même temps en présence du Seigneur.'),
('tb',4,1,'crampon1923','Tobie croyant que sa prière était exaucée et qu''il allait mourir, appela auprès de lui Tobie, son fils,'),
('tb',4,2,'crampon1923','et lui dit: " Ecoute, mon fils, les paroles de ma bouche et pose-les comme un solide fondement dans ton cœur.'),
('tb',4,3,'crampon1923','Lorsque Dieu aura reçu mon âme, mets mon corps en terre. Tu honoreras ta mère tous les jours de sa vie;'),
('tb',4,4,'crampon1923','car tu dois te souvenir de ce qu''elle a souffert et des grands dangers qu''elle a courus à cause de toi, lorsqu''elle te portait dans son sein.'),
('tb',4,5,'crampon1923','Et quand elle-même aura aussi achevé le temps de sa vie, tu lui donneras la sépulture auprès de moi.'),
('tb',4,6,'crampon1923','Tous les jours de ta vie aie Dieu présent à ta pensée, et garde-toi de consentir jamais au péché et de transgresser les préceptes du Seigneur, ton Dieu.'),
('tb',4,7,'crampon1923','Fais l''aumône de ton bien, et ne détourne point ton visage d''aucun pauvre; car il arrivera ainsi que le visage de Dieu ne se détournera point de toi.'),
('tb',4,8,'crampon1923','De la manière que tu le pourras, sois miséricordieux.'),
('tb',4,9,'crampon1923','Si tu as beaucoup de bien, donne largement; si tu en as peu, aie soin de partager même ce peu de bon cœur.'),
('tb',4,10,'crampon1923','Tu t''amasseras ainsi un grand trésor pour le jour du besoin.'),
('tb',4,11,'crampon1923','Car l''aumône délivre de tout péché et de la mort, et elle ne laissera point l''âme descendre dans les ténèbres.'),
('tb',4,12,'crampon1923','L''aumône sera, pour tous ceux qui l''auront faite, un grand sujet de confiance devant le Dieu souverain.'),
('tb',4,13,'crampon1923','Garde-toi, mon fils, de toute impureté, et qu''en dehors de ton épouse ta conscience ne te reproche jamais une action criminelle.'),
('tb',4,14,'crampon1923','Ne laisse jamais l''orgueil dominer dans ton cœur ou dans tes paroles, car c''est par lui que tous les maux ont pris commencement.'),
('tb',4,15,'crampon1923','Quand un homme aura fait pour toi un travail, paye-lui aussitôt son salaire, et que le salaire du mercenaire ne reste pas un instant chez toi.'),
('tb',4,16,'crampon1923','Ce que tu serais fâché qu''on te fît, aie soin de ne le faire jamais à un autre.'),
('tb',4,17,'crampon1923','Mange ton pain avec ceux qui ont faim et avec les indigents, et couvre de tes vêtements ceux qui sont nus.'),
('tb',4,18,'crampon1923','Fais servir ton pain et ton vin à célébrer la sépulture des justes, mais ne le mange ni ne le bois avec les pécheurs.'),
('tb',4,19,'crampon1923','Cherche toujours conseil auprès d''un homme sage.'),
('tb',4,20,'crampon1923','Bénis Dieu en tout temps; demande-lui qu''il dirige tes voies, et que tous tes desseins réussissent par lui.'),
('tb',4,21,'crampon1923','Je t''informe, aussi, mon fils, que, lorsque tu étais encore petit enfant, j''ai donné dix talents d''argent à Gabélus de Ragès, ville des Mèdes, et que j''ai son reçu entre les mains. C''est pourquoi fais tes diligences pour l''aller trouver et retirer cette somme d''argent, et tu lui rendras son obligation. N''aie point de crainte, mon fils. Il est vrai que nous menons une vie pauvre, mais nous aurons beaucoup de biens si nous craignons Dieu, si nous évitons tout péché et faisons de bonnes œuvres.'),
('tb',5,1,'crampon1923','Alors Tobie répondit à son père, en disant: " Tout ce que tu m''as ordonné, je le ferai mon père.'),
('tb',5,2,'crampon1923','Mais je ne sais comment je pourrai retirer cet argent. Cet homme ne me connaît pas, et il m''est également inconnu; quel signe lui donnerai-je? Je ne sais pas même le chemin qui conduit en ce pays-là. "'),
('tb',5,3,'crampon1923','Son père lui répondit en disant: " J''ai son écrit entre les mains; aussitôt que tu le lui auras montré, il te remboursera.'),
('tb',5,4,'crampon1923','Mais va maintenant chercher un homme fidèle qui aille avec toi, moyennant salaire, afin que tu rentres en possession de cet argent, pendant que je vis encore. "'),
('tb',5,5,'crampon1923','Tobie, étant sorti, trouva un beau jeune homme, debout et ceint, comme disposé à se mettre en route.'),
('tb',5,6,'crampon1923','Ignorant que ce fût un ange de Dieu, il le salua et lui dit: " D''où es-tu, bon jeune homme? "'),
('tb',5,7,'crampon1923','L''ange répondit: " Je suis un des enfants d''Israël. " Et Tobie lui dit: " Connais-tu la route qui conduit au pays des Mèdes? "'),
('tb',5,8,'crampon1923','Il lui répondit: " Je la connais, j''ai souvent parcouru tous ces chemins et j''ai logé chez Gabélus, notre frère, qui demeure à Ragès, ville des Mèdes, laquelle est située dans les montagnes d''Ecbatane. "'),
('tb',5,9,'crampon1923','Tobie lui dit: " Attends-moi, je te prie, jusqu''à ce que j''aie annoncé cela à mon père. "'),
('tb',5,10,'crampon1923','Alors Tobie étant rentré raconta tout à son père. Sur quoi le père émerveillé demanda qu''on fît entrer le jeune homme.'),
('tb',5,11,'crampon1923','Celui-ci entra et salua, en disant: " Que la joie soit toujours avec toi! " —'),
('tb',5,12,'crampon1923','" Quelle joie puis-je avoir, répondit Tobie, moi qui suis assis dans les ténèbres et qui ne vois pas la lumière du ciel? "'),
('tb',5,13,'crampon1923','Le jeune homme lui dit: " Aie bon courage! Il est facile à Dieu de te guérir. "'),
('tb',5,14,'crampon1923','Ensuite Tobie lui dit: " Pourrais-tu bien conduire mon fils chez Gabélus, à Ragès, ville des Mèdes? A ton retour, je te donnerai ton salaire. " —'),
('tb',5,15,'crampon1923','" Je le conduirai, répondit l''ange, et je le ramènerai auprès de toi. "'),
('tb',5,16,'crampon1923','Tobie lui dit: " Dis-moi, je t''en prie, de quelle famille et de quelle tribu es-tu? "'),
('tb',5,17,'crampon1923','L''ange Raphaël lui répondit: " Est-ce la famille du mercenaire que tu cherches, ou le mercenaire lui-même, qui doit accompagner ton fils?'),
('tb',5,18,'crampon1923','Mais pour ne pas te rendre inquiet, je suis Azarias, fils du grand Ananie. "'),
('tb',5,19,'crampon1923','" Tu es d''une noble race, lui dit Tobie. Mais ne te fâche pas, je te prie, de ce que j''ai désiré connaître ta famille. "'),
('tb',5,20,'crampon1923','Et l''ange lui dit: " Je conduirai ton fils sain et sauf, et je te le ramènerai sain et sauf. "'),
('tb',5,21,'crampon1923','Tobie ajouta: " Fais un heureux voyage! Que Dieu soit sur votre chemin, et que son ange vous accompagne! "'),
('tb',5,22,'crampon1923','Quand on eut préparé tout ce qu''ils devaient emporter en voyage, Tobie dit adieu à son père et à sa mère, et il se mit en route avec l''ange.'),
('tb',5,23,'crampon1923','Lorsqu''ils furent partis, la mère se mit à pleurer, en disant: " Tu nous as ôté le bâton de notre vieillesse, et tu l''as éloigné de nous. Plût à Dieu que cet argent pour lequel tu l''as envoyé, n''eût jamais existé! Car notre pauvreté nous suffisait, et c''était pour nous une richesse que de voir notre fils. " Tobie lui répondit: " Ne pleure point; notre fils arrivera sain et sauf, et il reviendra vers nous sain et sauf, et tes yeux le reverront. Car je crois qu''un bon ange de Dieu l''accompagne, et qu''il dispose heureusement tout ce qui lui arrive, en sorte qu''il reviendra vers nous avec joie. " A cette parole, sa mère cessa de pleurer et elle se tut.'),
('tb',6,1,'crampon1923','Tobie partit, suivi du chien, et il fit sa première halte près du fleuve du Tigre.'),
('tb',6,2,'crampon1923','Comme il descendait sur la rive pour se laver les pieds, voici qu''un énorme poisson s''élança pour le dévorer.'),
('tb',6,3,'crampon1923','Effrayé, Tobie poussa un grand cri, en disant: " Seigneur, il se jette sur moi! "'),
('tb',6,4,'crampon1923','L''ange lui dit: " Prends-le par les ouïes et tire-le à toi. " Ce qu''ayant fait, il le tira sur la terre sèche, et le poisson se débattit à ses pieds.'),
('tb',6,5,'crampon1923','L''ange lui dit: " Vide ce poisson, et conserves-en le cœur, le fiel et le foie, car ils sont employés comme d''utiles remèdes. "'),
('tb',6,6,'crampon1923','Il obéit; puis il fit rôtir une partie de la chair, qu''ils emportèrent avec eux pour la route; ils salèrent le reste, qui devait leur suffire jusqu''à ce qu''ils arrivassent à Ragès, ville des Mèdes.'),
('tb',6,7,'crampon1923','Et Tobie interrogea l''ange, en disant: " Je te prie, Azarias mon frère, de me dire quelle vertu curative possèdent les parties de ce poisson que tu m''as commandé de garder. "'),
('tb',6,8,'crampon1923','L''ange lui répondit: " Si tu poses sur des charbons une petite partie du cœur, la fumée qui s''en exhale chasse toute espèce de démons, soit d''un homme, soit d''une femme, en sorte qu''ils ne peuvent plus s''en approcher.'),
('tb',6,9,'crampon1923','Et le fiel sert à oindre les yeux couverts d''une taie, et il les guérit. "'),
('tb',6,10,'crampon1923','Tobie lui dit: " Où veux-tu que nous prenions du repos? "'),
('tb',6,11,'crampon1923','L''ange lui répondit: " Il y a ici un homme appelé Raguel, de ta tribu et de ta famille; il a une fille nommée Sara, mais, en dehors d''elle, il n''a aucun autre enfant, fils ou fille.'),
('tb',6,12,'crampon1923','Tout son bien doit te revenir, et il faut que tu la prennes pour épouse.'),
('tb',6,13,'crampon1923','Demande-la donc à son père, et il te la donnera pour femme. "'),
('tb',6,14,'crampon1923','Alors Tobie répondit: " J''ai ouï dire qu''elle avait déjà épousé sept maris, et qu''ils sont tous morts et l''on m''a dit encore qu''un démon les avait tués.'),
('tb',6,15,'crampon1923','Je crains donc que le même chose ne m''arrive à moi-même, et que, étant fils unique de mes parents, je ne fasse descendre avec tristesse leur vieillesse dans le tombeau. "'),
('tb',6,16,'crampon1923','Et l''ange Raphaël lui dit: " Ecoute-moi, et je t''apprendrai qui sont ceux sur lesquels le démon a du pouvoir.'),
('tb',6,17,'crampon1923','Ce sont ceux qui entrent dans le mariage en bannissant Dieu de leur cœur et de leur pensée, pour se livrer à leur passion, comme le cheval et le mulet qui n''ont pas de raison: sur ceux-là le démon a pouvoir.'),
('tb',6,18,'crampon1923','Mais toi, lorsque tu l''auras épousée, étant entré dans la chambre, vis avec elle en continence pendant trois jours, et ne songe à autre chose qu''à prier Dieu avec elle.'),
('tb',6,19,'crampon1923','La première nuit, livre au feu le foie du poisson, et le démon s''enfuira. La seconde nuit, tu seras admis dans la société des saints patriarches. La troisième nuit, tu recevras la bénédiction promise à leur postérité, afin qu''il naisse de vous des enfants pleins de vigueur. La troisième nuit passée, tu prendras la jeune fille dans la crainte du Seigneur, guidé bien plus par le désir d''avoir des enfants que par la passion, afin que tu obtiennes dans tes enfants la bénédiction promise à la race d''Abraham. "'),
('tb',7,1,'crampon1923','Ils entrèrent chez Raguel, qui les reçut avec joie.'),
('tb',7,2,'crampon1923','A la vue de Tobie, Raguel dit à Anne, sa femme: " Comme ce jeune homme ressemble à mon cousin! "'),
('tb',7,3,'crampon1923','Ayant ainsi parlé, il dit aux voyageurs: " D''où êtes-vous, jeunes gens, nos frères? " Ils répondirent: " Nous sommes de la tribu de Nephthali, du nombre des captifs de Ninive. "'),
('tb',7,4,'crampon1923','Raguel leur dit: " Connaissez-vous Tobie, mon frère? " — " Nous le connaissons ", répondirent-ils.'),
('tb',7,5,'crampon1923','Et comme Raguel disait beaucoup de bien de Tobie, l''ange lui dit: " Tobie, dont tu nous parles, est le père de ce jeune homme. "'),
('tb',7,6,'crampon1923','Aussitôt Raguel courut à lui et l''embrassa avec larmes, pleurant à son cou.'),
('tb',7,7,'crampon1923','" Sois béni, mon fils, dit-il, car tu es fils d''un homme de bien, du meilleur des hommes! "'),
('tb',7,8,'crampon1923','Et Anne, sa femme, et Sara, leur fille, versaient des larmes.'),
('tb',7,9,'crampon1923','Après qu''ils se furent ainsi parlés, Raguel fit tuer un bélier et préparer un festin; et, comme il les engageait à s''asseoir pour le repas,'),
('tb',7,10,'crampon1923','Tobie dit: " Je ne mangerai ni ne boirai ici aujourd''hui, que tu ne m''aies d''abord accordé ma demande, et que tu ne me promettes de me donner Sara, ta fille. "'),
('tb',7,11,'crampon1923','En entendant ces mots, Raguel fut saisi de frayeur, sachant ce qui était arrivé aux sept maris qui s''étaient approchés d''elle, et il commença à craindre que pareil malheur n''arrivât encore à celui-ci. Comme il était dans cette incertitude et ne donnait aucune réponse à la demande de Tobie,'),
('tb',7,12,'crampon1923','l''ange lui dit: " N''appréhende point de donner ta fille à ce jeune homme; car c''est à lui, qui craint Dieu, qu''elle doit appartenir comme épouse; voilà pourquoi aucun autre n''a pu la posséder. "'),
('tb',7,13,'crampon1923','Alors Raguel dit: " Je ne doute pas que Dieu n''ait admis en sa présence mes prières et mes larmes.'),
('tb',7,14,'crampon1923','Et je crois qu''il vous a fait venir vers moi, afin que ma fille épousât son parent, selon la loi de Moïse. N''aie donc plus de doute que je te la donne. "'),
('tb',7,15,'crampon1923','Et prenant la main droite de sa fille, il la mit dans la main droite de Tobie, en disant: " Que le Dieu d''Abraham, le Dieu d''Isaac et le Dieu de Jacob soit avec vous, que lui-même vous unisse et qu''il répande sur vous sa pleine bénédiction! "'),
('tb',7,16,'crampon1923','Puis ayant pris du papier, ils rédigèrent l''acte du mariage.'),
('tb',7,17,'crampon1923','Après quoi, ils prirent part au festin, en bénissant Dieu. Raguel appela Anne, sa femme, et lui ordonna de préparer une autre chambre. Elle y conduisit Sara, sa fille, qui se prit à pleurer. Et elle lui dit: " Aie bon courage, ma fille. Que le Seigneur du ciel te donne la joie à la place du chagrin que tu as éprouvé! "'),
('tb',8,1,'crampon1923','Le repas achevé, ils conduisirent le jeune homme auprès de Sara.'),
('tb',8,2,'crampon1923','Tobie, se ressouvenant des paroles de l''ange, tira de son sac une partie du foie et la posa sur des charbons ardents.'),
('tb',8,3,'crampon1923','Alors l''ange Raphaël saisit le démon et l''enchaîna dans le désert de la Haute-Egypte.'),
('tb',8,4,'crampon1923','Et Tobie exhorta la jeune fille, en lui disant: " Sara, lève-toi, et prions Dieu aujourd''hui, demain et après-demain; durant ces trois nuits nous serons unis à Dieu, et, après la troisième nuit, nous vivrons dans notre mariage.'),
('tb',8,5,'crampon1923','Car nous sommes enfants des saints, et nous ne pouvons pas nous unir comme les nations qui ne connaissent pas Dieu. "'),
('tb',8,6,'crampon1923','S''étant donc levés ensemble, tous deux prièrent instamment Dieu de leur accorder la santé.'),
('tb',8,7,'crampon1923','Tobie dit: " Seigneur, Dieu de nos pères, que le ciel et la terre, que la mer, les fontaines et les fleuves, avec toutes vos créatures qu''ils renferment, vous bénissent!'),
('tb',8,8,'crampon1923','Vous avez fait Adam du limon de la terre, et vous lui avez donné Eve pour compagne.'),
('tb',8,9,'crampon1923','Et maintenant, Seigneur, vous savez que ce n''est point pour satisfaire ma passion que je prends ma sœur pour épouse, mais dans le seul désir de laisser des enfants qui bénissent votre nom dans tous les siècles. "'),
('tb',8,10,'crampon1923','Sara dit aussi: " Ayez pitié de nous, Seigneur, ayez pitié de nous, et puissions-nous tous deux ensemble arriver à la vieillesse dans une parfaite santé! "'),
('tb',8,11,'crampon1923','A l''heure du chant du coq, Raguel commanda qu''on fît venir ses serviteurs, et ils s''en allèrent avec lui pour creuser une fosse.'),
('tb',8,12,'crampon1923','Car il disait: " Il pourrait bien lui être arrivé la même chose qu''aux sept autres maris qui sont allés auprès d''elle. "'),
('tb',8,13,'crampon1923','Lorsqu''ils eurent préparé la fosse, Raguel revint vers sa femme et lui dit:'),
('tb',8,14,'crampon1923','" Envoie une de tes servantes pour voir s''il est mort afin que je le mette en terre avant qu''il fasse jour. "'),
('tb',8,15,'crampon1923','Anne envoya une de ses servantes. Celle-ci étant entrée dans la chambre, les trouva sains et saufs, pareillement endormis.'),
('tb',8,16,'crampon1923','Etant retournée, elle annonça cette bonne nouvelle; et Raguel et Anne, sa femme, bénirent le Seigneur,'),
('tb',8,17,'crampon1923','en disant: " Nous vous bénissons Seigneur, Dieu d''Israël, car le malheur que nous redoutions n''est pas arrivé.'),
('tb',8,18,'crampon1923','Vous avez usé envers nous de miséricorde, et vous avez éloigné de nous l''ennemi qui nous persécutait.'),
('tb',8,19,'crampon1923','Vous avez eu pitié de deux enfants uniques. Faites, Seigneur, qu''ils vous bénissent de plus en plus, et qu''ils vous offrent un sacrifice de louange pour leur préservation, afin que toutes les nations reconnaissent que vous seul êtes Dieu sur toute la terre. "'),
('tb',8,20,'crampon1923','Aussitôt Raguel commanda à ses serviteurs de combler avant le jour la fosse qu''ils avaient faite.'),
('tb',8,21,'crampon1923','Et il dit à sa femme d''apprêter un festin et de disposer toutes les choses nécessaires à des voyageurs pour leur entretien. Il fit aussi tuer deux vaches grasses et quatre béliers, pour préparer un repas à tous ses voisins et à tous ses amis. Et Raguel conjura Tobie de rester chez lui pendant deux semaines. Raguel donna à Tobie, la moitié de tout ce qu''il possédait, et il rédigea un écrit afin que la moitié qui restait devînt la propriété de Tobie, après leur mort.'),
('tb',9,1,'crampon1923','Alors Tobie appela auprès de lui l''ange, qu''il croyait un homme et lui dit: " Azarias, mon frère, je te prie d''écouter mes paroles.'),
('tb',9,2,'crampon1923','Quand je me donnerais à toi comme esclave, je ne reconnaîtrais pas encore assez tous tes soins.'),
('tb',9,3,'crampon1923','Néanmoins je t''adresse encore cette prière: Prends avec toi des bêtes de somme et des serviteurs, et va trouver Gabélus, à Ragès, ville des Mèdes; tu lui rendras son écrit, tu recevras de lui l''argent et tu le prieras de venir à mes noces.'),
('tb',9,4,'crampon1923','Car tu sais toi-même que mon père compte les jours, et que, si je tarde un jour de plus, son âme sera dans la tristesse.'),
('tb',9,5,'crampon1923','Tu vois aussi de quelle manière Raguel m''a conjuré de rester ici, et que je ne puis résister à ses instances. "'),
('tb',9,6,'crampon1923','Alors Raphaël, prenant quatre des serviteurs de Raguel et deux chameaux, se rendit à Ragès, ville des Mèdes. Ayant trouvé Gabélus, il lui rendit son billet et en reçut tout l''argent; et, après lui avoir raconté tout ce qui était arrivé à Tobie, fils de Tobie, il le fit venir avec lui aux noces. Lorsque Gabélus entra dans la maison de Raguel, il trouva Tobie à table; celui-ci se leva aussitôt; ils se baisèrent mutuellement, et Gabélus pleura et bénit Dieu, en disant: " Que le Dieu d''Israël te bénisse, car tu es le fils d''un homme excellent, juste et craignant Dieu, et faisant beaucoup d''aumônes! Que la bénédiction se répande aussi sur ta femme et sur vos parents! Puissiez-vous voir vos fils et les fils de vos fils, jusqu''à la troisième et à la quatrième génération! Que votre postérité soit bénie du Dieu d''Israël, qui règne dans les siècles des siècles! " Tous ayant dit: Amen! ils se mirent à table, et c''est dans la crainte de Dieu qu''ils firent le festin des noces.'),
('tb',10,1,'crampon1923','Pendant que Tobie différait son départ à cause de ses noces, son père Tobie était rempli d''inquiétude: " D''où vient, se disait-il, le retard de mon fils? Quelle raison peut le retenir dans ce pays?'),
('tb',10,2,'crampon1923','Gabélus serait-il mort, et n''y aurait-il plus personne pour lui rendre cet argent? "'),
('tb',10,3,'crampon1923','Il commença donc à s''attrister beaucoup, lui et Anne, sa femme, et ils se mirent ensemble à pleurer de ce que leur fils n''était pas revenu près d''eux au jour marqué.'),
('tb',10,4,'crampon1923','Sa mère surtout répandait des larmes intarissables: " Hélas! hélas! mon fils, disait-elle, pourquoi t''avons-nous envoyé si loin, toi qui étais la lumière de nos yeux, le bâton de notre vieillesse, la consolation de notre vie et l''espérance de notre postérité?'),
('tb',10,5,'crampon1923','Nous qui avions tout en toi seul, nous n''aurions pas dû t''éloigner de nous. "'),
('tb',10,6,'crampon1923','Tobie lui disait: " Cesse tes plaintes et ne te trouble pas; notre fils se porte bien et l''homme avec qui nous l''avons fait partir est très fidèle. "'),
('tb',10,7,'crampon1923','Mais rien ne pouvait la consoler; sortant chaque jour de sa maison, elle regardait de tous côtés, et allait sur tous les chemins par lesquels il y avait espoir qu''il reviendrait, afin, s''il était possible, de l''apercevoir de loin.'),
('tb',10,8,'crampon1923','Cependant Raguel disait à son gendre: " Reste ici, et j''enverrai des nouvelles de ta santé à Tobie, ton père. "'),
('tb',10,9,'crampon1923','Tobie lui répondit: " Je sais que mon père et ma mère comptent les jours et que leur esprit se tourmente au-dedans d''eux. "'),
('tb',10,10,'crampon1923','Après avoir fait encore de grandes instances à Tobie, sans que celui-ci voulût rien entendre à ses raisons, Raguel lui remit Sara avec la moitié de tout ce qu''il possédait, en serviteurs et en servantes, en troupeaux, en chameaux, en vaches, en argent, dont il avait beaucoup, et il le laissa partir, plein de santé et de joie,'),
('tb',10,11,'crampon1923','en disant: " Que le saint ange du Seigneur soit en votre chemin, qu''il vous conduise jusque chez vous sains et saufs; puissiez-vous trouver toute chose prospère chez vos parents, et puissent mes yeux voir vos enfants avant que je meure! "'),
('tb',10,12,'crampon1923','Et le père et la mère, prenant leur fille, l''embrassèrent et la laissèrent aller,'),
('tb',10,13,'crampon1923','après lui avoir recommandé d''honorer ses beaux-parents, d''aimer son mari, de bien conduire sa famille, de gouverner sa maison et de se conserver elle-même sans reproche.'),
('tb',10,14,'crampon1923',''),
('tb',11,1,'crampon1923','Comme ils s''en retournaient, ils arrivèrent le onzième jour à Charan, ville située à moitié chemin vers Ninive.'),
('tb',11,2,'crampon1923','Et l''ange dit: " Tobie, mon frère, tu sais en quel état tu as laissé ton père.'),
('tb',11,3,'crampon1923','Si donc tu le trouves bon, prenons les devants, et que tes serviteurs suivent à petites journées, avec ta femme et tes troupeaux. "'),
('tb',11,4,'crampon1923','Tobie ayant approuvé ce dessein, Raphaël lui dit: " Prends avec toi du fiel du poisson, car tu en auras besoin. " Tobie prit de ce fiel, et ils partirent.'),
('tb',11,5,'crampon1923','Anne cependant allait tous les jours s''asseoir près du chemin, au sommet d''une éminence, d''où elle pouvait découvrir de loin.'),
('tb',11,6,'crampon1923','Et comme elle épiait de là l''arrivée de son fils, elle l''aperçut dans le lointain qui revenait et, l''ayant reconnu, elle courut l''annoncer à son mari, en disant: " Voici ton fils qui arrive. "'),
('tb',11,7,'crampon1923','En même temps, Raphaël dit à Tobie: " Lorsque tu seras entré dans ta maison, adore aussitôt le Seigneur, ton Dieu, et lui rends grâces; puis, t''approchant de ton père, tu le baiseras,'),
('tb',11,8,'crampon1923','et tu étendras tout de suite sur ses yeux de ce fiel de poisson que tu portes avec toi; car sache que ses yeux s''ouvriront à l''instant, et que ton père verra la lumière du ciel, et que ta vue le comblera de joie. "'),
('tb',11,9,'crampon1923','Alors le chien qui les avait accompagnés dans le voyage courut devant eux, comme pour apporter la nouvelle, caressant de la queue et tout joyeux.'),
('tb',11,10,'crampon1923','Et le père aveugle se leva et se mit à courir, et, comme il heurtait des pieds, il donna la main à un serviteur pour aller au-devant de son fils.'),
('tb',11,11,'crampon1923','Le prenant dans ses bras, il le baisa, ce que fit aussi sa femme, et tous deux versaient des larmes de joie.'),
('tb',11,12,'crampon1923','Après qu''ils eurent adoré Dieu et lui eurent rendu grâces, il s''assirent.'),
('tb',11,13,'crampon1923','Aussitôt Tobie, prenant du fiel du poisson, l''étendit sur les yeux de son père.'),
('tb',11,14,'crampon1923','Au bout d''une demi-heure environ d''attente, une taie blanche, comme la pellicule d''un œuf, commença à sortir de ses yeux.'),
('tb',11,15,'crampon1923','Tobie la saisit, et l''arracha des yeux de son père, et à l''instant celui-ci recouvra la vue.'),
('tb',11,16,'crampon1923','Et ils rendaient gloire à Dieu, lui et sa femme et tous ceux qui le connaissaient.'),
('tb',11,17,'crampon1923','Tobie disait: " Je vous bénis, Seigneur, Dieu d''Israël, parce que vous m''avez châtié et que vous m''avez guéri; et voici que je vois mon fils Tobie! "'),
('tb',11,18,'crampon1923','Sept jours après arriva aussi Sara, la femme de son fils, avec tous ses serviteurs en bonne santé, avec les troupeaux et les chameaux, et tout l''argent de son mariage et celui qu''avait rendu Gabélus.'),
('tb',11,19,'crampon1923','Et Tobie raconta à ses parents tous les bienfaits dont Dieu l''avait comblé par l''homme qui l''avait conduit. Achior et Nabath, parents de Tobie, vinrent le trouver, pleins de joie, et le félicitèrent de tous les biens que Dieu lui avait faits. Et pendant sept jours, mangeant ensemble, ils se livrèrent à de grandes réjouissances.'),
('tb',12,1,'crampon1923','Alors Tobie appela auprès de lui son fils et lui dit: " Que donnerons-nous à ce saint homme qui t''a accompagné dans ton voyage? "'),
('tb',12,2,'crampon1923','Tobie répondit à son père: " Mon père, quelle récompense pouvons-nous lui offrir? Y a-t-il quelque chose qui soit en rapport avec ses services?'),
('tb',12,3,'crampon1923','Il m''a conduit et ramené sain et sauf; il a été lui-même recevoir l''argent de Gabélus; il m''a fait avoir une femme, dont il a éloigné le démon, et il a rempli de joie ses parents; il m''a sauvé moi-même du poisson qui allait me dévorer; il t''a fait voir la lumière du ciel, et par lui nous avons été comblés de toutes sortes de biens. Que pouvons-nous lui donner qui égale ce qu''il a fait pour nous?'),
('tb',12,4,'crampon1923','Mais je te prie, mon père, de lui demander s''il ne daignerait pas accepter la moitié de tout le bien que nous avons apporté. "'),
('tb',12,5,'crampon1923','L''ayant donc appelé, Tobie et son fils le prirent à part, et le prièrent de vouloir bien accepter la moitié de tout ce qu''ils avaient rapporté.'),
('tb',12,6,'crampon1923','Alors l''ange, seul avec eux, leur dit: " Bénissez le Dieu du ciel et rendez-lui gloire devant tout être qui a vie, parce qu''il a exercé envers vous sa miséricorde.'),
('tb',12,7,'crampon1923','Il est bon de tenir caché le secret du roi, mais il est honorable de révéler et de publier les œuvres de Dieu.'),
('tb',12,8,'crampon1923','La prière est bonne avec le jeûne, et l''aumône vaut mieux que l''or et les trésors.'),
('tb',12,9,'crampon1923','Car l''aumône délivre de la mort, et c''est elle qui efface les péchés, et qui fait trouver la miséricorde et la vie éternelle.'),
('tb',12,10,'crampon1923','Mais ceux qui commettent le péché et l''iniquité sont leurs propres ennemis.'),
('tb',12,11,'crampon1923','Je vais donc vous découvrir la vérité, et je ne veux vous rien cacher.'),
('tb',12,12,'crampon1923','Lorsque tu priais avec larmes et que tu donnais la sépulture aux morts; lorsque, quittant ton repas, tu cachais les morts dans ta maison pendant le jour, et que tu les mettais en terre pendant la nuit, je présentais ta prière au Seigneur.'),
('tb',12,13,'crampon1923','Et parce que tu étais agréable à Dieu, il a fallu que la tentation t''éprouvât.'),
('tb',12,14,'crampon1923','Maintenant, le Seigneur m''a envoyé pour te guérir, et pour délivrer du démon Sara, la femme de ton fils.'),
('tb',12,15,'crampon1923','Je suis l''ange Raphaël, un des sept qui nous tenons en présence du Seigneur. "'),
('tb',12,16,'crampon1923','En entendant ces paroles, ils furent hors d''eux-mêmes, et, tout tremblant, ils tombèrent la face contre terre.'),
('tb',12,17,'crampon1923','Et l''ange leur dit: " Que la paix soit avec vous! Ne craignez point.'),
('tb',12,18,'crampon1923','Car, lorsque j''étais avec vous, j''y étais par la volonté de Dieu; bénissez-le donc et chantez ses louanges.'),
('tb',12,19,'crampon1923','Il vous a paru que je mangeais et buvais avec vous; mais je me nourrissais d''un aliment invisible et d''une boisson que l''œil de l''homme ne peut atteindre.'),
('tb',12,20,'crampon1923','Il est donc temps que je retourne vers celui qui m''a envoyé; mais vous, bénissez Dieu et publiez toutes ses merveilles. "'),
('tb',12,21,'crampon1923','Après avoir ainsi parlé, il fut dérobé à leurs regards, et ils ne purent plus le voir.'),
('tb',12,22,'crampon1923','Alors, s''étant prosternés pendant trois heures le visage contre terre, ils bénirent Dieu, et, s''étant levés, ils racontèrent toutes ses merveilles.'),
('tb',13,1,'crampon1923','Le vieux Tobie, ouvrant la bouche, bénit le Seigneur en disant: " Vous êtes grand, Seigneur, dans l''éternité, et votre règne s''étend à tous les siècles.'),
('tb',13,2,'crampon1923','Car vous châtiez et vous sauvez, vous conduisez au tombeau et vous en ramenez, et il n''est personne qui puisse échapper à votre main.'),
('tb',13,3,'crampon1923','Célébrez le Seigneur, enfants d''Israël, et louez-le devant les nations.'),
('tb',13,4,'crampon1923','Car il vous a dispersés parmi les nations qui l''ignorent, afin que vous racontiez ses merveilles, et que vous leur fassiez connaître qu''il n''y a point d''autre Dieu tout-puissant que lui seul.'),
('tb',13,5,'crampon1923','Il nous a châtiés à cause de nos iniquités, et il nous sauvera à cause de sa miséricorde.'),
('tb',13,6,'crampon1923','Considérez comment il a agi envers nous, et bénissez-le avec crainte et tremblement, et glorifiez par vos œuvres le Roi des siècles.'),
('tb',13,7,'crampon1923','Pour moi, je veux le bénir dans ce pays où je suis captif, parce qu''il a fait éclater sa gloire sur une nation criminelle.'),
('tb',13,8,'crampon1923','Convertissez-vous donc, pécheurs, et pratiquez la justice devant Dieu, dans la confiance qu''il vous fera miséricorde!'),
('tb',13,9,'crampon1923','Pour moi, je me réjouirai en lui de toute mon âme.'),
('tb',13,10,'crampon1923','Bénissez le Seigneur, vous tous qui êtes le peuple choisi; célébrez des jours de joie et chantez ses louanges!'),
('tb',13,11,'crampon1923','Jérusalem, cité de Dieu, le Seigneur t''a châtiée à cause des œuvres de tes mains.'),
('tb',13,12,'crampon1923','Glorifie le Seigneur par tes bonnes œuvres, et bénis le Dieu des siècles, afin qu''il rebâtisse en toi son sanctuaire, qu''il rappelle à toi tous les captifs et que tu te réjouisses dans tous les siècles des siècles.'),
('tb',13,13,'crampon1923','Tu brilleras d''une éclatante lumière, et tous les pays de la terre se prosterneront devant toi.'),
('tb',13,14,'crampon1923','Les nations viendront à toi des contrées lointaines, apportant des présents, elles adoreront dans tes murs le Seigneur, et considéreront ta terre comme un sanctuaire;'),
('tb',13,15,'crampon1923','car elles invoqueront le grand Nom au milieu de toi.'),
('tb',13,16,'crampon1923','Seront maudits ceux qui te mépriseront, condamnés ceux qui te blasphémeront, bénis ceux qui t''édifieront.'),
('tb',13,17,'crampon1923','Et toi, tu te réjouiras dans tes enfants, parce qu''ils seront tous bénis et se rassembleront auprès du Seigneur.'),
('tb',13,18,'crampon1923','Heureux tous ceux qui t''aiment et qui se réjouissent de ta paix! Mon âme, bénis le Seigneur, parce qu''il a délivré Jérusalem, sa ville, de toutes ses tribulations, lui, le Seigneur, notre Dieu! Heureux serai-je, s''il reste des rejetons de ma race pour voir la splendeur de Jérusalem! Les portes de Jérusalem seront bâties de saphirs et d''émeraudes, et toute l''enceinte de ses murailles de pierres précieuses. Des pierres d''une blancheur immaculée formeront le pavé de ses places, et l''on chantera dans ses rues: Alléluia! Béni soit le Seigneur qui a donné cette gloire à Jérusalem, et qu''il règne sur elle aux siècles des siècles! Amen! "'),
('tb',14,1,'crampon1923','Ainsi finirent les paroles de Tobie. Après qu''il eut recouvré la vue, Tobie vécut encore quarante-deux ans, et il vit les enfants de ses petits-enfants.'),
('tb',14,2,'crampon1923','Il vécut en tout cent deux ans, et il fut inhumé honorablement à Ninive.'),
('tb',14,3,'crampon1923','Car il avait cinquante-six ans lorsqu''il perdit la vue, et il la recouvra à soixante.'),
('tb',14,4,'crampon1923','Tout le reste de sa vie se passa dans la joie, et plus il faisait de progrès dans la crainte de Dieu, plus il goûtait de paix.'),
('tb',14,5,'crampon1923','A l''heure de sa mort, il appela auprès de lui Tobie, son fils, et les sept jeunes fils de ce dernier, ses petits-fils, et il leur dit:'),
('tb',14,6,'crampon1923','" La ruine de Ninive est proche, car la parole de Dieu doit avoir son accomplissement; et nos frères qui y sont dispersés loin du pays d''Israël y retourneront.'),
('tb',14,7,'crampon1923','Tout le pays d''Israël, après avoir été désert, sera repeuplé, et la maison de Dieu, après avoir été brûlée, sera rebâtie, et tous ceux qui craignent Dieu y reviendront.'),
('tb',14,8,'crampon1923','Les nations abandonneront leurs idoles; elles viendront à Jérusalem et y habiteront;'),
('tb',14,9,'crampon1923','et tous les rois de la terre s''y réjouiront en adorant le Roi d''Israël.'),
('tb',14,10,'crampon1923','" Ecoutez donc, mes enfants, votre père, servez le Seigneur dans la vérité, et efforcez-vous de faire ce qui lui est agréable.'),
('tb',14,11,'crampon1923','Recommandez à vos enfants de pratiquer la justice et de faire des aumônes, de se souvenir de Dieu et de le bénir en tout temps dans la vérité et de toute leur force.'),
('tb',14,12,'crampon1923','" Ecoutez-moi donc maintenant, mes enfants, et ne demeurez point dans cette ville; mais le jour même où vous aurez inhumé votre mère auprès de moi dans un même sépulcre, mettez-vous en route pour sortir d''ici;'),
('tb',14,13,'crampon1923','car je vois que l''iniquité de Ninive amènera sa ruine. "'),
('tb',14,14,'crampon1923','Après la mort de sa mère, le jeune Tobie sortit de Ninive avec sa femme, ses enfants et les enfants de ses enfants, et il retourna chez ses beaux-parents.'),
('tb',14,15,'crampon1923','Il les trouva bien portants dans une heureuse vieillesse; il eut soin d''eux et il leur ferma les yeux; il recueillit tout l''héritage de la maison de Raguel, et il vit les enfants de ses enfants jusqu''à la cinquième génération. Après qu''il eut vécu quatre-vingt-dix-neuf ans dans la crainte du Seigneur, ses enfants l''inhumèrent avec joie. Tous ceux de sa parenté et tous ses descendants persévérèrent dans une bonne vie et une sainte conduite, en sorte qu''ils furent aimés de Dieu et des hommes, et de tous ceux qui habitaient le pays.'),
('jdt',1,1,'crampon1923','Arphaxad, roi des Mèdes, après avoir soumis à son empire beaucoup de nations, bâtit de pierres de taille équarries une ville très forte, qu''il appela Ecbatane.'),
('jdt',1,2,'crampon1923','Il l''entoura de murailles hautes de soixante-dix coudées, sur trente coudées de largeur, et il y construisit des tours hautes de cent coudées,'),
('jdt',1,3,'crampon1923','de forme carrée, chaque côté ayant vingt pieds de largeur, et il fit les portes en proportion de la hauteur des tours.'),
('jdt',1,4,'crampon1923','Il se glorifiait comme étant invincible par la puissance de son armée et par la multitude de ses chars.'),
('jdt',1,5,'crampon1923','Or, la douzième année de son règne, Nabuchodonosor, roi des Assyriens, qui régnait à Ninive, la grande ville, fit la guerre à Arphaxad et le vainquit'),
('jdt',1,6,'crampon1923','dans la grande plaine appelée Ragau, avec l''aide de ceux qui habitent près de l''Euphrate, du Tigre et du Jadason, dans la plaine d''Erioch, le roi des Eliciens.'),
('jdt',1,7,'crampon1923','Alors fut agrandie la domination de Nabuchodonosor, et son cœur s''éleva, et il envoya des messagers à tous ceux qui habitaient en Cilicie, à Damas et sur le mont Liban,'),
('jdt',1,8,'crampon1923','aux peuples du Carmel, de Cédar, aux habitants de la Galilée, dans la grande plaine d''Esdrelon,'),
('jdt',1,9,'crampon1923','à tous ceux qui étaient dans la Samarie, au-delà du fleuve du Jourdain, jusqu''à Jérusalem, et dans tout le pays de Gessen jusqu''aux frontières de l''Ethiopie:'),
('jdt',1,10,'crampon1923','à tous ces peuples, Nabuchodonosor, roi d''Assyrie, envoya des messagers.'),
('jdt',1,11,'crampon1923','Et tous, d''un commun accord, refusèrent; ils les renvoyèrent sans présents et n''eurent pour eux que du mépris.'),
('jdt',1,12,'crampon1923','Alors le roi Nabuchodonosor entra en fureur contre tous ces pays, et jura par son trône et par son royaume de tirer vengeance de toutes ces contrées.'),
('jdt',1,13,'crampon1923',''),
('jdt',1,14,'crampon1923',''),
('jdt',1,15,'crampon1923',''),
('jdt',1,16,'crampon1923',''),
('jdt',2,1,'crampon1923','La treizième année du roi Nabuchodonosor, le vingt-deuxième jour du premier mois, il fut décidé dans la maison de Nabuchodonosor, roi d''Assyrie, qu''il se vengerait.'),
('jdt',2,2,'crampon1923','Et il convoqua tous les anciens, tous ses chefs et ses guerriers, et il tint avec eux un conseil secret.'),
('jdt',2,3,'crampon1923','Il leur dit que son dessein était de soumettre toute la terre à son empire.'),
('jdt',2,4,'crampon1923','Ce discours ayant été approuvé de tous, le roi Nabuchodonosor fit venir Holoferne, général en chef de son armée,'),
('jdt',2,5,'crampon1923','et il lui dit: " Mets-toi en marche contre tous les royaumes d''Occident, et principalement contre ceux qui ont méprisé mon ordre.'),
('jdt',2,6,'crampon1923','Ton œil n''épargnera aucun royaume, et tu me soumettras toutes les villes fortes.'),
('jdt',2,7,'crampon1923','Alors Holoferne, ayant appelé les chefs et les officiers de l''armée des Assyriens, enrôla des hommes pour l''expédition, selon l''ordre du roi, au nombre de cent vingt mille fantassins et douze mille archers à cheval.'),
('jdt',2,8,'crampon1923','Il fit précéder son armée d''une multitude innombrable de chameaux, avec des provisions en abondance pour ses soldats, et d''innombrables troupeaux de bœufs et de moutons.'),
('jdt',2,9,'crampon1923','Il fit préparer sur son passage du blé de toute la Syrie.'),
('jdt',2,10,'crampon1923','Il prit de la maison du roi des sommes immenses d''or et d''argent.'),
('jdt',2,11,'crampon1923','Et il se mit en marche, lui et toute l''armée, avec les chariots, les cavaliers et les archers, qui couvraient la face de la terre, comme des sauterelles.'),
('jdt',2,12,'crampon1923','Ayant franchi la frontière de l''Assyrie, il arriva aux grandes montagnes d''Angé, qui sont au nord de la Cilicie, et il pénétra dans toutes leurs forteresses et s''empara de tous les retranchements.'),
('jdt',2,13,'crampon1923','Il emporta d''assaut la célèbre ville de Mélitène, et pilla tous les habitants de Tarse, ainsi que les enfants d''Ismaël qui étaient en face du désert et au sud du pays de Cellon.'),
('jdt',2,14,'crampon1923','Passant l''Euphrate, il alla en Mésopotamie, et força toutes les places fortes de la contrée, depuis le torrent de Chaboras jusqu''à la mer.'),
('jdt',2,15,'crampon1923','Ensuite il s''empara de tous les pays limitrophes de l''Euphrate depuis la Cilicie jusqu''au territoire de Japheth, qui s''étend vers le sud.'),
('jdt',2,16,'crampon1923','Il emmena captifs tous les fils de Madian, pilla toutes leurs richesses et fit périr par le glaive tous ceux qui lui résistèrent.'),
('jdt',2,17,'crampon1923','Il descendit ensuite dans les campagnes de Damas, au temps de la moisson, brûla toutes les récoltes et fit couper tous les arbres et toutes les vignes.'),
('jdt',2,18,'crampon1923','Et la terreur de ses armes s''empara de tous les habitants de la terre.'),
('jdt',2,19,'crampon1923',''),
('jdt',2,20,'crampon1923',''),
('jdt',2,21,'crampon1923',''),
('jdt',2,22,'crampon1923',''),
('jdt',2,23,'crampon1923',''),
('jdt',2,24,'crampon1923',''),
('jdt',2,25,'crampon1923',''),
('jdt',2,26,'crampon1923',''),
('jdt',2,27,'crampon1923','')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('jdt',2,28,'crampon1923',''),
('jdt',3,1,'crampon1923','Alors les rois et les princes de toutes les villes et de tous les pays, savoir de la Syrie Mésopotamienne, de la Syrie de Soba, de la Libye et de la Cilicie envoyèrent leurs ambassadeurs, qui se rendirent auprès d''Holoferne et lui dirent:'),
('jdt',3,2,'crampon1923','" Apaise ta colère contre nous; il vaut mieux, avec la vie sauve, servir Nabuchodonosor, le grand roi, et nous soumettre à toi, que de mourir, après avoir souffert, en périssant, les maux de la servitude.'),
('jdt',3,3,'crampon1923','Toutes nos villes, tout ce que nous possédons, toutes nos montagnes, nos collines, nos champs, nos troupeaux de bœufs, de brebis, de chèvres, de chevaux, de chameaux, tous nos biens et nos familles sont devant toi.'),
('jdt',3,4,'crampon1923','Que tout ce que nous avons soit sous ta dépendance.'),
('jdt',3,5,'crampon1923','Nous et nos enfants, nous sommes tes serviteurs.'),
('jdt',3,6,'crampon1923','Viens à nous comme un maître pacifique, et fais usage de nos services comme il te plaira. "'),
('jdt',3,7,'crampon1923','Holoferne descendit alors des montagnes avec ses cavaliers, en grande force, et il se rendit maître de toutes les villes et de tous les habitants du pays.'),
('jdt',3,8,'crampon1923','Il prit de toutes les villes, pour en faire des auxiliaires, des hommes vaillants et choisis pour la guerre.'),
('jdt',3,9,'crampon1923','Or, telle était la frayeur qui pesait sur ces provinces, que les habitants de toutes les villes, les magistrats et les plus honorables personnages, comme les gens du peuple, sortaient à son approche au-devant de lui,'),
('jdt',3,10,'crampon1923','et le recevaient avec des couronnes et des flambeaux, en dansant au son des tambours et des flûtes. Néanmoins, même par cette conduite, ils ne purent pas adoucir la férocité de son cœur. Il détruisit leurs villes et coupa leurs bois sacrés. Car Nabuchodonosor lui avait ordonné d''exterminer tous les dieux de la terre, afin que lui-même fût seul appelé Dieu par toutes les nations que la puissance d''Holoferne pourrait soumettre. Après avoir parcouru la Syrie et Soba, toute l''Apamée et toute la Mésopotamie, il arriva chez les Iduméens dans le pays de Gabaa; et, ayant pris leurs villes, il s''arrêta là trente jours, pendant lesquels il fit rassembler toutes les troupes de son armée.'),
('jdt',4,1,'crampon1923','Les enfants d''Israël qui habitaient dans le pays de Juda, ayant appris ces choses, furent saisis de crainte à l''approche d''Holoferne.'),
('jdt',4,2,'crampon1923','Ils éprouvèrent un sentiment d''effroi et d''horreur à la pensée qu''il pourrait traiter Jérusalem et le temple du Seigneur comme il avait traité les autres villes et leurs temples.'),
('jdt',4,3,'crampon1923','Ils envoyèrent des messagers dans toute la Samarie et aux environs jusqu''à Jéricho, et ils occupèrent d''avance tous les sommets des montagnes.'),
('jdt',4,4,'crampon1923','Ils entourèrent leurs bourgs de murailles et firent des provisions de blé pour se préparer à soutenir la lutte.'),
('jdt',4,5,'crampon1923','Le grand prêtre Eliacim écrivit aussi à tous ceux qui demeuraient en face d''Esdrelon, vis-à-vis de la grande plaine qui est près de Dothaïn, et à tous ceux sur le territoire desquels étaient les passages,'),
('jdt',4,6,'crampon1923','leur recommandant d''occuper les versants des montagnes par où l''on pouvait aller à Jérusalem, et de garder les défilés qui pouvaient offrir un chemin entre les montagnes.'),
('jdt',4,7,'crampon1923','Les enfants d''Israël exécutèrent les ordres d''Eliacim, prêtre du Seigneur.'),
('jdt',4,8,'crampon1923','Et tout le peuple invoqua le Seigneur avec grande instance, et ils humilièrent leurs âmes dans le jeûne et la prière, eux et leurs femmes.'),
('jdt',4,9,'crampon1923','Les prêtres se revêtirent de cilices, et les enfants se prosternèrent devant le temple du Seigneur, et l''on couvrit d''un cilice l''autel du Seigneur.'),
('jdt',4,10,'crampon1923','Et d''un cœur unanime ils crièrent vers le Seigneur, Dieu d''Israël, afin qu''il ne permît pas que leurs enfants devinssent la proie d''un vainqueur et leurs femmes un butin à partager, que leurs villes fussent livrées à la destruction et leur sanctuaire profané, et qu''eux-mêmes fussent un objet d''opprobre parmi les nations.'),
('jdt',4,11,'crampon1923','Alors Eliacim, le grand prêtre du Seigneur, parcourut tout le pays d''Israël, et il s''adressa au peuple,'),
('jdt',4,12,'crampon1923','en disant: " Sachez que le Seigneur exaucera vos supplications, si vous persévérez dans le jeûne et la prière en sa présence.'),
('jdt',4,13,'crampon1923','Souvenez-vous de Moïse, serviteur du Seigneur: Amalec se confiait dans sa force et dans sa puissance, dans son armée, dans ses boucliers, dans ses chars et dans ses cavaliers; Moïse le vainquit, non en combattant avec le fer, mais en adressant à Dieu de saintes prières.'),
('jdt',4,14,'crampon1923','Il en sera ainsi de tous les ennemis d''Israël, si vous persévérez dans l''œuvre que vous avez commencée. "'),
('jdt',4,15,'crampon1923','A la suite de cette exhortation, ils supplièrent le Seigneur, demeurant en sa présence: en sorte que ceux mêmes qui offraient des holocaustes, les offraient au Seigneur étant revêtus de cilices et ayant de la cendre sur leurs têtes. Et tous priaient Dieu de tout leur cœur, afin qu''il visitât son peuple d''Israël.'),
('jdt',5,1,'crampon1923','On annonça à Holoferne, chef de l''armée des Assyriens, que les enfants d''Israël se préparaient à la résistance et qu''ils avaient fermé les passages des montagnes.'),
('jdt',5,2,'crampon1923','Transporté de fureur et brûlant de colère, il appela tous les princes de Moab et les chefs d''Ammon,'),
('jdt',5,3,'crampon1923','et il leur dit: " Dites-moi quel est ce peuple qui occupe les montagnes; quelles sont leurs villes, quelle en est la force et l''importance; quelle est leur puissance militaire, quel est leur nombre et quel chef les commande.'),
('jdt',5,4,'crampon1923','Pourquoi sont-ils les seuls, parmi tous les peuples de l''Occident, qui nous ont méprisés et ne sont pas sortis au-devant de nous pour nous recevoir en paix? "'),
('jdt',5,5,'crampon1923','Alors Achior, chef de tous les fils d''Ammon, lui répondit: " Si tu daignes m''écouter, mon seigneur, je dirai devant toi la vérité sur ce peuple qui habite dans les montagnes, et aucune parole fausse ne sortira de ma bouche.'),
('jdt',5,6,'crampon1923','Ce peuple est de la race des Chaldéens.'),
('jdt',5,7,'crampon1923','Il vint habiter d''abord en Mésopotamie, parce qu''ils ne voulaient pas suivre les dieux de leurs pères, qui étaient dans le pays des Chaldéens.'),
('jdt',5,8,'crampon1923','Ayant donc abandonné les rites de leurs ancêtres, qui rendaient honneur à une multitude de dieux,'),
('jdt',5,9,'crampon1923','ils adorèrent le seul Dieu du ciel, qui leur avait ordonné de sortir de leur pays et d''aller demeurer en Chanaan. La famine ayant envahi toute la terre, ils descendirent en Egypte, et là ils se multiplièrent de telle sorte pendant quatre cents ans, qu''ils devinrent une multitude innombrable.'),
('jdt',5,10,'crampon1923','Traités durement par le roi d''Egypte et forcés de bâtir ses villes avec du mortier et de la brique, ils invoquèrent le Seigneur, leur Dieu, qui frappa de différentes plaies tout le pays d''Egypte.'),
('jdt',5,11,'crampon1923','Les Egyptiens les chassèrent de chez eux, et la plaie cessa de les frapper; mais ils voulurent les prendre de nouveau et en faire encore une fois leurs esclaves.'),
('jdt',5,12,'crampon1923','Alors les Israélites s''enfuirent et Dieu ouvrit devant eux la mer, en sorte que les eaux devinrent solides comme une muraille de chaque côté, et qu''ils purent passer en marchant à pied sec au fond de la mer.'),
('jdt',5,13,'crampon1923','L''innombrable armée des Egyptiens les y ayant poursuivis, elle fut ensevelie sous les eaux, au point qu''il n''en resta pas un seul qui pût transmettre à la postérité le récit de cet événement.'),
('jdt',5,14,'crampon1923','Lorsque les Israélites furent sortis de la mer Rouge, ils occupèrent les déserts du mont Sinaï, dans lesquels aucun homme ne put jamais habiter, ni aucun fils d''homme fixer son séjour.'),
('jdt',5,15,'crampon1923','Là les fontaines amères se changèrent en eaux douces pour les désaltérer, et durant quarante ans ils reçurent du ciel leur nourriture.'),
('jdt',5,16,'crampon1923','Partout où ils s''avancèrent sans arc et sans flèche, sans bouclier et sans épée, leur Dieu combattit pour eux et remporta la victoire.'),
('jdt',5,17,'crampon1923','Et nul n''a jamais triomphé de ce peuple, si ce n''est quand il s''est éloigné du service du Seigneur, son Dieu.'),
('jdt',5,18,'crampon1923','Mais toutes les fois qu''ils ont adoré un autre Dieu que lui, ils ont été livrés au pillage, à l''épée et à l''opprobre.'),
('jdt',5,19,'crampon1923','Et toutes les fois qu''ils se sont repentis d''avoir abandonné le service de leur Dieu, le Dieu du ciel leur a donné la force de résister à leurs ennemis.'),
('jdt',5,20,'crampon1923','Enfin ils ont vaincu les rois des Chananéens, des Jébuséens, des Phérézéens, des Héthéens, des Hévéens, des Amorrhéens et tous les puissants d''Hésebon, et ils ont pris possession de leurs terres et de leurs villes.'),
('jdt',5,21,'crampon1923','Tant qu''ils ne péchèrent pas en présence de leur Dieu, le bonheur fut avec eux; car leur Dieu hait l''iniquité.'),
('jdt',5,22,'crampon1923','En effet, avant ces dernières années même, s''étant éloignés de la voie où Dieu leur avait commandé de marcher, ils furent taillés en pièces dans les combats par plusieurs nations, et beaucoup d''entre eux ont été emmenés captifs dans une terre étrangère.'),
('jdt',5,23,'crampon1923','Mais depuis peu, étant revenus au Seigneur, leur Dieu, ils se sont réunis après cette dispersion, ils ont occupé toutes ces montagnes, et ils possèdent de nouveau Jérusalem, où est leur sanctuaire.'),
('jdt',5,24,'crampon1923','Maintenant donc, mon seigneur, prends des informations: s''ils sont coupables de quelque iniquité devant leur Dieu, montons contre eux, car leur Dieu te les livrera certainement, et ils seront assujettis au joug de ta puissance. Mais si ce peuple n''a point offensé son Dieu, nous ne pourrons pas tenir devant eux, car leur Dieu les défendra, et nous deviendrons un objet de moquerie pour toute la terre. " Lorsqu''Achior eut cessé de parler, tous les grands d''Holoferne, en proie à la colère, songeaient à le tuer, se disant les uns aux autres: " Quel est cet homme qui ose dire que les enfants d''Israël peuvent résister au roi Nabuchodonosor et à ses armées, eux, des gens sans armes, sans force, étrangers à l''art de la guerre? Afin donc de faire voir à Achior qu''il nous trompe, gravissons ces montagnes, et lorsque les plus forts d''entre eux seront entre nos mains, nous le passerons avec eux au fil de l''épée: afin que toutes les nations sachent que Nabuchodonosor est le Dieu de la terre, et qu''il n''y en a point d''autre que lui. "'),
('jdt',6,1,'crampon1923','Lorsqu''ils eurent cessé de parler, Holoferne, transporté de fureur, dit à Achior:'),
('jdt',6,2,'crampon1923','" Puisque, t''érigeant en prophète, tu nous annonces que le peuple d''Israël sera défendu par son Dieu, je veux te montrer qu''il n''y a pas de Dieu que Nabuchodonosor.'),
('jdt',6,3,'crampon1923','Lorsque nous les aurons tous frappés comme un seul homme, tu périras toi-même par l''épée des Assyriens, et tout Israël sera anéanti avec toi.'),
('jdt',6,4,'crampon1923','Tu connaîtras ainsi que Nabuchodonosor est le maître de toute la terre. Et alors l''épée de mes soldats traversera tes flancs, tu tomberas percé parmi les blessés d''Israël, et tu ne respireras plus, jusqu''à ce que tu sois exterminé avec eux.'),
('jdt',6,5,'crampon1923','Si tu crois que ta prophétie soit véritable, que ton visage cesse d''être abattu; et que la pâleur qui le couvre s''éloigne de toi, si tu t''imagines que mes paroles ne puissent s''accomplir.'),
('jdt',6,6,'crampon1923','Mais pour que tu saches bien que tu périras avec eux, dès ce moment tu seras associé à ce peuple, afin que, lorsque mon épée leur fera subir le châtiment qu''ils méritent, tu tombes avec eux sous ma vengeance. "'),
('jdt',6,7,'crampon1923','Alors Holoferne donna ordre à ses serviteurs de saisir Achior, de le conduire vers Béthulie et de le livrer aux mains des enfants d''Israël.'),
('jdt',6,8,'crampon1923','Les serviteurs d''Holoferne, s''étant saisis de lui, traversèrent la plaine; mais lorsqu''ils furent près de la montagne, les frondeurs sortirent contre eux.'),
('jdt',6,9,'crampon1923','Les Assyriens se détournèrent en côtoyant la montagne, lièrent Achior à un arbre par les mains et les pieds et, l''ayant laissé là, ils revinrent vers leur maître.'),
('jdt',6,10,'crampon1923','Alors les enfants d''Israël, descendant de Béthulie, vinrent à lui et, l''ayant délié, ils le conduisirent à Béhtulie; puis ils l''amenèrent au milieu du peuple, et lui demandèrent pourquoi les Assyriens l''avaient abandonné ainsi garrotté.'),
('jdt',6,11,'crampon1923','— En ces jours-là, Ozias, fils de Micha, de la tribu de Siméon, et Charmi, nommé aussi Gothoniel, étaient les chefs qui commandaient dans la ville. —'),
('jdt',6,12,'crampon1923','Achior raconta donc, au milieu des anciens et en présence de tout le peuple, tout ce qu''il avait répondu aux questions d''Holoferne, comment les gens d''Holoferne avaient voulu le tuer à cause de ce qu''il avait dit,'),
('jdt',6,13,'crampon1923','et comment Holoferne lui-même avait ordonné, dans sa colère, qu''on le livrât pour cela entre les mains des Israélites, afin qu''après sa victoire sur les enfants d''Israël, il fit aussi mourir Achior par divers supplices, parce qu''il avait dit que le Dieu du ciel était leur défenseur.'),
('jdt',6,14,'crampon1923','Achior ayant achevé son récit, tout le peuple se prosterna le visage contre terre, adorant le Seigneur, et, mêlant leurs gémissements et leurs larmes, ils répandirent d''un même cœur leurs prières devant le Seigneur,'),
('jdt',6,15,'crampon1923','en disant: " Seigneur, Dieu du ciel et de la terre, voyez leur orgueil et considérez notre abaissement; tournez vos regards sur la face de vos saints, et montrez que vous n''abandonnez pas ceux qui mettent en vous leur confiance, et que vous abaissez ceux qui présument d''eux-mêmes et s''enorgueillissent de leur puissance. "'),
('jdt',6,16,'crampon1923','Lorsque le peuple eut cessé de pleurer et qu''il eut passé tout le jour en prières, ils consolèrent Achior,'),
('jdt',6,17,'crampon1923','en disant: " Le Dieu de nos pères, dont tu as proclamé la puissance, t''accordera en retour de voir plutôt leur ruine.'),
('jdt',6,18,'crampon1923','Et lorsque le Seigneur, notre Dieu, aura donné cette délivrance à ses serviteurs, que Dieu soit encore avec toi au milieu de nous, afin que, selon qu''il te plaira, tu vives avec nous, toi et tous les tiens. "'),
('jdt',6,19,'crampon1923','Quand l''assemblée se fut séparée, Ozias reçut Achior dans sa maison et lui offrit un grand festin.'),
('jdt',6,20,'crampon1923','Il y invita les anciens, et, le jeûne étant passé, ils mangèrent ensemble.'),
('jdt',6,21,'crampon1923','Puis tout le peuple se rassembla de nouveau et ils prièrent toute la nuit dans le lieu où ils étaient réunis, implorant le secours du Dieu d''Israël.'),
('jdt',7,1,'crampon1923','Le lendemain, Holoferne donna l''ordre à ses troupes de monter contre Béthulie.'),
('jdt',7,2,'crampon1923','Son armée était forte de cent vingt mille hommes de pied et de vingt-deux mille cavaliers, sans compter les hommes propres à la guerre qu''il avait faits prisonniers et les jeunes gens qu''il avait amenés des provinces et des villes.'),
('jdt',7,3,'crampon1923','Tous ensemble se préparèrent au combat contre les enfants d''Israël et, marchant le long de la montagne jusqu''au sommet qui regarde Dothaïn, ils campèrent depuis le lieu appelé Belma, jusqu''à Chelmon, qui est vis-à-vis d''Esdrelon.'),
('jdt',7,4,'crampon1923','Quand les enfants d''Israël aperçurent cette multitude, ils se prosternèrent contre terre et, se couvrant la tête de cendres, ils prièrent tous ensemble le Dieu d''Israël de faire éclater sa miséricorde sur son peuple.'),
('jdt',7,5,'crampon1923','Puis, ayant pris leurs armes de guerre, ils occupèrent les lieux où de petits sentiers permettaient de passer entre les montagnes, et ils y faisaient la garde jour et nuit.'),
('jdt',7,6,'crampon1923','En parcourant les environs, Holoferne découvrit une fontaine en dehors de la ville, du côté du midi, laquelle y conduisait ses eaux par un aqueduc, et il fit couper cet aqueduc.'),
('jdt',7,7,'crampon1923','Cependant il y avait, non loin des murs, d''autres sources où les assiégés venaient puiser à la dérobée un peu d''eau, plutôt, ce semble, pour soulager leur soif que pour l''apaiser.'),
('jdt',7,8,'crampon1923','Mais les fils d''Ammon et de Moab vinrent trouver Holoferne, en disant: " Les enfants d''Israël n''ont confiance ni dans leurs lances ni dans leurs flèches; mais ces montagnes les défendent et ces collines suspendues sur des précipices font leur force.'),
('jdt',7,9,'crampon1923','Afin donc que vous puissiez triompher d''eux sans livrer bataille, placez près des sources des gardes qui les empêchent d''y puiser de l''eau; vous les ferez périr ainsi sans coup férir, ou bien, épuisés par la soif, ils rendront leur ville, qu''ils regardent comme imprenable parce qu''elle est placée sur les montagnes. "'),
('jdt',7,10,'crampon1923','Le conseil plut à Holoferne et à ses officiers, et il fit mettre un poste de cent hommes autour de chaque fontaine.'),
('jdt',7,11,'crampon1923','Cette garde ayant été faite pendant vingt jours, toutes les citernes et les réservoirs d''eau furent à sec pour tous les habitants de Béthulie, de sorte qu''il ne restait pas dans la ville de quoi rassasier leur soif même un seul jour, car on distribuait chaque jour au peuple l''eau par mesure.'),
('jdt',7,12,'crampon1923','Alors tous les hommes et les femmes, les jeunes gens et les enfants se rassemblèrent auprès d''Ozias, et d''une commune voix'),
('jdt',7,13,'crampon1923','tous lui dirent: " Que Dieu soit juge entre toi et nous, car tu as agi pour notre malheur en refusant de faire des propositions de paix aux Assyriens; et c''est pour cela que Dieu nous a livrés entre leurs mains.'),
('jdt',7,14,'crampon1923','C''est pourquoi il n''y a personne qui vienne à notre secours, alors que la soif et une grande misère nous font tomber en défaillance sous leurs regards.'),
('jdt',7,15,'crampon1923','Maintenant donc, assemble tous ceux qui sont dans la ville, afin que nous nous rendions tous volontairement aux gens d''Holoferne.'),
('jdt',7,16,'crampon1923','Car il vaut mieux pour nous avoir la vie sauve et bénir Dieu dans la captivité, que de mourir et d''être en opprobre à tous les hommes, après avoir vu nos femmes et nos enfants périr sous nos yeux.'),
('jdt',7,17,'crampon1923','Prenant aujourd''hui à témoin le ciel et la terre, et le Dieu de nos pères, qui nous châtie selon nos péchés, nous te conjurons de livrer incessamment la ville entre les mains des soldats d''Holoferne, afin que nous trouvions une prompte mort par le tranchant du glaive, au lieu d''une mort lente dans les ardeurs de la soif. "'),
('jdt',7,18,'crampon1923','Lorsqu''ils eurent ainsi parlé, il se fit des lamentations et de grands cris dans toute l''assemblée, et tous d''une voix, pendant de nombreuses heures, ils crièrent vers Dieu, en disant:'),
('jdt',7,19,'crampon1923','" Nous avons péché avec nos pères, nous avons été infidèles, nous avons commis l''iniquité.'),
('jdt',7,20,'crampon1923','Vous, qui êtes miséricordieux, ayez pitié de nous; ou bien tirez vengeance de nos crimes en nous châtiant vous-même, et ne livrez pas ceux qui vous glorifient à un peuple qui ne vous connaît point,'),
('jdt',7,21,'crampon1923','afin qu''on ne dise pas parmi les nations: Où est leur Dieu? "'),
('jdt',7,22,'crampon1923','Après s''être fatigués à force de crier et de pleurer, ils se turent.'),
('jdt',7,23,'crampon1923','Alors Ozias se leva, baigné de larmes, et dit: " Ayez bon courage, mes frères, et attendons pendant cinq jours la miséricorde du Seigneur.'),
('jdt',7,24,'crampon1923','Car peut-être mettra-t-il fin à sa colère et donnera-t-il gloire à son nom.'),
('jdt',7,25,'crampon1923','Ces cinq jours passés, si le secours n''est pas venu, nous ferons ce que vous nous avez proposé. "'),
('jdt',7,26,'crampon1923',''),
('jdt',7,27,'crampon1923',''),
('jdt',7,28,'crampon1923',''),
('jdt',7,29,'crampon1923',''),
('jdt',7,30,'crampon1923',''),
('jdt',7,31,'crampon1923',''),
('jdt',7,32,'crampon1923',''),
('jdt',8,1,'crampon1923','Ces paroles furent rapportées à Judith, une veuve, fille de Mérari, fils d''Idox, fils de Joseph, fils d''Ozias, fils d''Elaï, fils de Jamnor, fils de Gédéon, fils de Raphaïm, fils d''Achitob, fils de Melchias, fils d''Enan, fils de Nathanias, fils de Salathiel, fils de Siméon, fils d''Israël.'),
('jdt',8,2,'crampon1923','Son mari, appelé Manassès, était mort au temps de la moisson de l''orge.'),
('jdt',8,3,'crampon1923','Comme il surveillait les moissonneurs, qui liaient les gerbes dans les champs, l''ardeur du soleil le frappa à la tête, et il mourut dans Béthulie, sa ville, et il y fut inhumé avec ses pères.'),
('jdt',8,4,'crampon1923','Il y avait déjà trois ans et six mois que Judith était restée veuve.'),
('jdt',8,5,'crampon1923','Elle s''était construit, sur le toit de sa maison, une chambre retirée, où elle demeurait enfermée avec ses servantes.'),
('jdt',8,6,'crampon1923','Les reins couverts d''un cilice, elle jeûnait tous les jours de sa vie, excepté les jours de sabbat et de nouvelle lune et les fêtes de la maison d''Israël.'),
('jdt',8,7,'crampon1923','Elle était très belle de figure, et son mari lui avait laissé de grandes richesses, de nombreux serviteurs et des domaines remplis de troupeaux de bœufs et de brebis.'),
('jdt',8,8,'crampon1923','Elle était en grande estime auprès de tous, parce qu''elle craignait beaucoup le Seigneur, et il n''y avait personne qui dit d''elle une parole de blâme.'),
('jdt',8,9,'crampon1923','Ayant donc appris qu''Ozias avait promis de livrer la ville passé le cinquième jour, elle envoya vers les anciens du peuple Chabri et Charmi.'),
('jdt',8,10,'crampon1923','Ils se rendirent auprès d''elle, et elle leur dit: " Comment Ozias a-t-il pu dire qu''il livrerait la ville aux Assyriens, si dans cinq jours, il ne vous arrive pas de secours?'),
('jdt',8,11,'crampon1923','Et qui êtes-vous, pour mettre ainsi le Seigneur à l''épreuve?'),
('jdt',8,12,'crampon1923','Ce n''est pas là une parole qui attire la miséricorde, mais plutôt qui excite la colère et allume la fureur.'),
('jdt',8,13,'crampon1923','Vous avez fixé au Seigneur un terme dans le quel il doit exercer sa miséricorde, et vous lui avez marqué un jour selon votre bon plaisir!'),
('jdt',8,14,'crampon1923','Mais parce que le Seigneur est patient, faisons pénitence de cette faute, et implorons son pardon en versant des larmes.'),
('jdt',8,15,'crampon1923','Car Dieu ne menace point à la manière de l''homme, et il ne s''enflamme point de colère comme un fils d''homme.'),
('jdt',8,16,'crampon1923','Humilions donc nos âmes devant lui, et mettons en nous un esprit d''humilité, comme il convient à ses serviteurs.'),
('jdt',8,17,'crampon1923','Prions le Seigneur avec larmes de nous faire sentir, en la manière qu''il lui plaira, les effets de sa miséricorde, afin que, comme l''orgueil de nos ennemis a jeté le trouble dans notre cœur, ainsi notre humilité nous devienne un sujet de gloire.'),
('jdt',8,18,'crampon1923','Car nous n''avons pas imité les péchés de nos pères qui ont abandonné leur Dieu et adoré des dieux étrangers.'),
('jdt',8,19,'crampon1923','C''est à cause de ce crime qu''ils ont été livrés au glaive, au pillage et à la moquerie de leurs ennemis; mais nous, nous ne connaissons pas d''autres Dieu que lui.'),
('jdt',8,20,'crampon1923','Attendons humblement sa consolation, et il vengera notre sang sur nos ennemis qui nous affligent; il humiliera toutes les nations qui s''élèvent contre nous, et il les couvrira de confusion, lui, le Seigneur notre Dieu.'),
('jdt',8,21,'crampon1923','Et maintenant, mes frères, puisque vous êtes les anciens du peuple de Dieu, et que leur vie dépend de vous, relevez leurs cœurs par vos paroles, pour qu''ils se souviennent que nos pères ont été éprouvés afin que l''on connût s''ils servaient véritablement leur Dieu.'),
('jdt',8,22,'crampon1923','Ils doivent se rappeler comment Abraham, notre père, a été tenté, et comment, éprouvé par beaucoup de tribulations, il est devenu l''ami de Dieu.'),
('jdt',8,23,'crampon1923','De même Isaac, de même Jacob, de même Moïse et tous ceux qui ont plu à Dieu, ont passé par beaucoup d''afflictions en demeurant fidèles.'),
('jdt',8,24,'crampon1923','Mais ceux qui n''ont pas accepté ces épreuves avec la crainte du Seigneur, et qui ont donné cours à leur impatience et à d''injurieux murmures contre le Seigneur,'),
('jdt',8,25,'crampon1923','ceux-là, l''exterminateur les a frappés de mort, et les serpents les ont fait périr.'),
('jdt',8,26,'crampon1923','Ne nous laissons donc pas aller à l''impatience à cause des maux que nous souffrons.'),
('jdt',8,27,'crampon1923','Mais estimons que ces tourments, moindres que nos péchés, sont les verges dont le Seigneur nous châtie, comme ses serviteurs, pour nous amender, et croyons que ce n''est pas pour notre perte qu''ils nous ont été envoyés. "'),
('jdt',8,28,'crampon1923','Ozias et les anciens lui répondirent: " Tout ce que tu as dit est vrai, et il n''y a rien à reprendre dans tes paroles.'),
('jdt',8,29,'crampon1923','Maintenant donc, prie Dieu pour nous, car tu es une femme sainte et craignant Dieu. "'),
('jdt',8,30,'crampon1923','Et Judith leur dit: " Comme vous reconnaissez que ce que j''ai pu dire est de Dieu,'),
('jdt',8,31,'crampon1923','éprouvez si ce que j''ai résolu de faire est aussi de lui, et priez que Dieu me donne la force de réaliser mon dessein.'),
('jdt',8,32,'crampon1923','Vous vous tiendrez cette nuit à la porte, et je sortirai, avec ma compagne; et priez afin que dans cinq jours, comme vous l''avez dit, le Seigneur regarde son peuple d''Israël.'),
('jdt',8,33,'crampon1923','Mais je ne veux point que vous cherchiez à savoir ce que j''entreprends; jusqu''à ce que je revienne vous en donner des nouvelles, qu''on ne fasse pas autre chose que de prier pour moi le Seigneur notre Dieu. "'),
('jdt',8,34,'crampon1923','Ozias, le prince de Juda, lui dit: " Va en paix et que le Seigneur soit avec toi pour tirer vengeance de nos ennemis! " Et l''ayant quittée, ils s''en allèrent.'),
('jdt',8,35,'crampon1923',''),
('jdt',8,36,'crampon1923',''),
('jdt',9,1,'crampon1923','Lorsqu''ils furent partis, Judith entra dans son oratoire, et, revêtue d''un cilice, la tête couverte de cendre, elle se prosterna devant le Seigneur et l''invoqua, en disant:'),
('jdt',9,2,'crampon1923','" Seigneur, Dieu de mon père Siméon, qui lui avez donné l''épée pour se venger des étrangers qui, entraînés par la passion, avaient violé une vierge et lui avaient fait outrage pour sa confusion;'),
('jdt',9,3,'crampon1923','vous qui avez livré leurs femmes aux ravisseurs, leurs filles à l''esclavage et toutes leurs dépouilles en partage à vos serviteurs brûlants de zèle pour votre cause, assistez-moi, je vous en prie, Seigneur, mon Dieu, secourez une veuve.'),
('jdt',9,4,'crampon1923','C''est vous qui avez opéré les merveilles des temps anciens, et qui avez formé le dessein de celles qui ont suivi, et elles se sont accomplies parce que vous l''avez voulu.'),
('jdt',9,5,'crampon1923','Toutes vos voies sont tracées d''avance, et vous avez disposé vos jugements par votre prévision.'),
('jdt',9,6,'crampon1923','Regardez en ce moment le camp des Assyriens, comme vous avez daigné autrefois regarder celui des Egyptiens, lorsqu''ils poursuivaient les armes à la main vos serviteurs, se confiant dans leurs chars, dans leurs cavaliers et dans la multitude de leurs combattants.'),
('jdt',9,7,'crampon1923','Mais vous avez regardé leur camp, et les ténèbres leur ont ôté leur force.'),
('jdt',9,8,'crampon1923','L''abîme a retenu leurs pieds, et les eaux les ont engloutis.'),
('jdt',9,9,'crampon1923','Qu''il en soit de même, Seigneur, de ceux-ci, qui se confient dans leur multitude, dans leurs chars, dans leurs javelots, dans leurs boucliers et dans leurs flèches, et qui sont fiers de leurs lances.'),
('jdt',9,10,'crampon1923','Ils ne savent pas que c''est vous qui êtes notre Dieu, vous qui dès le commencement terrassiez les armées et dont le nom est Seigneur.'),
('jdt',9,11,'crampon1923','Levez votre bras, comme aux siècles passés; brisez leur puissance par votre puissance; que leur force tombe devant votre colère, eux qui se promettent de violer votre sanctuaire, de profaner le tabernacle de votre nom et d''abattre de leur épée les cornes de votre autel.'),
('jdt',9,12,'crampon1923','Faites, Seigneur, que l''orgueil de cet homme soit abattu par sa propre épée.'),
('jdt',9,13,'crampon1923','Qu''il se prenne aux lacs de son regard sur moi, et frappez-le par les douces paroles de mes lèvres.'),
('jdt',9,14,'crampon1923','Mettez dans mon cœur assez de fermeté pour le mépriser, assez de force pour le perdre. Ce sera pour votre nom une gloire mémorable qu''il soit abattu par la main d''une femme. Car votre puissance, Seigneur, n''est point dans le grand nombre, et votre volonté ne dépend pas de la force des chevaux; et dès le commencement les superbes ne vous ont pas plu, mais vous avez toujours eu pour agréable la prière des hommes humbles et doux. Dieu du ciel, Créateur des eaux et Seigneur de toute la création, exaucez-moi, malheureuse, qui vous supplie et qui mets ma confiance en votre miséricorde. Souvenez-vous, Seigneur, de votre alliance, donnez la parole à ma bouche, la force au dessein qui est dans mon cœur, afin que votre maison conserve la sainteté dont vous l''avez revêtue, et que toutes les nations reconnaissent que vous êtes Dieu, et qu''il n''y en a point d''autre que vous. "'),
('jdt',10,1,'crampon1923','Lorsqu''elle eut achevé sa prière au Seigneur, Judith se leva du lieu où elle était prosternée contre terre devant le Seigneur.'),
('jdt',10,2,'crampon1923','Elle appela sa servante et, étant descendue dans sa maison, elle ôta son cilice et se dépouilla des vêtements de son veuvage.'),
('jdt',10,3,'crampon1923','Elle se lava le corps, s''oignit de la myrrhe la plus fine, disposa sa chevelure, mit le turban sur sa tête, revêtit ses vêtements de fête, attacha des sandales à ses pieds, prit ses bracelets, son collier, ses pendants d''oreilles, et ses anneaux, en un mot, se para de tous ses ornements.'),
('jdt',10,4,'crampon1923','Le Seigneur releva encore son éclat, parce que tout cet ajustement avait son principe, non dans la volupté, mais dans la vertu; c''est pourquoi le Seigneur augmenta sa beauté de telle sorte qu''elle brillât aux yeux de tous d''un éclat incomparable.'),
('jdt',10,5,'crampon1923','Puis elle fit porter à sa servante une outre de vin, un vase d''huile, de la farine grillée, des fruits secs, du pain et du fromage, et elle partit.'),
('jdt',10,6,'crampon1923','Arrivée, elle et sa servante, à la porte de la ville, elle trouva Ozias et les anciens qui l''attendaient.'),
('jdt',10,7,'crampon1923','En la voyant, ils furent ravis d''admiration pour sa beauté.'),
('jdt',10,8,'crampon1923','Cependant ils ne lui adressèrent aucune question, et la laissèrent passer, en disant: " Que le Dieu de nos pères te donne sa grâce; qu''il affermisse par sa puissance tous les desseins qui sont dans ton cœur, afin que Jérusalem soit glorifiée à cause de toi, et que ton nom figure parmi ceux des saints et des justes. "'),
('jdt',10,9,'crampon1923','Ceux qui étaient présents répondirent tous d''une seule voix: " Ainsi soit-il! Ainsi soit-il! "'),
('jdt',10,10,'crampon1923','Et Judith franchit les portes, elle et sa servante, en priant le Seigneur.'),
('jdt',10,11,'crampon1923','Comme elle descendait la montagne, au lever du jour, les postes avancés des Assyriens la rencontrèrent et l''arrêtèrent, en disant: " D''où viens-tu, et où vas-tu? "'),
('jdt',10,12,'crampon1923','Elle répondit: " Je suis une fille des Hébreux, et je me suis enfuie du milieu d''eux, ayant reconnu qu''ils vous seront livrés en proie, parce qu''ils vous ont méprisés et qu''ils n''ont pas voulu se rendre à vous volontairement, pour trouver grâce devant vous.'),
('jdt',10,13,'crampon1923','C''est pourquoi j''ai dit en moi-même: Je me présenterai devant le prince Holoferne, pour lui découvrir leurs secrets et lui indiquer un accès par où il pourra les prendre sans perdre un seul homme de son armée. "'),
('jdt',10,14,'crampon1923','Lorsque ces hommes eurent entendu ses paroles, ils considérèrent son visage, et la surprise était dans leurs yeux, tant ils admiraient sa grande beauté:'),
('jdt',10,15,'crampon1923','" Tu as sauvé ta vie, lui dirent-ils, en prenant cette résolution de descendre vers notre seigneur.'),
('jdt',10,16,'crampon1923','Tu peux être assurée que, lorsque tu paraîtras devant lui, il te traitera bien et que tu seras très agréable à son cœur. " Puis, l''ayant conduite à la tente d''Holoferne, ils l''annoncèrent.'),
('jdt',10,17,'crampon1923','Dès qu''elle fut entrée en sa présence, Holoferne fut aussitôt pris par les yeux.'),
('jdt',10,18,'crampon1923','Ses officiers lui dirent: " Qui donc pourrait mépriser le peuple des Hébreux qui a de si belles femmes? Ne méritent-elles pas bien que, pour les posséder, nous lui fassions la guerre? "'),
('jdt',10,19,'crampon1923','Judith vit Holoferne assis sous son pavillon, dont le tissu de pourpre et d''or était orné d''émeraudes et de pierres précieuses.'),
('jdt',10,20,'crampon1923','Ayant arrêté les yeux sur son visage, elle l''adora en se prosternant jusqu''à terre. Aussitôt, sur l''ordre de leur maître, les serviteurs d''Holoferne la relevèrent.'),
('jdt',10,21,'crampon1923',''),
('jdt',10,22,'crampon1923',''),
('jdt',10,23,'crampon1923',''),
('jdt',11,1,'crampon1923','Alors Holoferne lui dit: " Rassure-toi et bannis la crainte de ton cœur, car je n''ai jamais fait de mal à quiconque a voulu servir le roi Nabuchodonosor.'),
('jdt',11,2,'crampon1923','Si ton peuple ne m''avait pas méprisé, je n''aurais pas levé ma lance contre lui.'),
('jdt',11,3,'crampon1923','Maintenant, dis-moi pourquoi tu t''es éloignée d''eux et tu as pris le parti de venir vers nous? "'),
('jdt',11,4,'crampon1923','Judith lui répondit: " Accueille les paroles de ta servante, car si tu suis les paroles de ta servante, le Seigneur réalisera pleinement ses desseins sur toi,'),
('jdt',11,5,'crampon1923','aussi vrai que Nabuchodonosor, le roi de la terre, est vivant, et que sa puissance est vivante, cette puissance dont tu es dépositaire pour le châtiment de tous ceux qui sont égarés; car non seulement les hommes sont amenés par toi à le servir, mais les animaux mêmes des champs lui obéissent.'),
('jdt',11,6,'crampon1923','En effet, la sagesse de ton esprit est célèbre dans toutes les nations; tout le monde sait que dans tout son royaume tu es le seul bon et puissant, et ton gouvernement est vanté dans toutes les provinces.'),
('jdt',11,7,'crampon1923','On sait aussi ce qu''a dit Achior, et on n''ignore pas de quelle manière tu as ordonné de le traiter.'),
('jdt',11,8,'crampon1923','Car il est certain que notre Dieu est tellement offensé par les péchés de son peuple, qu''il lui a fait annoncer par ses prophètes qu''il allait le livrer à ses ennemis à cause de ses infidélités.'),
('jdt',11,9,'crampon1923','Et parce que les enfants d''Israël savent qu''ils ont offensé leur Dieu, ils tremblent de frayeur devant toi.'),
('jdt',11,10,'crampon1923','En outre, la famine les presse, et, les réservoirs d''eau étant desséchés, ils sont déjà à compter parmi les morts.'),
('jdt',11,11,'crampon1923','Ils ont même pris la résolution de tuer leur bétail et d''en boire le sang.'),
('jdt',11,12,'crampon1923','Il n''est pas jusqu''aux choses consacrées au Seigneur, leur Dieu, auxquelles Dieu leur a défendu de toucher, le blé, le vin et l''huile des dîmes et des prémices, qu''ils n''aient résolu de faire servir à leur usage, osant se nourrir de choses qu''il ne leur est pas même permis de toucher de leurs mains. Puisqu''ils agissent ainsi, il est certain qu''ils seront livrés à la ruine.'),
('jdt',11,13,'crampon1923','Voilà ce que je sais, moi, ta servante, et j''ai fui loin d''eux, et le Seigneur m''a envoyée t''en informer.'),
('jdt',11,14,'crampon1923','Car moi, ta servante, je sers Dieu, maintenant même que je suis auprès de toi; et ta servante sortira du camp pour aller prier Dieu.'),
('jdt',11,15,'crampon1923','Et il me fera connaître quand il doit les châtier pour leur péché, et je viendrai te l''annoncer. Je te conduirai alors à travers la Judée jusqu''à Jérusalem, et tu trouveras tout le peuple d''Israël comme des brebis qui n''ont plus de pasteur, et il n''y aura pas même un chien qui aboie contre toi.'),
('jdt',11,16,'crampon1923','C''est la prescience de Dieu qui m''a révélé ces choses;'),
('jdt',11,17,'crampon1923','et comme il est irrité contre eux, j''ai reçu mission de te les annoncer. "'),
('jdt',11,18,'crampon1923','Tout ce discours plut à Holoferne et à ses serviteurs. Ils admiraient la sagesse de Judith et se disaient les uns aux autres:'),
('jdt',11,19,'crampon1923','" Il n''existe pas sur la terre de femme qui soit semblable à celle-ci pour la prestance, pour la beauté et pour la sagesse de ses discours. " Holoferne lui dit:'),
('jdt',11,20,'crampon1923','" Dieu a bien fait de t''envoyer devant ce peuple, pour nous le livrer entre les mains.'),
('jdt',11,21,'crampon1923','Comme ta proposition est bonne, si ton Dieu fait cela pour moi, il sera aussi mon Dieu, et toi, tu seras grande dans la maison de Nabuchodonosor, et ton nom deviendra célèbre dans toute la terre. "'),
('jdt',11,22,'crampon1923',''),
('jdt',11,23,'crampon1923',''),
('jdt',12,1,'crampon1923','Alors Holoferne ordonna qu''on fît entrer Judith sous la tente où étaient déposés ses trésors, afin qu''elle y demeurât et il régla ce qu''on devait lui donner de sa table.'),
('jdt',12,2,'crampon1923','Judith lui répondit: " Je ne puis manger maintenant des choses que tu commandes qu''on me donne, de peur de me rendre coupable d''un péché; je mangerai de ce que j''ai apporté pour moi. "'),
('jdt',12,3,'crampon1923','Holoferne lui dit: " Quand les vivres que tu as apportés seront épuisés, que ferons-nous pour toi? "'),
('jdt',12,4,'crampon1923','" Seigneur, répondit Judith, je jure par ta vie que ta servante n''aura pas consommé toutes ces provisions, avant que Dieu ait réalisé par ma main le dessein que j''ai formé. " Et ses serviteurs l''introduisirent dans la tente qu''il avait désignée.'),
('jdt',12,5,'crampon1923','En y entrant, elle demanda qu''on lui accordât la faculté de sortir, la nuit et avant le jour, pour aller prier et invoquer le Seigneur.'),
('jdt',12,6,'crampon1923','Et Holoferne ordonna à ses serviteurs de la laisser sortir et entrer à son gré, pendant trois jours pour adorer son Dieu.'),
('jdt',12,7,'crampon1923','Elle sortait donc chaque nuit dans la vallée de Béthulie, et elle se lavait dans une fontaine.'),
('jdt',12,8,'crampon1923','Lorsqu''elle était remontée, elle priait le Seigneur, Dieu d''Israël, de diriger sa voie pour la délivrance de son peuple.'),
('jdt',12,9,'crampon1923','Puis, rentrant dans sa tente, elle y demeurait pure jusqu''à ce qu''elle prît sa nourriture vers le soir.'),
('jdt',12,10,'crampon1923','Le quatrième jour, Holoferne donna un festin à ses serviteurs, et il dit à Vagao, son eunuque: " Va, et persuade à cette Juive de consentir de bon cœur à habiter avec moi.'),
('jdt',12,11,'crampon1923','Ce serait une honte pour un homme, chez les Assyriens, qu''une femme se moquât de lui et le quittât sans avoir cédé à ses désirs. "'),
('jdt',12,12,'crampon1923','Alors Vagao entra chez Judith et lui dit: " Que la bonne fille ne craigne point de venir auprès de mon seigneur, pour être honorée en sa présence, pour manger avec lui et boire du vin avec joie. "'),
('jdt',12,13,'crampon1923','" Qui suis-je, répondit Judith, pour résister à mon seigneur?'),
('jdt',12,14,'crampon1923','Tout ce qui est bon et excellent à ses yeux, je le ferai; et tout ce qu''il préfère sera pour moi le meilleur, tous les jours de ma vie. "'),
('jdt',12,15,'crampon1923','Et elle se leva et, s''étant parée de ses ornements, elle entra et se présenta devant Holoferne.'),
('jdt',12,16,'crampon1923','Le cœur d''Holoferne fut agité, parce qu''il brûlait de désir pour elle. Holoferne lui dit:'),
('jdt',12,17,'crampon1923','" Bois donc et mange avec joie, car tu as trouvé grâce devant moi. "'),
('jdt',12,18,'crampon1923','Judith répondit: " Je boirai, seigneur, car mon âme est plus honorée en ce jour qu''elle ne l''a été tous les jours de ma vie. "'),
('jdt',12,19,'crampon1923','Et prenant ce que sa servante lui avait préparé, elle mangea et but devant lui.'),
('jdt',12,20,'crampon1923','Holoferne fut transporté de joie à cause d''elle, et il but du vin à l''excès, plus qu''il n''en avait jamais bu dans sa vie.'),
('jdt',13,1,'crampon1923','Quand le soir fut venu, les serviteurs d''Holoferne se hâtèrent de regagner leurs tentes; et Vagao, ayant fermé les portes de la chambre, s''en alla.'),
('jdt',13,2,'crampon1923','Tous étaient appesantis par le vin,'),
('jdt',13,3,'crampon1923','et Judith restait seule dans la chambre.'),
('jdt',13,4,'crampon1923','Holoferne était étendu sur son lit, plongé dans l''assoupissement d''une complète ivresse.'),
('jdt',13,5,'crampon1923','Judith avait dit à sa servante de se tenir dehors devant la chambre, et de faire le guet.'),
('jdt',13,6,'crampon1923','Debout devant le lit, Judith pria quelque temps avec larmes, remuant les lèvres en silence:'),
('jdt',13,7,'crampon1923','" Seigneur, Dieu d''Israël, disait-elle, fortifiez-moi, et jetez en ce moment un regard favorable sur l''œuvre de mes mains, afin que, selon votre promesse, vous releviez votre ville de Jérusalem, et que j''achève ce que j''ai cru possible par votre assistance. "'),
('jdt',13,8,'crampon1923','Ayant dit ces paroles, elle s''approcha de la colonne qui était à la tête du lit d''Holoferne, détacha son épée qui y était suspendue et,'),
('jdt',13,9,'crampon1923','l''ayant tirée du fourreau, elle saisit les cheveux d''Holoferne, en disant: " Seigneur Dieu, fortifiez-moi à cette heure! "'),
('jdt',13,10,'crampon1923','Et de deux coups sur la nuque, elle lui trancha la tête. Puis elle détacha le rideau des colonnes et roula par terre le corps décapité;'),
('jdt',13,11,'crampon1923','et, sortant sans retard, elle donna la tête d''Holoferne à sa servante, en lui ordonnant de la mettre dans son sac.'),
('jdt',13,12,'crampon1923','Elles partirent ensuite toutes deux, selon leur coutume, comme pour aller prier, et, après avoir traversé le camp et contourné la vallée, elles arrivèrent à la porte de la ville.'),
('jdt',13,13,'crampon1923','Judith cria de loin aux gardiens des murailles: " Ouvrez la porte, car Dieu est avec nous, et il a signalé sa puissance en faveur d''Israël. "'),
('jdt',13,14,'crampon1923','Ayant entendu ses paroles, les gardes appelèrent les anciens de la ville.'),
('jdt',13,15,'crampon1923','Aussitôt tous les habitants accoururent vers elle, depuis le plus petit jusqu''au plus grand, car ils commençaient à désespérer de son retour.'),
('jdt',13,16,'crampon1923','Allumant des flambeaux, ils se rassemblèrent tous autour d''elle. Judith, montant sur un lieu élevé, commanda qu''on fit silence; lorsque tous se furent tus,'),
('jdt',13,17,'crampon1923','elle leur dit: " Louez le Seigneur, notre Dieu, qui n''a point abandonné ceux qui espéraient en lui.'),
('jdt',13,18,'crampon1923','Par moi, sa servante, il a accompli ses promesses de miséricorde en faveur de la maison d''Israël, et il a tué cette nuit par ma main l''ennemi de son peuple. "'),
('jdt',13,19,'crampon1923','Alors, tirant du sac la tête d''Holoferne, elle la leur montra en disant: " Voici la tête d''Holoferne, chef de l''armée des Assyriens, et voici le rideau sous lequel il était couché dans son ivresse, lorsque le Seigneur notre Dieu l''a frappé par la main d''une femme.'),
('jdt',13,20,'crampon1923','Aussi vrai que le Seigneur est vivant, son ange m''a gardée à mon départ, durant mon séjour au milieu d''eux, et à mon retour, et le Seigneur n''a pas permis que sa servante fût souillée; mais il m''a rendue à vous sans aucune tache de péché, toute joyeuse de sa victoire, de ma conservation et de votre délivrance. Vous tous, chantez ses louanges, car il est bon, car sa miséricorde dure à jamais! " Tous, adorant le Seigneur, lui dirent: " Le Seigneur t''a bénie dans sa force, car par toi il a réduit à néant tous nos ennemis. " Ozias, le prince du peuple d''Israël, lui dit: " Ma fille, tu es bénie par le Seigneur, le Dieu très haut, plus que toutes les femmes qui sont sur la terre. Béni soit le Seigneur, créateur du ciel et de la terre, qui a conduit ta main pour trancher la tête au plus grand de nos ennemis! Il a rendu aujourd''hui ton nom si glorieux, que ta louange ne disparaîtra pas de la bouche des hommes, qui se souviendront éternellement de la puissance du Seigneur; car, en leur faveur, tu n''as pas épargné ta vie en voyant les souffrances et la détresse de ta race, mais tu nous a sauvés de la ruine en marchant dans la droiture en présence de notre Dieu. " Et tout le peuple répondit: " Ainsi soit-il! Ainsi soit-il! " Ensuite on fit venir Achior, et Judith lui dit: " Le Dieu d''Israël, à qui tu as rendu ce témoignage qu''il tire vengeance de ses ennemis, a tranché lui-même cette nuit, par ma main, la tête du chef de tous les infidèles. Et pour te convaincre qu''il en est ainsi, voici la tête d''Holoferne qui, dans l''insolence de son orgueil, méprisait le Dieu d''Israël et t''a menacé de mort, en disant: Lorsque le peuple d''Israël sera vaincu, je te ferai passer au fil de l''épée. " A la vue de la tête d''Holoferne, Achior frissonna d''horreur; il tomba le visage contre terre, et s''évanouit. Lorsqu''il eut repris ses sens et fut revenu à lui, il se prosterna aux pieds de Judith et lui dit: " Sois proclamée bénie de ton Dieu dans toutes les tentes de Jacob! Parmi tous les peuples qui entendront ton nom, le Dieu d''Israël sera glorifié à cause de toi. "'),
('jdt',14,1,'crampon1923','Alors Judith dit à tout le peuple: " Ecoutez-moi, mes frères, suspendez cette tête au haut de nos murailles.'),
('jdt',14,2,'crampon1923','Et, quand le soleil sera levé, que chacun prenne ses armes; puis sortez avec impétuosité, non pour descendre seulement dans la vallée, mais comme pour faire une attaque générale.'),
('jdt',14,3,'crampon1923','Il faudra bien alors que les avant-postes s''enfuient vers leur général, afin de le réveiller pour le combat.'),
('jdt',14,4,'crampon1923','Et lorsque leurs chefs auront couru à la tente d''Holoferne et qu''ils le trouveront décapité, baigné dans son sang, l''épouvante s''emparera d''eux.'),
('jdt',14,5,'crampon1923','Et lorsque vous les verrez fuir, mettez-vous hardiment à leur poursuite, car le Seigneur les écrasera sous vos yeux. "'),
('jdt',14,6,'crampon1923','Alors Achior, voyant la puissance qu''exerçait le Dieu d''Israël, abandonna le culte des nations; il crut en Dieu, se circoncit, et fut incorporé au peuple d''Israël, ainsi que tous ses descendants, jusqu''au temps présent.'),
('jdt',14,7,'crampon1923','Dès que le jour parut, les habitants de Béthulie suspendirent aux murailles la tête d''Holoferne, et, chaque homme ayant pris ses armes, ils sortirent de la ville avec un grand tumulte et de grands cris.'),
('jdt',14,8,'crampon1923','Les avant-postes s''en étant aperçus coururent à la tente d''Holoferne.'),
('jdt',14,9,'crampon1923','Ceux qui étaient dans la tente vinrent et firent du bruit à la porte de la chambre à coucher pour l''éveiller, augmentant à dessein le tumulte, afin qu''Holoferne fût tiré de son sommeil par tout ce bruit, sans qu''un des siens eût besoin de le réveiller.'),
('jdt',14,10,'crampon1923','Car personne n''osait, ni en frappant, ni en entrant, ouvrir la porte de la chambre à coucher du plus grand des Assyriens.'),
('jdt',14,11,'crampon1923','Mais ses généraux, ses commandants et tous les officiers de l''armée du roi des Assyriens étant venus, dirent aux chambellans:'),
('jdt',14,12,'crampon1923','" Entrez et éveillez-le, car ces rats sont sortis de leurs trous et ont osé nous provoquer au combat. "'),
('jdt',14,13,'crampon1923','Alors, Vagao, étant entré dans la chambre, s''arrêta devant le rideau, et il frappa des mains, car il s''imaginait que son maître dormait avec Judith.'),
('jdt',14,14,'crampon1923','Mais quand, prêtant l''oreille, il n''entendit aucun des mouvements d''un homme qui eût été couché là, il s''approcha du rideau et, l''ayant levé, il aperçut le cadavre d''Holoferne étendu par terre, sans tête, et baigné dans son sang. Aussitôt il jeta un grand cri, en pleurant, et déchira ses vêtements.'),
('jdt',14,15,'crampon1923','Et, étant entré dans la tente de Judith, il ne la trouva pas. Il sortit en toute hâte vers le peuple,'),
('jdt',14,16,'crampon1923','et dit: " Une seule femme juive a mis la confusion dans la maison du roi Nabuchodonosor; voici qu''Holoferne est étendu par terre, et sa tête n''est plus avec son corps! "'),
('jdt',14,17,'crampon1923','En entendant ces paroles, tous les princes de l''armée des Assyriens déchirèrent leurs vêtements, une crainte et une frayeur extrêmes s''emparèrent d''eux, leurs esprits furent bouleversés,'),
('jdt',14,18,'crampon1923','et une clameur indicible retentit au milieu de leur camp.'),
('jdt',14,19,'crampon1923',''),
('jdt',15,1,'crampon1923','Lorsque toute l''armée eut appris qu''Holoferne avait eu la tête tranchée, ils perdirent tout sens et toute prudence, et, n''écoutant que la peur et l''effroi, ils cherchèrent leur salut dans la fuite.'),
('jdt',15,2,'crampon1923','Sans se dire un mot les uns aux autres, la tête basse et laissant là tout, pressés d''échapper aux Hébreux qu''ils entendaient venir sur eux les armes à la main, ils s''enfuirent à travers champs et par les sentiers des montagnes.'),
('jdt',15,3,'crampon1923','Les enfants d''Israël, les voyant fuir, se mirent à leur poursuite; ils descendirent en sonnant de la trompette et en poussant de grands cris derrière eux.'),
('jdt',15,4,'crampon1923','Et comme les Assyriens fuyaient dispersés, et en toute hâte, les enfants d''Israël, qui les poursuivaient réunis en un seul corps, taillaient en pièces tous ceux qu''ils pouvaient atteindre.'),
('jdt',15,5,'crampon1923','En même temps Ozias envoya des messages dans toutes les villes et dans toutes les campagnes d''Israël.'),
('jdt',15,6,'crampon1923','Ainsi chaque village et chaque ville, ayant fait prendre les armes à l''élite de leurs jeunes gens, les envoyèrent après les Assyriens, et ils les poursuivirent à la pointe de l''épée jusqu''à leur extrême frontière.'),
('jdt',15,7,'crampon1923','Ceux qui étaient restés à Béthulie entrèrent dans le camp des Assyriens, emportèrent le butin que les Assyriens avaient abandonné dans leur fuite, et en revinrent tout chargés.'),
('jdt',15,8,'crampon1923','D''autre part, ceux qui, après la victoire, retournèrent à Béthulie, amenèrent avec eux tout ce qui avait appartenu aux Assyriens, des bestiaux sans nombre, des animaux de trait et tout leur bagage, en sorte que, tous, depuis le plus petit jusqu''au plus grand, s''enrichirent de leurs dépouilles.'),
('jdt',15,9,'crampon1923','Joakim, le grand prêtre, vint de Jérusalem à Béthulie, avec tous ses anciens, pour voir Judith.'),
('jdt',15,10,'crampon1923','Lorsqu''elle sortit pour aller au devant de lui, tous la bénirent d''une seule voix, en disant: " Tu es la gloire de Jérusalem; tu es la joie d''Israël; tu es l''honneur de notre peuple!'),
('jdt',15,11,'crampon1923','Car tu as montré une âme virile, et ton cœur a été plein de vaillance. Parce que tu as aimé la chasteté et que, après avoir perdu ton mari, tu n''as pas voulu en connaître un autre, la main du Seigneur t''a revêtue de force, et tu seras bénie éternellement. "'),
('jdt',15,12,'crampon1923','Tout le peuple répondit: " Ainsi soit-il! Ainsi soit-il! "'),
('jdt',15,13,'crampon1923','Trente jours suffirent à peine au peuple d''Israël pour recueillir les dépouilles des Assyriens.'),
('jdt',15,14,'crampon1923','Tout ce qu''on reconnut avoir appartenu à Holoferne, l''or et l''argent, les vêtements, les pierres précieuses et tous les objets divers, on le donna à Judith, et tout cela lui fut abandonné par le peuple. Et tout le peuple se réjouit, avec les femmes, les jeunes filles et les jeunes gens, au son des harpes et des cithares.'),
('jdt',16,1,'crampon1923','Alors Judith chanta ce cantique au Seigneur, en disant:'),
('jdt',16,2,'crampon1923','" Célébrez le Seigneur au son des tambourins, chantez le Seigneur avec les cymbales, modulez en son honneur un cantique nouveau, exaltez et acclamez son nom.'),
('jdt',16,3,'crampon1923','Le Seigneur met fin aux guerres; le Seigneur est son nom!'),
('jdt',16,4,'crampon1923','Il a dressé son camp au milieu de son peuple, pour nous délivrer des mains de tous nos ennemis.'),
('jdt',16,5,'crampon1923','Assur est venu des montagnes, du côté de l''Aquilon, avec les myriades de ses guerriers; leur multitude arrêtait les torrents, et leurs chevaux couvraient les vallées.'),
('jdt',16,6,'crampon1923','Il se promettait de ravager par le feu mon territoire, d''immoler par l''épée mes jeunes gens, de faire de mes enfants un butin, de mes vierges des captives.'),
('jdt',16,7,'crampon1923','Mais le Seigneur tout-puissant l''a couvert d''ignominie; il l''a livré aux mains d''une femme, et elle en a triomphé.'),
('jdt',16,8,'crampon1923','Leur héros n''est point tombé sous les coups des jeunes gens; les fils des braves ne l''ont point frappé; les géants à haute stature ne se sont pas mesurés avec lui. C''est Judith, la fille de Mérari, qui l''a renversé par la beauté de son visage.'),
('jdt',16,9,'crampon1923','Elle s''est dépouillée des vêtements de son veuvage, elle s''est parée de ses vêtements de fête, pour le triomphe des enfants d''Israël;'),
('jdt',16,10,'crampon1923','elle a fait couler sur son visage une huile parfumée, elle a disposé sous le turban les boucles de sa chevelure. Elle a revêtu une robe neuve pour le séduire.'),
('jdt',16,11,'crampon1923','L''éclat de sa chaussure a ébloui ses yeux, sa beauté a rendu son âme captive, et elle lui a tranché la tête avec l''épée.'),
('jdt',16,12,'crampon1923','Les Perses ont frémi de sa vaillance, les Mèdes de son audace;'),
('jdt',16,13,'crampon1923','le camp des Assyriens a retenti de hurlements, quand se sont montrés les miens, exténués et desséchés par la soif.'),
('jdt',16,14,'crampon1923','Des fils de jeunes femmes les ont transpercés et les ont tués comme des enfants qui s''enfuient: ils ont péri dans le combat, devant la face du Seigneur mon Dieu.'),
('jdt',16,15,'crampon1923','Chantons un cantique au Seigneur, chantons au Seigneur un cantique nouveau:'),
('jdt',16,16,'crampon1923','Maître souverain, Seigneur, vous êtes grand, et magnifique dans votre puissance, et nul ne peut vous surpasser.'),
('jdt',16,17,'crampon1923','Que toutes vos créatures vous servent, parce que vous avez parlé, et tout a été fait; vous avez envoyé votre esprit, et tout a été créé, et nul ne peut résister à votre voix.'),
('jdt',16,18,'crampon1923','Les montagnes, ainsi que les eaux, sont agitées sur leurs bases, les pierres se fondent comme la cire, devant votre face;'),
('jdt',16,19,'crampon1923','mais ceux qui vous craignent sont grands devant vous en toutes choses.'),
('jdt',16,20,'crampon1923','Malheur à la nation qui s''élève contre mon peuple! Car le Seigneur, le Tout-Puissant, se vengera d''elle, il la visitera au jour du jugement,'),
('jdt',16,21,'crampon1923','il livrera leur chair au feu et aux vers, afin qu''ils brûlent et qu''ils éprouvent ce supplice éternellement. "'),
('jdt',16,22,'crampon1923','Après cette victoire, tout le peuple se rendit à Jérusalem pour adorer le Seigneur et, aussitôt qu''ils furent purifiés, ils offrirent tous les holocaustes et acquittèrent leurs vœux et leurs promesses.'),
('jdt',16,23,'crampon1923','Judith offrit toutes les armes d''Holoferne, que le peuple lui avait données, et le rideau qu''elle avait elle-même enlevé du lit, en anathème d''oubli.'),
('jdt',16,24,'crampon1923','Tout le peuple était dans l''allégresse en face du sanctuaire, et la joie de cette victoire fut célébrée avec Judith pendant trois mois.'),
('jdt',16,25,'crampon1923','Ces jours de fête étant passés, chacun retourna dans sa maison; Judith fut honorée dans Béthulie, et elle jouit d''un grand renom dans tout le pays d''Israël. Joignant au courage la chasteté, elle ne connut point d''homme le reste de sa vie, depuis la mort de Manassès, son mari. Les jours de fête, elle paraissait magnifiquement parée. Après avoir demeuré cent cinq ans dans la maison de son mari et donné la liberté à sa servante, elle mourut et fut inhumée à Béthulie avec son mari; et tout le peuple la pleura pendant sept jours. Dans tout le cours de sa vie et après sa mort, il n''y eut personne, pendant de longues années, qui troubla la paix d''Israël. Le jour de fête institué en souvenir de cette victoire est compté par les Hébreux au nombre des saints jours, et il est célébré par les Juifs depuis ce temps-là jusqu''aujourd''hui.'),
('est',1,1,'crampon1923','C''était au temps d''Assuérus, — de cet Assuérus qui régna, depuis l''Inde jusqu''à l''Ethiopie, sur cent vingt-sept provinces, —'),
('est',1,2,'crampon1923','au temps où le Roi Assuérus était assis sur son trône royal à Suse, la capitale.'),
('est',1,3,'crampon1923','La troisième année de son règne, il fit un festin à tous ses princes et à tous ses ministres. Les chefs de l''armée des Perses et des Mèdes, les grands et les gouverneurs des provinces furent réunis en sa présence;'),
('est',1,4,'crampon1923','c''est alors qu''il déploya devant eux la riche splendeur de son royaume et l''éclatante magnificence de sa grandeur, pendant un grand nombre de jours, pendant cent quatre-vingts jours.'),
('est',1,5,'crampon1923','Lorsque ces jours furent écoulés, le roi fit pour tout le peuple qui se trouvait à Suse, la capitale, depuis le plus grand jusqu''au plus petit, un festin de sept jours, dans la cour du jardin de la maison royale.'),
('est',1,6,'crampon1923','Des tentures blanches, vertes et bleues étaient attachées par des cordons de byssus et de pourpre à des anneaux d''argent et à des colonnes de marbre; des lits d''or et d''argent étaient posés sur un pavé de porphyre, de marbre blanc, de nacre et de marbre noir.'),
('est',1,7,'crampon1923','On servait à boire dans des vases d''or de différentes formes, et le vin royal était offert en abondance, grâce à la libéralité du roi.'),
('est',1,8,'crampon1923','Suivant le décret, chacun buvait sans que personne lui fît violence, car le roi avait ordonné à tous les officiers de sa maison de se conformer à la volonté de chacun des convives.'),
('est',1,9,'crampon1923','La reine Vasthi fit aussi un festin pour les femmes, dans la maison royale du roi Assuérus.'),
('est',1,10,'crampon1923','Le septième jour, comme le vin avait mis la joie au cœur du roi, il ordonna à Maüman, Bazatha, Harbona, Bagatha, Abgatha, Zéthar et Charchas, les sept eunuques qui servaient devant le roi Assuérus,'),
('est',1,11,'crampon1923','d''amener en sa présence la reine Vasthi, couronnée du diadème royal, pour montrer sa beauté aux peuples et aux grands, car elle était belle de figure.'),
('est',1,12,'crampon1923','Mais la reine Vasthi refusa de se rendre au commandement du roi, qu''elle avait reçu par l''intermédiaire des eunuques, et le roi fut très irrité et sa colère s''enflamma.'),
('est',1,13,'crampon1923','Alors le roi s''adressa aux sages qui avaient la connaissance des temps: — car ainsi se traitaient les affaires du roi, devant tous ceux qui étaient experts dans la loi et le droit,'),
('est',1,14,'crampon1923','et les plus près de lui étaient Charséna, Séthar, Admatha, Tharsis, Marès, Marsana et Mamuchan, les sept princes de Perse et de Médie, qui voyaient la face du roi et qui occupaient le premier rang dans le royaume. —'),
('est',1,15,'crampon1923','" Quelle loi, dit-il, doit-on appliquer à la reine Vasthi, pour n''avoir pas exécuté l''ordre du roi Assuérus, qu''il lui a donné par l''intermédiaire des eunuques? "'),
('est',1,16,'crampon1923','Mamuchan répondit devant le roi et les princes: " Ce n''est pas seulement à l''égard du roi que la reine Vasthi a mal agi, mais aussi envers tous les princes et tous les peuples qui sont dans toutes les provinces du roi Assuérus.'),
('est',1,17,'crampon1923','Car l''action de la reine viendra à la connaissance de toutes les femmes et les portera à mépriser leurs maris; elles diront: Le roi Assuérus avait ordonné qu''on amenât en sa présence la reine Vasthi, et elle n''y est point allée.'),
('est',1,18,'crampon1923','Et dès aujourd''hui, les princesses de Perse et de Médie, qui auront appris l''action de la reine, la citeront à tous les princes du roi, et il en résultera beaucoup de mépris et de colère.'),
('est',1,19,'crampon1923','Si le roi le trouve bon, qu''on publie de sa part et qu''on inscrive parmi les lois des Perses et des Mèdes, pour n''être pas enfreinte, une ordonnance royale portant que la reine Vasthi ne paraîtra plus devant le roi Assuérus, et que le roi donnera sa dignité de reine à une autre qui soit meilleure qu''elle.'),
('est',1,20,'crampon1923','Et quand l''édit du roi sera connu dans tout son royaume, qui est vaste, toutes les femmes rendront honneur à leurs maris, depuis le plus grand jusqu''au plus petit. "'),
('est',1,21,'crampon1923','Le conseil plut au roi et aux princes, et le roi agit selon le discours de Mamuchan.'),
('est',1,22,'crampon1923','Il envoya des lettres à toutes les provinces du royaume, à chaque province selon son écriture et à chaque peuple selon sa langue; elles portaient que tout mari devait être le maître dans sa maison et qu''il parlerait le langage de son peuple.'),
('est',2,1,'crampon1923','Après ces choses, quand la colère du roi Assuérus se fut calmée, il se rappela Vasthi, ce qu''elle avait fait et la décision qui avait été prise à son sujet.'),
('est',2,2,'crampon1923','Alors les serviteurs du roi, qui étaient en fonctions près de lui, dirent: " Qu''on cherche pour le roi des jeunes filles, vierges et belles de figure;'),
('est',2,3,'crampon1923','que le roi établisse dans toutes les provinces de son royaume des officiers chargés de rassembler toutes les jeunes filles, vierges et belles de figure, à Suse, la capitale, dans la maison des femmes, sous la surveillance d''Egée, eunuque du roi et gardien des femmes, qui pourvoira à leur toilette;'),
('est',2,4,'crampon1923','et que la jeune fille qui plaira au roi devienne reine à la place de Vasthi. " Le roi approuva cet avis, et il fit ainsi.'),
('est',2,5,'crampon1923','Il y avait à Suse, la capitale, un Juif nommé Mardochée, fils de Jaïr, fils de Séméï, fils de Cis, de la race de Benjamin,'),
('est',2,6,'crampon1923','qui avait été emmené de Jérusalem parmi les captifs déportés avec Jéchonias, roi de Juda, par Nabuchodonosor, roi de Babylone.'),
('est',2,7,'crampon1923','Il élevait Edissa, qui est Esther, fille de son oncle; car elle n''avait ni père ni mère. La jeune fille était belle de forme et d''un gracieux visage; à la mort de son père et de sa mère, Mardochée l''avait adoptée pour fille.'),
('est',2,8,'crampon1923','Lorsqu''on eut publié l''ordre du roi et son édit, et que de nombreuses jeunes filles furent rassemblées à Suse, la capitale, sous la surveillance d''Egée, Esther fut prise aussi et amenée dans la maison du roi, sous la surveillance d''Egée, gardien des femmes.'),
('est',2,9,'crampon1923','La jeune fille lui plut et gagna sa faveur; il s''empressa de lui fournir les choses nécessaires à sa toilette et à sa subsistance, de lui donner sept jeunes filles choisies dans la maison du roi, et il la fit passer avec elles dans le meilleur appartement de la maison des femmes.'),
('est',2,10,'crampon1923','Esther ne fit connaître ni son peuple ni sa naissance, car Mardochée lui avait défendu d''en parler.'),
('est',2,11,'crampon1923','Chaque jour Mardochée se promenait devant la cour de la maison des femmes, pour savoir comment se portait Esther et comment on la traitait.'),
('est',2,12,'crampon1923','Et quand arrivait pour chaque jeune fille le tour d''aller vers le Roi Assuérus, après avoir passé douze mois à accomplir ce qui était prescrit aux femmes, — et voici ce que comportait le temps de leur purification: pendant six mois, elles se purifiaient avec de l''huile de myrrhe, et pendant six mois avec des aromates et des parfums en usage parmi les femmes, —'),
('est',2,13,'crampon1923','et que la jeune fille allait vers le roi, on lui permettait de prendre avec elle ce qu''elle voulait, pour aller de la maison des femmes dans la maison du roi.'),
('est',2,14,'crampon1923','Elle s''y rendait le soir, et le lendemain matin elle passait dans la seconde maison des femmes, sous la surveillance de Susagaz, eunuque du roi et gardien des concubines. Elle ne retournait plus vers le roi, à moins que le roi ne la désirât et qu''elle ne fût appelée nommément.'),
('est',2,15,'crampon1923','Lorsque son tour d''aller vers le roi fut arrivé, Esther, fille d''Abihaïl, oncle de Mardochée qui l''avait adoptée pour fille, ne demanda pas autre chose que ce que désigna Egée, eunuque du roi et gardien des femmes; mais Esther plut aux yeux de tous ceux qui la virent.'),
('est',2,16,'crampon1923','Esther fut conduite auprès du roi Assuérus, dans sa maison royale, le dixième mois, qui est le mois de Tébeth, la septième année de son règne.'),
('est',2,17,'crampon1923','Le roi aima Esther plus que toutes les femmes, et elle obtint grâce et faveur auprès de lui plus que toutes les jeunes filles. Il mit le diadème royal sur sa tête, et la fit reine à la place de Vasthi.'),
('est',2,18,'crampon1923','Le roi donna un grand festin à tous ses princes et à ses serviteurs, le festin d''Esther; il accorda du repos aux provinces et fit des largesses avec une munificence royale.'),
('est',2,19,'crampon1923','La seconde fois qu''on rassembla des jeunes filles, Mardochée était assis à la porte du roi.'),
('est',2,20,'crampon1923','Esther n''avait fait connaître ni sa naissance ni son peuple, selon que Mardochée le lui avait ordonné; et Esther suivait les ordres de Mardochée, comme lorsqu''elle était élevée par lui.'),
('est',2,21,'crampon1923','En ces jours-là, comme Mardochée était assis à la porte du roi, Bagathan et Tharès, deux eunuques du roi, gardes du palais, poussés par la colère, voulurent porter la main sur le roi Assuérus.'),
('est',2,22,'crampon1923','Mardochée eut connaissance du complot et il en informa la reine Esther, qui le redit au roi de la part de Mardochée.'),
('est',2,23,'crampon1923','Le fait ayant été examiné et trouvé exact, les deux eunuques furent pendus à un bois, et cela fut écrit dans le livre des Chroniques en présence du roi.'),
('est',3,1,'crampon1923','Après ces choses, le roi Assuérus éleva en dignité Aman, fils d''Amadatha, du pays d''Agag; il l''éleva et plaça son siège au-dessus de tous les chefs qui étaient auprès de lui.'),
('est',3,2,'crampon1923','Tous les serviteurs du roi, qui se tenaient à sa porte, fléchissaient le genou et se prosternaient devant Aman, car ainsi l''avait ordonné le roi à son sujet. Mais Mardochée ne fléchissait point le genou et ne se prosternait point.'),
('est',3,3,'crampon1923','Les serviteurs du roi, qui se tenaient à sa porte, dirent à Mardochée: " Pourquoi transgresses-tu l''ordre du roi? "'),
('est',3,4,'crampon1923','Comme ils le lui répétaient chaque jour et qu''il ne les écoutait pas, ils en informèrent Aman, pour voir si Mardochée persévérerait dans sa résolution, car il leur avait dit qu''il était Juif.'),
('est',3,5,'crampon1923','Aman vit que Mardochée ne fléchissait pas le genou et ne se prosternait pas devant lui; et Aman fut rempli de fureur.'),
('est',3,6,'crampon1923','Mais il dédaigna de porter la main sur Mardochée seul, car on lui avait appris de quel peuple était Mardochée; et Aman voulut détruire le peuple de Mardochée, tous les Juifs qui se trouvaient dans tout le royaume d''Assuérus.'),
('est',3,7,'crampon1923','Le premier mois, qui est le mois de Nisan, la douzième année du roi Assuérus, on jeta le PUR, c''est-à-dire le sort, devant Aman, pour chaque jour et pour chaque mois, jusqu''au douzième mois, qui est le mois d''Adar.'),
('est',3,8,'crampon1923','Alors Aman dit au roi Assuérus: " Il y a dans toutes les provinces de ton royaume un peuple dispersé et vivant à part parmi les autres peuples, ayant des lois différentes de celles de tous les autres peuples, et n''observant pas les lois du roi. Il n''est pas de l''intérêt du roi de le laisser en repos.'),
('est',3,9,'crampon1923','Si le roi le trouve bon, qu''on écrive l''ordre de les faire périr, et je pèserai dix mille talents d''argent entre les mains des fonctionnaires, pour qu''on les porte au trésor du roi. "'),
('est',3,10,'crampon1923','Le roi ôta son anneau de son doigt et le remit à Aman, fils d''Amadatha, du pays d''Agag, ennemi des Juifs;'),
('est',3,11,'crampon1923','et le roi dit à Aman: " L''argent t''est donné et ce peuple aussi, pour que tu en fasses ce qui te paraîtra bon. "'),
('est',3,12,'crampon1923','Les secrétaires du roi furent appelés le treizième jour du premier mois, et l''on écrivit, conformément à tous les ordres d''Aman, aux satrapes du roi, aux gouverneurs de chaque province et aux chefs de chaque peuple, à chaque province selon son écriture, et à chaque peuple selon sa langue. Ce fut au nom du roi Assuérus que l''on écrivit, et on scella l''édit avec l''anneau royal.'),
('est',3,13,'crampon1923','Des lettres furent envoyées par les courriers dans toutes les provinces du roi, pour qu''on détruisit, qu''on égorgeât et qu''on fît périr tous les Juifs, jeunes et vieux, petits enfants et femmes, en un seul jour, le treizième du douzième mois, qui est le mois d''Adar, et qu''on pillât leurs biens. *** Voir le texte de l''édit, fragment IV, chapitre Est 13, 1-7 ***'),
('est',3,14,'crampon1923','Une copie de l''édit, qui devait être publié comme loi dans chaque province, fut adressée ouverte à tous les peuples, afin qu''ils fussent prêts pour ce jour-là.'),
('est',3,15,'crampon1923','Les courriers partirent en toute hâte, d''après l''ordre du roi. L''édit fut aussi publié dans Suse la capitale; et, tandis que le roi et Aman étaient assis à boire, l''agitation régnait dans la ville de Suse.'),
('est',4,1,'crampon1923','Mardochée, ayant appris tout ce qui se passait, déchira ses vêtements, se revêtit d''un sac et se couvrit la tête de cendre; puis il alla au milieu de la ville en poussant avec force des gémissements amers.'),
('est',4,2,'crampon1923','Et il se rendit jusque devant la porte du roi; car nulle personne revêtue d''un sac n''avait le droit de franchir la porte du roi.'),
('est',4,3,'crampon1923','Dans chaque province, partout où arrivaient l''ordre du roi et son édit, il y eut un grand deuil parmi les Juifs; ils jeûnaient, pleuraient et se lamentaient, et le sac et la cendre servaient de couche à beaucoup d''entre eux.'),
('est',4,4,'crampon1923','Les servantes d''Esther et ses eunuques vinrent lui apporter cette nouvelle, et la reine fut très effrayée. Elle envoya des vêtements à Mardochée pour s''en revêtir, afin qu''il ôtât son sac; mais il ne les accepta pas.'),
('est',4,5,'crampon1923','Alors Esther, ayant appelé Athach, l''un des eunuques que le roi avait placés auprès d''elle, le chargea d''aller demander à Mardochée ce que c''était et d''où venait son deuil.'),
('est',4,6,'crampon1923','Athach se rendit auprès de Mardochée, qui se tenait sur la place de la ville, devant la porte du roi;'),
('est',4,7,'crampon1923','et Mardochée lui fit connaître tout ce qui lui était arrivé, et la somme d''argent qu''Aman avait promis de peser pour le trésor du roi en retour du massacre des Juifs.'),
('est',4,8,'crampon1923','Il lui remit aussi une copie de l''édit publié dans Suse en vue de leur extermination, afin qu''il le montrât à Esther, lui apprît tout, et lui commandât de se rendre chez le roi afin de le supplier et de lui demander grâce pour son peuple. *** Voir l''exhortation de Mardochée à Esther, fragment VI, Est 15, 1-3 ***'),
('est',4,9,'crampon1923','Athach vint rapporter à Esther les paroles de Mardochée.'),
('est',4,10,'crampon1923','Esther donna l''ordre à Athach d''aller dire à Mardochée:'),
('est',4,11,'crampon1923','" Tous les serviteurs du roi et le peuple de ses provinces savent que si quelqu''un, homme ou femme, pénètre chez le roi, dans la cour intérieure, sans avoir été appelé, l''unique loi qu''on lui applique porte peine de mort; à moins que le roi, lui tendant son sceptre d''or, ne lui donne la vie. Et moi, je n''ai pas été appelée à aller auprès du roi depuis trente jours. "'),
('est',4,12,'crampon1923','Quand les paroles d''Esther eurent été rapportées à Mardochée,'),
('est',4,13,'crampon1923','celui-ci lui fit répondre: " Ne t''imagine pas en toi-même que tu échapperas seule d''entre tous les Juifs, parce que tu es dans la maison du roi.'),
('est',4,14,'crampon1923','Car, si tu te tais maintenant, il surgira d''ailleurs un secours et une délivrance pour les Juifs, et toi et la maison de ton père, vous périrez. Et qui sait si ce n''est pas pour un temps comme celui-ci que tu es parvenue à la dignité royale? "'),
('est',4,15,'crampon1923','Esther fit répondre à Mardochée:'),
('est',4,16,'crampon1923','" Va, rassemble tous les Juifs qui se trouvent à Suse, et jeûnez pour moi, sans manger ni boire pendant trois jours, ni la nuit ni le jour. Moi aussi, je jeûnerai de même avec mes servantes, puis j''entrerai chez le roi, malgré la loi; et si je dois mourir, je mourrai. "'),
('est',4,17,'crampon1923','Mardochée s''en alla, et il fit tout ce qu''Esther lui avait ordonné. *** Voir la prière de Mardochée et d''esther, fragment V, Est 13, 8-18 puis Est 14, 1-19 ***'),
('est',5,1,'crampon1923','Le troisième jour, Esther revêtit ses vêtements royaux et se tint dans la cour intérieure de la maison du roi, devant l''appartement du roi. Le roi était assis sur son trône royal dans l''appartement royal, en face de l''entrée du palais.'),
('est',5,2,'crampon1923','Lorsque le roi vit la reine Esther debout dans la cour, elle trouva grâce à ses yeux, et le roi tendit à Esther le sceptre d''or qu''il tenait à la main. Esther, s''approchant, toucha le bout du sceptre.'),
('est',5,3,'crampon1923','Et le roi lui dit: " Qu''as-tu, reine Esther, et que demandes-tu? Quand ce serait la moitié du royaume, elle te serait donnée. "'),
('est',5,4,'crampon1923','Esther dit: " Si le roi le trouve bon, que le roi vienne aujourd''hui avec Aman au festin que je lui ai préparé. "'),
('est',5,5,'crampon1923','Le roi dit: " Qu''on appelle de suite Aman, pour faire ce qu''a dit Esther. " Le roi se rendit avec Aman au festin qu''Esther avait préparé.'),
('est',5,6,'crampon1923','Au festin du vin, le roi dit à Esther: " Quelle est ta demande? Elle te sera accordée. Que désires-tu? Quand ce serait la moitié du royaume, tu l''obtiendras. "'),
('est',5,7,'crampon1923','Esther répondit et dit: " Voici ma demande et mon désir:'),
('est',5,8,'crampon1923','si j''ai trouvé grâce aux yeux du roi et s''il plaît au roi d''accorder ma demande et d''accomplir mon désir, que le roi vienne avec Aman au festin que je leur préparerai, et demain je ferai au roi la réponse qu''il demande. "'),
('est',5,9,'crampon1923','Aman sortit ce jour-là content et le cœur joyeux. Mais lorsqu''il vit, à la porte du roi, Mardochée qui ne se levait ni ne bougeait devant lui, il fut rempli de colère contre Mardochée.'),
('est',5,10,'crampon1923','Aman se contint néanmoins et s''en alla chez lui. Puis, ayant envoyé chercher ses amis et Zarès, sa femme,'),
('est',5,11,'crampon1923','Aman leur parla de la magnificence de ses richesses, du grand nombre de ses fils, et du haut rang que le roi lui avait conféré, en l''élevant au-dessus de ses princes et de ses serviteurs.'),
('est',5,12,'crampon1923','" Je suis même le seul, ajouta-t-il, que la reine Esther ait admis avec le roi au festin qu''elle a préparé, et je suis encore invité pour demain chez elle avec le roi.'),
('est',5,13,'crampon1923','Mais tout cela ne peut me suffire, aussi longtemps que je verrai Mardochée, le Juif, assis à la porte du roi. "'),
('est',5,14,'crampon1923','Zarès, sa femme, et tous ses amis lui dirent: " Qu''on prépare un bois haut de cinquante coudées, et demain matin demande au roi qu''on y pende Mardochée, et tu iras joyeux au festin avec le roi. " Cet avis plut à Aman, et il fit préparer le bois.'),
('est',6,1,'crampon1923','Cette nuit-là, le roi, ne pouvant trouver le sommeil, se fit apporter le livre des annales, les Chroniques. On en fit lecture devant le roi,'),
('est',6,2,'crampon1923','et l''on trouva le récit de la révélation que Mardochée avait faite au sujet de Bagathan et de Tharès, les deux eunuques du roi, gardes du palais, qui avaient voulu porter la main sur le roi Assuérus.'),
('est',6,3,'crampon1923','Le roi dit: " Quelle marque d''honneur et quelle dignité a-t-on données à Mardochée pour cela? " — " Il n''en a reçu aucune ", répondirent les serviteurs du roi qui étaient en fonction près de lui.'),
('est',6,4,'crampon1923','Et le roi dit: " Qui est dans la cour? " — Or Aman était venu dans la cour extérieure de la maison du roi, pour demander au roi de faire pendre Mardochée au bois qu''il avait préparé pour lui. —'),
('est',6,5,'crampon1923','Les serviteurs du roi lui répondirent: " C''est Aman qui se tient dans la cour. " Et le roi dit: " Qu''il entre! "'),
('est',6,6,'crampon1923','Aman étant entré, le roi lui dit: " Que faut-il faire pour l''homme que le roi veut honorer? " Aman se dit en lui-même: " Quel autre le roi voudrait-il honorer de préférence à moi? "'),
('est',6,7,'crampon1923','Et Aman dit au roi: " Pour l''homme que le roi veut honorer,'),
('est',6,8,'crampon1923','il faut prendre un vêtement royal dont le roi s''est revêtu, et un cheval que le roi a monté et sur la tête duquel est posée une couronne royale,'),
('est',6,9,'crampon1923','remettre ce vêtement et ce cheval à l''un des principaux chefs du roi, puis revêtir l''homme que le roi veut honorer, le promener à cheval à travers la place de la ville, et crier devant lui: C''est ainsi qu''il est fait à l''homme que le roi veut honorer! "'),
('est',6,10,'crampon1923','Le roi dit à Aman: " Prends sans tarder le vêtement et le cheval, ainsi que tu l''as dit, et fais ainsi pour Mardochée, le Juif, qui est assis à la porte du roi; ne néglige rien de tout ce que tu as indiqué. "'),
('est',6,11,'crampon1923','Aman prit le vêtement et le cheval, il revêtit Mardochée et le promena à cheval à travers la place de la ville, en criant devant lui: " C''est ainsi que l''on fait à l''homme que le roi veut honorer! "'),
('est',6,12,'crampon1923','Mardochée retourna à la porte du roi, et Aman se hâta de se rendre chez lui, désolé et la tête voilée.'),
('est',6,13,'crampon1923','Aman raconta à Zarès, sa femme, et à tous ses amis tout ce qui lui était arrivé. Ses sages et sa femme Zarès lui dirent: " Si Mardochée, devant lequel tu as commencé de tomber, est de la race des Juifs, tu ne pourras rien contre lui, mais tu succomberas certainement devant lui. "'),
('est',6,14,'crampon1923','Comme ils lui parlaient encore, les eunuques du roi arrivèrent et emmenèrent en hâte Aman au festin qu''Esther avait préparé.'),
('est',7,1,'crampon1923','Le roi et Aman allèrent au festin d''Esther.'),
('est',7,2,'crampon1923','Ce second jour, le roi dit encore à Esther, lorsqu''on fut au festin du vin: " Quelle est ta demande, reine Esther? Elle te sera accordée. Quel est ton désir? Quand ce serait la moitié du royaume, tu l''obtiendras. "'),
('est',7,3,'crampon1923','La reine Esther répondit: " Si j''ai trouvé grâce à tes yeux, ô roi, et si le roi le trouve bon, accorde-moi la vie: voilà ma demande; accorde-la à mon peuple: voilà mon désir.'),
('est',7,4,'crampon1923','Car nous sommes vendus, moi et mon peuple, pour être détruits, égorgés, anéantis. Encore si nous étions vendus pour devenir esclaves et servantes, je me tairais; mais maintenant, l''oppresseur ne peut compenser le dommage fait au roi. "'),
('est',7,5,'crampon1923','Le roi Assuérus prenant la parole, dit à la reine Esther: " Qui est-il et où est-il celui que son cœur pousse à agir ainsi? "'),
('est',7,6,'crampon1923','Esther répondit: " L''oppresseur, l''ennemi, c''est Aman, ce méchant! " Aman fut saisi d''effroi en présence du roi et de la reine.'),
('est',7,7,'crampon1923','Le roi, dans sa colère, se leva et quitta le festin du vin pour aller dans le jardin du palais; et Aman resta pour demander grâce de la vie à la reine Esther, car il voyait bien que, du côté du roi, sa perte était assurée.'),
('est',7,8,'crampon1923','Lorsque le roi revint du jardin du palais dans la salle du festin du vin, il vit Aman qui s''était prosterné sur le lit sur lequel était Esther; et le roi dit: " Quoi! ferait-il violence à la reine chez moi, dans le palais? " Cette parole était à peine sortie de la bouche du roi qu''on voila le visage d''Aman.'),
('est',7,9,'crampon1923','Harbona, l''un des eunuques, dit devant le roi: " Voici que le bois préparé par Aman pour Mardochée, qui a parlé pour le bien du roi, est dressé dans la maison d''Aman, à une hauteur de cinquante coudées. " Le roi dit: " Qu''on y pendre Aman! "'),
('est',7,10,'crampon1923','Et l''on pendit Aman au bois qu''il avait préparé pour Mardochée. Et la colère du roi s''apaisa.'),
('est',8,1,'crampon1923','Ce même jour, le roi Assuérus donna à la reine Esther la maison d''Aman, l''ennemi des Juifs, et Mardochée se présenta devant le roi, car Esther avait fait connaître ce qu''il était pour elle.'),
('est',8,2,'crampon1923','Le roi ôta son anneau, qu''il avait repris à Aman, et le donna à Mardochée; et Esther établit Mardochée sur la maison d''Aman.'),
('est',8,3,'crampon1923','Ensuite Esther parla de nouveau en présence du roi; se jetant à ses pieds, elle le supplia avec larmes d''écarter les effets de la méchanceté d''Aman, du pays d''Agag, et des projets qu''il avait formés contre les Juifs.'),
('est',8,4,'crampon1923','Le roi tendit le sceptre d''or à Esther, qui se releva et se tint debout devant le roi.'),
('est',8,5,'crampon1923','" Si le roi le trouve bon, dit-elle, et si j''ai trouvé grâce devant lui, si la chose paraît convenable au roi et si je suis agréable à ses yeux, qu''on écrive pour révoquer les lettres conçues par Aman, fils d''Amadatha, du pays d''Agag, et écrites par lui dans le but de faire périr les Juifs qui sont dans toutes les provinces du roi.'),
('est',8,6,'crampon1923','Car comment pourrais-je voir le malheur qui atteindrait mon peuple, et comment pourrais-je voir l''extermination de ma race? "'),
('est',8,7,'crampon1923','Le roi Assuérus dit à la reine Esther et au Juif Mardochée: " Voici que j''ai donné à Esther la maison d''Aman, et il a été pendu au bois pour avoir étendu la main contre les Juifs.'),
('est',8,8,'crampon1923','Vous, écrivez en faveur des Juifs comme il vous plaira, au nom du roi, et scellez avec l''anneau du roi; car une lettre écrite au nom du roi et scellée avec l''anneau royal ne peut être révoquée. "'),
('est',8,9,'crampon1923','Les secrétaires du roi furent alors appelés, le vingt-troisième jour du troisième mois, qui est le mois de Sivan, et l''on écrivit, conformément à tout ce qu''ordonna Mardochée, aux Juifs, aux satrapes, aux gouverneurs et aux chefs des provinces, des cent vingt-sept provinces situées de l''Inde à l''Ethiopie, à chaque province selon son écriture, à chaque peuple selon sa langue, et aux Juifs selon leur écriture et selon leur langue.'),
('est',8,10,'crampon1923','On écrivit au nom du roi Assuérus, et l''on scella avec l''anneau royal. On expédia les lettres par l''intermédiaire de courriers à cheval, montés sur des coursiers de l''Etat, provenant des haras du roi.'),
('est',8,11,'crampon1923','Par ces lettres, le roi permettait aux Juifs, en quelque ville qu''ils fussent, de se rassembler et de défendre leur vie, de détruire, de tuer et de faire périr, avec leurs petits enfants et leurs femmes, les troupes de chaque peuple et de chaque province qui les attaqueraient, et de livrer leurs biens au pillage,'),
('est',8,12,'crampon1923','et cela en un seul jour, dans toutes les provinces du roi Assuérus, le treizième jour du douzième mois, qui est le mois d''Adar. *** Voir le texte de l''édit, fragment VIII, Est 16, 1-24. ***'),
('est',8,13,'crampon1923','Une copie de l''édit, qui devait être publié comme loi dans chaque province, fut adressée ouverte à tous les peuples, afin que les Juifs fussent prêts ce jour-là à se venger de leurs ennemis.'),
('est',8,14,'crampon1923','Aussitôt les courriers, montés sur des coursiers de l''Etat, partirent en toute hâte, d''après l''ordre du roi. L''édit fut aussi publié dans Suse, la capitale.'),
('est',8,15,'crampon1923','Mardochée sortit de chez le roi avec un vêtement royal bleu et blanc, une grande couronne d''or, et un manteau de byssus et de pourpre; et la ville de Suse témoignait sa joie par des cris d''allégresse.'),
('est',8,16,'crampon1923','Il n''y avait pour les Juifs que bonheur et joie, jubilation et gloire.'),
('est',8,17,'crampon1923','Dans chaque province et dans chaque ville, partout où arrivaient l''ordre du roi et son édit, il y eut pour les Juifs de la joie et de l''allégresse, des festins et des fêtes. Et beaucoup de gens d''entre les peuples du pays se firent Juifs, car la crainte des Juifs les avait saisis.'),
('est',9,1,'crampon1923','Au douzième mois, qui est le mois d''Adar, le treizième jour du mois, où devaient s''exécuter l''ordre et l''édit du roi, jour où les ennemis des Juifs avaient espéré dominer sur eux, ce fut le contraire qui arriva, et les Juifs dominèrent sur leurs ennemis.'),
('est',9,2,'crampon1923','Les Juifs se rassemblèrent dans leurs villes, dans toutes les provinces du roi Assuérus, pour frapper ceux qui cherchaient leur perte, et personne ne put leur résister, car la crainte qu''ils inspiraient s''était répandue chez tous les peuples.'),
('est',9,3,'crampon1923','Tous les chefs des provinces, les satrapes, les gouverneurs, les fonctionnaires du roi soutinrent les Juifs, car la crainte de Mardochée pesait sur eux.'),
('est',9,4,'crampon1923','Car Mardochée était puissant dans la maison du roi, et sa renommée se répandait dans toutes les provinces, car cet homme, Mardochée, allait toujours grandissant.'),
('est',9,5,'crampon1923','Les Juifs frappèrent donc à coup d''épée tous leurs ennemis; ce fut un massacre et une destruction; ils traitèrent comme il leur plut ceux qui leur étaient hostiles.'),
('est',9,6,'crampon1923','Dans Suse, la capitale, les Juifs tuèrent et firent périr cinq cents hommes,'),
('est',9,7,'crampon1923','et ils massacrèrent Pharsandatha, Delphon, Esphatha,'),
('est',9,8,'crampon1923','Phoratha, Adalia, Aridatha,'),
('est',9,9,'crampon1923','Phermestha, Arisaï, Aridaï et Jézatha,'),
('est',9,10,'crampon1923','les dix fils d''Aman, fils d''Amadatha, l''ennemi des Juifs. Mais ils ne mirent pas la main au pillage.'),
('est',9,11,'crampon1923','Le jour même, le nombre de ceux qui avaient été tués dans Suse, la capitale, parvint à la connaissance du roi.'),
('est',9,12,'crampon1923','Et le roi dit à la reine Esther: " Les Juifs ont tué et fait périr dans Suse, la capitale, cinq cents hommes et les dix fils d''Aman; que n''auront-ils pas fait dans le reste des provinces du roi?... Quelle est ta demande? Elle te sera accordée. Quel est ton désir? Il sera accompli. "'),
('est',9,13,'crampon1923','Esther répondit: " Si le roi le trouve bon, qu''il soit permis aux Juifs qui sont à Suse d''agir encore demain selon le décret d''aujourd''hui, et que l''on pende au bois des dix fils d''Aman. "'),
('est',9,14,'crampon1923','Le roi ordonna de faire ainsi, et l''édit fut publié dans Suse. On pendit les dix fils d''Aman,'),
('est',9,15,'crampon1923','et les Juifs qui se trouvaient à Suse, s''étant rassemblés de nouveau le quatorzième jour du mois d''Adar, tuèrent dans Suse trois cents hommes. Mais ils ne mirent pas la main au pillage.'),
('est',9,16,'crampon1923','Les autres Juifs qui étaient dans les provinces du roi se rassemblèrent pour défendre leur vie et obtenir que leurs ennemis les laissassent en repos; ils tuèrent soixante-quinze mille de ceux qui leur étaient hostiles. Mais ils ne mirent pas la main au pillage.'),
('est',9,17,'crampon1923','Ces choses arrivèrent le treizième jour du mois d''Adar. Les Juifs se reposèrent le quatorzième, et ils en firent un jour de festin et de joie.'),
('est',9,18,'crampon1923','Les Juifs qui se trouvaient à Suse, s''étant rassemblés le treizième et le quatorzième jour, se reposèrent le quinzième, et ils en firent un jour de festin et de joie.'),
('est',9,19,'crampon1923','C''est pourquoi les Juifs de la campagne, qui habitent des villes sans murailles, font du quatorzième jour du mois d''Adar un jour de joie, de festin et de fête, où l''on s''envoie des portions les uns aux autres.'),
('est',9,20,'crampon1923','Mardochée écrivit ces choses, et il envoya des lettres à tous les Juifs qui étaient dans toutes les provinces du roi Assuérus, à ceux qui étaient près comme à ceux qui étaient loin,'),
('est',9,21,'crampon1923','pour leur enjoindre de célébrer chaque année les quatorzième et quinzième jours du mois d''Adar,'),
('est',9,22,'crampon1923','comme étant les jours où ils avaient obtenu d''être laissés en repos par leurs ennemis, et le mois où avaient été changés leur tristesse en joie et leur deuil en jour de fête; on devait donc faire de ces jours des jours de festin et de joie, où l''on s''envoie des portions les uns aux autres, et où l''on distribue des dons aux indigents.'),
('est',9,23,'crampon1923','Les Juifs adoptèrent pour usage, ce qu''ils avaient déjà commencé à faire et ce que Mardochée leur écrivit.'),
('est',9,24,'crampon1923','Car Aman, fils d''Amadatha, du pays d''Agag, ennemi de tous les Juifs, avait formé contre les Juifs le projet de les perdre et il avait jeté le PUR, c''est-à-dire le sort, afin de les exterminer et des détruire.'),
('est',9,25,'crampon1923','Mais Esther s''étant présentée devant le roi, celui-ci ordonna par écrit de faire retomber sur la tête d''Aman le méchant projet qu''il avait formé contre les Juifs, et on le pendit au bois avec ses fils.'),
('est',9,26,'crampon1923','C''est pourquoi on appela ces jours PURIM, du nom de PUR. Ainsi, d''après tout le contenu de cette lettre, d''après ce qu''ils en avaient eux-mêmes vu et ce qui leur était arrivé,'),
('est',9,27,'crampon1923','les Juifs établirent et adoptèrent pour eux, pour leurs descendants et pour tous ceux qui s''attacheraient à eux, la coutume irrévocable de célébrer chaque année ces deux jours, selon le rite prescrit et au temps fixé.'),
('est',9,28,'crampon1923','Ces jours devaient être rappelés et célébrés, de génération en génération, dans chaque famille, dans chaque province et dans chaque ville, et ces jours des PURIM ne devaient jamais être abolis au milieu des Juifs, ni le souvenir s''en effacer dans leur postérité.'),
('est',9,29,'crampon1923','La reine Esther, fille d''Abihaïl, et le Juif Mardochée écrivirent une seconde fois, de la manière la plus pressante, pour confirmer cette lettre sur les PURIM.'),
('est',9,30,'crampon1923','On envoya des lettres à tous les Juifs, dans les cent vingt-sept provinces du royaume d''Assuérus: des paroles de paix et de fidélité,'),
('est',9,31,'crampon1923','et la recommandation de maintenir ces jours des PURIM au temps fixé, comme le Juif Mardochée et la reine Esther les avaient établis pour eux, et comme ils les avaient établis pour eux-mêmes et pour leurs descendants, avec les jeûnes et leurs lamentations.'),
('est',9,32,'crampon1923','Ainsi l''ordre d''Esther établit ces observances des PURIM, et cela fut écrit dans le livre.'),
('est',10,1,'crampon1923','Le roi Assuérus établit un tribut sur le continent et les îles de la mer.'),
('est',10,2,'crampon1923','Tous les faits concernant sa puissance et ses exploits, et les détails sur la grandeur à laquelle le roi éleva Mardochée, cela n''est-il pas écrit dans le livre des Chroniques des rois de Médie et de Perse?'),
('est',10,3,'crampon1923','Car le Juif Mardochée était le premier ministre du roi Assuérus, considéré en même temps parmi les Juifs, aimé de la multitude de ses frères, recherchant le bien de son peuple et parlant pour le bonheur de toute sa race. Ici finit le texte hébreu Fragments complémentaires conservés seulement dans la version grecque I — Conclusion du livre: Mardochée reconnait la réalisation du songe dont Dieu l''avait favorisé. (Est 10, 4-13)'),
('est',10,4,'crampon1923','Alors Mardochée dit: " C''est Dieu qui a fait toutes ces choses!'),
('est',10,5,'crampon1923','Je me souviens en effet du songe que j''ai eu à ce sujet; aucun trait de la vision n''est resté sans accomplissement:'),
('est',10,6,'crampon1923','la petite source qui devint un fleuve, et la lumière qui se fit, et le soleil et la masse d''eau. Le fleuve, c''est Esther, que le roi a prise pour femme et qu''il a faite reine.'),
('est',10,7,'crampon1923','Les deux dragons, c''est moi et Aman.'),
('est',10,8,'crampon1923','Les nations sont ceux qui s''étaient réunis pour détruire le nom des Juifs;'),
('est',10,9,'crampon1923','et mon peuple, c''est Israël qui a crié vers Dieu et qui a été sauvé. Ainsi le Seigneur a sauvé son peuple, et il nous a délivrés de tous ces maux; Dieu a fait des miracles et de grands prodiges, comme il n''est est point arrivé parmi les nations.'),
('est',10,10,'crampon1923','A cet effet, il a préparé deux sorts: un pour le peuple de Dieu et un pour toutes les nations.'),
('est',10,11,'crampon1923','Et ces deux sorts sont venus à l''heure, au temps et au jour du jugement, marqués devant Dieu pour toutes les nations.'),
('est',10,12,'crampon1923','Et Dieu s''est souvenu de son peuple, et il a rendu justice à son héritage.'),
('est',10,13,'crampon1923','Et ces jours du mois d''Adar, le quatorzième et le quinzième de ce mois, seront célébrés par eux en assemblée, avec joie et allégresse devant Dieu, durant les générations, à perpétuité, dans Israël, son peuple. " II — Apostille de la version grecque. (Est 11, 1)'),
('est',11,1,'crampon1923','La quatrième année du règne de Ptolémée et de Cléopâtre, Dosithée, qui se disait prêtre et de la race de Lévi, ainsi que Ptolémée, son fils, apportèrent cette lettre des Phrouraï, qu''ils dirent être authentique et avoir été traduite par Lysimaque, fils de Ptolémée, résidant à Jérusalem. III — Songe de Mardochée, sa faveur à la cour, haine d''Aman. (Est 11, 2-12, 6) Prologue.'),
('est',11,2,'crampon1923','La seconde année du règne d''Assuérus, le grand roi, le premier jour du mois de Nisan, Mardochée, fils de Jaïr, fils de Séméi, fils de Cis, de la tribu de Benjamin, eut un songe.'),
('est',11,3,'crampon1923','C''était un Juif qui demeurait dans la ville de Suse, homme illustre et attaché à la cour du roi.'),
('est',11,4,'crampon1923','Il était du nombre des captifs que Nabuchodonosor, roi de Babylone, avait transporté de Jérusalem avec Jéchonias, roi de Juda.'),
('est',11,5,'crampon1923','Voici quel fut son songe: Soudain on entendit des voix, un grand bruit et des tonnerres; la terre trembla et fut bouleversée.'),
('est',11,6,'crampon1923','Puis soudain deux grands dragons s''avancèrent, tous deux prêts à combattre.'),
('est',11,7,'crampon1923','Ils firent entendre un grand cri et, à leur voix, toutes les nations se préparèrent à la lutte, pour combattre le peuple des justes.'),
('est',11,8,'crampon1923','Puis soudain, ce fut un jour de ténèbres et d''obscurité; il y eut angoisse, détresse, tribulation et grande épouvante sur la terre.'),
('est',11,9,'crampon1923','Le peuple entier des justes, craignant pour lui tous les maux, était dans le trouble et se préparait à périr.'),
('est',11,10,'crampon1923','Ils crièrent vers Dieu et, à leurs cris, il y eut comme une petite source d''où sortit un grand fleuve, une masse d''eau.'),
('est',11,11,'crampon1923','La lumière et le soleil brillèrent; ceux qui étaient dans l''humiliation furent élevés, et ils dévorèrent ceux qui étaient dans les honneurs.'),
('est',11,12,'crampon1923','S''étant réveillé après avoir vu ce songe et ce que Dieu avait résolu de faire, Mardochée le retint gravé dans son esprit et, jusqu''à la nuit, il fit tous ses efforts pour le comprendre.'),
('est',12,1,'crampon1923','Puis Mardochée demeura à la cour avec Bagathan et Tharès, les deux eunuques du roi, gardiens de la porte du palais.'),
('est',12,2,'crampon1923','Ayant connu leurs pensées et pénétré leurs desseins, il découvrit qu''ils s''étaient proposés de porter la main sur le roi Assuérus, et il en donna avis au roi.'),
('est',12,3,'crampon1923','Celui-ci fit mettre à la question les deux eunuques et, sur leur aveu, les envoya au supplice.'),
('est',12,4,'crampon1923','Le roi fit écrire dans les Chroniques ce qui s''était passé, et Mardochée en consigna aussi par écrit le souvenir.'),
('est',12,5,'crampon1923','Et le roi ordonna qu''il exercerait un office dans le palais, et il lui donna des présents pour sa dénonciation.'),
('est',12,6,'crampon1923','Mais Aman, fils d''Amadatha, l''Agagite, était en grand honneur auprès du roi, et il chercha à perdre Mardochée et son peuple à cause des deux eunuques du roi. IV — Édit d''Assuérus en vue de l''extermination des Juifs (Est 13, 1-7). A lire après Est 3, 13.'),
('est',13,1,'crampon1923','Voici la copie de cette lettre: " Assuérus, le grand roi, aux satrapes et aux gouverneurs des cent vingt-sept provinces, de l''Inde à l''Ethiopie, lesquels sont soumis à ses ordres, mande ce qui suit:'),
('est',13,2,'crampon1923','" Quoique je commande à un très grand nombre de nations et que j''aie soumis tout l''univers, je veux, non pas abuser de ma puissance pour m''enorgueillir, mais, par un gouvernement toujours clément et doux, assurer continuellement à mes sujets une vie sans trouble; et, procurant à mon royaume le calme et la sécurité jusqu''à ses extrêmes frontières, faire refleurir la paix chère à tous les mortels.'),
('est',13,3,'crampon1923','Ayant donc demandé à mes conseillers de quelle manière mes intentions pouvaient être réalisées, l''un d''eux, nommé Aman, qui excelle parmi nous en sagesse, qui est connu pour son dévouement inaltérable et sa fidélité constante, et qui occupe la seconde place dans le royaume,'),
('est',13,4,'crampon1923','m''a fait connaître qu''il y a un peuple mal intentionné, mêlé à toutes les tribus qui sont sur la terre, en opposition avec tous les peuples au nom de ses lois, méprisant continuellement les commandements des rois, de façon à empêcher la parfaite harmonie de l''empire que nous dirigeons.'),
('est',13,5,'crampon1923','Ayant donc appris que ce seul peuple, en contradiction perpétuelle avec tout le genre humain, s''en séparant par le caractère étrange de ses lois, et mal affectionné à nos intérêts, commet les derniers excès et empêche ainsi la prospérité du royaume,'),
('est',13,6,'crampon1923','nous avons ordonné que ceux qui vous sont désignés dans les lettres d''Aman, lequel est à la tête des affaires et honoré comme notre second père, soient tous, avec femmes et enfants, radicalement exterminés par le glaive de leurs ennemis, sans aucune miséricorde ni clémence, le quatorzième jour du douzième mois, le mois d''Adar, de la présente année;'),
('est',13,7,'crampon1923','afin que ces hommes, autrefois et maintenant encore hostiles, descendant le même jour, par mort violente, aux enfers, rendent pour les temps à venir à nos affaires une prospérité et une paix parfaites ". V — Prières d''Esther et de Mardochée (Est 13,8-14,19). A lire après Est 4, 17.'),
('est',13,8,'crampon1923','Et Mardochée pria le Seigneur, se souvenant de toutes ses œuvres.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('est',13,9,'crampon1923','Il dit: " Seigneur, Seigneur, Roi tout-puissant, toutes choses sont soumises à votre pouvoir, et il n''est personne qui puisse Vous faire obstacle, si Vous avez résolu de sauver Israël.'),
('est',13,10,'crampon1923','C''est Vous qui avez fait le ciel et la terre, et toutes les merveilles qui sont sous le ciel.'),
('est',13,11,'crampon1923','Vous êtes le Seigneur de toutes choses et nul ne peut Vous résister, à Vous le Seigneur!'),
('est',13,12,'crampon1923','Vous connaissez toutes choses et Vous savez que ce n''est ni par insolence, ni par orgueil, ni par quelque désir de gloire que j''ai agi en ne me prosternant pas devant le superbe Aman,'),
('est',13,13,'crampon1923','car volontiers, pour le salut d''Israël, je serais prêt à baiser les traces mêmes de ses pas.'),
('est',13,14,'crampon1923','Mais je l''ai fait pour ne pas mettre l''honneur d''un homme au-dessus de l''honneur dû à mon Dieu; et jamais je ne me prosternerai devant un autre que Vous, mon Seigneur, et ce n''est pas par orgueil que j''agirai de la sorte.'),
('est',13,15,'crampon1923','Maintenant donc, Seigneur mon Dieu et mon Roi, Dieu d''Abraham, ayez pitié de votre peuple, parce que nos ennemis jettent les yeux sur nous pour nous perdre et veulent détruire votre antique héritage.'),
('est',13,16,'crampon1923','Ne méprisez pas votre lot, que Vous avez racheté pour Vous de la terre d''Egypte. Exaucez ma prière!'),
('est',13,17,'crampon1923','Soyez favorable à votre part d''héritage et changez notre deuil en joie, afin que, conservant la vie, nous célébrions votre nom, Seigneur, et ne fermez pas la bouche de ceux qui vous louent. "'),
('est',13,18,'crampon1923','Tout Israël cria aussi vers le Seigneur de toutes ses forces; car ils avaient la mort devant les yeux.'),
('est',14,1,'crampon1923','La reine Esther aussi, se sentant placée en un extrême péril de mort, eut recours au Seigneur.'),
('est',14,2,'crampon1923','Quittant ses vêtements splendides, elle prit des habits d''angoisse et de deuil; à la place de ses parfums précieux, elle se couvrit la tête de cendre et de poussière, affligea durement son corps et, s''arrachant les cheveux, elle en remplissait tous les lieux où elle avait coutume de se livrer à la joie.'),
('est',14,3,'crampon1923','Et elle adressa cette prière au Seigneur, Dieu d''Israël: " Mon Seigneur, qui êtes seul notre Roi, assistez-moi dans mon délaissement, moi qui n''ai, pas d''autre secours que Vous;'),
('est',14,4,'crampon1923','car le danger qui me menace, je le touche déjà de mes mains.'),
('est',14,5,'crampon1923','J''ai appris dès mon bas âge, au sein de ma tribu paternelle, que Vous, Seigneur, avez pris Israël de préférence à toutes les nations, et nos pères de préférence à tous leurs ancêtres, pour votre héritage éternel, et que Vous avez accompli en leur faveur toutes vos promesses.'),
('est',14,6,'crampon1923','Et maintenant, nous avons péché en votre présence, et Vous nous avez livrés aux mains de nos ennemis,'),
('est',14,7,'crampon1923','parce que nous avons rendu hommage à leurs dieux. Vous êtes juste, Seigneur!'),
('est',14,8,'crampon1923','Et maintenant, il ne leur suffit plus de faire peser sur nous une amère servitude, mais ils ont mis leurs mains dans les mains de leurs idoles,'),
('est',14,9,'crampon1923','pour faire serment d''abolir les décrets de votre bouche, d''anéantir votre héritage, de fermer la bouche de ceux qui Vous louent, et d''éteindre la gloire de votre temple et de votre autel,'),
('est',14,10,'crampon1923','afin que s''ouvre la bouche des nations, pour louer la puissance des idoles et célébrer à jamais un roi de chair.'),
('est',14,11,'crampon1923','Ne livrez pas, Seigneur, votre sceptre à ceux qui ne sont rien, afin qu''ils ne se rient pas de notre ruine; mais faites retomber sur eux leur dessein et faites un exemple de celui qui le premier s''est déchaîné contre nous.'),
('est',14,12,'crampon1923','Souvenez-Vous de nous, Seigneur; faites-Vous connaître dans ce temps de notre affliction et donnez-moi du courage, Roi des Dieux et Dominateur de toute puissance!'),
('est',14,13,'crampon1923','Mettez de sages paroles sur mes lèvres en présence du lion, et faites passer son cœur à la haine de notre ennemi, afin qu''il périsse, lui et tous ceux qui ont les mêmes sentiments.'),
('est',14,14,'crampon1923','Mais nous, délivrez-nous par votre main, et assistez-moi, moi qui suis seule et n''ai que Vous, Seigneur! Vous connaissez toutes choses,'),
('est',14,15,'crampon1923','et Vous savez que je hais la splendeur des méchants, que j''ai horreur de la couche des incirconcis et de tout étranger.'),
('est',14,16,'crampon1923','Vous savez la contrainte que je subis, vous savez que j''ai en horreur l''insigne de mon élévation, qui est posé sur ma tête aux jours où je dois me laisser voir; je l''ai en horreur comme un linge souillé, et je ne le porte point aux jours que je puis passer dans la retraite.'),
('est',14,17,'crampon1923','Votre servante n''a jamais mangé à la table d''Aman, ni fait grand cas des festins du roi, ni bu le vin des libations.'),
('est',14,18,'crampon1923','Jamais, depuis le jour où j''ai été amenée ici jusqu''à maintenant, votre servante n''a goûté la joie, si ce n''est en Vous, Seigneur Dieu, Dieu d''Abraham.'),
('est',14,19,'crampon1923','O Dieu, qui l''emportez sur tous en puissance, exaucez la prière de ceux qui n''ont aucun autre espoir; délivrez-nous des mains des méchants et tirez-moi de mon angoisse! " VI — Exhortation de Mardochée à Esther (Est 15, 1-3.) A lire après Est 4, 8.'),
('est',15,1,'crampon1923','Il fit mander à Esther d''entrer chez le roi, afin de lui adresser une supplication pour son peuple et sa patrie.'),
('est',15,2,'crampon1923','" Rappelle-toi, lui dit-il, les jours de ton abaissement, et comment tu as été nourrie de ma main; car Aman, le premier après le roi, a parlé contre nous pour notre perte.'),
('est',15,3,'crampon1923','Mais toi, invoque le Seigneur et parle pour nous au roi; sauve-nous de la mort! " VII — Esther chez le roi (Est 15, 4-19). A lire au commencement du ch. 5.'),
('est',15,4,'crampon1923','Le troisième jour, ayant fini sa prière, Esther quitta ses habits de pénitence, et revêtit les ornements de sa dignité.'),
('est',15,5,'crampon1923','Dans tout l''éclat de sa parure, après avoir invoqué Dieu, l''arbitre et le sauveur de tous, elle prit avec elle les deux suivantes d''usage.'),
('est',15,6,'crampon1923','Elle s''appuyait sur l''une comme pouvant à peine soutenir son corps délicat;'),
('est',15,7,'crampon1923','l''autre suivait, relevant la longue robe de sa maîtresse.'),
('est',15,8,'crampon1923','Celle-ci, tout empourprée du puissant éclat de sa beauté, avait le visage joyeux et l''air aimable; mais la crainte lui serrait le cœur.'),
('est',15,9,'crampon1923','Ayant donc franchi toutes les portes, elle se présenta devant le roi. Assuérus était assis sur son trône royal, revêtu de tous les insignes de sa majesté, tout brillant d''or et de pierres précieuses; son aspect était terrible.'),
('est',15,10,'crampon1923','Lorsqu''il eut relevé sa tête rayonnante de gloire et lancé un regard étincelant de colère, la reine tomba en défaillance, changeant de couleur et s''inclinant sur l''épaule de la servante qui marchait devant elle.'),
('est',15,11,'crampon1923','Alors Dieu changea la colère du roi en douceur; inquiet, il s''élança de son trône et soutint Esther dans ses bras, jusqu''à ce qu''elle eût repris ses sens, calmant sa frayeur par des paroles amicales:'),
('est',15,12,'crampon1923','" Qu''as-tu donc, Esther? lui disait-il, je suis ton frère, aie confiance;'),
('est',15,13,'crampon1923','tu ne mourras point, car notre ordonnance est pour le commun de nos sujets.'),
('est',15,14,'crampon1923','Approche! "'),
('est',15,15,'crampon1923','Et levant le sceptre d''or, il le lui posa sur le cou et lui donna un baiser, en disant: " Parle-moi. "'),
('est',15,16,'crampon1923','Elle répondit: " Je vous ai vu, seigneur, comme un ange de Dieu, et mon cœur a été troublé par la crainte de votre majesté;'),
('est',15,17,'crampon1923','car vous êtes digne d''admiration, seigneur, et votre visage est plein d''amabilité. "'),
('est',15,18,'crampon1923','Comme elle parlait, elle s''affaissa de nouveau, prête à s''évanouir.'),
('est',15,19,'crampon1923','Le roi était consterné, et tous ses serviteurs cherchaient à ranimer la reine. VIII — Édit d''Assuérus en faveur des Juifs (Est 16, 1-24). A lire après Est 8, 12.'),
('est',16,1,'crampon1923','Ce qui suit est la copie de cette lettre: " Assuérus, le grand roi, aux satrapes et aux chefs des cent vingt-sept provinces, de l''Inde à l''Ethiopie, et à ceux qui ont à cœur nos intérêts, salut!'),
('est',16,2,'crampon1923','" Plusieurs, après avoir été comblés de distinctions par la grande bonté des princes leurs bienfaiteurs, deviennent arrogants.'),
('est',16,3,'crampon1923','Non seulement ils prennent à tâche d''opprimer nos sujets, mais, incapables de porter le poids des honneurs, ils ourdissent des trames contre leurs bienfaiteurs.'),
('est',16,4,'crampon1923','Ce n''est pas assez pour eux de bannir la reconnaissance du milieu des hommes; enflés par le fastueux éclat d''une fortune inaccoutumée, ils vont jusqu''à se persuader qu''ils pourront échapper à la justice vengeresse de Dieu, qui toujours voit toutes choses.'),
('est',16,5,'crampon1923','Maintes et maintes fois, le langage artificieux des hommes que l''amitié des princes avait chargés d''administrer les affaires, a engagé dans d''irrémédiables maux ceux qui étaient à la tête des empires, en les rendant complices de l''effusion du sang innocent;'),
('est',16,6,'crampon1923','les fallacieux mensonges de la malice trompant ainsi la bienveillante simplicité des gouvernants.'),
('est',16,7,'crampon1923','Et ce n''est pas seulement dans les anciennes histoires — comme nous venons de le rappeler, — que vous pourrez voir des actes impies dus à l''influence pestilentielle de ceux qui exercent indignement le pouvoir; vous le pourrez mieux encore en examinant ce qui se passe auprès de vous.'),
('est',16,8,'crampon1923','Il nous faut donc pourvoir à l''avenir, afin d''assurer, en faveur de tous les hommes, la tranquillité et la paix du royaume,'),
('est',16,9,'crampon1923','opérant les changements nécessaires et jugeant avec prudence les choses qui se présentent à nous, afin d''y faire face avec une constante équité.'),
('est',16,10,'crampon1923','" Vous savez, en effet, comment Aman, fils d''Amadatha, un Macédonien, vraiment étranger à la race des Perses et fort éloigné de notre mansuétude, ayant été recueilli par notre hospitalité,'),
('est',16,11,'crampon1923','éprouva les effets de la bienveillance que nous portons à tous les peuples, jusqu''à être appelé notre père et à voir tout le monde se prosterner devant lui, comme possédant la dignité la plus proche du trône royal.'),
('est',16,12,'crampon1923','Mais incapable de porter dignement une si haute fortune, il s''étudia à nous priver de la royauté et de la vie.'),
('est',16,13,'crampon1923','Par toutes sortes d''artifices et de mensonges, il s''efforça de perdre et Mardochée, qui nous a sauvé et toujours utilement servi, et Esther, la compagne irréprochable de notre royauté, avec leur peuple tout entier.'),
('est',16,14,'crampon1923','De cette manière il espérait nous surprendre dans l''isolement et livrer l''empire des Perses aux Macédoniens.'),
('est',16,15,'crampon1923','Mais ces Juifs, voués à la mort par le plus scélérat des hommes, nous avons reconnu qu''ils n''étaient coupables d''aucune faute, mais qu''ils obéissent à des lois très justes,'),
('est',16,16,'crampon1923','et qu''ils sont les enfants du Dieu très haut, très grand et éternellement vivant, lequel, pour nous comme pour nos ancêtres, conserve ce royaume dans l''état le plus florissant.'),
('est',16,17,'crampon1923','" C''est pourquoi, vous ferez bien de ne pas tenir compte des lettres envoyées par Aman, fils d''Amadatha,'),
('est',16,18,'crampon1923','attendu que l''auteur de ces crimes a été pendu au bois, avec toute sa maison, devant les portes de Suse; Dieu, Maître souverain de toutes choses, lui ayant infligé sans retard le châtiment mérité.'),
('est',16,19,'crampon1923','Affichant la copie de la présente lettre publiquement en tout lieu, permettez aux Juifs de suivre leurs lois en toute liberté,'),
('est',16,20,'crampon1923','et prêtez-leur assistance, afin qu''ils puissent repousser l''attaque de ceux qui, durant les jours d''oppression, se sont élevés contre eux; et cela, le treizième jour du douzième mois, appelé Adar, en un même jour.'),
('est',16,21,'crampon1923','Car Dieu, le Maître de toutes choses, a changé, pour la race choisie, ce jour de malheur en un jour d''allégresse.'),
('est',16,22,'crampon1923','Vous donc, célébrez aussi ce grand jour avec toutes sortes de réjouissances, comme une de vos fêtes solennelles, afin qu''il soit, maintenant et dans l''avenir,'),
('est',16,23,'crampon1923','pour nous et pour tous ceux qui sont affectionnés aux Perses, un gage de salut et au contraire un souvenir de ruine pour ceux qui complotent contre nous.'),
('est',16,24,'crampon1923','" Toute ville, et généralement toute contrée qui n''aura pas suivi ces prescriptions, sera dévastée avec fureur par le fer et le feu, de telle sorte qu''elle soit à jamais, non seulement inaccessible aux hommes, mais encore abhorrée des bêtes sauvages et des oiseaux. " Que des copies de ce décret soient exposées aux yeux dans toute l''étendue de l''empire et qu''ainsi tous les Juifs soient prêts, pour le jour susdit, à combattre leurs ennemis. "'),
('1m',1,1,'crampon1923','Lorsqu''Alexandre, fils de Philippe, Macédonien, sorti du pays de Céthim, eut battu Darius, roi des Perses et des Mèdes, et fut devenu roi à sa place, après avoir régné d''abord sur la Grèce,'),
('1m',1,2,'crampon1923','il fit de nombreuses guerres, prit beaucoup de forteresses et mit à mort des rois de la terre.'),
('1m',1,3,'crampon1923','Il poussa jusqu''aux extrémités de la terre, et s''empara des dépouilles d''une multitude de nations, et la terre se tut devant lui.'),
('1m',1,4,'crampon1923','Son cœur s''éleva et s''enfla d''orgueil; il rassembla une armée très forte'),
('1m',1,5,'crampon1923','et soumit des contrées, des nations et des souverains, et ils devinrent ses tributaires.'),
('1m',1,6,'crampon1923','Après cela, il tomba sur son lit et connut qu''il allait mourir.'),
('1m',1,7,'crampon1923','Il appela auprès de lui ses officiers d''un rang supérieur, les compagnons de sa jeunesse, et il partagea entre eux son empire pendant qu''il vivait encore.'),
('1m',1,8,'crampon1923','Alexandre régna douze ans, et il mourut.'),
('1m',1,9,'crampon1923','Ses officiers prirent possession du pouvoir, chacun dans son lieu.'),
('1m',1,10,'crampon1923','Tous ceignirent le diadème après sa mort, et leurs fils après eux, durant de longues années, et ils multiplièrent les maux sur la terre.'),
('1m',1,11,'crampon1923','De ces rois sortit une racine d''iniquité, Antiochus Épiphane, fils du roi Antiochus, qui avait été à Rome comme otage; et il devint roi en la cent trente-septième année du royaume des Grecs.'),
('1m',1,12,'crampon1923','En ces jours-là, il sortit d''Israël des enfants infidèles qui en entraînaient beaucoup d''autres en disant: " Allons et unissons-nous aux nations qui sont autour de nous; car, depuis que nous nous tenons séparés d''elles, il nous est arrivé beaucoup de malheurs. "'),
('1m',1,13,'crampon1923','Et ce discours parut bon à leurs yeux.'),
('1m',1,14,'crampon1923','Quelques-uns du peuple s''empressèrent d''aller trouver le roi, et il leur donna l''autorisation de suivre les coutumes des nations.'),
('1m',1,15,'crampon1923','Ils construisirent donc à Jérusalem un gymnase, selon les usages des nations.'),
('1m',1,16,'crampon1923','Ils firent disparaître les marques de leur circoncision et ainsi, se séparant de l''alliance sainte, ils s''associèrent aux nations et se vendirent pour faire le péché.'),
('1m',1,17,'crampon1923','Quand son pouvoir lui parut bien affermi, Antiochus songea à régner sur l''Egypte, afin d''être souverain des deux royaumes.'),
('1m',1,18,'crampon1923','Il entra en Egypte avec une puissante armée, avec des chars, des éléphants et des cavaliers, et un grand nombre de vaisseaux.'),
('1m',1,19,'crampon1923','Il attaqua Ptolémée, roi d''Egypte; mais Ptolémée eut peur devant lui et prit la fuite, et une multitude d''hommes tombèrent frappés à mort.'),
('1m',1,20,'crampon1923','Les Syriens prirent les villes fortes du pays d''Egypte, et Antiochus enleva les dépouilles de toute l''Egypte.'),
('1m',1,21,'crampon1923','Après avoir battu l''Egypte l''an cent quarante-trois, Antiochus revint sur ses pas et marcha contre Israël.'),
('1m',1,22,'crampon1923','Etant monté à Jérusalem avec une armée puissante,'),
('1m',1,23,'crampon1923','il entra avec une audace insolente dans le sanctuaire et en enleva l''autel d''or, le chandelier de la lumière avec tous ses ustensiles, la table des pains de proposition, les coupes, tasses et écuelles d''or, le rideau, les couronnes et les ornements d''or sur la façade du temple, et il détacha partout le placage.'),
('1m',1,24,'crampon1923','Il prit aussi l''or et l''argent et les vases précieux, ainsi que les trésors cachés qu''il put trouver. Emportant le tout, il entra dans son pays,'),
('1m',1,25,'crampon1923','après avoir massacré beaucoup de gens et proféré des paroles insolentes.'),
('1m',1,26,'crampon1923','Il y eut un grand deuil parmi les Israélites, dans tous les lieux où ils résidaient.'),
('1m',1,27,'crampon1923','Les chefs et les anciens poussèrent des gémissements; les jeunes filles et les jeunes gens perdirent leur vigueur et la beauté des femmes s''altéra.'),
('1m',1,28,'crampon1923','Le nouvel époux fit entendre des lamentations; assise dans la chambre nuptiale, la jeune épouse versa des larmes.'),
('1m',1,29,'crampon1923','La terre trembla pour ses habitants, et toute la famille de Jacob était couverte de confusion.'),
('1m',1,30,'crampon1923','Deux ans après, le roi envoya dans les villes de Juda un commissaire des contributions. Celui-ci arriva à Jérusalem avec beaucoup de troupes,'),
('1m',1,31,'crampon1923','et il adressa par ruse des paroles amicales aux habitants, qui l''accueillirent sans défiance;'),
('1m',1,32,'crampon1923','puis, tout à coup, il se jeta sur la ville, la frappa d''une grande plaie et tua beaucoup d''Israélites.'),
('1m',1,33,'crampon1923','Il pilla la ville, y mit le feu, abattit les maisons et démolit les murs d''enceinte.'),
('1m',1,34,'crampon1923','Il emmena en captivité les femmes et les enfants, et s''empara du bétail.'),
('1m',1,35,'crampon1923','Ensuite les Syriens entourèrent la cité de David d''une grande et forte muraille, avec de puissantes tours: ce fut leur citadelle.'),
('1m',1,36,'crampon1923','Ils y mirent une race perverse, des gens sans foi ni loi, et s''y fortifièrent.'),
('1m',1,37,'crampon1923','Ils y entassèrent des armes et des provisions, et, rassemblant les dépouilles de Jérusalem, ils les y déposèrent; ils devinrent ainsi un grand danger pour la ville.'),
('1m',1,38,'crampon1923','Cette citadelle fut comme une embûche dressée contre le sanctuaire, et un adversaire redoutable pour Israël pendant tout ce temps,'),
('1m',1,39,'crampon1923','Ils répandirent aussi le sang innocent autour du temple, et souillèrent le sanctuaire.'),
('1m',1,40,'crampon1923','A cause d''eux, les habitants s''enfuirent de Jérusalem, qui devint un séjour d''étrangers. La ville devint étrangère à ceux qui y étaient nés, ses propres enfants l''avaient abandonnée.'),
('1m',1,41,'crampon1923','Son sanctuaire resta désolé comme un désert, ses fêtes se changèrent en jours de deuil, ses sabbats en opprobre, et ce qui avait été son honneur devint une cause d''outrage.'),
('1m',1,42,'crampon1923','A l''égal de sa gloire s''est multipliée son humiliation, et sa grandeur s''est changée en deuil.'),
('1m',1,43,'crampon1923','Le roi Antiochus publia un édit dans tout son royaume, pour que tous ne fissent plus qu''un seul peuple et que chacun abandonnât sa loi particulière.'),
('1m',1,44,'crampon1923','Toutes les nations se conformèrent à l''ordre du roi.'),
('1m',1,45,'crampon1923','Beaucoup d''Israélites consentirent aussi à suivre son culte; ils sacrifièrent aux idoles et profanèrent le sabbat.'),
('1m',1,46,'crampon1923','Le roi envoya des lettres par des messagers à Jérusalem et aux autres villes de Juda, leur ordonnant de suivre les coutumes des étrangers au pays,'),
('1m',1,47,'crampon1923','de faire cesser dans le temple les holocaustes, les sacrifices et les libations,'),
('1m',1,48,'crampon1923','de profaner les sabbats et les fêtes,'),
('1m',1,49,'crampon1923','de souiller le sanctuaire et les saints,'),
('1m',1,50,'crampon1923','de construire des autels, des bois sacrés et des temples d''idoles, et d''offrir en sacrifice des pourceaux et d''autres animaux impurs,'),
('1m',1,51,'crampon1923','de laisser leurs enfants mâles incirconcis, de se souiller eux-mêmes par toutes sortes d''impuretés et de profanations, de manière à leur faire oublier la loi et à en changer toutes les prescriptions.'),
('1m',1,52,'crampon1923','Et quiconque n''obéirait pas aux ordres du roi Antiochus serait puni de mort. —'),
('1m',1,53,'crampon1923','Telles sont les lettres qu''il publia dans tout son royaume, et il établit des surveillants sur tout le peuple;'),
('1m',1,54,'crampon1923','il commanda aussi aux villes de Juda d''offrir des sacrifices dans chaque ville.'),
('1m',1,55,'crampon1923','Beaucoup de Juifs, tous ceux qui abandonnaient la loi, se rallièrent aux Syriens; ils pratiquèrent le mal dans le pays,'),
('1m',1,56,'crampon1923','et réduisirent les Israélites fidèles à se réfugier dans des cachettes, dans toutes sortes de retraites.'),
('1m',1,57,'crampon1923','Le quinzième jour du mois de Casleu, l''an cent quarante-cinq, ils construisirent l''abomination de la désolation sur l''autel des holocaustes. Ils construisirent aussi des autels dans les villes de Juda à l''entour.'),
('1m',1,58,'crampon1923','Ils brûlaient de l''encens aux portes des maisons et sur les places.'),
('1m',1,59,'crampon1923','S''ils trouvaient quelque part les livres de la loi, ils les brûlaient après les avoir déchirés.'),
('1m',1,60,'crampon1923','Celui chez qui un livre de l''alliance était trouvé, et quiconque montrait de l''attachement à la loi, était mis à mort en vertu de l''édit du roi.'),
('1m',1,61,'crampon1923','C''est avec cette violence qu''ils traitaient Israël, exécutant dans les villes, un jour de chaque mois, ceux qui étaient surpris en contravention.'),
('1m',1,62,'crampon1923','Le vingt-cinq du mois, ils offraient un sacrifice sur l''autel qui avait été construit sur l''autel des holocaustes.'),
('1m',1,63,'crampon1923','On mettait aussi à mort, selon l''édit, les femmes qui avaient fait circoncire leurs enfants,'),
('1m',1,64,'crampon1923','en suspendant les enfants à leur cou; on pillait leurs maisons et l''on tuait ceux qui avaient pratiqué l''opération. Cependant beaucoup d''Israélites résistèrent courageusement et prirent la ferme résolution de ne rien manger d''impur. Ils préférèrent mourir plutôt que de se souiller par la nourriture, et de profaner la sainte alliance; et ils moururent. C''était un très grand courroux qui se déchargeait sur Israël.'),
('1m',2,1,'crampon1923','En ces jours-là parut Mathathias, fils de Jean, fils de Siméon, prêtre d''entre les fils de Joarib de Jérusalem, qui habitait Modin.'),
('1m',2,2,'crampon1923','Il avait cinq fils: Jean, surnommé Gaddis;'),
('1m',2,3,'crampon1923','Simon, appelé Thasi;'),
('1m',2,4,'crampon1923','Judas, surnommé Machabée;'),
('1m',2,5,'crampon1923','Eléazar, surnommé Abaron, et Jonathas, surnommé Apphus.'),
('1m',2,6,'crampon1923','Voyant les outrages qui se commettaient en Juda et en Jérusalem,'),
('1m',2,7,'crampon1923','Mathathias dit: " Hélas! pourquoi suis-je né pour voir la ruine de mon peuple et la ruine de la ville sainte, et rester là oisif pendant qu''elle est livrée aux mains des ennemis,'),
('1m',2,8,'crampon1923','et que son sanctuaire est au pouvoir des étrangers? Son temple est devenu comme la demeure d''un homme infâme;'),
('1m',2,9,'crampon1923','les objets précieux qui faisaient sa gloire, on les a emportés comme un butin; ses petits enfants ont été massacrés dans ses rues; l''épée de l''ennemi a abattu ses jeunes hommes.'),
('1m',2,10,'crampon1923','Quel peuple n''a pas hérité de son royaume, et n''a pas eu sa part de ses dépouilles?'),
('1m',2,11,'crampon1923','On lui a enlevé toute sa parure; de libre, elle est devenue esclave.'),
('1m',2,12,'crampon1923','Tout ce que nous avions de saint, de beau et de glorieux est ravagé, profané par les nations.'),
('1m',2,13,'crampon1923','Pourquoi donc vivrions-nous encore? "'),
('1m',2,14,'crampon1923','Alors Mathathias et ses fils déchirèrent leurs vêtements, se couvrirent de sacs et menèrent grand deuil.'),
('1m',2,15,'crampon1923','Les officiers du roi chargés de contraindre à l''apostasie vinrent à Modin pour organiser des sacrifices.'),
('1m',2,16,'crampon1923','Un grand nombre d''Israélites se joignirent à eux; Mathathias et ses fils se réunirent aussi de leur côté.'),
('1m',2,17,'crampon1923','Les envoyés d''Antiochus, s''adressant à Mathathias, lui dirent: " Tu es le premier dans cette ville, le plus grand par la considération et l''influence, et entouré de fils et de frères.'),
('1m',2,18,'crampon1923','Approche donc le premier et exécute le commandement du roi, comme ont fait toutes les nations, les hommes de Juda et ceux qui sont restés dans Jérusalem, et tu seras, toi et les tiens, parmi les amis du roi; toi et tes fils, vous aurez des ornements d''or et d''argent et des présents nombreux. "'),
('1m',2,19,'crampon1923','Mathathias répondit et dit à haute voix: " Quand toutes les nations qui font partie du royaume d''Antiochus lui obéiraient, chacune abandonnant le culte de ses pères, et se soumettraient volontiers à ses ordres,'),
('1m',2,20,'crampon1923','moi, mes fils et mes frères, nous suivrons l''alliance de nos pères.'),
('1m',2,21,'crampon1923','Que Dieu nous garde d''abandonner la loi et ses préceptes!'),
('1m',2,22,'crampon1923','Nous n''obéirons pas aux ordres du roi pour nous écarter de notre culte, soit à droite soit à gauche. "'),
('1m',2,23,'crampon1923','Dès qu''il eut achevé ce discours, un Juif s''avança aux yeux de tous pour sacrifier, selon l''ordre du roi, sur l''autel élevé à Modin.'),
('1m',2,24,'crampon1923','A cette vue, Mathathias fut indigné et ses reins s''émurent; il laissa monter sa colère selon la loi et, se précipitant, il tua cet homme sur l''autel.'),
('1m',2,25,'crampon1923','Il tua en même temps l''officier du roi qui forçait à sacrifier, et renversa l''autel.'),
('1m',2,26,'crampon1923','C''est ainsi qu''il fut transporté de zèle pour la loi, à l''exemple de Phinées, qui tua Zambri, fils de Salum.'),
('1m',2,27,'crampon1923','Alors Mathathias parcourut la ville en criant à haute voix: " Quiconque a le zèle de la loi et maintient l''alliance, qu''il sorte de la ville et me suive! "'),
('1m',2,28,'crampon1923','Et il s''enfuit, lui et ses fils, dans la montagne, abandonnant tout ce qu''ils possédaient dans la ville.'),
('1m',2,29,'crampon1923','Un grand nombre de Juifs qui cherchaient la justice et la loi, descendirent alors dans le désert,'),
('1m',2,30,'crampon1923','pour y demeurer, eux, leurs enfants et leurs femmes, ainsi que leurs bestiaux, parce que les maux qui les accablaient étaient à leur comble.'),
('1m',2,31,'crampon1923','On annonça aux officiers du roi et aux troupes qui étaient à Jérusalem, dans la cité de David, que des hommes qui avaient transgressé l''ordre du roi étaient descendus au désert, dans des retraites cachées.'),
('1m',2,32,'crampon1923','Aussitôt un grand nombre de soldats se mirent à leur poursuite. Lorsqu''ils les eurent atteints, ils campérent vis-à-vis d''eux et se disposèrent à les attaquer le jour du sabbat.'),
('1m',2,33,'crampon1923','Ils leur dirent: " C''est assez d''avoir résisté jusqu''ici. Sortez et exécutez l''ordre du roi, et vous vivrez! "'),
('1m',2,34,'crampon1923','Les Juifs répondirent: " Nous ne sortirons point et nous n''obéirons point à l''ordre du roi; ce serait violer le jour du sabbat. "'),
('1m',2,35,'crampon1923','Aussitôt les Syriens engagèrent contre eux le combat.'),
('1m',2,36,'crampon1923','Ils ne leur répondirent pas, ne leur jetèrent pas une seule pierre et ne bouchèrent pas leur retraite.'),
('1m',2,37,'crampon1923','" Mourons tous, disaient-ils, dans la simplicité de notre cœur! Le ciel et la terre sont témoins pour nous que vous nous faites mourir injustement. "'),
('1m',2,38,'crampon1923','Les soldats les ayant donc attaqués le jour du sabbat, ils moururent, eux, leurs femmes et leurs enfants, ainsi que leurs troupeaux; ils étaient environ mille hommes.'),
('1m',2,39,'crampon1923','Mathathias et ses amis apprirent ce massacre, et ils en éprouvèrent une très grande douleur.'),
('1m',2,40,'crampon1923','Et ils se dirent entre eux: " Si nous faisons tous comme ont fait nos frères, et que nous ne combattions pas contre les nations pour nos vies et pour nos institutions, ils nous auront bientôt exterminés de la terre. "'),
('1m',2,41,'crampon1923','Ils prirent donc en ce jour-là cette résolution: " Qui que ce soit qui vienne en guerre contre nous le jour du sabbat, combattons contre lui, et ne nous laissons pas tuer comme ont fait nos frères dans leurs retraites. "'),
('1m',2,42,'crampon1923','Alors se joignit à eux une troupe d''Assidéens, formée d''hommes vaillants d''Israël, de tous ceux dont le cœur était attaché à la loi.'),
('1m',2,43,'crampon1923','Tous ceux qui cherchaient à échapper aux maux présents vinrent aussi à eux et accrurent leur force.'),
('1m',2,44,'crampon1923','Ayant ainsi formé une armée, ils frappèrent d''abord les prévaricateurs dans leur colère et les impies dans leur indignation; le reste chercha le salut dans la fuite auprès des nations.'),
('1m',2,45,'crampon1923','Mathathias parcourut le pays avec ses fils; ils détruisirent les autels,'),
('1m',2,46,'crampon1923','circoncirent par force tous les enfants incirconcis qu''ils trouvèrent dans la terre d''Israël,'),
('1m',2,47,'crampon1923','et poursuivirent ceux qu''enflait l''orgueil. L''entreprise réussit sous leur conduite;'),
('1m',2,48,'crampon1923','ils soutinrent la cause de la loi contre la puissance des païens et contre la puissance des rois, et ils ne courbèrent pas le front devant le pécheur.'),
('1m',2,49,'crampon1923','Lorsque les jours de Mathathias touchèrent à leur fin, il dit à ses fils: " Maintenant règne l''orgueil et sévit le châtiment; c''est un temps de ruine et d''ardente colère.'),
('1m',2,50,'crampon1923','Maintenant donc, ô mes fils, déployez votre zèle pour la loi et donnez vos vies pour l''alliance de nos pères.'),
('1m',2,51,'crampon1923','Souvenez-vous des œuvres que nos pères ont accomplies de leur temps, et vous recevrez une gloire et un nom immortel.'),
('1m',2,52,'crampon1923','Abraham n''a-t-il pas été trouvé fidèle dans l''épreuve, et sa foi ne lui a-t-elle pas été imputée à justice?'),
('1m',2,53,'crampon1923','Joseph, dans le temps de son affliction, a gardé les commandements, et il est devenu seigneur de l''Egypte.'),
('1m',2,54,'crampon1923','Phinées, notre père, parce qu''il brûla de zèle pour la cause de Dieu, reçut l''assurance d''un sacerdoce saint.'),
('1m',2,55,'crampon1923','Jésus, pour avoir accompli la parole, est devenu juge en Israël.'),
('1m',2,56,'crampon1923','Caleb. pour avoir rendu témoignage dans l''assemblée, reçut une portion du pays.'),
('1m',2,57,'crampon1923','David, par sa piété, obtint un trône royal pour tous les siècles.'),
('1m',2,58,'crampon1923','Elie, parce qu''il brûla de zèle pour la loi, a été enlevé au ciel.'),
('1m',2,59,'crampon1923','Ananias, Azarias et Misaël, ayant eu confiance, ont été sauvés des flammes.'),
('1m',2,60,'crampon1923','Daniel, par son innocence, fut délivré de la gueule des lions.'),
('1m',2,61,'crampon1923','Ainsi considérez, dans tous les âges, que tous ceux qui espèrent en Lui ne succombent point.'),
('1m',2,62,'crampon1923','Ne craignez point les menaces d''un homme pécheur, car sa gloire va à la corruption et aux vers.'),
('1m',2,63,'crampon1923','Il s''élève aujourd''hui, et demain on ne le trouvera plus, parce qu''il sera retourné dans sa poussière et que ses pensées se seront évanouies.'),
('1m',2,64,'crampon1923','Vous donc, mes fils, soyez forts et vaillants à défendre la loi, car par elle vous serez glorifiés.'),
('1m',2,65,'crampon1923','Voici Simon, votre frère; je sais qu''il est homme de conseil, écoutez-le toujours, il sera pour vous un père.'),
('1m',2,66,'crampon1923','Que Judas Machabée, vaillant héros depuis sa jeunesse, soit le chef de votre armée et dirige la guerre contre les peuples.'),
('1m',2,67,'crampon1923','Vous vous adjoindrez tous les observateurs de la loi et vous vengerez votre peuple.'),
('1m',2,68,'crampon1923','Rendez aux nations ce qu''elles ont fait à Israël, et observez les commandements de la loi. "'),
('1m',2,69,'crampon1923','Et après qu''il les eut bénis, il fut réuni à ses pères.'),
('1m',2,70,'crampon1923','Il mourut l''an cent quarante-six; ses fils l''ensevelirent dans le tombeau de leurs pères à Modin, et Israël le pleura dans un grand deuil.'),
('1m',3,1,'crampon1923','Judas, son fils, surnommé Machabée, se leva après lui.'),
('1m',3,2,'crampon1923','Il avait pour auxiliaires tous ses frères et tous ceux qui s''étaient joints à son père, et ensemble ils combattirent joyeusement les combats d''Israël.'),
('1m',3,3,'crampon1923','Il étendit au loin la gloire de son peuple; il revêtit la cuirasse comme un héros, il ceignit ses armes de guerre et engagea des batailles, protégeant de son épée le camp d''Israël.'),
('1m',3,4,'crampon1923','Il était dans l''action pareil au lion, comme le lionceau qui rugit sur sa proie.'),
('1m',3,5,'crampon1923','Il poursuivit les impies, fouillant leurs retraites, et livra aux flammes ceux qui troublaient son peuple.'),
('1m',3,6,'crampon1923','Les impies reculèrent effrayés devant lui, tous les ouvriers d''iniquité furent dans l''épouvante, et sa main conduisit heureusement la délivrance de son peuple.'),
('1m',3,7,'crampon1923','Par ses exploits il causa de l''amertume à plusieurs rois, et de la joie à Jacob, et sa mémoire est à jamais bénie.'),
('1m',3,8,'crampon1923','Il parcourut les villes de Juda et en extermina les impies, et il détourna d''Israël la colère.'),
('1m',3,9,'crampon1923','Son nom devint célèbre jusqu''aux extrémités de la terre, et il recueillit ceux qui allaient périr.'),
('1m',3,10,'crampon1923','Apollonius rassembla des troupes païennes, une grande armée tirée de la Samarie, pour combattre Israël.'),
('1m',3,11,'crampon1923','Dès que Judas en fut informé, il marcha contre lui, le défit et le tua; un grand nombre d''ennemis périrent, et le reste s''enfuit.'),
('1m',3,12,'crampon1923','Les Juifs s''emparèrent de leurs dépouilles, et Judas prit l''épée d''Apollonius, et il s''en servit toujours depuis dans les combats.'),
('1m',3,13,'crampon1923','Séron, chef de l''armée des Syriens, ayant appris que Judas avait rassemblé beaucoup de monde, une troupe de Juifs fidèles marchant avec lui aux combats,'),
('1m',3,14,'crampon1923','il dit: " Je me ferai un nom et j''aurai de la gloire dans le royaume; je combattrai Judas et ceux qui sont avec lui, qui méprisent les ordres du roi. "'),
('1m',3,15,'crampon1923','Il fit donc une seconde expédition; avec lui monta une puissante armée d''impies, pour l''aider et tirer vengeance des enfants d''Israël.'),
('1m',3,16,'crampon1923','Lorsqu''ils furent proches de la montée de Béthoron, Judas marcha à leur rencontre avec une petite troupe.'),
('1m',3,17,'crampon1923','Ses hommes voyant l''armée qui s''avançait contre eux, dirent à Judas: " Comment pourrons-nous, si peu nombreux, combattre contre une si puissante multitude; surtout épuisés que nous sommes par le jeûne d''aujourd''hui? "'),
('1m',3,18,'crampon1923','Judas répondit: " C''est chose facile qu''une multitude soit enfermée dans les mains d''un petit nombre; pour le Dieu du ciel il n''y a point de différence à sauver par un grand nombre ou par un petit nombre.'),
('1m',3,19,'crampon1923','Car la victoire à la guerre n''est pas dans la multitude des combattants; c''est du ciel que vient la force.'),
('1m',3,20,'crampon1923','Ils s''avancent contre nous, remplis d''orgueil et d''impiété, pour nous perdre, nous, nos femmes et nos enfants, et pour nous piller.'),
('1m',3,21,'crampon1923','Mais nous, nous combattons pour notre vie et pour notre loi.'),
('1m',3,22,'crampon1923','Dieu les brisera devant nous; vous donc, ne les craignez pas. "'),
('1m',3,23,'crampon1923','Dès qu''il eut fini de parler, il se jeta subitement sur eux: Séron fut battu et vit écraser son armée sous ses yeux.'),
('1m',3,24,'crampon1923','Judas le poursuivit sur la descente de Béthoron jusqu''à la plaine; huit cents hommes de leurs troupes furent tués, et le reste s''enfuit au pays des Philistins.'),
('1m',3,25,'crampon1923','Alors commença à se répandre la crainte de Judas et de ses frères, et la terreur parmi les nations d''alentour.'),
('1m',3,26,'crampon1923','Son nom arriva jusqu''au roi, et tous les peuples parlaient des combats de Judas.'),
('1m',3,27,'crampon1923','Quand le roi Antiochus eut appris ces nouvelles, il fut transporté de colère; il donna des ordres et rassembla toutes les troupes de son royaume, une armée très puissante.'),
('1m',3,28,'crampon1923','Il ouvrit son trésor et donna à ses troupes une année de solde, et il commanda qu''elles fussent prêtes à tout.'),
('1m',3,29,'crampon1923','Alors il s''aperçut que l''argent manquait dans ses caisses; et les tributs de la province rapportaient peu, à cause des troubles et des maux qu''il avait déchaînés dans le pays, en voulant abolir les lois qui étaient en usage dès les jours anciens.'),
('1m',3,30,'crampon1923','Il craignit de ne pas avoir, comme il était arrivé plusieurs fois, de quoi fournir aux dépenses et aux libéralités qu''il prodiguait auparavant à profusion et plus largement que tous les rois qui l''avaient précédé.'),
('1m',3,31,'crampon1923','Dans cet embarras extrême, il résolut d''aller en Perse pour lever les tributs de ces provinces et recueillir beaucoup d''argent.'),
('1m',3,32,'crampon1923','Il laissa donc Lysias, personnage considérable et de la famille royale, à la tête des affaires du royaume, depuis le fleuve de l''Euphrate jusqu''aux frontières de l''Egypte,'),
('1m',3,33,'crampon1923','et pour prendre soin de son fils Antiochus jusqu''à son retour.'),
('1m',3,34,'crampon1923','Il lui confia la moitié de ses troupes et les éléphants, et lui donna des ordres pour l''exécution de tous ses desseins, et spécialement au sujet de tous les habitants de la Judée et de Jérusalem.'),
('1m',3,35,'crampon1923','Lysias devait envoyer contre eux une armée pour briser et anéantir la puissance d''Israël et le reste de Jérusalem, et effacer de ce lieu leur souvenir,'),
('1m',3,36,'crampon1923','et pour établir dans tout leur pays des fils d''étrangers, auxquels il distribuerait leurs terres par la voie du sort.'),
('1m',3,37,'crampon1923','Puis, ayant pris avec lui l''autre moitié de ses troupes, le roi partit d''Antioche, sa capitale, en l''an cent quarante-sept, passa le fleuve de l''Euphrate et traversa le haut pays.'),
('1m',3,38,'crampon1923','Lysias choisit Ptolémée, fils de Dorymène, Nicanor et Gorgias, habiles capitaines et amis du roi;'),
('1m',3,39,'crampon1923','et il envoya avec eux quarante mille hommes de pied et sept mille cavaliers, pour envahir le pays de Juda et le ruiner selon l''ordre du roi.'),
('1m',3,40,'crampon1923','Ils se mirent en marche avec toutes leurs troupes et, étant entrés en Judée, ils campèrent près d''Emmaüs, dans la plaine.'),
('1m',3,41,'crampon1923','Quand les marchands du pays apprirent leur arrivée, ils prirent avec eux beaucoup d''argent et d''or, ainsi que des entraves, et vinrent au camp des Syriens pour acheter comme esclaves les enfants d''Israël. A cette armée se joignirent les troupes de Syrie et celles du pays des Philistins.'),
('1m',3,42,'crampon1923','Judas et ses frères, voyant que la situation avait empiré et que les armées ennemies campaient à leurs frontières, ayant eu aussi connaissance de l''ordre qu''avait donné le roi de détruire et d''exterminer leur peuple,'),
('1m',3,43,'crampon1923','se dirent les uns aux autres: " Relevons les ruines de notre peuple, et combattons pour notre peuple et notre sanctuaire! "'),
('1m',3,44,'crampon1923','L''assemblée se réunit donc pour être prête au combat, et pour prier et implorer pitié et miséricorde.'),
('1m',3,45,'crampon1923','Or Jérusalem était sans habitants, comme un désert; aucun de ses enfants n''y entrait ou n''en sortait, le sanctuaire était foulé aux pieds et les fils de l''étranger occupaient la forteresse; elle était la demeure des nations. La joie avait disparu de Jacob, la flûte et la harpe étaient muettes.'),
('1m',3,46,'crampon1923','S''étant donc rassemblés, ils vinrent à Maspha, vis-à-vis de Jérusalem, parce qu''il y avait autrefois à Maspha un lieu de prière pour Israël.'),
('1m',3,47,'crampon1923','Ils jeûnèrent ce jour-là, se couvrirent de sacs, jetèrent de la cendre sur leur tête et déchirèrent leurs vêtements.'),
('1m',3,48,'crampon1923','Ils étendirent le livre de la loi, que les nations recherchaient pour y peindre les images de leurs idoles.'),
('1m',3,49,'crampon1923','Ils apportèrent les vêtements sacerdotaux, les prémices et les dîmes, et firent venir des Nazaréens qui avaient accompli le temps de leur vœu;'),
('1m',3,50,'crampon1923','et ils crièrent à haute voix vers le ciel, disant: " Que ferons-nous pour ces hommes, et où les conduirons-nous?'),
('1m',3,51,'crampon1923','Votre sanctuaire a été foulé aux pieds et profané; et vos prêtres sont dans le deuil et l''humiliation.'),
('1m',3,52,'crampon1923','Et voici que les nations se sont assemblées contre nous pour nous anéantir! Vous connaissez leurs desseins contre nous.'),
('1m',3,53,'crampon1923','Comment pourrons-nous tenir devant elles, si vous ne nous assistez pas? "'),
('1m',3,54,'crampon1923','Et ils sonnèrent de la trompette et poussèrent de grands cris.'),
('1m',3,55,'crampon1923','Ensuite Judas établit des chefs du peuple: chefs de mille hommes, de cent, de cinquante et de dix.'),
('1m',3,56,'crampon1923','Et il dit à ceux qui venaient de bâtir une maison, de prendre femme, de planter une vigne, et à ceux qui avaient peur, de s''en retourner chacun dans sa demeure, selon la loi.'),
('1m',3,57,'crampon1923','Puis l''armée se mit en marche et alla camper au sud d''Emmaüs.'),
('1m',3,58,'crampon1923','Là Judas leur dit: " Ceignez-vous et soyez des braves, et tenez-vous prêts pour demain matin à combattre contre ces nations assemblées pour nous perdre, nous et notre sanctuaire.'),
('1m',3,59,'crampon1923','Car mieux vaut pour nous mourir les armes à la main que de voir les maux de notre peuple et notre sanctuaire profané.'),
('1m',3,60,'crampon1923','Quelle que soit la volonté du ciel, qu''elle s''accomplisse! "'),
('1m',4,1,'crampon1923','Gorgias prit avec lui cinq mille hommes et mille cavaliers d''élite, et ils se mirent en marche pendant la nuit,'),
('1m',4,2,'crampon1923','pour s''approcher du camp des Juifs et les frapper à l''improviste; les hommes de la forteresse de Sion leur servaient de guides.'),
('1m',4,3,'crampon1923','Judas, l''ayant appris, se leva, lui et les vaillants, pour frapper l''armée du roi qui était à Emmaüs,'),
('1m',4,4,'crampon1923','pendant que les troupes étaient encore dispersées hors du camp.'),
('1m',4,5,'crampon1923','Gorgias arriva pendant la nuit au camp de Judas, mais il ne trouva personne; alors il se mit à leur recherche dans les montagnes, car il disait: " Ils fuient devant nous! "'),
('1m',4,6,'crampon1923','Dès que vint le jour, Judas apparut dans la plaine, avec trois mille hommes; seulement ils n''avaient, ni pour se couvrir ni pour frapper, les armes qu''ils auraient désirées.'),
('1m',4,7,'crampon1923','A la vue du camp fortifié des nations, des soldats couverts de cuirasses et des cavaliers qui faisaient patrouille autour d''eux, tous exercés au combat,'),
('1m',4,8,'crampon1923','Judas dit aux hommes qui étaient avec lui: " Ne craignez pas leur multitude, et ne redoutez pas leur attaque.'),
('1m',4,9,'crampon1923','Rappelez-vous comment nos pères ont été sauvés dans la mer Rouge, lorsque Pharaon les poursuivait avec une puissante armée.'),
('1m',4,10,'crampon1923','Crions maintenant vers le ciel, dans l''espoir qu''il daignera avoir pitié de nous, se souvenir de son alliance avec nos pères, et détruire aujourd''hui cette armée devant nos yeux.'),
('1m',4,11,'crampon1923','Et toutes les nations sauront qu''il y a quelqu''un qui délivre et sauve Israël. "'),
('1m',4,12,'crampon1923','Alors les étrangers levèrent les yeux et les aperçurent marchant contre eux;'),
('1m',4,13,'crampon1923','et ils sortirent du camp pour livrer bataille; en même temps ceux qui étaient avec Judas sonnèrent de la trompette.'),
('1m',4,14,'crampon1923','On en vint aux mains, et les nations furent abattues et s''enfuirent dans la plaine.'),
('1m',4,15,'crampon1923','Les derniers rangs tombèrent tous par l''épée, et les Juifs les poursuivirent jusqu''à Gazara, et jusque dans les plaines de Judée, d''Azot et de Jamnia, et ils leur tuèrent près de trois mille hommes.'),
('1m',4,16,'crampon1923','Alors Judas, avec son armée, revint sur ses pas et cessa de les poursuivre,'),
('1m',4,17,'crampon1923','disant au peuple: " Ne soyez pas avides de butin, car un combat nous attend.'),
('1m',4,18,'crampon1923','Gorgias et ses troupes sont près de nous dans la montagne; mais tenez ferme en ce moment contre nos ennemis, battez-les, et vous pourrez ensuite prendre sans crainte leurs dépouilles. "'),
('1m',4,19,'crampon1923','Judas parlait encore, lorsqu''une division de Gorgias se montra sortant de la montagne.'),
('1m',4,20,'crampon1923','Ils virent que les leurs étaient en fuite et que les Juifs avaient mis le feu au camp; car la fumée qu''on apercevait manifestait ce qui s''était passé.'),
('1m',4,21,'crampon1923','A cette vue, ils eurent une grande peur; et comme ils apercevaient en même temps l''armée de Judas rangée dans la plaine, prête à livrer bataille,'),
('1m',4,22,'crampon1923','ils s''enfuirent tous dans le pays des Philistins.'),
('1m',4,23,'crampon1923','Judas revint pour piller le camp; ils emportèrent beaucoup d''or et d''argent, ainsi que des étoffes de pourpre violette et de pourpre écarlate, et de grandes richesses.'),
('1m',4,24,'crampon1923','A leur retour, ils chantaient des cantiques, faisant monter vers le ciel des louanges au Seigneur: " Car il est bon, car sa miséricorde subsiste à jamais. "'),
('1m',4,25,'crampon1923','Une grande délivrance fut donnée à Israël en ce jour-là.'),
('1m',4,26,'crampon1923','Ceux des étrangers qui avaient échappé vinrent annoncer à Lysias tout ce qui était arrivé.'),
('1m',4,27,'crampon1923','En apprenant cette nouvelle, il fut attristé et abattu, parce que ses desseins contre Israël avaient échoué et que les ordres du roi n''étaient pas exécutés.'),
('1m',4,28,'crampon1923','L''année suivante, Lysias rassembla une armée de soixante mille fantassins d''élite et de cinq mille cavaliers, afin de venir à bout des Juifs.'),
('1m',4,29,'crampon1923','Ils s''avancèrent vers la Judée et établirent leur camp près de Béthoron. Judas marcha contre eux à la tête de dix mille hommes.'),
('1m',4,30,'crampon1923','A la vue de cette armée redoutable, il pria en disant: " Vous êtes béni, ô libérateur d''Israël, qui avez brisé la force du géant par la main de votre serviteur David, et livré le camp des Philistins entre les mains de Jonathas, fils de Saül, et de son écuyer.'),
('1m',4,31,'crampon1923','Enfermez cette armée dans les mains de votre peuple d''Israël, et qu''ils soient confondus avec leurs fantassins et leurs cavaliers.'),
('1m',4,32,'crampon1923','Inspirez-leur la terreur, abattez leur audace présomptueuse, et qu''ils soient ébranlés par leur défaite.'),
('1m',4,33,'crampon1923','Faites-les tomber par l''épée de ceux qui vous aiment, et que tous ceux qui connaissent votre nom vous adressent des hymnes de louange. "'),
('1m',4,34,'crampon1923','Ils engagèrent le combat, et cinq mille hommes de l''armée de Lysias tombèrent devant les Juifs.'),
('1m',4,35,'crampon1923','Voyant la déroute de son armée et l''intrépidité des soldats de Judas, qui se montraient disposés à vivre ou à mourir honorablement, Lysias retourna à Antioche et recruta des étrangers; il se promettait, après avoir augmenté son armée, de revenir en Judée.'),
('1m',4,36,'crampon1923','Alors Judas et ses frères dirent: " Voilà nos ennemis défaits; montons maintenant purifier le temple et le reconsacrer. "'),
('1m',4,37,'crampon1923','Toute l''armée se rassembla, et ils montèrent au mont Sion.'),
('1m',4,38,'crampon1923','En voyant le sanctuaire désert, l''autel profané, les portes brûlées, des arbrisseaux croissant dans le parvis comme dans un bois ou sur les montagnes, et les chambres détruites,'),
('1m',4,39,'crampon1923','ils déchirèrent leurs vêtements, se lamentèrent en grand deuil, répandirent de la cendre sur leur tête,'),
('1m',4,40,'crampon1923','se prosternèrent le visage contre terre, et, pendant que les trompettes sonnaient en fanfare, poussèrent des cris vers le ciel.'),
('1m',4,41,'crampon1923','Alors Judas détacha un corps de troupes pour combattre les Syriens qui étaient dans la citadelle, jusqu''à ce que les lieux saints fussent purifiés.'),
('1m',4,42,'crampon1923','Puis il choisit des prêtres sans défauts, attachés à la loi de Dieu;'),
('1m',4,43,'crampon1923','et ils purifièrent le sanctuaire et transportèrent dans un lieu immonde les pierres souillées.'),
('1m',4,44,'crampon1923','On délibéra sur ce qu''on devait faire à l''autel des holocaustes qui avait été profané,'),
('1m',4,45,'crampon1923','et l''heureuse pensée leur vint de le détruire, de peur qu''il ne fût pour eux un opprobre après que les Gentils l''avaient souillé. Ils démolirent l''autel,'),
('1m',4,46,'crampon1923','et en déposèrent les pierres sur la montagne du temple, dans un lieu convenable, en attendant la venue d''un prophète qui donnerait une décision à leur sujet.'),
('1m',4,47,'crampon1923','Et ils prirent des pierres brutes, selon la loi, et construisirent un autel nouveau sur le modèle de l''ancien.'),
('1m',4,48,'crampon1923','Ils rebâtirent le sanctuaire, ainsi que l''intérieur du temple, et ils sanctifièrent les parvis.'),
('1m',4,49,'crampon1923','Ils confectionnèrent de nouveaux ustensiles sacrés, replacèrent dans le temple le chandelier, l''autel des parfums et la table.'),
('1m',4,50,'crampon1923','Ils firent fumer l''encens sur l''autel, allumèrent les lampes du chandelier et elles éclairaient dans le temple.'),
('1m',4,51,'crampon1923','Ils placèrent des pains sur la table et suspendirent les voiles. Après avoir achevé tous les ouvrages qu''ils avaient faits,'),
('1m',4,52,'crampon1923','ils se levèrent de grand matin, le vingt-cinquième jour du neuvième mois — c''est le mois nommé Casleu — de l''an cent quarante-huit,'),
('1m',4,53,'crampon1923','et ils offrirent un sacrifice, selon la loi, sur le nouvel autel des holocaustes qu''ils avaient construit.'),
('1m',4,54,'crampon1923','Dans le même mois et le même jour qu''il avait été profané par les nations, l''autel fut consacré de nouveau, au chant des psaumes, au son des harpes, des lyres et des cymbales.'),
('1m',4,55,'crampon1923','Tout le peuple tomba sur sa face et adora et, levant les yeux vers le ciel, il bénissait Celui qui lui avait donné prospérité.'),
('1m',4,56,'crampon1923','Ils célébrèrent la dédicace de l''autel pendant huit jours, et ils offrirent des holocaustes avec joie, et des sacrifices d''actions de grâces et de louanges.'),
('1m',4,57,'crampon1923','Ils ornèrent la façade du temple de couronnes et d''écussons, et réparèrent les entrées du temple et les chambres, et leur mirent des portes.'),
('1m',4,58,'crampon1923','Il y eut parmi le peuple une très grande joie, et l''opprobre infligé par les nations fut ôté.'),
('1m',4,59,'crampon1923','Judas, d''accord avec ses frères et toute l''assemblée d''Israël, établit que les jours de la dédicace de l''autel seraient célébrés en leur temps chaque année pendant huit jours, à partir du vingt-cinq Casleu, avec joie et allégresse.'),
('1m',4,60,'crampon1923','En ce même temps, ils construisirent sur le mont Sion une enceinte de hautes murailles et de fortes tours, afin que les nations ne vinssent plus, comme elles l''avaient fait auparavant, fouler aux pieds les saints lieux.'),
('1m',4,61,'crampon1923','Et Judas y mit un détachement pour en avoir la garde, et pour sa défense. On fortifia Bethsur, afin que le peuple eût une forteresse en face de l''Idumée.'),
('1m',5,1,'crampon1923','Lorsque les nations d''alentour eurent appris que l''autel avait été reconstruit et le sanctuaire rétabli comme il était auparavant, elles furent très irritées.'),
('1m',5,2,'crampon1923','Elles résolurent d''exterminer les descendants de Jacob qui vivaient parmi elles, et elles commencèrent à en massacrer plusieurs et à les poursuivre.'),
('1m',5,3,'crampon1923','Judas fit la guerre aux fils d''Esaü dans l''Idumée, au pays d''Acrabathane, parce qu''ils attaquaient les enfants d''Israël; il leur infligea une grande défaite, les humilia et prit leurs dépouilles.'),
('1m',5,4,'crampon1923','Il se souvint aussi de la méchanceté des fils de Béan, qui étaient pour le peuple un piège et un danger, par les embûches qu''ils lui dressaient dans les chemins.'),
('1m',5,5,'crampon1923','Il les bloqua dans leurs tours, les assiégea, les voua à l''anathème et brûla leurs tours avec tous ceux qui étaient dedans.'),
('1m',5,6,'crampon1923','Puis il passa chez les Ammonites, et il trouva là une forte armée et un peuple nombreux, qui avait pour chef Timothée.'),
('1m',5,7,'crampon1923','Il leur livra de nombreux combats et ils furent écrasés devant lui, et il les tailla en pièces.'),
('1m',5,8,'crampon1923','Il prit Jazer et les villes de sa dépendance, et revint en Judée.'),
('1m',5,9,'crampon1923','Les nations qui sont en Galaad se réunirent contre les Israélites qui habitaient sur leur territoire, afin de les exterminer, et ceux-ci se réfugièrent dans la forteresse de Dathéman.'),
('1m',5,10,'crampon1923','Ils envoyèrent des lettres à Judas et à ses frères, en disant: " Les nations qui nous entourent se sont rassemblées contre nous pour nous faire périr.'),
('1m',5,11,'crampon1923','Elles se préparent à venir et à s''emparer de la forteresse dans laquelle nous nous sommes réfugiés; et Timothée est le chef de leur armée.'),
('1m',5,12,'crampon1923','Viens donc maintenant nous délivrer de leurs mains, car déjà un grand nombre des nôtres sont tombés.'),
('1m',5,13,'crampon1923','Tous nos frères qui étaient dans le pays de Tob ont été mis à mort; nos ennemis ont emmené en captivité leurs femmes et leurs enfants et pris leurs biens; ils ont tué là prés de mille hommes. "'),
('1m',5,14,'crampon1923','On était encore à lire leurs lettres, lorsqu''arrivèrent de la Galilée d''autres messagers, les vêtements déchirés, apportant cette nouvelle:'),
('1m',5,15,'crampon1923','« Les gens de Ptolémaïs, de Tyr, de Sidon et de toute la Galilée des étrangers, se sont rassemblés pour nous faire périr. »'),
('1m',5,16,'crampon1923','Lorsque Judas et le peuple eurent entendu ces discours, il se tint une grande assemblée pour examiner ce qu''ils devaient faire pour leurs frères qui étaient dans la tribulation et attaqués par ces ennemis.'),
('1m',5,17,'crampon1923','Judas dit à Simon son frère: " Choisis-toi des hommes et va délivrer tes frères qui sont en Galilée; mon frère Jonathas et moi, nous irons en Galaad. "'),
('1m',5,18,'crampon1923','Il laissa en Judée Joseph, fils de Zacharie, et Azarias, chefs du peuple, avec le reste de l''armée pour faire la garde,'),
('1m',5,19,'crampon1923','et il leur donna cet ordre: " Gouvernez ce peuple, mais n''engagez pas de combat avec les nations jusqu''à notre retour. "'),
('1m',5,20,'crampon1923','On assigna à Simon trois mille hommes pour aller en Galilée, et huit mille à Judas pour aller en Galaad.'),
('1m',5,21,'crampon1923','Simon se rendit en Galilée et livra aux nations de nombreux combats, et les nations furent écrasées devant lui, et il les poursuivit jusqu''à la porte'),
('1m',5,22,'crampon1923','de Ptolémaïs. Près de trois mille hommes périrent d''entre les nations, et il enleva leurs dépouilles.'),
('1m',5,23,'crampon1923','Il recueillit les Juifs qui étaient en Galilée et dans Arbates, avec leurs femmes, leurs enfants et tout ce qui leur appartenait, et il les emmena en Judée avec une grande joie.'),
('1m',5,24,'crampon1923','De leur côté Judas Machabée et Jonathas, son frère, franchirent le Jourdain et s''avancèrent à trois jours de marche dans le désert.'),
('1m',5,25,'crampon1923','Ils rencontrèrent les Nabatéens, qui les reçurent avec amitié et leur racontèrent tout ce qui était arrivé à leurs frères en Galaad:'),
('1m',5,26,'crampon1923','" Un grand nombre d''entre eux, leur dirent-ils, sont tenus enfermés à Bossora et à Bosor, dans Alimes, Casphor, Maced et Carnaïm, villes qui sont toutes fortifiées et grandes;'),
('1m',5,27,'crampon1923','il y en a aussi d''enfermés dans les autres villes de Galaad. Et leurs ennemis se préparent à attaquer dès demain ces forteresses, à s''en emparer et à les faire périr tous en un seul jour. "'),
('1m',5,28,'crampon1923','Judas, changeant de direction, prit avec son armée une route vers l''intérieur du désert et parut tout à coup devant Bosor; il s''empara de la ville, passa au fil de l''épée toute la population mâle, prit toutes leurs dépouilles et livra la ville aux flammes.'),
('1m',5,29,'crampon1923','Il partit de là pendant la nuit et marcha jusqu''à la forteresse de Dathéman.'),
('1m',5,30,'crampon1923','Le matin venu, ils levèrent les yeux et aperçurent une multitude innombrable portant des échelles et des machines pour s''emparer de la forteresse et combattant les Juifs.'),
('1m',5,31,'crampon1923','Voyant que le combat était engagé et que le cri des habitants montait jusqu''au ciel avec le son des trompettes et de grandes clameurs, Judas'),
('1m',5,32,'crampon1923','dit aux hommes de son armée: " Battez-vous aujourd''hui pour vos frères! "'),
('1m',5,33,'crampon1923','Et il s''avança en trois corps sur les derrières de l''ennemi; puis ils firent retentir les trompettes et prièrent avec de grands cris.'),
('1m',5,34,'crampon1923','Dès que l''armée de Timothée eut reconnu que c''était Machabée, ils s''enfuirent devant lui, et il leur infligea une sanglante défaite; prés de huit mille hommes d''entre eux périrent dans cette journée.'),
('1m',5,35,'crampon1923','De là, Judas se détourna vers Maspha; l''ayant attaquée, il s''en empara, tua toute la population mâle, prit leurs dépouilles et livra la ville aux flammes.'),
('1m',5,36,'crampon1923','S''avançant plus loin, il s''empara de Casphon, de Maced, de Bosor et des autres villes de la Galaaditide.'),
('1m',5,37,'crampon1923','Après ces événements, Timothée rassembla une autre armée et alla camper vis-à-vis de Raphon, au-delà du torrent.'),
('1m',5,38,'crampon1923','Judas envoya reconnaître cette armée, et on lui fit ce rapport: " Toutes les nations qui nous entourent se sont réunies aux troupes de Timothée et forment une armée très nombreuse.'),
('1m',5,39,'crampon1923','Ils ont soudoyé des Arabes comme auxiliaires et ont placé leur camp au-delà du torrent, prêts à te livrer bataille. " Et Judas s''avança à leur rencontre.'),
('1m',5,40,'crampon1923','Timothée dit aux chefs de son armée: " Quand Judas avec ses troupes s''approchera du cours d''eau, s''il passe vers nous le premier, vous ne pourrez lui résister; il l''emportera sur nous.'),
('1m',5,41,'crampon1923','Mais s''il craint de passer, et établit son camp au-delà du fleuve, passons vers lui et nous prévaudrons contre lui. "'),
('1m',5,42,'crampon1923','Judas, étant arrivé au cours d''eau, fit arrêter sur le bord les scribes de l''armée et leur donna cet ordre: " Ne laissez personne faire halte, mais que tous viennent à la bataille! "'),
('1m',5,43,'crampon1923','Et, marchant à l''ennemi, il passa l''eau le premier, suivi de tout le peuple. Tous les Gentils furent écrasés devant lui; ils jetèrent toutes leurs armes et s''enfuirent dans le temple qui est à Carnaïm.'),
('1m',5,44,'crampon1923','Les Juifs s''emparèrent de la ville, brûlèrent le temple avec tous ceux qui s''y trouvaient, et Carnaïm fut abaissée, et les ennemis ne purent plus tenir devant Judas.'),
('1m',5,45,'crampon1923','Alors Judas rassembla tous les Israélites qui étaient en Galaad, depuis le plus petit jusqu''au plus grand, avec leurs femmes, leurs enfants et leurs biens, immense multitude! pour les amener dans le pays de Juda.'),
('1m',5,46,'crampon1923','Ils arrivèrent à Ephron, grande ville commandant l''entrée du pays et très fortifiée; on ne pouvait s''en détourner ni à droite ni à gauche, mais il fallait la traverser.'),
('1m',5,47,'crampon1923','Les habitants s''y enfermèrent et en obstruèrent les portes avec des pierres. Judas leur envoya adresser des paroles de paix:'),
('1m',5,48,'crampon1923','" Que nous puissions traverser votre territoire pour aller dans notre pays; personne ne vous causera de dommage; nous ne demandons qu''à passer seulement. " Mais ils ne voulurent pas lui ouvrir.'),
('1m',5,49,'crampon1923','Alors Judas fit publier dans son armée que chacun prit position où il était.'),
('1m',5,50,'crampon1923','Les hommes de l''armée prirent donc leurs positions; puis il donna l''assaut à la ville tout le jour et toute la nuit, et la ville fut livrée entre ses mains.'),
('1m',5,51,'crampon1923','Il passa tous les mâles au fil de l''épée, détruisit la ville de fond en comble, en enleva les dépouilles et la traversa sur les cadavres.'),
('1m',5,52,'crampon1923','Puis, franchissant le Jourdain, les Juifs arrivèrent dans la grande plaine qui est vis-à-vis de Bethsan.'),
('1m',5,53,'crampon1923','Judas se tenait à l''arrière garde, ralliant les traînards et exhortant le peuple sur tout le chemin, jusqu''à ce qu''ils fussent arrivés dans le pays de Juda.'),
('1m',5,54,'crampon1923','Et ils montèrent sur le mont Sion avec joie et allégresse, et ils offrirent des holocaustes, parce qu''ils étaient heureusement revenus, sans perdre aucun des leurs.'),
('1m',5,55,'crampon1923','Pendant que Judas était, avec Jonathas, dans le pays de Galaad, et que Simon, son frère, était en Galilée devant Ptolémaïs,'),
('1m',5,56,'crampon1923','Joseph, fils de Zacharie, et Azarias, chefs de l''armée, apprirent les actions d''éclat qu''ils avaient faites et les combats qu''ils avaient livrés;'),
('1m',5,57,'crampon1923','et ils se dirent: " Faisons-nous un nom, nous aussi, et allons combattre contre les nations qui sont autour de nous! "'),
('1m',5,58,'crampon1923','Ils donnèrent donc leurs ordres aux hommes de leur armée, et ils marchèrent contre Jamnia.'),
('1m',5,59,'crampon1923','Gorgias sortit de la ville avec ses hommes et s''avança à leur rencontre pour les combattre.'),
('1m',5,60,'crampon1923','Joseph et Azarias furent battus et poursuivis jusqu''à la frontière de Judée; il périt ce jour-là deux mille hommes du peuple d''Israël. Cette grande défaite arriva au peuple d''Israël'),
('1m',5,61,'crampon1923','parce qu''ils n''avaient pas écouté Judas et ses frères, s''imaginant faire preuve de vaillance.'),
('1m',5,62,'crampon1923','Mais ils n''étaient pas de la race de ces hommes aux mains desquels était livré le salut d''Israël.'),
('1m',5,63,'crampon1923','Le vaillant Judas et ses frères eurent une grande gloire devant tout Israël et toutes les nations où leur nom était prononcé.'),
('1m',5,64,'crampon1923','On se rassemblait autour d''eux pour les féliciter.'),
('1m',5,65,'crampon1923','Ensuite Judas se mit en marche avec ses frères pour combattre les fils d''Esaü dans le pays du midi; il s''empara d''Hébron et des villes de sa dépendance, détruisit ses fortifications et brûla les tours de son enceinte.'),
('1m',5,66,'crampon1923','Ayant levé son camp, il alla dans le pays des Philistins et traversa Marésa.'),
('1m',5,67,'crampon1923','En ce jour périrent dans le combat plusieurs prêtres qui voulaient faire preuve de bravoure, en prenant part imprudemment à la lutte.'),
('1m',5,68,'crampon1923','Puis Judas se dirigea sur Azot, territoire des Philistins; il démolit leurs autels, brûla les images taillées de leurs dieux et, après avoir pillé les villes, revint dans le pays de Juda.'),
('1m',6,1,'crampon1923','Cependant, le roi Antiochus parcourait les hautes provinces. Ayant appris qu''il y avait en Perse, dans l''Elymaïde, une ville célèbre par ses richesses en argent et en or,'),
('1m',6,2,'crampon1923','avec un temple très riche renfermant des armures d''or, des cuirasses et d''autres armes qu''y avait laissées Alexandre, fils de Philippe, roi de Macédoine, qui régna le premier sur les Grecs,'),
('1m',6,3,'crampon1923','il s''y rendit, et il cherchait à prendre la ville et à la piller; mais il n''y réussit pas, parce que les habitants de la ville eurent connaissance de son dessein.'),
('1m',6,4,'crampon1923','Ils se levèrent pour le combattre, et il prit la fuite et se retira avec une grande tristesse, pour retourner à Babylone.'),
('1m',6,5,'crampon1923','Alors vint en Perse un messager qui lui annonça la défaite des troupes qui étaient entrées dans le pays de Juda:'),
('1m',6,6,'crampon1923','Lysias, s''étant avancé avec une armée très forte, avait dû fuir devant les Juifs, et ceux-ci avaient accru leur puissance en armes, en soldats et en dépouilles enlevées aux armées vaincues;'),
('1m',6,7,'crampon1923','ils avaient détruit l''abomination élevée par lui sur l''autel qui était à Jérusalem, ils avaient entouré le temple de hautes murailles, comme il était auparavant, et fait de même à Bethsur, une de ses villes.'),
('1m',6,8,'crampon1923','En apprenant ces nouvelles, le roi fut frappé de terreur, un grand trouble le saisit; il se jeta sur son lit et tomba malade de tristesse, parce que ses désirs ne s''étaient pas réalisés.'),
('1m',6,9,'crampon1923','Il demeura là pendant plusieurs jours, retombant sans cesse dans sa profonde mélancolie. Lorsqu''il se crut sur le point de mourir,'),
('1m',6,10,'crampon1923','il appela ses amis et leur dit: " Le sommeil s''est retiré de mes yeux, et le chagrin fait défaillir mon cœur.'),
('1m',6,11,'crampon1923','Je me dis: A quel degré d''affliction suis-je arrivé, et dans quel profond abîme suis-je maintenant! Moi qui étais bon et aimé dans mon empire!'),
('1m',6,12,'crampon1923','Mais maintenant, je me souviens des maux que j''ai faits dans Jérusalem; j''ai emporté tous les ustensiles d''or et d''argent qui s''y trouvaient, et j''ai envoyé une armée pour exterminer tous les habitants de la Judée sans motif.'),
('1m',6,13,'crampon1923','Je reconnais donc que c''est à cause de cela que ces maux m''ont atteint, et voici que je meurs dans une grande affliction sur une terre étrangère. "'),
('1m',6,14,'crampon1923','Alors il appela Philippe, un de ses amis, et l''établit sur tout son royaume.'),
('1m',6,15,'crampon1923','Il lui donna son diadème, sa robe et le sceau royal, le chargeant d''instruire son fils Antiochus et de l''élever pour la royauté.'),
('1m',6,16,'crampon1923','Et le roi Antiochus mourut en ce lieu, l''an cent quarante-neuf.'),
('1m',6,17,'crampon1923','Lorsque Lysias eut appris la mort du roi, il établit pour régner à sa place son fils Antiochus, qu''il avait nourri depuis son enfance, et il lui donna le nom d''Eupator.'),
('1m',6,18,'crampon1923','La garnison de la citadelle tenait Israël enfermé autour du sanctuaire; elle cherchait sans cesse à le molester, et elle était un appui pour les nations.'),
('1m',6,19,'crampon1923','Judas résolut de la détruire et rassembla tout le peuple pour l''assiéger.'),
('1m',6,20,'crampon1923','Ils se réunirent tous, en firent le siège l''an cent cinquante et construisirent contre elle des tours à balistes et des machines.'),
('1m',6,21,'crampon1923','Mais quelques-uns des assiégés s''échappèrent et plusieurs Israélites impies se joignirent à eux.'),
('1m',6,22,'crampon1923','Ils allèrent trouver le roi et lui dirent: " Jusqu''à quand tarderas-tu à nous rendre justice et à venger nos frères?'),
('1m',6,23,'crampon1923','Nous nous sommes mis volontiers au service de ton père, faisant ce qu''il nous disait et exécutant ses ordres.'),
('1m',6,24,'crampon1923','A cause de cela les fils de notre peuple sont devenus nos ennemis; tous ceux d''entre nous qui sont tombés entre leurs mains ont été massacrés, et ils ont mis au pillage nos héritages.'),
('1m',6,25,'crampon1923','Ce n''est pas seulement sur nous qu''ils ont étendu la main, mais sur tous les pays limitrophes.'),
('1m',6,26,'crampon1923','Vois, ils sont campés en ce moment devant la citadelle de Jérusalem pour s''en emparer, et ils ont fortifié le temple et Bethsur.'),
('1m',6,27,'crampon1923','Si tu ne te hâtes pas de les prévenir, ils en feront encore plus et tu ne pourras plus les arrêter. "'),
('1m',6,28,'crampon1923','Le roi, les ayant entendus, fut pris de colère; il convoqua tous ses amis, les chefs de son armée et ceux qui commandaient la cavalerie.'),
('1m',6,29,'crampon1923','Il lui vint aussi des troupes mercenaires d''autres royaumes et des îles de la mer.'),
('1m',6,30,'crampon1923','Son armée comptait cent mille fantassins, vingt mille cavaliers et trente-deux éléphants dressés à la guerre.'),
('1m',6,31,'crampon1923','Ils s''avancèrent par l''Idumée et établirent leur camp devant Bethsur; ils combattirent longtemps et construisirent des machines; mais les Juifs firent une sortie et les brûlèrent, déployant une grande vaillance.'),
('1m',6,32,'crampon1923','Alors Judas quitta la citadelle et alla camper à Beth-Zacharia, vis-à-vis du camp du roi.'),
('1m',6,33,'crampon1923','Le roi se leva de grand matin et fit prendre brusquement à son armée le chemin de Beth-Zacharia, et les troupes se disposèrent pour l''attaque et sonnèrent de la trompette.'),
('1m',6,34,'crampon1923','Ils mirent sous les yeux des éléphants du jus de raisin et de mûre, pour les exciter au combat.'),
('1m',6,35,'crampon1923','Ils distribuèrent ces animaux entre les phalanges; chaque éléphant était accompagné de mille hommes revêtus de cuirasses en mailles de fer, avec un casque d''airain sur la tête, et cinq cents cavaliers d''élite étaient rangés auprès de lui.'),
('1m',6,36,'crampon1923','Ces derniers, d''avance, étaient partout où était la bête; là où elle allait, ils y allaient, et ils ne la quittaient jamais.'),
('1m',6,37,'crampon1923','Sur chacun des éléphants s''élevait, pour sa défense, une solide tour de bois attachée autour de lui par des sangles, et chaque animal portait trente-deux hommes de l''armée, combattant sur les tours, en plus de son cornac.'),
('1m',6,38,'crampon1923','Ils placèrent le reste de la cavalerie sur les deux flancs de l''armée, afin d''inquiéter l''ennemi et de protéger les phalanges.'),
('1m',6,39,'crampon1923','Lorsque les rayons du soleil tombèrent sur les boucliers d''or et d''airain, les montagnes resplendirent de leur éclat et brillèrent comme des lampes de feu.'),
('1m',6,40,'crampon1923','Une partie de l''armée du roi se déploya sur les hautes montagnes et l''autre partie dans les vallées, et ils s''avançaient d''un pas assuré et en bon ordre.'),
('1m',6,41,'crampon1923','Tous étaient épouvantés des cris de cette multitude, du bruit de leur marche et du fracas de leurs armes. C''était en effet une armée extrêmement nombreuse et puissante.'),
('1m',6,42,'crampon1923','Judas s''avança avec son armée pour livrer bataille, et six cents hommes de l''armée du roi tombèrent.'),
('1m',6,43,'crampon1923','Eléazar, surnommé Abaron, aperçut un des éléphants couvert des harnais royaux et dépassant tous les autres en hauteur. S''imaginant que le roi était dessus,'),
('1m',6,44,'crampon1923','il se dévoua pour délivrer son peuple et s''acquérir un nom immortel.'),
('1m',6,45,'crampon1923','Il courut hardiment vers lui à travers la phalange, tuant à droite et à gauche, et devant lui les ennemis s''écartaient de part et d''autre.'),
('1m',6,46,'crampon1923','Alors il se glissa sous l''éléphant, lui enfonça son épée et le tua; l''éléphant tomba par terre sur lui, et Eléazar mourut là.'),
('1m',6,47,'crampon1923','Les Juifs, voyant les forces du royaume et l''impétuosité des troupes, se retirèrent devant elles.'),
('1m',6,48,'crampon1923','En même temps ceux de l''armée du roi montèrent vers Jérusalem à la rencontre des Juifs, et le roi établit son camp contre la Judée et contre le mont Sion.'),
('1m',6,49,'crampon1923','Il fit la paix avec ceux qui étaient à Bethsur, et ceux-ci sortirent de la ville, parce qu''il n''y avait pas eu de vivres à renfermer pour eux dans la place, car c''était l''année du repos de la terre.'),
('1m',6,50,'crampon1923','Le roi s''empara ainsi de Bethsur, et il y laissa une garnison pour la garder.'),
('1m',6,51,'crampon1923','Il établit son camp devant le lieu saint pendant beaucoup de jours, et il y dressa des tours à balistes, des machines de guerre, des catapultes pour lancer des traits enflammés et des pierres, des scorpions pour lancer des flèches, et des frondes.'),
('1m',6,52,'crampon1923','Les assiégés construisirent aussi des machines pour les opposer à celles des assiégeants, et prolongèrent longtemps la résistance.'),
('1m',6,53,'crampon1923','Mais il n''y avait pas de vivres dans les magasins, parce que c''était la septième année, et que les Israélites qui s''étaient réfugiés en Judée devant les nations avaient consommé le reste de ce qu''on avait mis en réserve.'),
('1m',6,54,'crampon1923','Il ne resta dans le lieu saint qu''un petit nombre de Juifs, car la faim se faisait de plus en plus sentir; les autres se dispersèrent chacun chez soi.'),
('1m',6,55,'crampon1923','Cependant Philippe, que le roi Antiochus encore vivant avait désigné pour élever Antiochus son fils et en faire un roi,'),
('1m',6,56,'crampon1923','était revenu de Perse et de Médie, et avec lui les troupes qui avaient accompagné le roi; et il cherchait à prendre en main les affaires du royaume.'),
('1m',6,57,'crampon1923','A cette nouvelle, Lysias n''eut rien de plus pressé que de se retirer; il dit au roi, aux chefs de l''armée et aux troupes: " Nous nous amoindrissons ici de jour en jour; nous n''avons que peu de vivres, et le lieu que nous assiégeons est bien fortifié, et nous avons à nous occuper des affaires de l''Etat.'),
('1m',6,58,'crampon1923','Maintenant donc, tendons la main à ces hommes, et faisons la paix avec eux et avec toute leur nation.'),
('1m',6,59,'crampon1923','Reconnaissons-leur le droit de vivre selon leurs lois, comme auparavant; car c''est à cause de ces lois, que nous avons voulu abolir, qu''ils se sont irrités et ont fait tout cela. "'),
('1m',6,60,'crampon1923','Ce discours plut au roi et aux chefs, et il envoya vers eux pour traiter de la paix, et ils l''acceptèrent.'),
('1m',6,61,'crampon1923','Le roi et les chefs confirmèrent le traité par serment; là-dessus, les assiégés sortirent de la forteresse.'),
('1m',6,62,'crampon1923','Mais le roi ayant pénétré dans l''enceinte du mont Sion et en ayant vu les fortifications, il viola le serment qu''il avait prêté et donna l''ordre de détruire les murailles tout autour.'),
('1m',6,63,'crampon1923','Puis il partit en grande hâte et retourna à Antioche, où il trouva Philippe maître de la ville; il combattit contre lui et se rendit maître de la ville.'),
('1m',7,1,'crampon1923','L''an cent cinquante et un, Démétrius, fils de Séleucus, s''échappa de la ville de Rome et aborda, avec un petit nombre de gens, dans une ville maritime où il prit le titre de roi.'),
('1m',7,2,'crampon1923','Dès qu''il eut fait son entrée dans le royaume de ses pères, l''armée se saisit d''Antiochus et de Lysias pour les lui amener.'),
('1m',7,3,'crampon1923','Lorsqu''il en fut averti, il dit: " Ne me faites pas voir leur visage. "'),
('1m',7,4,'crampon1923','Alors l''armée les tua, et Démétrius s''assit sur le trône de son royaume.'),
('1m',7,5,'crampon1923','Alors tous les hommes iniques et impies d''Israël vinrent le trouver, conduits par Alcime, qui voulait être grand prêtre.'),
('1m',7,6,'crampon1923','Ils accusèrent le peuple auprès du roi en disant: " Judas et ses frères ont fait périr tous tes amis, et nous ont expulsés de notre terre.'),
('1m',7,7,'crampon1923','Envoie donc maintenant un homme en qui tu aies confiance, pour qu''il aille constater toute la ruine qu''ils ont faite parmi nous et dans les provinces du roi, et qu''il punisse les coupables avec tous ceux qui leur viennent en aide. "'),
('1m',7,8,'crampon1923','Le roi choisit parmi ses amis Bacchidès, gouverneur du pays situé au-delà du fleuve, homme très considérable dans le royaume et fidèle au roi;'),
('1m',7,9,'crampon1923','et il l''envoya avec l''impie Alcime, auquel il assura la souveraine sacrificature, et lui ordonna de tirer vengeance des enfants d''Israël.'),
('1m',7,10,'crampon1923','S''étant mis en route, ils vinrent avec une grande armée dans le pays de Juda, et ils envoyèrent des messagers porter à Judas et à ses frères des paroles de paix, pour les tromper.'),
('1m',7,11,'crampon1923','Mais ceux-ci, voyant qu''ils étaient venus avec une grande armée, n''écoutèrent pas leur discours.'),
('1m',7,12,'crampon1923','Cependant une troupe de scribes se rendit auprès d''Alcime et de Bacchidès pour chercher le droit;'),
('1m',7,13,'crampon1923','et ceux qui tenaient le premier rang parmi les enfants d''Israël, les Assidéens, leur demandèrent la paix;'),
('1m',7,14,'crampon1923','car ils disaient: " Un prêtre de la race d''Aaron est venu avec l''armée; il ne saurait nous maltraiter. "'),
('1m',7,15,'crampon1923','Il leur fit entendre des paroles de paix et leur fit ce serment: " Nous ne voulons vous faire aucun mal, ni à vous, ni à vos amis. "'),
('1m',7,16,'crampon1923','Ils le crurent; mais lui fit saisir soixante d''entre eux et les fit massacrer le même jour, selon la parole de l''Ecriture:'),
('1m',7,17,'crampon1923','" Ils ont dispersé la chair et répandu le sang de tes saints autour de Jérusalem, et il n''y a personne pour les ensevelir. "'),
('1m',7,18,'crampon1923','Alors la crainte et la terreur s''emparèrent de tout le peuple: " Il n''y a plus, disait-on, ni vérité ni justice parmi eux, car ils ont violé leur engagement et le serment qu''ils avaient fait. "'),
('1m',7,19,'crampon1923','Bacchidès partit de Jérusalem et alla camper à Bézeth; là il envoya saisir un grand nombre de ceux qui avaient déserté son parti, avec quelques-uns du peuple, et les ayant tués, il jeta leurs cadavres dans la grande citerne.'),
('1m',7,20,'crampon1923','Après avoir confié le pays à Alcime, en lui laissant des troupes pour le défendre, Bacchidès s''en retourna auprès du roi.'),
('1m',7,21,'crampon1923','Alcime s''efforça de se mettre en possession du pontificat.'),
('1m',7,22,'crampon1923','Tous ceux qui troublaient leur peuple s''assemblèrent autour de lui, se rendirent maîtres du pays de Juda et causèrent une grande affliction en Israël.'),
('1m',7,23,'crampon1923','Voyant tous les maux que faisaient aux enfants d''Israël Alcime et ses partisans, plus funestes que les Gentils eux-mêmes,'),
('1m',7,24,'crampon1923','Judas parcourut en tout sens le territoire de la Judée, châtiant les apostats et les empêchant de se répandre dans les campagnes.'),
('1m',7,25,'crampon1923','Lorsque Alcime vit que Judas et ses compagnons étaient devenus puissants, reconnaissant qu''il ne pouvait tenir contre eux, il retourna auprès du roi et les accusa des plus grands méfaits.'),
('1m',7,26,'crampon1923','Le roi envoya Nicanor, un de ses plus illustres généraux, rempli de haine et d''animosité contre Israël, avec ordre d''exterminer le peuple.'),
('1m',7,27,'crampon1923','Arrivé à Jérusalem avec une forte armée, Nicanor fit adresser à Judas et à ses frères des paroles de paix, pour les tromper:'),
('1m',7,28,'crampon1923','" Qu''il n''y ait pas, disait-il, de guerre entre vous et moi; je veux aller avec un petit nombre d''hommes voir vos visages en amitié. "'),
('1m',7,29,'crampon1923','Il vint donc vers Judas, et ils se saluèrent mutuellement avec des démonstrations amicales; mais les ennemis étaient prêts à se saisir de Judas.'),
('1m',7,30,'crampon1923','Informé que Nicanor était venu le trouver dans un but perfide, Judas effrayé se retira et refusa de le voir davantage.'),
('1m',7,31,'crampon1923','Nicanor reconnut alors que son projet était découvert, et il en vint immédiatement aux armes contre Judas près de Capharsalama.'),
('1m',7,32,'crampon1923','Environ cinq mille hommes de l''armée de Nicanor furent tués; le reste s''enfuit dans la ville de David.'),
('1m',7,33,'crampon1923','Après ces événements, Nicanor étant monté au mont Sion, quelques-uns des prêtres sortirent du lieu saint, accompagnés de plusieurs anciens du peuple, pour le saluer amicalement et lui montrer les holocaustes qui étaient offerts pour le roi.'),
('1m',7,34,'crampon1923','Mais lui, les raillant et les traitant avec mépris, les souilla et prononça des paroles insolentes;'),
('1m',7,35,'crampon1923','et il fit ce serment avec colère: " Si Judas et son armée ne sont pas livrés sur le champ entre mes mains, dès que je serai revenu en paix, je brûlerai cet édifice. " Et il sortit tout en colère.'),
('1m',7,36,'crampon1923','Alors les prêtres rentrèrent et, se tenant devant l''autel et le sanctuaire, ils dirent en pleurant:'),
('1m',7,37,'crampon1923','" C''est vous, Seigneur, qui avez choisi cette maison pour y mettre votre nom, afin qu''elle fût pour votre peuple une maison de prière et de supplication.'),
('1m',7,38,'crampon1923','Tirez vengeance de cet homme et de son armée, et qu''ils tombent par l''épée! Souvenez-vous de leurs blasphèmes, et ne permettez pas qu''ils demeurent! "'),
('1m',7,39,'crampon1923','Nicanor, quittant Jérusalem, alla camper près de Béthoron, et un corps de Syriens vint au-devant de lui.'),
('1m',7,40,'crampon1923','Judas, de son côté, campa près d''Adasa avec trois mille hommes, et il pria en disant:'),
('1m',7,41,'crampon1923','" Ceux qui avaient été envoyés par le roi des Assyriens vous ayant blasphémé, Seigneur, votre ange vint et leur tua cent quatre vingt-cinq mille hommes.'),
('1m',7,42,'crampon1923','Exterminez de même en ce jour cette armée en notre présence, afin que tous les autres reconnaissent qu''il a tenu un langage impie sur votre sanctuaire, et jugez-le selon sa méchanceté. "')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('1m',7,43,'crampon1923','Les armées en vinrent aux mains le treizième jour du mois d''Adar, et les troupes de Nicanor furent taillées en pièces; lui-même tomba le premier dans le combat.'),
('1m',7,44,'crampon1923','Les troupes, voyant que Nicanor était tombé, jetèrent leurs armes et prirent la fuite.'),
('1m',7,45,'crampon1923','Les Juifs les poursuivirent une journée de chemin, depuis Adasa jusqu''aux environs de Gazara, sonnant derrière eux les trompettes en fanfare.'),
('1m',7,46,'crampon1923','De tous les villages de Judée aux alentours sortirent des gens qui enveloppèrent les Syriens: ceux-ci alors se retournaient les uns sur les autres, et tous tombèrent par l''épée, sans qu''aucun d''eux échappât, pas même un seul.'),
('1m',7,47,'crampon1923','Ils prirent les dépouilles des vaincus, ainsi que leur butin; et ayant coupé la tête de Nicanor et sa main droite, qu''il avait insolemment étendue, ils les apportèrent et les suspendirent en vue de Jérusalem.'),
('1m',7,48,'crampon1923','Le peuple fut rempli de joie, et ils célébrèrent ce jour comme un jour de grande allégresse.'),
('1m',7,49,'crampon1923','On décida que ce jour serait célébré chaque année, le treize du mois d''Adar.'),
('1m',7,50,'crampon1923','Et le pays de Juda fut tranquille pendant un peu de temps.'),
('1m',8,1,'crampon1923','Or, Judas entendit parler des Romains: ils sont, lui dit-on, puissants dans les combats; ils montrent de la bienveillance à tous ceux qui s''attachent à leur cause et font amitié avec quiconque vient à eux, et ils sont puissants dans les combats.'),
('1m',8,2,'crampon1923','On lui raconta leurs guerres et les exploits accomplis par eux chez les Galates, qu''ils avaient soumis et rendus tributaires;'),
('1m',8,3,'crampon1923','tout ce qu''ils avaient fait dans le pays d''Espagne, pour s''emparer des mines d''or et d''argent qui s''y trouvent, et comment ils avaient soumis tout ce pays par leur prudence et leur patience:'),
('1m',8,4,'crampon1923','ce pays était très éloigné d''eux. Il en avait été de même des rois qui étaient venus les attaquer des extrémités de la terre; ils les avaient battus et frappés d''une grande plaie, et les autres leur paient un tribut annuel.'),
('1m',8,5,'crampon1923','Ils avaient vaincu à la guerre Philippe et Persée, roi des Céthéens, et ceux qui avaient pris les armes contre eux, et ils les avaient soumis.'),
('1m',8,6,'crampon1923','Antiochus le Grand, roi de l''Asie, qui s''était avancé contre eux pour les combattre avec cent vingt éléphants, de la cavalerie, des chariots et une très puissante armée, avait été aussi battu par eux;'),
('1m',8,7,'crampon1923','ils l''avaient pris vivant et lui avaient imposé l''engagement de leur payer, lui et ses successeurs, un tribut considérable, de livrer des otages et de céder une partie de son royaume,'),
('1m',8,8,'crampon1923','savoir le pays de l''Inde, la Médie et la Lydie, et des portions de ses plus belles provinces, et, après les avoir reçues de lui, ils les avaient cédées au roi Eumène.'),
('1m',8,9,'crampon1923','Ceux de la Grèce ayant formé le dessein d''aller les détruire, les Romains l''avaient appris'),
('1m',8,10,'crampon1923','et avaient envoyé contre eux un seul général; ils leur avaient fait la guerre, en avaient tué un grand nombre, emmené en captivité leurs femmes et leurs enfants, pillé leurs biens, soumis leur pays, détruit leurs forteresses et réduit les habitants en servitude jusqu''à ce jour.'),
('1m',8,11,'crampon1923','Tous les autres royaumes et les îles qui leur avaient résisté, ils les avaient détruits et assujettis.'),
('1m',8,12,'crampon1923','Mais à leurs amis et à ceux qui mettent en eux leur confiance, ils gardent amitié; ils se sont rendus maîtres des royaumes voisins et éloignés, et tous ceux qui entendent leur nom les redoutent.'),
('1m',8,13,'crampon1923','Tous ceux à qui ils veulent prêter secours et conférer la royauté règnent, et ils ôtent le pouvoir à qui il leur plaît; c''est une nation très puissante.'),
('1m',8,14,'crampon1923','Malgré tout cela nul d''entre eux ne ceint le diadème, nul ne se vêtit de pourpre pour se grandir ainsi.'),
('1m',8,15,'crampon1923','Ils se sont formé un sénat, où délibèrent chaque jour trois cent vingt membres s''occupant constamment des intérêts du peuple, pour le rendre prospère.'),
('1m',8,16,'crampon1923','Ils confient chaque année le pouvoir à un seul homme pour commander dans tout leur pays; tous obéissent à ce seul homme, et il n''y a parmi eux ni envie, ni jalousie.'),
('1m',8,17,'crampon1923','Judas choisit Eupolème, fils de Jean, fils d''Accos, et Jason, fils d''Eléazar, et il les envoya à Rome pour faire avec eux amitié et alliance,'),
('1m',8,18,'crampon1923','et pour qu''ils les délivrassent du joug, car ils voyaient que le royaume des Grecs réduisait Israël en servitude.'),
('1m',8,19,'crampon1923','Ils se rendirent donc à Rome, et le voyage fut très long; et, étant entrés dans le sénat, il prirent la parole en ces termes:'),
('1m',8,20,'crampon1923','" Judas Machabée, ses frères et le peuple juif nous ont envoyés vers vous pour conclure avec vous un traité d''alliance et de paix, et pour que nous soyons inscrits au nombre de vos alliés et de vos amis. "'),
('1m',8,21,'crampon1923','Cette requête fut accueillie favorablement;'),
('1m',8,22,'crampon1923','et voici la copie du traité que les Romains gravèrent sur des tables d''airain, et envoyèrent à Jérusalem, pour y demeurer comme un monument de paix et d''alliance:'),
('1m',8,23,'crampon1923','" Prospérité aux Romains et à la nation juive sur mer et sur terre, à jamais! Loin d''eux l''épée et l''ennemi!'),
('1m',8,24,'crampon1923','S''il survient une guerre aux Romains d''abord, ou à l''un de leurs alliés dans toute l''étendue de leur empire,'),
('1m',8,25,'crampon1923','la nation juive leur prêtera secours, selon que les circonstances le permettront, de tout cœur;'),
('1m',8,26,'crampon1923','ils ne donneront aux combattants et ne fourniront ni blé, ni armes, ni argent, ni vaisseaux. Telle est la volonté des Romains; et les Juifs observeront leurs engagements sans rien recevoir.'),
('1m',8,27,'crampon1923','De même, s''il survient une guerre à la nation juive d''abord, les Romains combattront avec eux de toute leur âme, selon que les circonstances le leur permettront,'),
('1m',8,28,'crampon1923','sans qu''il soit fourni aux troupes auxiliaires ni blé, ni armes, ni argent, ni vaisseaux. Telle est la volonté de Rome; et ils observeront leurs engagements sans tromperie.'),
('1m',8,29,'crampon1923','Telles sont les clauses du traité des Romains avec le peuple juif.'),
('1m',8,30,'crampon1923','Que si, dans la suite, les uns et les autres veulent y ajouter ou en retrancher, ils le feront à leur gré, et ce qui aura été ajouté ou retranché sera obligatoire. "'),
('1m',8,31,'crampon1923','" Au sujet des maux que le roi Démétrius leur a faits, nous lui avons écrit en ces termes: " Pourquoi fais-tu peser le joug sur les Juifs, qui sont nos amis et nos alliés?'),
('1m',8,32,'crampon1923','Si donc ils t''accusent encore auprès de nous, nous soutiendrons leurs droits, et nous te combattrons sur mer et sur terre. "'),
('1m',9,1,'crampon1923','Ayant appris que Nicanor et son armée étaient tombés dans le combat, Démétrius envoya encore une fois Bacchidès et Alcime en Judée, avec l''aile droite de son armée.'),
('1m',9,2,'crampon1923','Ils prirent la route qui mène à Galgala, et dressèrent leur camp à Masaloth, qui est dans le territoire d''Arbèles; ils s''emparèrent de cette ville et tuèrent un grand nombre d''habitants.'),
('1m',9,3,'crampon1923','Le premier mois de l''an cent cinquante-deux, ils rangèrent leurs troupes devant Jérusalem.'),
('1m',9,4,'crampon1923','Puis ils levèrent le camp et allèrent à Bérée avec vingt mille hommes et deux mille cavaliers.'),
('1m',9,5,'crampon1923','Judas avait établi son camp à Eléasa, ayant avec lui trois mille guerriers d''élite.'),
('1m',9,6,'crampon1923','A la vue du grand nombre d''ennemis, ils furent remplis de frayeur, et beaucoup s''enfuirent secrètement du camp; il n''en resta que huit cents.'),
('1m',9,7,'crampon1923','Judas vit que son armée s''était dérobée, et que cependant la bataille était imminente; alors son cœur fut brisé, parce que le temps lui manquait pour rassembler les siens, et il se sentit défaillir.'),
('1m',9,8,'crampon1923','Cependant il dit à ceux qui lui restaient: " Allons, marchons contre nos adversaires, si toutefois nous pouvons lutter contre eux! "'),
('1m',9,9,'crampon1923','Mais eux l''en détournaient en disant: " Nous ne le pouvons pas; sauvons maintenant notre vie et retournons auprès de nos frères, ensuite nous reviendrons combattre nos ennemis; mais nous sommes trop peu. "'),
('1m',9,10,'crampon1923','Judas leur dit: " Loin de moi d''agir ainsi, de prendre la fuite devant eux! Si notre heure est venue, mourons bravement pour nos frères et ne laissons pas une tache à notre gloire! "'),
('1m',9,11,'crampon1923','L''armée syrienne sortit du camp, s''avançant à leur rencontre; les cavaliers étaient partagés en deux corps, les frondeurs et les archers marchaient en tête, les plus vaillants au premier rang.'),
('1m',9,12,'crampon1923','Bacchidès était à l''aide droite, et la phalange s''avançait des deux côtés, au son de la trompette.'),
('1m',9,13,'crampon1923','Ceux du côté de Judas sonnèrent aussi de la trompette et la terre était ébranlée du bruit des deux armées. Le combat s''engagea et dura du matin jusqu''au soir.'),
('1m',9,14,'crampon1923','Judas, voyant que Bacchidès et ses meilleures troupes étaient à l''aile droite, rassembla autour de lui tous les hommes de cœur,'),
('1m',9,15,'crampon1923','battit l''aile droite des Syriens et la poursuivit jusqu''à la montagne d''Azot.'),
('1m',9,16,'crampon1923','Mais ceux qui étaient à l''aile gauche, s''apercevant que l''aile droite était battue, firent volte-face et suivirent par derrière Judas et les siens;'),
('1m',9,17,'crampon1923','la lutte devint acharnée, et il y eut de part et d''autre un grand nombre de morts.'),
('1m',9,18,'crampon1923','Judas tomba aussi, et ses compagnons prirent la fuite.'),
('1m',9,19,'crampon1923','Jonathas et Simon emportèrent Judas, leur frère, et ils l''ensevelirent dans le sépulcre de leurs pères, à Modin.'),
('1m',9,20,'crampon1923','Là tout Israël le pleura et fit entendre sur lui de grandes lamentations; on mena le deuil pendant plusieurs jours,'),
('1m',9,21,'crampon1923','et l''on disait: " Comment est-il tombé le héros, celui qui sauvait Israël! "'),
('1m',9,22,'crampon1923','Le reste de l''histoire de Judas, ses autres guerres, les autres exploits qu''il accomplit, et ses titres de gloire n''ont pas été écrits; car ils sont très nombreux.'),
('1m',9,23,'crampon1923','Après la mort de Judas, les impies se montrèrent dans tout le territoire d''Israël, et tous ceux qui commettent l''iniquité levèrent la tête.'),
('1m',9,24,'crampon1923','En ces jours-là, survint une très grande famine, et le sol lui-même fut infidèle avec eux.'),
('1m',9,25,'crampon1923','Bacchidès choisit les hommes impies et les établit pour administrer le pays.'),
('1m',9,26,'crampon1923','Ils recherchaient les amis de Judas et, quand ils en avaient trouvé, ils les amenaient à Bacchidès, qui les punissait et les tournait en dérision.'),
('1m',9,27,'crampon1923','Et Israël fut affligé d''une grande tribulation, telle qu''il n''y en avait pas eu de pareille depuis le jour où il ne parut plus de prophète en Israël.'),
('1m',9,28,'crampon1923','Alors tous les amis de Judas s''assemblèrent et dirent à Jonathas:'),
('1m',9,29,'crampon1923','" Depuis que ton frère Judas est mort, il ne se trouve plus d''homme semblable à lui pour marcher contre nos ennemis, Bacchidés et tous ceux qui haïssent notre nation.'),
('1m',9,30,'crampon1923','Nous te choisissons donc aujourd''hui pour être notre chef à sa place, et pour nous commander dans nos combats. "'),
('1m',9,31,'crampon1923','Jonathas reçut donc en ce temps-là le commandement, et il se leva à la place de Judas, son frère.'),
('1m',9,32,'crampon1923','Dès que Bacchidés eut appris l''élection de Jonathas, il chercha à le faire périr.'),
('1m',9,33,'crampon1923','Informés de ce dessein, Jonathas, son frère Simon et tous ceux qui étaient avec lui s''enfuirent au désert de Thécué, et ils s''établirent près des eaux de la citerne Asphar.'),
('1m',9,34,'crampon1923','— Bacchidés en eut connaissance le jour du sabbat, et il se rendit lui-même avec toute son armée au-delà du Jourdain. —'),
('1m',9,35,'crampon1923','Jonathas envoya son frère Jean, comme chef du peuple, chez les Nabatéens, ses amis, les priant de leur permettre de déposer chez eux ses bagages, qui étaient considérables.'),
('1m',9,36,'crampon1923','Mais les fils de Jambri, étant sortis de Madaba, se saisirent de Jean et de tous ses bagages, et s''en allèrent avec tout ce butin.'),
('1m',9,37,'crampon1923','Quelque temps après, on vint annoncer à Jonathas et à son frère Simon que les fils de Jambri célébraient une noce solennelle et qu''ils amenaient de Nadabat en grande pompe la fiancée, fille d''un des puissants princes de Chanaan.'),
('1m',9,38,'crampon1923','Alors, se souvenant de leur frère jean, ils montèrent et se cachèrent à l''abri de la montagne.'),
('1m',9,39,'crampon1923','Levant les yeux, ils observaient, et voici qu''un grand bruit se fit entendre et que parut un nombreux convoi; l''époux, accompagné de ses frères et de ses amis, s''avançait à leur rencontre, avec des tambourins, des instruments de musique et un attirail considérable.'),
('1m',9,40,'crampon1923','A cette vue, les compagnons de Jonathas se levèrent de leur embuscade et se précipitèrent sur eux pour les massacrer; un grand nombre tombèrent sous leurs coups, le reste s''enfuit dans les montagnes, et les Juifs s''emparèrent de leurs dépouilles.'),
('1m',9,41,'crampon1923','Ainsi les noces se changèrent en deuil, et les sons joyeux de leur musique en lamentation.'),
('1m',9,42,'crampon1923','Après avoir ainsi vengé le meurtre de leur frère, Jonathas et Simon se retirèrent vers les marais du Jourdain.'),
('1m',9,43,'crampon1923','Bacchidès en fut instruit, et il vint le jour du sabbat jusqu''aux berges du Jourdain, avec une puissante armée.'),
('1m',9,44,'crampon1923','Alors Jonathas dit à ses compagnons: " Levons-nous maintenant, et combattons pour notre vie! Car il n''en est pas aujourd''hui comme hier et avant-hier.'),
('1m',9,45,'crampon1923','Voici l''ennemi en armes devant nous et derrière nous, et de tous côtés l''eau du Jourdain, un marais et un bois; nul moyen d''échapper.'),
('1m',9,46,'crampon1923','Maintenant donc criez vers le ciel, afin que vous soyez sauvés de la main de vos ennemis. " Le combat s''engagea.'),
('1m',9,47,'crampon1923','Jonathas étendit la main pour frapper Bacchidés, mais celui-ci, pour l''éviter, se rejeta en arrière.'),
('1m',9,48,'crampon1923','Alors Jonathas sauta dans le Jourdain, avec ses compagnons; ils le passèrent à la nage, et les Syriens ne le passèrent point pour les poursuivre.'),
('1m',9,49,'crampon1923','Il périt ce jour-là mille hommes du côté de Bacchidés. Celui-ci retourna à Jérusalem,'),
('1m',9,50,'crampon1923','et bâtit des villes fortes dans la Judée, la forteresse près de Jéricho, Emmaüs, Béthoron, Béthel, Thamnatha, Phara et Téphon, avec de hautes murailles, des portes et des verrous,'),
('1m',9,51,'crampon1923','et il y mit des garnisons pour exercer les hostilités contre Israël.'),
('1m',9,52,'crampon1923','Il fortifia la ville de Bethsur, Gazara et la citadelle, et il y mit des troupes et des dépôts de vivres.'),
('1m',9,53,'crampon1923','Il prit pour otages les fils des principaux du pays, et les retint prisonniers dans la citadelle de Jérusalem.'),
('1m',9,54,'crampon1923','L''an cent cinquante-trois, au deuxième mois, Alcime commanda d''abattre les murs du parvis intérieur du sanctuaire, détruisant ainsi l''œuvre des prophètes, et il commença à les démolir.'),
('1m',9,55,'crampon1923','En ce temps-là, Alcime fut frappé de Dieu, et ses entreprises furent arrêtées; sa bouche se ferma; atteint de paralysie, il ne put plus prononcer une seule parole, ni donner aucun ordre au sujet des affaires de sa maison.'),
('1m',9,56,'crampon1923','Et Alcime mourut en ce temps-là dans de grandes tortures.'),
('1m',9,57,'crampon1923','Voyant qu''Alcime était mort, Bacchidès s''en retourna auprès du roi, et le pays de Juda fut en paix pendant deux ans.'),
('1m',9,58,'crampon1923','Alors tous les Juifs infidèles tinrent conseil, en disant: " Voici que Jonathas et ses compagnons vivent en paix et sécurité; faisons donc venir Bacchidès, et il les prendra tous en une nuit. "'),
('1m',9,59,'crampon1923','Et ils allèrent s''entendre avec lui.'),
('1m',9,60,'crampon1923','Bacchidès se mit en marche à la tête d''une grande armée, et il envoya secrètement des lettres à tous ses partisans qui étaient en Judée, pour qu''ils se saisissent de Jonathas et de ses compagnons; mais il n''y réussirent pas, parce que ces derniers eurent connaissance de leur dessein.'),
('1m',9,61,'crampon1923','Et parmi les hommes du pays, chefs du complot, ils en prirent cinquante et les firent périr.'),
('1m',9,62,'crampon1923','Puis Jonathas, avec Simon et ceux qui étaient avec eux, se rendit à Bethbasi dans le désert, et il en répara les ruines et la fortifia.'),
('1m',9,63,'crampon1923','Bacchidès l''apprit, rassembla toutes ses troupes et fit appel à ses partisans de Judée.'),
('1m',9,64,'crampon1923','Il vint et établit son camp près de Bethbasi; il assiégea cette ville pendant beaucoup de jours et construisit des machines.'),
('1m',9,65,'crampon1923','Mais Jonathas, laissant dans la ville son frère Simon, sortit dans la campagne et revint avec une petite troupe.'),
('1m',9,66,'crampon1923','Il battit Odoarrès, ainsi que ses frères et les fils de Phaséron dans leurs tentes, et il commença à attaquer les assiégeants et à marcher contre eux avec des forces.'),
('1m',9,67,'crampon1923','Simon, de son côté, fit une sortie avec ses compagnons et brûla les machines de guerre.'),
('1m',9,68,'crampon1923','Tous deux combattirent contre Bacchidès, le mirent en déroute, et le jetèrent dans une profonde affliction de ce que son dessein et son expédition étaient complètement manqués.'),
('1m',9,69,'crampon1923','Outré de colère contre les hommes impies qui lui avaient conseillé de venir dans le pays, il en fit périr un grand nombre et prit la résolution de retourner dans son pays.'),
('1m',9,70,'crampon1923','Jonathas le sut, et il lui envoya des messagers pour traiter avec lui de la paix et obtenir qu''on leur rendit les prisonniers.'),
('1m',9,71,'crampon1923','Bacchidès les accueillit et accepta leurs propositions; il s''engagea par serment envers Jonathas à ne lui faire aucun mal, tant qu''il vivrait.'),
('1m',9,72,'crampon1923','Il lui rendit les prisonniers qu''il avait faits auparavant dans le pays de Juda, et, s''en étant allé dans son pays, il ne revint plus sur le territoire des Juifs.'),
('1m',9,73,'crampon1923','L''épée se reposa dans Israël, et Jonathas fixa sa demeure à Machmas; et il commença à juger le peuple, et il fit disparaître les impies du milieu d''Israël.'),
('1m',10,1,'crampon1923','L''an cent soixante, Alexandre, fils d''Antiochus et surnommé Epiphane, se mit en marche, et s''empara de Ptolémaïs; les habitants le reçurent, et il fut roi.'),
('1m',10,2,'crampon1923','Le roi Démétrius, l''ayant appris, rassembla une très forte armée et s''avança contre lui pour le combattre.'),
('1m',10,3,'crampon1923','En même temps Démétrius envoyait à Jonathas une lettre avec des paroles de paix, lui promettant de l''élever en dignité.'),
('1m',10,4,'crampon1923','" Hâtons-nous, disait-il, de faire la paix avec lui, avant qu''il la fasse avec Alexandre contre nous.'),
('1m',10,5,'crampon1923','Car il se souviendra de tout le mal que nous lui avons fait, à lui, à son frère et à tout son peuple. "'),
('1m',10,6,'crampon1923','Il l''autorisait à lever des troupes, à fabriquer des armes et à se dire son allié, et il ordonnait qu''on lui remit les otages détenus dans la citadelle.'),
('1m',10,7,'crampon1923','Aussitôt Jonathas se rendit à Jérusalem et lut la lettre devant tout le peuple et devant ceux qui étaient dans la citadelle.'),
('1m',10,8,'crampon1923','Ils furent saisis d''une grande crainte, en apprenant que le roi donnait à Jonathas le pouvoir de former une armée.'),
('1m',10,9,'crampon1923','Ceux de la citadelle livrèrent les otages à Jonathas, qui les rendit à leurs parents.'),
('1m',10,10,'crampon1923','Jonathas s''établit à Jérusalem, et commença à rebâtir et à renouveler la ville.'),
('1m',10,11,'crampon1923','Il commanda aux ouvriers de reconstruire les murailles et d''entourer le mont Sion de pierres carrées pour le fortifier. Ces ordres furent exécutés.'),
('1m',10,12,'crampon1923','Alors les étrangers qui étaient dans les forteresses que Bacchidès avait bâties s''enfuirent,'),
('1m',10,13,'crampon1923','et chacun d''eux, quittant sa demeure, s''en retourna dans son pays.'),
('1m',10,14,'crampon1923','Quelques-uns seulement de ceux qui avaient abandonné la loi et les commandements restèrent dans Bethsur, qui devint leur refuge.'),
('1m',10,15,'crampon1923','Cependant le roi Alexandre apprit les offres que Démétrius avait faites à Jonathas; on lui raconta aussi les combats que celui-ci avait livrés, les exploits qu''il avait accomplis, lui et ses frères, ainsi que les maux qu''ils avaient endurés.'),
('1m',10,16,'crampon1923','Et il dit: " Trouverions-nous jamais un homme pareil? Faisons-nous en donc un ami et un allié. "'),
('1m',10,17,'crampon1923','Il écrivit une lettre et la lui envoya, ainsi conçue:'),
('1m',10,18,'crampon1923','" Le roi Alexandre à son frère Jonathas, salut.'),
('1m',10,19,'crampon1923','Nous avons appris sur toi que tu es un homme puissant et que tu es disposé à être notre ami.'),
('1m',10,20,'crampon1923','C''est pourquoi nous te constituons aujourd''hui grand prêtre de la nation et te donnons le titre d''ami du roi; — il lui envoyait en même temps une robe de pourpre et une couronne d''or — prends intérêt à nos affaires et garde-nous ton amitié. "'),
('1m',10,21,'crampon1923','Jonathas revêtit les ornements sacrés le septième mois de l''an cent soixante, en la fête des Tabernacles, et il leva une armée et fabriqua beaucoup d''armes.'),
('1m',10,22,'crampon1923','En apprenant ces choses, Démétrius ressentit une grande affliction:'),
('1m',10,23,'crampon1923','" Qu''avons-nous fait, dit-il, qu''Alexandre nous ait prévenus en obtenant l''amitié des Juifs pour affermir sa puissance?'),
('1m',10,24,'crampon1923','Moi aussi je veux leur adresser des paroles persuasives, leur offrir une haute situation et des présents, afin qu''ils soient mes auxiliaires. "'),
('1m',10,25,'crampon1923','Il leur envoya donc une lettre ainsi conçue: " Le roi Démétrius à la nation juive, salut.'),
('1m',10,26,'crampon1923','Vous avez gardé fidèlement l''alliance faite avec nous, persévérant dans notre amitié et ne vous unissant pas à nos ennemis; nous l''avons appris et nous nous en sommes réjouis.'),
('1m',10,27,'crampon1923','Et maintenant, continuez de nous garder fidélité, et nous récompenserons par des bienfaits ce que vous faites pour nous.'),
('1m',10,28,'crampon1923','Nous vous accorderons beaucoup d''exemptions et de faveurs.'),
('1m',10,29,'crampon1923','Dès à présent je vous décharge et je fais remise à tous les Juifs des tributs, des droits sur le sel et des couronnes. Ce qui me revient pour le tiers du produit du sol'),
('1m',10,30,'crampon1923','et pour la moitié du produit des arbres fruitiers, je vous en fais aujourd''hui la remise; et je n''exigerai plus rien désormais, et en aucun temps, du pays de Juda, ni des trois cantons qui lui sont réunis de la Samarie et de la Galilée.'),
('1m',10,31,'crampon1923','Je veux que Jérusalem soit une ville sainte et exempte, ainsi que son territoire, ses dîmes et ses tributs.'),
('1m',10,32,'crampon1923','Je renonce aussi à mon autorité sur la citadelle qui est à Jérusalem, et je la donne au grand prêtre afin qu''il y établisse, pour la garder, les hommes qu''il aura choisis.'),
('1m',10,33,'crampon1923','Tous les Juifs qui ont été emmenés captifs du pays de Judas dans toute l''étendue de mon royaume, je les renvoie libres sans rançon; je veux que tous leur fassent aussi remise des tributs, même pour leurs animaux.'),
('1m',10,34,'crampon1923','Que toutes les solennités, les sabbats, les néoménies, les jours fixés et les trois jours qui précédent ou qui suivent une fête solennelle, soient tous des jours d''immunité et de franchise pour tous les Juifs qui habitent dans mon royaume.'),
('1m',10,35,'crampon1923','En ces jours-là, nul n''aura le droit de poursuivre l''un d''entre eux, ou de lui intenter une action pour quelque affaire que ce soit.'),
('1m',10,36,'crampon1923','On enrôlera dans l''armée du roi jusqu''à trente mille juifs et on leur donnera la même solde qui est allouée à toutes les troupes du roi. Un certain nombre d''entre eux seront placés dans les grandes forteresses du roi,'),
('1m',10,37,'crampon1923','et plusieurs seront admis aux emplois de confiance du royaume; de plus, ces troupes auront à leur tête des chefs pris dans leurs rangs, et elles vivront selon leurs lois, comme le roi l''a ordonné pour le pays de Juda.'),
('1m',10,38,'crampon1923','Les trois cantons de la Samarie annexés à la Judée lui seront incorporés et comptés comme ne faisant qu''un avec elle, de telle sorte qu''ils n''obéissent à nulle autre autorité que celle du grand prêtre.'),
('1m',10,39,'crampon1923','Je donne Ptolémaïs et son territoire au sanctuaire de Jérusalem, pour les dépenses nécessaires au culte.'),
('1m',10,40,'crampon1923','Et moi je donne chaque année quinze mille sicles d''argent, qui seront pris sur le fisc royal dans les localités convenables.'),
('1m',10,41,'crampon1923','Et tout le surplus, que les employés du fisc n''auront pas payé comme dans les années antérieures, ils le solderont à l''avenir pour le service du temple.'),
('1m',10,42,'crampon1923','En outre, des cinq mille sicles d''argent que les officiers soustrayaient chaque année aux besoins du sanctuaire, en les prélevant sur ses revenus, il sera fait remise, parce qu''ils appartiennent aux prêtres qui font le service.'),
('1m',10,43,'crampon1923','Quiconque sera réfugié dans le sanctuaire de Jérusalem et dans toute son enceinte, étant redevable des impôts royaux ou de toute autre dette, sera libre, avec tous les biens qu''il possède dans mon royaume.'),
('1m',10,44,'crampon1923','Les dépenses pour la construction et la restauration du sanctuaire seront aussi prélevées sur les revenus du roi.'),
('1m',10,45,'crampon1923','En outre, pour reconstruire les murailles de Jérusalem et pour en fortifier l''enceinte, les dépenses seront encore prélevées sur les revenus du roi; et il en sera de même pour relever les murailles des villes de la Judée. "'),
('1m',10,46,'crampon1923','Lorsque Jonathas et le peuple entendirent ces paroles, ils n''y crurent pas et refusèrent de les accepter, parce qu''ils se souvenaient des grands maux que Démétrius avait faits à Israël et des calamités qu''il leur avait causées.'),
('1m',10,47,'crampon1923','Ils se décidèrent donc en faveur d''Alexandre, dont les propositions pacifiques obtinrent la préférence à leurs yeux, et ils furent constamment ses alliés.'),
('1m',10,48,'crampon1923','Le roi Alexandre rassembla une grande armée et s''avança contre Démétrius.'),
('1m',10,49,'crampon1923','Les deux rois ayant engagé la bataille, l''armée de Démétrius prit la fuite et Alexandre la poursuivit; il l''emporta sur eux'),
('1m',10,50,'crampon1923','et combattit très vaillamment jusqu''au coucher du soleil, et Démétrius fut tué ce jour-là.'),
('1m',10,51,'crampon1923','Alexandre envoya à Ptolémée, roi d''Egypte, des ambassadeurs chargés de lui dire:'),
('1m',10,52,'crampon1923','" Je suis rentré dans mon royaume et je suis assis sur le trône de mes pères; j''ai reconquis le gouvernement par ma victoire sur Démétrius, et j''ai pris possession de notre pays.'),
('1m',10,53,'crampon1923','Je lui ai livré bataille et il a été défait par moi, lui et son armée, et je suis monté sur le siège de sa royauté.'),
('1m',10,54,'crampon1923','Maintenant, faisons amitié ensemble; donne-moi ta fille en mariage, je serai ton gendre, et je te donnerai, ainsi qu''à elle, des présents dignes de toi. "'),
('1m',10,55,'crampon1923','Le roi Ptolémée répondit en ces termes: " Heureux le jour où tu es rentré dans le pays de tes pères, et où tu t''es assis sur le trône de leur royauté!'),
('1m',10,56,'crampon1923','Maintenant, je ferai pour toi ce que tu as écrit; mais viens au-devant de moi à Ptolémaïs, afin que nous nous voyions ensemble, et je te ferai mon gendre, comme tu en as exprimé le désir. "'),
('1m',10,57,'crampon1923','Ptolémée partit d''Egypte, lui et sa fille Cléopâtre, et se rendit à Ptolémaïs, en l''an cent soixante-deux.'),
('1m',10,58,'crampon1923','Le roi Alexandre vint au-devant de lui, et celui-ci lui donna sa fille Cléopâtre, et il célébra les noces à Ptolémaïs avec une grande magnificence, selon la coutume des rois.'),
('1m',10,59,'crampon1923','Le roi Alexandre écrivit aussi à Jonathas, l''invitant à se rencontrer avec lui.'),
('1m',10,60,'crampon1923','Jonathas se rendit en grande pompe à Ptolémaïs, ou il se rencontra avec les deux rois; il leur offrit, ainsi qu''à leurs courtisans, de l''argent, de l''or et beaucoup de présents, et il se concilia leur faveur.'),
('1m',10,61,'crampon1923','Alors s''unirent contre lui des hommes pervers d''Israël, des impies, pour l''accuser; mais le roi ne les écouta pas.'),
('1m',10,62,'crampon1923','Le roi ordonna même qu''on ôtât à Jonathas ses vêtements et qu''on le revêtit de pourpre. Cet ordre ayant été exécuté, le roi le fit asseoir auprès de lui,'),
('1m',10,63,'crampon1923','et il dit aux grands de sa cour: " Sortez avec lui au milieu de la ville, et publiez que personne n''élève de plainte contre lui pour quoi que ce soit, et que nul ne le moleste sous aucun prétexte. "'),
('1m',10,64,'crampon1923','Quand ses accusateurs virent qu''on lui rendait ces honneurs publics et qu''il était revêtu de la pourpre, tous s''enfuirent.'),
('1m',10,65,'crampon1923','Ajoutant encore à ces honneurs, le roi l''inscrivit au nombre de ses premiers amis et le fit général et gouverneur de province.'),
('1m',10,66,'crampon1923','Et Jonathas revint à Jérusalem en paix et joyeux.'),
('1m',10,67,'crampon1923','L''an cent soixante-cinq, Démétrius, fils de Démétrius, vint de Crète dans le pays de ses pères.'),
('1m',10,68,'crampon1923','A cette nouvelle, le roi Alexandre ressentit une grande douleur, et il retourna à Antioche.'),
('1m',10,69,'crampon1923','Démétrius prit pour général Apollonius, gouverneur de la Cœlé-Syrie, et celui-ci rassembla une grande armée et vint camper près de Jamnia. Là, il envoya dire à Jonathas, le grand prêtre:'),
('1m',10,70,'crampon1923','" Toi, tout seul, tu t''élèves contre nous, et moi je suis devenu un objet de dérision et d''opprobre à cause de toi! Comment oses-tu, toi, jouer l''indépendant vis-à-vis de nous, dans tes montagnes?'),
('1m',10,71,'crampon1923','Maintenant donc, si tu as confiance dans tes forces, descends vers nous dans la plaine, et là mesurons-nous ensemble, car j''ai pour moi les puissantes villes de la côte.'),
('1m',10,72,'crampon1923','Informe-toi et apprends qui je suis et quels sont les autres qui me prêtent leur concours. Ils affirment que votre pied ne peut tenir devant nous, puisque deux fois tes pères ont été mis en fuite dans leur pays.'),
('1m',10,73,'crampon1923','Et maintenant, tu ne pourras soutenir le choc de la cavalerie et d''une armée si nombreuse, dans une plaine où il n''y a ni pierre, ni rocher, ni un lieu où l''on puisse se réfugier. "'),
('1m',10,74,'crampon1923','Quand Jonathas eut entendu les paroles d''Apollonius, il ressentit une vive indignation; il fit choix de dix mille hommes et partit de Jérusalem, et son frère Simon vint le rejoindre pour le soutenir.'),
('1m',10,75,'crampon1923','Ils allèrent camper près de Joppé; la ville leur ferma ses portes, car elle était occupée par une garnison d''Apollonius; aussi en commencèrent-ils le siège.'),
('1m',10,76,'crampon1923','Les habitants effrayés ouvrirent les portes, et Jonathas fut maître de Joppé.'),
('1m',10,77,'crampon1923','Dès qu''il en fut informé, Apollonius mit en ordre de bataille trois mille cavaliers et une armée nombreuse,'),
('1m',10,78,'crampon1923','et se dirigea du côté d''Azot, comme pour se retirer; et en même temps il s''avançait vers la plaine, parce qu''il avait un grand nombre de cavaliers en qui il avait confiance. Jonathas le suivit du côté d''Azot, et les deux armées en vinrent aux mains.'),
('1m',10,79,'crampon1923','Apollonius avait laissé derrière lui mille cavaliers dans un poste caché;'),
('1m',10,80,'crampon1923','mais Jonathas eut avis qu''il y avait une embuscade dressée derrière lui. Les cavaliers entourèrent sa troupe et lancèrent des traits contre ses hommes depuis le matin jusqu''au soir.'),
('1m',10,81,'crampon1923','Et ses hommes tinrent bon, ainsi que l''avait recommandé Jonathas, tandis que les chevaux des cavaliers se fatiguèrent.'),
('1m',10,82,'crampon1923','Alors Simon fit avancer sa troupe et attaqua la phalange, car la cavalerie était sans force; les Syriens furent battus par lui et prirent la fuite.'),
('1m',10,83,'crampon1923','La cavalerie se débanda dans la plaine, et les fuyards gagnèrent Azot, où ils entrèrent dans Beth-Dagon, leur temple d''idole, pour y trouver un asile.'),
('1m',10,84,'crampon1923','Jonathas brûla Azot et les villes d''alentour, après les avoir pillées, et il livra au feu le temple de Dagon avec ceux qui s''y étaient réfugiés.'),
('1m',10,85,'crampon1923','Le nombre de ceux qui périrent par l''épée ou qui furent consumés par le feu fut d''environ huit mille.'),
('1m',10,86,'crampon1923','Et, partant de là, Jonathas vint camper près d''Ascalon, dont les habitants vinrent au-devant de lui, lui rendant de grands honneurs.'),
('1m',10,87,'crampon1923','Puis Jonathas retourna à Jérusalem avec ses gens, ayant un riche butin.'),
('1m',10,88,'crampon1923','Lorsque le roi Alexandre apprit ces événements, il accorda de nouveaux honneurs à Jonathas.'),
('1m',10,89,'crampon1923','Il lui envoya une agrafe d''or, comme il est d''usage d''en gratifier les parents des rois, et il lui donna en propriété Accaron et son territoire.'),
('1m',11,1,'crampon1923','Le roi d''Egypte rassembla une armée innombrable comme le sable qui est sur le bord de la mer, et de nombreux vaisseaux, et il cherchait à se rendre maître du royaume d''Alexandre par ruse et à l''annexer à son royaume.'),
('1m',11,2,'crampon1923','Il s''avança donc vers la Syrie avec des paroles de paix; les habitants des villes les ouvraient devant lui et accouraient à sa rencontre; car le roi Alexandre avait ordonné d''aller au-devant de lui, parce qu''il était son beau-père.'),
('1m',11,3,'crampon1923','Mais, dès que Ptolémée était entré dans une ville, il y laissait de ses troupes pour la garder.'),
('1m',11,4,'crampon1923','Lorsqu''il approcha d''Azot, les habitants lui montrèrent le temple de Dagon brûlé, la ville elle-même et ses alentours en ruines, les cadavres épars et les restes de ceux qui avaient été brûlés dans la guerre; car ils en avaient fait des monceaux sur la route.'),
('1m',11,5,'crampon1923','Et ils racontèrent au roi ce qu''avait fait Jonathas, afin de le rendre odieux; mais le roi se tut.'),
('1m',11,6,'crampon1923','Jonathas se rendit auprès du roi à Joppé pour lui rendre hommage; ils se saluèrent mutuellement et passèrent là la nuit.'),
('1m',11,7,'crampon1923','Jonathas accompagna le roi jusqu''au fleuve nommé Eleuthère, puis il retourna à Jérusalem.'),
('1m',11,8,'crampon1923','Le roi Ptolémée se rendit ainsi maître des villes maritimes jusqu''à Séleucie sur la mer, et il méditait de mauvais desseins contre Alexandre.'),
('1m',11,9,'crampon1923','Il envoya des ambassadeurs au roi Démétrius, pour lui dire: " Viens, faisons alliance ensemble, et je te donnerai ma fille qu''Alexandre a épousée, et tu régneras dans le royaume de ton père.'),
('1m',11,10,'crampon1923','Je me repens de lui avoir donné ma fille, car il a cherché à m''assassiner. "'),
('1m',11,11,'crampon1923','Il le rabaissait ainsi parce qu''il avait envie de son royaume.'),
('1m',11,12,'crampon1923','Ayant enlevé sa fille, il la donna à Démétrius; dès lors il rompit avec Alexandre, et leur hostilité devint publique.'),
('1m',11,13,'crampon1923','Ptolémée fit son entrée à Antioche, prit le diadème d''Asie, mettant ainsi sur sa tête deux couronnes, celle d''Egypte et celle d''Asie.'),
('1m',11,14,'crampon1923','En ce temps-là, Alexandre était en Cilicie, parce que les habitants de cette contrée s''étaient révoltés.'),
('1m',11,15,'crampon1923','Dès qu''il apprit la trahison de son beau-père, Alexandre s''avança contre lui pour le combattre; le roi Ptolémée déploya son armée, marcha à sa rencontre avec de grandes forces, et le mit en fuite.'),
('1m',11,16,'crampon1923','Alexandre s''enfuit en Arabie pour y chercher un asile, et le roi Ptolémée triompha.'),
('1m',11,17,'crampon1923','L''Arabe Zabdiel trancha la tête à Alexandre et l''envoya à Ptolémée.'),
('1m',11,18,'crampon1923','Le roi Ptolémée mourut trois jours après, et les Egyptiens qui étaient dans les forteresses furent tués par leurs habitants.'),
('1m',11,19,'crampon1923','Et Démétrius devint roi, l''an cent soixante-sept.'),
('1m',11,20,'crampon1923','En ces jours-là, Jonathas rassembla ceux qui étaient en Judée afin de s''emparer de la citadelle de Jérusalem, et il dressa contre elle beaucoup de machines de guerre.'),
('1m',11,21,'crampon1923','Alors quelques hommes impies, qui haïssaient leur nation, allèrent trouver le roi Démétrius et lui rapportèrent que Jonathas assiégeait la citadelle.'),
('1m',11,22,'crampon1923','A ce récit, Démétrius fut irrité; dès qu''il l''eut entendu, il se hâta d''accourir à Ptolémaïs et il écrivit à Jonathas de cesser le siège de la citadelle et de venir immédiatement le trouver à Ptolémaïs, pour conférer avec lui.'),
('1m',11,23,'crampon1923','Lorsque Jonathas eut reçu cette lettre, il ordonna de continuer le siège et, ayant choisi pour l''accompagner quelques anciens d''Israël et plusieurs prêtres, il s''exposa au danger.'),
('1m',11,24,'crampon1923','Ayant pris avec lui de l''or, de l''argent, des vêtements et beaucoup d''autres présents, il se rendit auprès du roi à Ptolémaïs, et reçut de lui un accueil favorable.'),
('1m',11,25,'crampon1923','Quelques hommes pervers de la nation portèrent contre lui des plaintes.'),
('1m',11,26,'crampon1923','Mais le roi fit pour lui ce qu''avaient fait ses prédécesseurs: il le combla d''honneurs, en présence de tous ses amis,'),
('1m',11,27,'crampon1923','lui confirma le souverain pontificat et toutes les distinctions qu''il avait précédemment, et le fit inscrire au nombre de ses premiers amis.'),
('1m',11,28,'crampon1923','Jonathas demanda au roi d''affranchir de tout tribut la Judée et les trois toparchies de la Samarie, et il lui promit en retour trois cents talents.'),
('1m',11,29,'crampon1923','Le roi y consentit, et il écrivit sur tout cela à Jonathas une lettre ainsi conçue:'),
('1m',11,30,'crampon1923','" Le roi Démétrius à son frère Jonathas et à la nation des Juifs, salut!'),
('1m',11,31,'crampon1923','Nous vous adressons une copie de la lettre que nous avons écrite à votre sujet à Lasthénès, notre cousin, afin que vous la connaissiez:'),
('1m',11,32,'crampon1923','" Le roi Démétrius à Lasthénès, son père, salut!'),
('1m',11,33,'crampon1923','Nous avons résolu de faire du bien à la nation des Juifs, qui sont nos amis et observent ce qui est juste envers nous, à cause des bons sentiments qu''ils nous ont témoignés.'),
('1m',11,34,'crampon1923','Nous leur confirmons et le territoire de la Judée et les trois cantons détachés de la Samarie pour être réunis à la Judée, savoir Ephraïm, Lydda et Ramathaïm avec toutes leurs dépendances; en faveur de tous ceux qui vont sacrifier à Jérusalem nous faisons cette concession, au lieu des redevances qu''auparavant le roi recevait d''eux chaque année sur les productions du sol et les fruits des arbres.'),
('1m',11,35,'crampon1923','Et tous les autres droits qui nous appartiennent, à dater de ce jour, soit sur les dîmes et les tributs qui nous appartiennent, soit sur les marais salants et les couronnes qui nous étaient dues,'),
('1m',11,36,'crampon1923','nous leur en faisons encore remise complète. Il ne sera dérogé désormais et en aucun temps à aucune de ces faveurs.'),
('1m',11,37,'crampon1923','Maintenant donc, prenez soin de faire une copie de ce décret, et qu''elle soit donnée à Jonathas et déposée sur la montagne sainte dans un lieu apparent. "'),
('1m',11,38,'crampon1923','Le roi Démétrius, voyant que le pays était en paix devant lui, et qu''il n''avait plus à vaincre aucune résistance, renvoya toute son armée, chacun dans ses foyers, à l''exception des troupes étrangères qu''il avait recrutées dans les îles des nations; et ainsi toutes les armées de ses pères devinrent ses ennemies.'),
('1m',11,39,'crampon1923','Tryphon, qui avait été auparavant un des partisans d''Alexandre, voyant que toute l''armée murmurait contre Démétrius, alla trouver l''Arabe Emalchuel, qui élevait Antiochus, jeune fils d''Alexandre.'),
('1m',11,40,'crampon1923','Il le pressa de le lui livrer, afin de le faire régner à la place de son père; il lui raconta tout ce que Démétrius avait fait et la haine de ses troupes contre lui, et il demeura là un grand nombre de jours.'),
('1m',11,41,'crampon1923','Jonathas envoya demander au roi Démétrius de retirer les troupes qui étaient dans la citadelle de Jérusalem et dans les autres forteresses de la Judée, parce qu''elles faisaient la guerre à Israël.'),
('1m',11,42,'crampon1923','Démétrius fit répondre à Jonathas: " Je ne ferai pas seulement cela pour toi et pour ta nation; mais je veux te combler d''honneurs, toi et ta nation, aussitôt que les circonstances le permettront.'),
('1m',11,43,'crampon1923','Maintenant donc, tu feras bien d''envoyer des hommes à mon secours, car toute mon armée a fait défection. "'),
('1m',11,44,'crampon1923','Jonathas lui envoya à Antioche trois mille hommes des plus vaillants; ils se rendirent auprès du roi, qui se réjouit de leur arrivée.'),
('1m',11,45,'crampon1923','Les habitants de la ville se rassemblèrent dans l''intérieur même de la ville, au nombre de cent vingt mille, voulant tuer le roi.'),
('1m',11,46,'crampon1923','Le roi s''étant réfugié dans le palais, les habitants occupèrent les rues de la ville et commencèrent à combattre.'),
('1m',11,47,'crampon1923','Alors le roi appela les Juifs à son secours; tous ensemble se réunirent autour de lui, puis se répandirent à travers la ville; ils y tuèrent ce jour-là environ cent mille hommes;'),
('1m',11,48,'crampon1923','ils brûlèrent la ville, firent en ce jour-là un butin considérable et délivrèrent le roi.'),
('1m',11,49,'crampon1923','Voyant que les Juifs tenaient la ville à leur discrétion, les habitants perdirent courage et firent entendre au roi des cris suppliants:'),
('1m',11,50,'crampon1923','" Accorde-nous la paix, et que les Juifs cessent de combattre contre nous et contre la ville! "'),
('1m',11,51,'crampon1923','En même temps, ils jetèrent leurs armes et firent la paix. Les Juifs acquirent beaucoup de gloire devant le roi et devant tous ceux qui étaient dans son royaume, et ils retournèrent à Jérusalem avec de riches dépouilles.'),
('1m',11,52,'crampon1923','Le roi Démétrius put s''asseoir sur le trône de son royaume, et le pays fut en paix devant lui.'),
('1m',11,53,'crampon1923','Mais il renia toutes les promesses qu''il avait faites; il s''éloigna de Jonathas et ne réalisa pas les intentions bienveillantes qu''il lui avait témoignées, et il l''affligea beaucoup.'),
('1m',11,54,'crampon1923','Après cela, Tryphon revint, amenant avec lui Antiochus, un jeune enfant, et il le proclama roi et lui mit le diadème.'),
('1m',11,55,'crampon1923','Autour de lui se rassemblèrent toutes les troupes que Démétrius avait licenciées; elles combattirent contre ce dernier, qui prit la fuite et fut défait.'),
('1m',11,56,'crampon1923','Tryphon s''empara des éléphants et occupa Antioche.'),
('1m',11,57,'crampon1923','Alors le jeune Antiochus écrivit à Jonathas une lettre ainsi conçue: " Je te confirme dans le sacerdoce et je t''établis sur les quatre territoires, et te donne le rang d''ami du roi. "'),
('1m',11,58,'crampon1923','Il lui envoyait en même temps des vases d''or et un service de table, avec l''autorisation de boire dans une coupe d''or, de se vêtir de pourpre et de porter une agrafe d''or.'),
('1m',11,59,'crampon1923','Et il établit Simon, son frère, gouverneur du pays qui s''étend de l''Echelle de Tyr à la frontière d''Egypte.'),
('1m',11,60,'crampon1923','Alors Jonathas sortit et se mit à parcourir le pays au-delà du fleuve ainsi que les villes; et autour de lui se rassemblèrent, pour combattre avec lui, toutes les troupes de Syrie. Il vint donc à Ascalon, dont les habitants vinrent au devant de lui, lui rendant de grands honneurs.'),
('1m',11,61,'crampon1923','De là, il passa à Gaza. Les habitants lui ayant fermé leurs portes, il assiégea la ville, en brûla les alentours et les pilla.'),
('1m',11,62,'crampon1923','Alors ceux de Gaza implorèrent Jonathas, et il leur accorda la paix; mais il prit pour otages les fils de leurs chefs et les envoya à Jérusalem. Il parcourut ainsi la contrée jusqu''à Damas.'),
('1m',11,63,'crampon1923','Jonathas apprit alors que les généraux de Démétrius se trouvaient à Cadès en Galilée, à la tête d''une armée nombreuse, avec l''intention de le détourner de son entreprise.'),
('1m',11,64,'crampon1923','Il marcha contre eux, après avoir laissé son frère Simon dans le pays.'),
('1m',11,65,'crampon1923','Simon s''avança vers Bethsur, l''assiégea pendant beaucoup de jours et la cerna.'),
('1m',11,66,'crampon1923','Les assiégés lui ayant demandé la paix, il la leur accorda, les fit sortir de la ville, en prit possession et y mit une garnison.'),
('1m',11,67,'crampon1923','Jonathas et son armée campèrent prés des eaux de Génésar, et le lendemain, dès l''aurore, ils pénétrèrent dans la plaine d''Asor.'),
('1m',11,68,'crampon1923','Et voici que des troupes étrangères s''avançaient au-devant de lui dans la plaine, après avoir détaché contre lui une embuscade dans les montagnes, et elles marchèrent droit à sa rencontre.'),
('1m',11,69,'crampon1923','Tout à coup les hommes de l''embuscade sortirent de leur cachette et engagèrent le combat; et les gens de Jonathas prirent tous la fuite.'),
('1m',11,70,'crampon1923','Personne ne resta, à l''exception de Mathathias, fils d''Absalom, et de Judas, fils de Calphi, généraux des troupes.'),
('1m',11,71,'crampon1923','Alors Jonathas déchira ses vêtements, mit de la poussière sur sa tête et pria;'),
('1m',11,72,'crampon1923','puis il retourna contre eux au combat, les fit reculer et les mit en fuite.'),
('1m',11,73,'crampon1923','A cette vue, ceux des siens qui s''enfuyaient revinrent auprès de lui, et tous ensemble ils poursuivirent l''ennemi jusqu''à Cadès, où était son camp, et eux-mêmes campèrent en cet endroit.'),
('1m',11,74,'crampon1923','Il périt ce jour-là trois mille hommes de troupes étrangères, et Jonathas retourna à Jérusalem.'),
('1m',12,1,'crampon1923','Jonathas, voyant que les circonstances étaient favorables, choisit des hommes et les envoya à Rome pour confirmer et renouveler l''amitié des Juifs avec les Romains.'),
('1m',12,2,'crampon1923','Il envoya aussi aux Spartiates et en d''autres lieux des lettres dans le même sens.'),
('1m',12,3,'crampon1923','Ils se rendirent donc à Rome, entrèrent dans le sénat et dirent: " Jonathas, grand prêtre, et la nation des Juifs nous ont envoyés pour renouveler l''amitié et l''alliance avec eux, telles qu''elles existaient auparavant. "'),
('1m',12,4,'crampon1923','Et le sénat leur remit une lettre pour les autorités romaines de chaque lieu, recommandant de leur procurer un heureux retour dans le pays de Juda.'),
('1m',12,5,'crampon1923','Voici la copie de la lettre que Jonathas écrivit aux Spartiates:'),
('1m',12,6,'crampon1923','" Jonathas, grand prêtre, le sénat de la nation, les prêtres et le reste du peuple juif, aux Spartiates leurs frères, salut!'),
('1m',12,7,'crampon1923','Déjà, dans les temps passés, une lettre a été envoyée à Onias, grand prêtre, de la part d''Aréius qui régnait sur vous, attestant que vous êtes nos frères, comme en fait foi la copie ci-dessous.'),
('1m',12,8,'crampon1923','Onias accueillit avec honneur l''homme qui était envoyé, et reçut la lettre ou il était clairement parlé d''alliance et d''amitié.'),
('1m',12,9,'crampon1923','Nous donc, quoique nous n''eussions pas besoin de ces choses, ayant pour consolation les saints Livres qui sont entre nos mains,'),
('1m',12,10,'crampon1923','nous avons essayé d''envoyer vers vous pour renouveler la fraternité et l''amitié qui nous unissent à vous, afin que nous ne vous devenions pas étrangers; car de nombreuses années se sont écoulées depuis que vous avez envoyé vers nous.'),
('1m',12,11,'crampon1923','Nous donc, en tout temps, nous nous souvenons constamment de vous, et dans nos solennités et aux autres jours sacrés, dans les sacrifices que nous offrons et dans nos prières, comme il est juste et convenable de se souvenir de ses frères.'),
('1m',12,12,'crampon1923','Nous nous réjouissons de votre prospérité.'),
('1m',12,13,'crampon1923','Mais nous, de nombreuses calamités et des guerres incessantes nous assiègent; les rois qui nous entourent nous font la guerre.'),
('1m',12,14,'crampon1923','Nous n''avons pas voulu, à l''occasion de ces guerres, être à charge, soit à vous, soit à nos autres alliés et amis.'),
('1m',12,15,'crampon1923','Car nous avons le secours du ciel pour nous venir en aide, et nous avons été délivrés et nos ennemis ont été humiliés.'),
('1m',12,16,'crampon1923','C''est pourquoi nous avons choisi Numénius, fils d''Antiochus, et Antipater, fils de Jason, et nous les avons envoyés vers les Romains pour renouveler avec eux l''amitié et l''alliance ancienne.'),
('1m',12,17,'crampon1923','Nous leur avons donc mandé d''aller aussi vers vous, de vous saluer et de vous apporter notre lettre concernant le renouvellement de notre fraternité.'),
('1m',12,18,'crampon1923','Et maintenant vous ferez bien en nous répondant à ce sujet. "'),
('1m',12,19,'crampon1923','Voici la copie de la lettre qu''on avait envoyée à Onias:'),
('1m',12,20,'crampon1923','" Aréius, roi des Spartiates, au grand prêtre Onias, salut!'),
('1m',12,21,'crampon1923','Il a été trouvé dans un écrit sur les Spartiates et les Juifs que ces deux peuples sont frères, et qu''ils sont de la race d''Abraham.'),
('1m',12,22,'crampon1923','Maintenant que nous savons cela, vous ferez bien de nous écrire touchant votre prospérité.'),
('1m',12,23,'crampon1923','Nous aussi, à notre tour, nous vous écrirons. Vos troupeaux et vos biens sont à nous, et les nôtres sont à vous. — Les porteurs de cette lettre ont ordre de vous faire des déclarations en ce sens. "'),
('1m',12,24,'crampon1923','Ayant été informé que les généraux de Démétrius étaient revenus pour l''attaquer avec une armée plus considérable qu''auparavant,'),
('1m',12,25,'crampon1923','Jonathas partit de Jérusalem et marcha à leur rencontre jusqu''au pays d''Emath, car il ne leur laissa pas le temps d''envahir son pays.'),
('1m',12,26,'crampon1923','Il envoya des espions dans leur camp, et, à leur retour, ils lui rapportèrent que les Syriens avaient résolu de le surprendre pendant la nuit.'),
('1m',12,27,'crampon1923','Lorsque le soleil fut couché, Jonathas commanda aux siens de veiller et de se tenir en armes toute la nuit, prêts à combattre, et il détacha des sentinelles avancées tout autour du camp.'),
('1m',12,28,'crampon1923','Mais les ennemis, ayant appris que Jonathas et les siens se tenaient prêts à combattre, furent saisis de crainte, ils tremblèrent dans leur cœur; ils allumèrent des feux dans leur camp, et s''enfuirent.'),
('1m',12,29,'crampon1923','Jonathas et les siens ne s''aperçurent de leur retraite que le matin, car ils voyaient des feux allumés.'),
('1m',12,30,'crampon1923','Alors Jonathas se mit à leur poursuite, mais il ne les rejoignit pas, car ils avaient traversé le fleuve Eleuthère.'),
('1m',12,31,'crampon1923','Alors Jonathas se tourna vers les Arabes appelés Zabadéens; il les battit et s''empara de leurs dépouilles.'),
('1m',12,32,'crampon1923','De là il alla à Damas et parcourut toute la contrée.'),
('1m',12,33,'crampon1923','Simon, de son côté, s''étant mis en marche, s''avança jusqu''à Ascalon et jusqu''aux forteresses voisines; puis il se tourna vers Joppé et l''occupa,'),
('1m',12,34,'crampon1923','parce qu''il avait appris que la population avait le dessein de livrer la forteresse à Démétrius, et il y mit une garnison pour garder la ville.'),
('1m',12,35,'crampon1923','A son retour à Jérusalem, Jonathas convoqua les anciens du peuple et résolut avec eux de construire des forteresses en Judée,'),
('1m',12,36,'crampon1923','d''exhausser les murailles de Jérusalem et de bâtir un mur élevé entre la citadelle et la ville, afin de séparer l''une de l''autre, de manière que la citadelle fût isolée et qu''on n''y pût ni vendre ni acheter.'),
('1m',12,37,'crampon1923','Des ouvriers étant rassemblés pour construire la ville, on se mit au mur qui s''élevait au-dessus du torrent de Cédron, vers l''orient, et l''on répara la partie appelée Caphénatha.'),
('1m',12,38,'crampon1923','Simon, de son côté, bâtit Hadida dans la Séphéla, et il y mit des portes et des verrous.'),
('1m',12,39,'crampon1923','Cependant Tryphon aspirait à devenir roi d''Asie, à ceindre le diadème et à mettre la main sur le roi Antiochus.'),
('1m',12,40,'crampon1923','Craignant que Jonathas ne le laissât pas faire et ne combattit contre lui, il cherchait le moyen de se saisir de sa personne et de le mettre à mort. S''étant donc mis en route, il vint à Bethsan.'),
('1m',12,41,'crampon1923','Jonathas s''avança à sa rencontre, avec quarante mille hommes, guerriers d''élite, et il marcha sur Bethsan.'),
('1m',12,42,'crampon1923','Voyant que Jonathas était venu avec une armée nombreuse, Tryphon craignit de mettre la main sur lui.'),
('1m',12,43,'crampon1923','Il le reçut avec honneur, le recommanda à tous ses amis, lui offrit des présents et ordonna à ses troupes de lui obéir comme à lui-même.'),
('1m',12,44,'crampon1923','Et il dit à Jonathas: " Pourquoi as-tu fatigué tout ce peuple, puisqu''il n''y a pas de guerre entre nous?'),
('1m',12,45,'crampon1923','Renvoie-les donc dans leurs maisons, mais choisis-en quelques-uns pour t''accompagner et viens avec moi à Ptolémaïs; je te livrerai cette ville, ainsi que les autres forteresses, les autres troupes et tous les officiers royaux, puis je retournerai à Antioche; car c''est pour cela que je suis venu. "'),
('1m',12,46,'crampon1923','Jonathas le crut et fit comme il avait dit; il renvoya son armée, qui s''en retourna en Judée.'),
('1m',12,47,'crampon1923','Il garda avec lui trois mille hommes, dont il détacha deux mille en Galilée, et mille seulement l''accompagnèrent.'),
('1m',12,48,'crampon1923','Mais dès que Jonathas fut entré à Ptolémaïs, les habitants fermèrent les portes de la ville, se saisirent de lui et tuèrent par l''épée tous ceux qui étaient entrés avec lui.'),
('1m',12,49,'crampon1923','En même temps Tryphon envoya une armée et des cavaliers en Galilée et dans la grande plaine, pour massacrer tous les hommes de Jonathas.'),
('1m',12,50,'crampon1923','Mais ceux-ci, ayant entendu dire que Jonathas avait été pris et mis à mort avec tous ceux qui l''accompagnaient, s''encouragèrent mutuellement et se mirent en marche, les rangs serrés, prêts à combattre.'),
('1m',12,51,'crampon1923','Ceux qui les poursuivaient, voyant qu''ils étaient résolus à défendre leur vie, revinrent sur leurs pas;'),
('1m',12,52,'crampon1923','et eux rentrèrent tous sans être inquiétés dans le pays de Juda. Ils pleurèrent Jonathas et ses compagnons, et une grande crainte s''empara d''eux, et tout Israël mena grand deuil.'),
('1m',12,53,'crampon1923','Alors toutes les nations d''alentour cherchèrent à les perdre, car elles disaient:'),
('1m',12,54,'crampon1923','" Ils n''ont plus ni chef ni secours de personne; attaquons-les donc maintenant, et faisons disparaître leur mémoire d''entre les hommes. "'),
('1m',13,1,'crampon1923','Simon apprit que Tryphon assemblait une armée considérable pour envahir le pays de Juda et le dévaster.'),
('1m',13,2,'crampon1923','Voyant que le peuple était dans la crainte et l''épouvante, il monta à Jérusalem et convoqua le peuple.'),
('1m',13,3,'crampon1923','Il les exhorta en disant: " Vous savez tout ce que mes frères et moi, et toute la maison de mon père avons fait pour défendre nos lois et notre religion, les combats que nous avons soutenus et les souffrances que nous avons endurées.'),
('1m',13,4,'crampon1923','C''est pour cela que tous mes frères sont morts pour Israël, et je suis resté seul.'),
('1m',13,5,'crampon1923','Et maintenant, à Dieu ne plaise que j''épargne ma vie en aucun temps de tribulation, car je ne vaux pas mieux que mes frères!'),
('1m',13,6,'crampon1923','Mais je veux être le vengeur de mon peuple, du sanctuaire, de nos femmes et de nos enfants, car toutes les nations se sont unies pour nous détruire par haine. "'),
('1m',13,7,'crampon1923','L''esprit du peuple fut enflammé en entendant ces paroles;'),
('1m',13,8,'crampon1923','ils répondirent en poussant des acclamations: " Tu es notre chef, à la place de Judas et de Jonathas, ton frère.'),
('1m',13,9,'crampon1923','Conduis-nous aux combats, et nous ferons tout ce que tu nous diras. "'),
('1m',13,10,'crampon1923','Alors Simon rassembla tous les hommes de guerre, il hâta l''achèvement des murailles de Jérusalem et fortifia cette ville tout autour.'),
('1m',13,11,'crampon1923','En même temps, il envoya à Joppé, avec des forces considérables, Jonathan fils d''Absalom, lequel, en ayant expulsé les habitants, demeura dans cette ville.'),
('1m',13,12,'crampon1923','Tryphon partit de Ptolémaïs avec une nombreuse armée, pour envahir le pays de Juda, emmenant avec lui Jonathas enchaîné.'),
('1m',13,13,'crampon1923','Simon établit son camp à Hadida, en face de la plaine.'),
('1m',13,14,'crampon1923','Lorsque Tryphon sut que Simon avait pris le commandement à la place de Jonathas son frère, et qu''il se disposait à le combattre, il lui envoya des messagers pour lui dire:'),
('1m',13,15,'crampon1923','" C''est pour l''argent que ton frère Jonathas doit au trésor royal, à raison des fonctions qu''il remplissait, que nous le retenons prisonnier.'),
('1m',13,16,'crampon1923','Envoie donc cent talents d''argent et deux de ses fils en otage, afin que, une fois libre, il ne se tourne pas contre nous, et nous lui rendrons la liberté. "'),
('1m',13,17,'crampon1923','Simon comprit que les messagers lui parlaient ainsi pour le tromper; néanmoins il envoya l''argent et les deux jeunes enfants, pour ne pas attirer sur lui une grande haine de la part du peuple d''Israël, qui aurait pu dire:'),
('1m',13,18,'crampon1923','" C''est parce que Simon n''a pas envoyé l''argent et les enfants, que Jonathas a péri. "'),
('1m',13,19,'crampon1923','Il envoya donc les enfants et les cent talents d''argent; mais Tryphon ne tint pas sa parole et il ne relâcha pas Jonathas.'),
('1m',13,20,'crampon1923','Ensuite Tryphon s''avança pour fouler le pays et le dévaster; faisant un détour, il prit le chemin d''Adora; mais Simon et son armée s''attachaient à lui partout où il allait.'),
('1m',13,21,'crampon1923','Ceux qui étaient dans la citadelle de Jérusalem envoyèrent des messagers à Tryphon, le priant de venir en hâte par le désert et de leur amener des vivres.'),
('1m',13,22,'crampon1923','Tryphon disposa toute sa cavalerie pour arriver cette nuit-là; mais il tomba une neige très abondante, et il ne put arriver à Jérusalem à cause de la neige; il partit et alla en Galaad.'),
('1m',13,23,'crampon1923','Lorsqu''il fut proche de Bascama, il tua Jonathas, et celui-ci fut enterré en cet endroit.'),
('1m',13,24,'crampon1923','De là Tryphon retourna dans son pays.'),
('1m',13,25,'crampon1923','Simon envoya recueillir les restes de son frère Jonathas, et il les ensevelit à Modin, la ville de ses pères.'),
('1m',13,26,'crampon1923','Tout Israël mena sur lui un grand deuil, et ils le pleurèrent un grand nombre de jours.'),
('1m',13,27,'crampon1923','Sur le sépulcre de son père et de ses frères, Simon fit construire un mausolée, assez élevé pour être vu de loin, en pierres polies par devant et par derrière.'),
('1m',13,28,'crampon1923','Et il fit dresser au-dessus sept pyramides, se faisant face l''une à l''autre, pour son père, pour sa mère et pour ses quatre frères.'),
('1m',13,29,'crampon1923','Il y fit exécuter des ornements, les entourant de hautes colonnes surmontées de panoplies, en souvenir éternel; et, à côté des panoplies, il plaça des navires sculptés pour être vus de tous ceux qui naviguent sur la mer.'),
('1m',13,30,'crampon1923','Tel est le tombeau que Simon fit ériger à Modin, et qui subsiste jusqu''à ce jour.'),
('1m',13,31,'crampon1923','Tryphon, usant aussi de ruse à l''égard du jeune roi Antiochus, le tua.'),
('1m',13,32,'crampon1923','Il régna à sa place et ceignit le diadème des rois d''Asie, et causa de grands maux dans le pays.'),
('1m',13,33,'crampon1923','Simon rebâtit les forteresses de la Judée, les garnissant de hautes tours, de murailles élevées, de portes et de verrous, et il y mit des provisions de vivres.'),
('1m',13,34,'crampon1923','Simon choisit des hommes et les envoya vers le roi Démétrius pour qu''il accordât rémission à la Judée, car tous les actes de Tryphon n''étaient que brigandage.'),
('1m',13,35,'crampon1923','Le roi Démétrius lui fit répondre en conformité avec ces paroles, et lui écrivit cette lettre:'),
('1m',13,36,'crampon1923','" Le roi Démétrius à Simon, grand prêtre et ami des rois, aux anciens et à la nation des Juifs, salut!'),
('1m',13,37,'crampon1923','Nous avons reçu la couronne d''or et la palme que vous avez envoyées, et nous sommes disposés à faire avec vous une paix complète et à écrire aux intendants royaux de vous faire différentes remises.'),
('1m',13,38,'crampon1923','Tout ce que nous avons statué à votre égard est stable; que les forteresses que vous avez bâties soient à vous.'),
('1m',13,39,'crampon1923','Nous vous faisons remise de tous les oublis et de toutes les offenses jusqu''à ce jour, ainsi que de la couronne que vous deviez; et, s''il était levé quelque autre tribut à Jérusalem, qu''il ne soit plus levé.'),
('1m',13,40,'crampon1923','Si quelques-uns d''entre vous sont disposés à s''enrôler dans nos gardes du corps, qu''ils s''y enrôlent, et que la paix règne entre nous. "'),
('1m',13,41,'crampon1923','En l''an cent soixante-dix, le joug des nations fut ôté d''Israël.'),
('1m',13,42,'crampon1923','Et le peuple d''Israël commença à écrire sur les actes et les contrats: " En la première année de Simon, grand prêtre éminent, général et ethnarque des Juifs. "'),
('1m',13,43,'crampon1923','En ces jours-là, Simon marcha sur Gaza, qu''il fit investir par ses troupes; il construisit des hélépoles et les fit donner contre la ville; il fit ainsi une brèche à une des tours, et s''en rendit maître.'),
('1m',13,44,'crampon1923','Ceux qui étaient dans l''hélépole sautèrent dans la ville, ce qui y causa un grand émoi.'),
('1m',13,45,'crampon1923','Les habitants, avec leurs femmes et leurs enfants, montèrent sur les murailles, les vêtements déchirés, poussant de grands cris, et demandant à Simon de faire la paix avec eux:'),
('1m',13,46,'crampon1923','" Ne nous traite pas, disaient-ils, selon notre méchanceté, mais selon ta miséricorde! "'),
('1m',13,47,'crampon1923','Simon se laissa fléchir par eux, et ne les combattit plus; mais il bannit les habitants de la ville, purifia les maisons où il y avait des idoles, et fit son entrée au chant des hymnes de louanges et d''actions de grâces.'),
('1m',13,48,'crampon1923','Après avoir ôté de la ville toute impureté, il y établit des hommes observateurs de la loi; puis il la fortifia et s''y construisit une habitation.'),
('1m',13,49,'crampon1923','Cependant ceux qui étaient dans la citadelle de Jérusalem, ne pouvant ni sortir ni aller dans le pays, ni acheter, ni vendre, souffraient beaucoup de la famine, et un grand nombre moururent de faim.'),
('1m',13,50,'crampon1923','Ils demandèrent à grands cris à Simon de faire la paix avec eux, ce qu''il leur accorda; mais il les chassa de là et purifia la citadelle de toute souillure.'),
('1m',13,51,'crampon1923','Il y fit son entrée le vingt-troisième jour du second mois de l''an cent soixante et onze, avec des chants de louange, des rameaux de palmiers, des cithares, des cymbales, des harpes, des hymnes et des cantiques, parce qu''un grand ennemi d''Israël était brisé.'),
('1m',13,52,'crampon1923','Il ordonna qu''on célébrât chaque année ce jour d''allégresse;'),
('1m',13,53,'crampon1923','il fortifia la montagne du temple, située à côté de la citadelle, et il demeura là, lui et les siens. Puis Simon voyant que son fils Jean se montrait homme de courage, lui donna le commandement de toutes les troupes, avec Gazara pour résidence.'),
('1m',14,1,'crampon1923','L''an cent soixante-douze, le roi Démétrius assembla ses armées et s''en alla en Médie, pour y recruter des troupes auxiliaires, afin de combatte Tryphon.'),
('1m',14,2,'crampon1923','Arsace, roi de Perse et de Médie, ayant appris que Démétrius était entré sur son territoire, envoya un de ses généraux pour le prendre vivant.'),
('1m',14,3,'crampon1923','Celui-ci se mit en marche et, ayant battu l''armée de Démétrius, il s''empara de sa personne et l''amena à Arsace, qui le mit en prison.'),
('1m',14,4,'crampon1923','Le pays de Juda fut en paix durant tous les jours de Simon. Il s''appliqua à procurer la prospérité de son peuple, et son autorité et sa gloire plurent au peuple durant tous ces jours.'),
('1m',14,5,'crampon1923','Sans parler de ses autres titres de gloire, il prit Joppé pour en faire un port qui le mit en relation avec les îles de la mer.'),
('1m',14,6,'crampon1923','Il recula les frontières de sa nation et fut maître du pays.'),
('1m',14,7,'crampon1923','Il recueillit un grand nombre de prisonniers; il s''empara de Gazara, de Bethsur et de la citadelle, dont il ôta toutes les souillures, et il n''y avait personne qui pût lui résister.'),
('1m',14,8,'crampon1923','Chacun cultivait en paix sa terre; le sol donnait ses produits et les arbres des champs leurs fruits.'),
('1m',14,9,'crampon1923','Les vieillards, assis sur les places publiques, s''entretenaient tous de la prospérité du pays, et les jeunes gens revêtaient comme un ornement les habits de guerre.'),
('1m',14,10,'crampon1923','Simon distribuait des approvisionnements aux villes, et les pourvoyait de toutes les choses nécessaires à la défense: au point que son nom glorieux était célèbre jusqu''aux extrémités de la terre.'),
('1m',14,11,'crampon1923','Il rétablit la paix dans son pays, et Israël se rejouit d''une grande joie.'),
('1m',14,12,'crampon1923','Chacun était assis sous sa vigne et son figuier, et personne ne leur inspirait de crainte.'),
('1m',14,13,'crampon1923','Il n''y avait plus d''adversaire pour les attaquer dans le pays; les rois ennemis furent vaincus en ces jours-là.'),
('1m',14,14,'crampon1923','Il fut le soutien de tous les malheureux de son peuple; il se montra zélé pour la loi, et fit disparaître tous les impies et les méchants.'),
('1m',14,15,'crampon1923','Il glorifia le sanctuaire et multiplia les ustensiles sacrés.'),
('1m',14,16,'crampon1923','Quand la nouvelle de la mort de Jonathas arriva à Rome et jusqu''à Sparte, ils en furent très affligés.'),
('1m',14,17,'crampon1923','Mais lorsqu''ils surent que Simon, son frère, était grand prêtre à sa place et maître de tout le pays, ainsi que de toutes les villes qui s''y trouvent,'),
('1m',14,18,'crampon1923','ils lui écrivirent sur des tables d''airain pour renouveler avec lui l''alliance et l''amitié qu''ils avaient faites avec Judas et avec Jonathas, ses frères.'),
('1m',14,19,'crampon1923','Les lettres furent lues en présence de toute l''assemblée à Jérusalem, et voici la copie de celle que les Spartiates envoyèrent:'),
('1m',14,20,'crampon1923','" Les chefs des Spartiates et la cité à Simon, grand prêtre, aux anciens, aux prêtres et au reste du peuple des Juifs, leurs frères, salut!'),
('1m',14,21,'crampon1923','Les ambassadeurs qui ont été envoyés à notre peuple nous ont entretenus de la gloire et de l''honneur dont vous jouissez, et nous nous sommes réjouis de leur arrivée.'),
('1m',14,22,'crampon1923','Et nous avons inscrit parmi les plébiscites ce qui a été dit par eux, savoir: Numénius, fils d''Antiochus, et Antipater, fils de Jason, ambassadeurs des Juifs, sont venus vers nous pour renouveler amitié avec nous.'),
('1m',14,23,'crampon1923','Et il a plu au peuple de recevoir ces hommes avec honneur et de déposer la copie de leurs discours aux archives publiques, pour que le peuple de Sparte en conserve la mémoire. — Et nous en avons fait écrire cette copie pour Simon le grand prêtre. "'),
('1m',14,24,'crampon1923','Après cela, Simon envoya à Rome Numénius, avec un grand bouclier d''or du poids de mille mines, pour assurer l''alliance avec eux.'),
('1m',14,25,'crampon1923','Quand le peuple eut appris ces choses, il dit: " Quel témoignage de reconnaissance donnerons-nous à Simon et à ses fils?'),
('1m',14,26,'crampon1923','Car il a montré une fermeté inébranlable, lui, ses frères et la maison de son père; ils ont combattu et repoussé les ennemis d''Israël, et lui ont assuré la liberté. " Ils gravèrent ces choses sur des tables d''airain, qu''ils suspendirent à une colonne sur le mont Sion.'),
('1m',14,27,'crampon1923','En voici la copie: « Le dix-huitième jour du mois d''Elul, l''an cent soixante-douze, la troisième année de Simon, grand prêtre, dans Saramel,'),
('1m',14,28,'crampon1923','en la grande assemblée des prêtres et du peuple, des princes de la nation et des anciens du pays, il a été publié ceci: “Dans les nombreux combats dont notre pays a été le théâtre,'),
('1m',14,29,'crampon1923','Simon fils de Mathathias, d''entre les descendants de Jarib, et ses frères, se sont exposés au danger et ont résisté aux ennemis de leur nation, afin que leur sanctuaire restât debout, ainsi que la loi, et ils ont acquis à leur nation une grande gloire.'),
('1m',14,30,'crampon1923','Jonathas rassembla sa nation et devint leur grand prêtre; puis il fut réuni à son peuple.'),
('1m',14,31,'crampon1923','Leurs ennemis voulurent fouler leur pays et le dévaster, et étendre la main sur leur sanctuaire.'),
('1m',14,32,'crampon1923','Alors Simon se leva et combattit pour sa nation; il dépensa beaucoup de ses biens propres, fournit des armes aux hommes vaillants de sa nation et leur donna une solde,'),
('1m',14,33,'crampon1923','il fortifia les villes de Judée, ainsi que Bethsur, située à la frontière, où se trouvaient auparavant les armes des ennemis, et il y mit une garnison de troupes juives.'),
('1m',14,34,'crampon1923','Il fortifia Joppé, située sur la mer, et Gazara sur la frontière d''Azot, habitée autrefois par les ennemis; et il y établit des Juifs, et les approvisionna de toutes les choses nécessaires à leur relèvement.'),
('1m',14,35,'crampon1923','Le peuple vit la conduite de Simon et la gloire qu''il se proposait de donner à sa nation, et ils le constituèrent leur chef et leur grand prêtre, à cause de tous ces services qu''il leur avait rendus, et de la justice et de la fidélité qu''il garda envers sa nation, et parce qu''il travailla de toute manière à élever son peuple.'),
('1m',14,36,'crampon1923','« Pendant qu''il vécut, tout prospéra entre ses mains, au point qu''il chassa les nations du pays qu''elles occupaient, ainsi que ceux qui étaient dans la cité de David à Jérusalem, lesquels s''étaient construit une citadelle d''où ils faisaient des sorties, souillant les alentours du sanctuaire et profanant grandement sa sainteté.'),
('1m',14,37,'crampon1923','Il y établit des guerriers Juifs et la fortifia pour assurer la défense du pays et de la ville, et il exhaussa les murailles de Jérusalem.'),
('1m',14,38,'crampon1923','Le roi Démétrius lui assura en conséquence la souveraine sacrificature;'),
('1m',14,39,'crampon1923','il le déclara son ami et lui accorda les plus grands honneurs.'),
('1m',14,40,'crampon1923','Car il avait appris que les Romains appelaient les Juifs amis et alliés et frères, et qu''ils avaient reçu honorablement les envoyés de Simon.'),
('1m',14,41,'crampon1923','« Les Juifs et les prêtres ont donc trouvé bon que Simon soit prince et grand prêtre pour toujours, jusqu''à ce que paraisse un prophète digne de foi;'),
('1m',14,42,'crampon1923','qu''il commande leurs armées; qu''il ait le soin des choses saintes; qu''il établisse les officiers pour les services publics, pour administrer le pays, veiller sur les armements et défendre les forteresses;'),
('1m',14,43,'crampon1923','qu''il ait le soin des choses saintes, qu''il soit obéi de tous, que tous les actes publics dans le pays soient écrits en son nom, et qu''il soit revêtu de pourpre et d''or.'),
('1m',14,44,'crampon1923','Il ne sera permis à personne du peuple ou d''entre les prêtres de rejeter aucun de ces points, de contredire aucun ordre donné par lui, de convoquer sans sa permission aucune assemblée dans le pays, de porter robe de pourpre ou agrafe d''or.'),
('1m',14,45,'crampon1923','Quiconque agira contrairement à ce décret ou en violera quelque article, encourra un châtiment.'),
('1m',14,46,'crampon1923','« Il a paru bon au peuple d''investir Simon du pouvoir d''agir selon ce décret.'),
('1m',14,47,'crampon1923','Simon accepta; il voulut bien remplir les fonctions de grand prêtre, de chef des armées et d''ethnarque des Juifs et des prêtres, et exercer le commandement suprême.” »'),
('1m',14,48,'crampon1923','On décida de graver ce document sur des tables d''airain, et de les placer dans la galerie du temple, en un lieu apparent,'),
('1m',14,49,'crampon1923','et d''en déposer une copie dans la chambre du trésor, pour servir à Simon et à ses fils.'),
('1m',15,1,'crampon1923','Le roi Antiochus, fils de Démétrius, envoya des îles de la mer une lettre à Simon, grand prêtre et ethnarque des Juifs, et à toute la nation;'),
('1m',15,2,'crampon1923','elle était ainsi conçue: " Le roi Antiochus, à Simon, grand prêtre et ethnarque, et à la nation des Juifs, salut!'),
('1m',15,3,'crampon1923','Puisque des misérables se sont emparés du royaume de nos pères, que je veux le revendiquer afin de le rétablir tel qu''il était auparavant, et que j''ai rassemblé des troupes nombreuses et équipé beaucoup de vaisseaux de guerre;'),
('1m',15,4,'crampon1923','ayant l''intention de débarquer dans le pays, pour tirer vengeance de ceux qui ont ruiné notre pays et qui ont dévasté un grand nombre de villes de ce royaume,'),
('1m',15,5,'crampon1923','je te confirme toutes les remises de tributs que t''ont accordées les rois mes prédécesseurs, et toutes les autres remises qu''ils t''ont concédées.'),
('1m',15,6,'crampon1923','Je te permets de frapper monnaie à ton empreinte pour ton pays.'),
('1m',15,7,'crampon1923','Que Jérusalem et le temple soient libres; que toutes les armes que tu as fabriquées et les forteresses que tu as bâties et que tu occupes te demeurent.'),
('1m',15,8,'crampon1923','Que toute chose due ou à devoir au trésor royal te soit remise dès à présent et pour toujours.'),
('1m',15,9,'crampon1923','Lorsque nous serons rentrés en possession de notre royaume, nous t''honorerons magnifiquement, toi, ta nation et le sanctuaire, de telle sorte que votre gloire brillera dans tout l''univers. "'),
('1m',15,10,'crampon1923','L''an cent soixante-quatorze, Antiochus se mit en marche vers le pays de ses pères, et toutes les troupes vinrent se ranger auprès de lui, de sorte que peu d''hommes demeurèrent à Tryphon.'),
('1m',15,11,'crampon1923','Le roi Antiochus se mit à sa poursuite, et Tryphon vint en fuyant à Dora, sur la mer.'),
('1m',15,12,'crampon1923','Car il voyait que des maux s''amassaient sur lui et que son armée l''abandonnait.'),
('1m',15,13,'crampon1923','Antiochus vint camper devant Dora avec cent vingt mille combattants et huit mille cavaliers.'),
('1m',15,14,'crampon1923','Il investit la ville et, comme des navires s''approchèrent du côté de la mer, il la pressa et par terre et par mer, ne laissant personne y entrer ou en sortir.'),
('1m',15,15,'crampon1923','Cependant arrivèrent de la ville de Rome Numénius et ceux qui l''avaient accompagné, avec des lettres adressées aux rois et aux pays; en voici la teneur:'),
('1m',15,16,'crampon1923','« Lucius, consul des Romains, au roi Ptolémée, salut!'),
('1m',15,17,'crampon1923','Les ambassadeurs des Juifs se sont rendus auprès de nous comme nos amis et nos alliés, pour renouveler l''ancienne amitié et alliance, ayant été envoyés par le grand prêtre Simon et par le peuple juif.'),
('1m',15,18,'crampon1923','Ils ont apporté un bouclier d''or de mille mines.'),
('1m',15,19,'crampon1923','C''est pourquoi il nous a semblé bon d''écrire aux rois et aux pays de ne pas leur causer de dommage, de n''attaquer ni eux, ni leurs villes, ni leur pays, et de ne pas prêter assistance à ceux qui leur feraient la guerre.'),
('1m',15,20,'crampon1923','Il nous a semblé bon de recevoir d''eux le bouclier.'),
('1m',15,21,'crampon1923','Si donc des hommes pervers se sont enfuis de leur pays dans le vôtre, livrez-les au grand prêtre Simon pour qu''il les châtie selon leur loi. »'),
('1m',15,22,'crampon1923','La même lettre fut adressée au roi Démétrius, à Attale, à Ariarathe et à Arsace,'),
('1m',15,23,'crampon1923','ainsi qu''à tous les pays: à Lampsaque, aux Spartiates, à Délos, à Mynde, à Sicyone, à la Carie, à Samos, à la Pamphylie, à la Lycie, à Halicarnasse, à Rhodes, à Phasélis, à Cos, à Side, à Aradus, à Gortyne, à Cnide, à Chypre et à Cyrène.'),
('1m',15,24,'crampon1923','Ils firent une copie de cette lettre pour Simon, le grand prêtre.'),
('1m',15,25,'crampon1923','Le roi Antiochus attaqua Dora le second jour, faisant approcher ses troupes toujours de plus en plus près, et construisant des machines; et il enferma Tryphon, de manière qu''on ne pouvait ni entrer ni sortir.'),
('1m',15,26,'crampon1923','Alors Simon lui envoya un secours de deux mille hommes d''élite, ainsi que de l''argent, de l''or et un appareil considérable.'),
('1m',15,27,'crampon1923','Le roi ne voulut pas les recevoir, mais il révoqua tous les engagements antérieurs qu''il avait pris vis-à-vis de Simon et il se retira de lui.'),
('1m',15,28,'crampon1923','Il lui envoya Athénobius, un de ses amis, pour s''aboucher avec lui et lui dire: " Vous occupez Joppé, Gazara et la citadelle de Jérusalem, qui sont des villes de mon royaume.'),
('1m',15,29,'crampon1923','Vous avez dévasté leurs environs, faisant un grand ravage dans le pays, et vous vous êtes rendus maîtres de beaucoup de lieux qui font partie de mes états.'),
('1m',15,30,'crampon1923','Maintenant donc, livrez-nous les villes dont vous vous êtes emparés et les tributs des localités dont vous vous êtes rendus maîtres, en dehors du territoire de la Judée.'),
('1m',15,31,'crampon1923','Sinon, donnez à la place cinq cents talents d''argent, et, pour les dévastations que vous avez commises et pour les tributs dus par ces villes, cinq cents autres talents: faute de quoi nous irons vous faire la guerre. "'),
('1m',15,32,'crampon1923','Athénobius, ami du roi, étant arrivé à Jérusalem, vit la magnificence de Simon, un buffet couvert de vases d''or et d''argent, et la grande pompe dont il était entouré; il en fut stupéfait et il répéta les paroles du roi.'),
('1m',15,33,'crampon1923','Simon lui répondit: " Ce n''est point une terre étrangère que nous avons prise, ni des biens d''autrui dont nous nous sommes emparés; mais c''est l''héritage de nos pères, qui avait été pendant quelque temps injustement possédé par nos ennemis.'),
('1m',15,34,'crampon1923','Pour nous, trouvant l''occasion favorable, nous revendiquons l''héritage de nos pères.'),
('1m',15,35,'crampon1923','Quant à Joppé et à Gazara que tu réclames, ces deux villes faisaient beaucoup de mal à notre peuple et dans notre pays; nous donnerons pour elles cent talents. " Athénobius ne lui répondit pas un mot,'),
('1m',15,36,'crampon1923','mais il s''en retourna irrité vers le roi, et lui rapporta la réponse de Simon, la magnificence de sa cour et tout ce qu''il avait vu; ce qui jeta le roi dans une grande colère.'),
('1m',15,37,'crampon1923','Or, Tryphon s''enfuit sur un navire à Orthosias.'),
('1m',15,38,'crampon1923','Le roi nomma Cendébée commandant du littoral, et lui donna une armée de fantassins et de cavaliers.'),
('1m',15,39,'crampon1923','Et il lui ordonna d''établir son camp en face de la Judée, de fortifier Gédor, d''en assurer les portes et de guerroyer contre le peuple. Le roi cependant poursuivait Tryphon.'),
('1m',15,40,'crampon1923','Cendébée, s''étant rendu à Jamnia, commença à irriter le peuple, à envahir la Judée, à faire des prisonniers et à massacrer. Il fortifia Gédor'),
('1m',15,41,'crampon1923','et il y mit des cavaliers et des troupes de pied, pour faire des sorties et infester les chemins de la Judée, comme le roi le lui avait commandé.'),
('1m',16,1,'crampon1923','Jean monta de Gazara et vint annoncer à son père ce que faisait Cendébée.'),
('1m',16,2,'crampon1923','Simon appela ses deux fils aînés, Judas et Jean, et leur dit: " Mes frères et moi, et la maison de mon père, avons combattu les ennemis d''Israël depuis notre jeunesse jusqu''à ce jour, et nous avons souvent réussi par nos mains à sauver Israël.'),
('1m',16,3,'crampon1923','Maintenant je suis devenu vieux, et vous, par la grâce divine, vous avez assez d''années; prenez ma place et celle de mon frère; allez combattre pour notre nation, et que le secours du ciel soit avec vous! "'),
('1m',16,4,'crampon1923','Puis il choisit dans le pays vingt mille combattants et des cavaliers, qui se mirent en marche contre Cendébée; ils campèrent la nuit à Modin.'),
('1m',16,5,'crampon1923','S''étant levés le matin, ils s''avancèrent vers la plaine, et voici qu''une nombreuse armée de fantassins et de cavaliers vint à leur rencontre; le lit d''un torrent les séparait.'),
('1m',16,6,'crampon1923','Jean avec ses hommes établit son camp en face d''eux. S''apercevant que ses troupes tremblaient de traverser le torrent, il le franchit le premier; ce qu''ayant vu, ses guerriers le passèrent après lui.'),
('1m',16,7,'crampon1923','Il partagea son armée en deux corps, rangeant les cavaliers entre les fantassins; or la cavalerie des ennemis était fort nombreuse.'),
('1m',16,8,'crampon1923','Ils firent retentir les trompettes, et Cendébée fut mis en fuite avec son armée; beaucoup tombèrent frappés à mort, et le reste chercha un refuge dans la forteresse.'),
('1m',16,9,'crampon1923','Alors Judas, frère de jean, fut blessé; mais Jean poursuivit les fuyards jusqu''à ce qu''il arriva à Gédor, que Cendébée avait fortifié.'),
('1m',16,10,'crampon1923','Les vaincus s''enfuirent jusqu''aux tours qui sont dans les champs d''Azot, et il livra la ville au feu. Deux mille d''entre eux périrent, et Jean retourna en paix dans la Judée.'),
('1m',16,11,'crampon1923','Ptolémée, fils d''Abobus, avait été établi gouverneur militaire de la plaine de Jéricho; il possédait beaucoup d''or et d''argent,'),
('1m',16,12,'crampon1923','car il était gendre du grand prêtre.'),
('1m',16,13,'crampon1923','Son cœur s''enorgueillit; il aspira à se rendre maître du pays, et il méditait des desseins perfides contre Simon et ses fils, pour les perdre.'),
('1m',16,14,'crampon1923','Or Simon, qui inspectait les villes de Judée, s''occupant avec sollicitude de leur bien-être, descendit à Jéricho, lui, Mathathias son fils, et Judas, l''an cent soixante-dix-sept, au onzième mois; c''est le mois de Sabat.'),
('1m',16,15,'crampon1923','Le fils d''Abobus les reçut par ruse dans une petite forteresse, nommée Doch, qu''il avait fait construire; il leur prépara un grand festin et y tint des hommes cachés.'),
('1m',16,16,'crampon1923','Lorsque Simon fut ivre, ainsi que ses fils, Ptolémée se leva avec ses hommes, et, saisissant leurs armes, ils se précipitèrent sur Simon, dans la salle du festin, et le massacrèrent avec ses deux fils et quelques serviteurs.'),
('1m',16,17,'crampon1923','Il commit ainsi une grande trahison et rendit le mal pour le bien.'),
('1m',16,18,'crampon1923','Aussitôt Ptolémée écrivit au roi pour l''informer de l''événement, et lui demander d''envoyer des troupes à son aide, afin qu''il lui livrât le pays et les villes des Juifs.'),
('1m',16,19,'crampon1923','Il dépêcha d''autres émissaires à Gazara pour tuer Jean, et expédia des lettres aux généraux, les convoquant près de lui, pour leur donner de l''argent, de l''or et des présents.'),
('1m',16,20,'crampon1923','Il en envoya d''autres encore pour occuper Jérusalem et la montagne du temple.'),
('1m',16,21,'crampon1923','Mais un messager, ayant pris les devants, vint annoncer à Jean, dans Gazara, le meurtre de son père et de ses frères, et il ajouta; " Il a aussi envoyé des assassins pour te tuer ".'),
('1m',16,22,'crampon1923','A cette nouvelle, Jean fut tout bouleversé; il se saisit des hommes qui venaient pour le tuer et il les fit mourir; car il reconnut qu''ils avaient l''intention de le tuer.'),
('1m',16,23,'crampon1923','Le reste de l''histoire de Jean, de ses guerres, des exploits qu''il accomplit, des murailles qu''il fit construire et de toutes ses actions,'),
('1m',16,24,'crampon1923','voici que tout cela est écrit dans les Annales de sa souveraine sacrificature, à partir du jour où il devint grand prêtre après son père.'),
('2m',1,1,'crampon1923','A leurs frères, aux Juifs qui sont en Egypte, salut! Les Juifs, leurs frères, qui sont à Jérusalem et dans le pays de Juda souhaitent une heureuse paix!'),
('2m',1,2,'crampon1923','Que Dieu vous fasse du bien et qu''il se souvienne de son alliance avec Abraham, Isaac et Jacob, ses fidèles serviteurs!'),
('2m',1,3,'crampon1923','Qu''il vous donne à tous un cœur pour l''adorer et accomplir ses volontés de grand cœur et de bon gré!')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('2m',1,4,'crampon1923','Qu''il ouvre votre cœur à sa loi et à ses préceptes, et qu''il y fasse la paix!'),
('2m',1,5,'crampon1923','Qu''il exauce vos prières et se réconcilie avec vous, et qu''il ne vous délaisse pas au temps du malheur!'),
('2m',1,6,'crampon1923','Et maintenant, nous sommes ici priant pour vous.'),
('2m',1,7,'crampon1923','Sous le règne de Démétrius, en l''an cent soixante-neuf, nous, les Juifs, vous avions écrit, alors que nous étions dans la plus extrême détresse, survenue pendant ces années, depuis que Jason et ses partisans eurent trahi la cause de la terre sainte et du royaume.'),
('2m',1,8,'crampon1923','On avait brûlé la porte du temple et répandu le sang innocent. Alors nous avons prié le Seigneur, et nous avons été exaucés; nous avons offert le sacrifice et la fleur de farine; nous avons allumé les lampes et exposé les pains.'),
('2m',1,9,'crampon1923','Maintenant nous vous écrivons encore pour que vous célébriez les jours de la fête des Tabernacles du mois de Casleu.'),
('2m',1,10,'crampon1923','En l''année cent quatre-vingt-huit. Ceux de Jérusalem et de la Judée, le Sénat et Judas, à Aristobule, conseiller du roi Ptolémée, de la famille des prêtres consacrés, et aux Juifs qui sont en Egypte, salut et prospérité!'),
('2m',1,11,'crampon1923','Sauvés par Dieu de grands périls, nous lui rendons de grandes actions de grâces, nous qui sommes prêts à combattre contre le roi.'),
('2m',1,12,'crampon1923','Car Dieu même a rejeté ceux qui s''étaient rangés en bataille contre la ville sainte.'),
('2m',1,13,'crampon1923','En effet, le chef ennemi s''étant rendu en Perse à la tête d''une armée qui paraissait invincible, ils furent frappés dans le sanctuaire de Nanée, grâce à la ruse des prêtres de Nanée.'),
('2m',1,14,'crampon1923','Antiochus vint en ce lieu avec ses amis sous prétexte d''épouser la déesse, dans le but de s''emparer des trésors à titre de dot.'),
('2m',1,15,'crampon1923','Les prêtres de Nanée les exposèrent, et lui-même entra avec un petit nombre de ses gens dans l''enceinte sacrée.'),
('2m',1,16,'crampon1923','Dès qu''Antiochus fut entré, ils fermèrent le temple et, ayant ouvert la porte secrète du plafond, ils lancèrent des pierres, assommèrent le chef et ceux qui étaient avec lui, les coupèrent en morceaux et jetèrent leurs têtes à ceux qui étaient dehors.'),
('2m',1,17,'crampon1923','Que notre Dieu soit béni en toutes choses, lui qui a livré à la mort les impies!'),
('2m',1,18,'crampon1923','Devant donc célébrer au vingt-cinquième jour du mois de Casleu la purification du temple, nous avons cru nécessaire de vous en informer, afin que vous aussi, vous célébriez les jours de la fête des Tabernacles, et celui du feu qui s''alluma lorsque Néhémie, après avoir reconstruit le temple et l''autel, offrit des sacrifices.'),
('2m',1,19,'crampon1923','Car, lorsque nos pères furent emmenés en Perse, les prêtres pieux de ce temps-là, ayant pris du feu de l''autel, le cachèrent en secret dans le creux d''un puits desséché, et ils l''y mirent si bien en sûreté, que ce lieu demeura ignoré de tous.'),
('2m',1,20,'crampon1923','Après beaucoup d''années écoulées, lorsque tel fut le bon plaisir de Dieu, Néhémie, renvoyé en Judée par le roi de Perse, fit rechercher le feu par les descendants des prêtres qui l''avaient caché; mais, comme ils nous racontèrent qu''ils n''avaient pas trouvé de feu, mais une eau épaisse,'),
('2m',1,21,'crampon1923','il leur dit d''en puiser, et de lui en apporter; puis, quand on eut mis sur l''autel les choses nécessaires au sacrifice, Néhémie ordonna aux prêtres d''asperger de cette eau le bois et ce qui était dessus.'),
('2m',1,22,'crampon1923','Cet ordre ayant été exécuté, et le moment étant venu où le soleil, jusque-là couvert de nuages, resplendit, un grand brasier s''alluma, en sorte que tous furent dans l''admiration.'),
('2m',1,23,'crampon1923','Pendant que se consumaient les victimes, les prêtres firent une prière, et avec eux tous les assistants; ce fut Jonathan qui commença, et les autres unirent leurs voix à la sienne,'),
('2m',1,24,'crampon1923','ainsi que Néhémie. Cette prière était ainsi conçue: " Seigneur, Seigneur, Dieu, créateur de toutes choses, terrible et fort, juste et compatissant, qui êtes seul roi et bon,'),
('2m',1,25,'crampon1923','seul libéral et seul juste, tout-puissant et éternel, qui délivrez Israël de tout mal, qui avez fait de nos pères vos élus et les avez sanctifiés,'),
('2m',1,26,'crampon1923','recevez ce sacrifice pour tout votre peuple d''Israël; gardez votre héritage et sanctifiez-le.'),
('2m',1,27,'crampon1923','Rassemblez ceux d''entre nous qui sont dispersés, délivrez ceux qui sont esclaves parmi les nations, jetez un regard favorable sur ceux qui sont méprisés et en abomination, afin que les nations sachent que vous êtes notre Dieu.'),
('2m',1,28,'crampon1923','Châtiez ceux qui nous oppriment et qui nous outragent avec insolence.'),
('2m',1,29,'crampon1923','Implantez votre peuple dans votre lieu saint, comme l''a dit Moïse. " —'),
('2m',1,30,'crampon1923','En outre, les prêtres chantaient les hymnes.'),
('2m',1,31,'crampon1923','Quand le sacrifice fut consommé, Néhémie fit répandre le reste de l''eau sur de grandes pierres.'),
('2m',1,32,'crampon1923','Cela fait, une flamme s''y alluma et le liquide, ayant reçu les rayons lumineux qui partaient de l''autel, fut consumé.'),
('2m',1,33,'crampon1923','Le bruit de cet événement s''étant répandu, on informa le roi des Perses que, à l''endroit où les prêtres emmenés captifs avaient caché le feu sacré, l''eau avait été trouvée, et que Néhémie et ses gens avaient sanctifié par elle les sacrifices.'),
('2m',1,34,'crampon1923','Alors le roi fit enclore ce lieu et le rendit sacré, certifiant ainsi l''événement.'),
('2m',1,35,'crampon1923','Et à ceux qui étaient l''objet de sa bienveillance, il distribuait des présents nombreux et variés.'),
('2m',1,36,'crampon1923','Or, les compagnons de Néhémie appelèrent ce lieu NEPHTHAR, c''est-à-dire purification, mais la plupart le nomment NEPHTHAÏ.'),
('2m',2,1,'crampon1923','On trouve dans les archives publiques que le prophète Jérémie ordonna à ceux qu''on déportait, de prendre le feu sacré, ainsi qu''il a été dit; et comment le prophète fit des recommandations aux déportés,'),
('2m',2,2,'crampon1923','en leur remettant un exemplaire de la loi, afin qu''ils n''oubliassent pas les préceptes du Seigneur, et qu''ils ne s''égarassent pas dans leurs pensées en voyant des idoles d''or et d''argent et les ornements dont elles étaient revêtues.'),
('2m',2,3,'crampon1923','Entre autres discours de ce genre qu''il leur tint, il les exhorta à n''éloigner jamais la loi de leur cœur.'),
('2m',2,4,'crampon1923','On lisait dans les mêmes écrits comment le prophète, sur un ordre reçu de Dieu, fit transporter avec lui le tabernacle et l''arche, et qu''il se rendit ainsi à la montagne que gravit Moïse et d''où il contempla l''héritage de Dieu.'),
('2m',2,5,'crampon1923','Arrivé là, Jérémie trouva une habitation en forme d''antre, et il y déposa le tabernacle et l''arche, ainsi que l''autel des parfums, et en boucha l''entrée.'),
('2m',2,6,'crampon1923','Quelques-uns de ses compagnons étant venus ensuite pour marquer le chemin par des signes, ils ne purent le trouver.'),
('2m',2,7,'crampon1923','Jérémie le sut et il les blâma: " Ce lieu, leur dit-il, doit rester caché jusqu''à ce que Dieu ait rassemblé son peuple et lui ait fait miséricorde.'),
('2m',2,8,'crampon1923','Alors le Seigneur révélera ces objets sacrés, la gloire du Seigneur apparaîtra, ainsi que la nuée, comme elle apparut au temps de Moïse, et lorsque Salomon fit une prière pour que le temple fût glorieusement sanctifié. "'),
('2m',2,9,'crampon1923','Il était encore raconté dans ces écrits que ce roi, possédant la sagesse, offrît le sacrifice de la dédicace et de l''achèvement du sanctuaire.'),
('2m',2,10,'crampon1923','Et comme Moïse pria le Seigneur et qu''un feu tomba du ciel et consuma le sacrifice, ainsi Salomon pria, et le feu descendit et consuma les holocaustes.'),
('2m',2,11,'crampon1923','Moïse dit: " Parce que la victime pour le péché n''a pas été mangée, elle a été consumée. "'),
('2m',2,12,'crampon1923','Et Salomon célébra pareillement les huit jours de la dédicace.'),
('2m',2,13,'crampon1923','Ces mêmes choses se trouvent donc racontées dans les archives, et dans les mémoires de Néhémie; on y voit encore comment Néhémie fonda une bibliothèque et y recueillit les livres concernant les rois et les prophètes, ceux de David, et les lettres des rois de Perse au sujet de leurs présents.'),
('2m',2,14,'crampon1923','De même Judas a recueilli tous les livres qui avaient été dispersés pendant la guerre que nous avons eu à soutenir, et ils sont entre nos mains.'),
('2m',2,15,'crampon1923','Si donc vous avez besoin d''en avoir des exemplaires, envoyez-nous des messagers qui vous les porteront.'),
('2m',2,16,'crampon1923','C''est pourquoi, comme nous allons célébrer la fête de la purification, nous vous adressons cette lettre; vous ferez donc bien de solenniser ces jours avec nous.'),
('2m',2,17,'crampon1923','Dieu, qui a délivré tout son peuple et a rendu à tous l''héritage, le royaume, le sacerdoce et la sanctification,'),
('2m',2,18,'crampon1923','comme il l''a annoncé par la loi, aura bientôt, nous l''espérons, pitié de nous et nous rassemblera, de toutes les régions qui sont sous le ciel, dans le saint lieu;'),
('2m',2,19,'crampon1923','car il nous a arrachés à de grands maux et il a purifié le temple.'),
('2m',2,20,'crampon1923','L''histoire de Judas Machabée et de ses frères, la purification du temple auguste et la dédicace de l''autel;'),
('2m',2,21,'crampon1923','comme aussi les combats livrés, contre Antiochus Epiphane et son fils Eupator;'),
('2m',2,22,'crampon1923','les interventions éclatantes du ciel en faveur de ceux qui ont glorieusement combattu pour la défense du judaïsme, de telle sorte que, malgré leur petit nombre, ils ont reconquis tout le pays et mis en fuite une multitude de barbares,'),
('2m',2,23,'crampon1923','recouvré le sanctuaire célèbre dans tout l''univers, délivré la ville et rétabli les lois qu''on tentait d''abolir, le Seigneur les ayant favorisés de toute sa bienveillance:'),
('2m',2,24,'crampon1923','tous ces faits exposés par Jason de Cyrène en cinq livres, nous allons essayer de les résumer en un seul.'),
('2m',2,25,'crampon1923','Considérant la masse de chiffres qu''ils renferment, et la difficulté qui existe pour ceux qui veulent suivre dans les détails les récits de l''histoire, par suite de l''abondance de la matière,'),
('2m',2,26,'crampon1923','nous nous sommes appliqués à rendre la tache agréable à ceux qui se contentent d''une simple lecture, facile à ceux qui ont à cœur de confier les faits à leur mémoire, et profitable à tous indistinctement.'),
('2m',2,27,'crampon1923','Pour nous, qui avons entrepris ce travail d''abréviation, ce n''est pas une chose aisée, mais un labeur exigeant des sueurs et des veilles,'),
('2m',2,28,'crampon1923','labeur non moins difficile que celui de l''ordonnateur d''un festin, qui cherche à procurer l''avantage des autres. Cependant, pour mériter la reconnaissance de plusieurs, nous prendrons sur nous avec plaisir cette lourde tâche,'),
('2m',2,29,'crampon1923','laissant à l''auteur le soin de traiter exactement chaque chose, pour nous efforcer de suivre les règles du résumé.'),
('2m',2,30,'crampon1923','Or, de même que l''architecte d''une maison nouvelle doit embrasser dans sa pensée tout l''ensemble de la construction, tandis que celui qui se charge de la décorer et d''y peindre des figures doit se préoccuper de ce qui regarde l''ornementation, ainsi, je pense, en est-il pour nous.'),
('2m',2,31,'crampon1923','Approfondir le sujet, rendre compte de toutes choses, se donner de la peine pour les moindres détails, voilà le devoir de celui qui compose une histoire;'),
('2m',2,32,'crampon1923','mais à celui dont tout le dessein est d''en rédiger un abrégé, il faut accorder de ne poursuivre que la brièveté dans les récits, sans s''attacher à une exposition complète des faits. Commençons donc ici notre relation, sans rien ajouter à ce qui vient d''être dit; ce serait folie que de se montrer diffus avant de raconter l''histoire, et concis dans l''histoire elle-même.'),
('2m',3,1,'crampon1923','Pendant que les habitants de la ville sainte jouissaient d''une paix entière, et que les lois étaient encore exactement observées, grâce à la piété du grand prêtre Onias et à sa haine du mal,'),
('2m',3,2,'crampon1923','il arrivait que les rois eux-mêmes honoraient le saint lieu et ornaient le temple de dons magnifiques,'),
('2m',3,3,'crampon1923','au point que Séleucus, roi d''Asie, fournissait de son revenu toute la dépense nécessaire au service des sacrifices.'),
('2m',3,4,'crampon1923','Mais un certain Simon de la tribu de Benjamin, constitué administrateur du temple, entra en lutte avec le grand prêtre au sujet de l''intendance du marché de la ville.'),
('2m',3,5,'crampon1923','Comme il ne pouvait l''emporter sur Onias, il alla trouver Apollonius, fils de Thrasée, le gouverneur militaire, à cette époque, de la Cœlé-Syrie et de la Phénicie.'),
('2m',3,6,'crampon1923','Il lui rapporta que le trésor sacré de Jérusalem était rempli de sommes énormes, d''une quantité incalculable de richesses, nullement en rapport avec la dépense nécessaire pour les sacrifices, et qu''il était possible de faire passer tout ce trésor entre les mains du roi.'),
('2m',3,7,'crampon1923','Dans un entretien avec le roi, Apollonius lui donna avis des richesses qu''on lui avait signalées, et celui-ci choisit Héliodore, qui était préposé aux affaires de l''Etat et l''envoya avec ordre d''exécuter l''enlèvement des susdites richesses.'),
('2m',3,8,'crampon1923','Héliodore se mit aussitôt en route, sous le prétexte d''inspecter les villes de Cœlé-Syrie et de Phénicie mais en réalité pour exécuter le dessein du roi.'),
('2m',3,9,'crampon1923','Arrivé à Jérusalem, Héliodore fut reçu amicalement par le grand prêtre de la ville; puis il raconta ce qu''on lui avait appris et exposa le but de sa présence, en demandant si vraiment les choses étaient ainsi.'),
('2m',3,10,'crampon1923','Alors le grand prêtre lui représenta que le trésor renfermait les dépôts des veuves et des orphelins;'),
('2m',3,11,'crampon1923','qu''une partie de l''argent appartenait à Hircan, fils de Tobie, homme très considérable; que la situation n''était pas ce que disait le calomniateur impie, Simon, mais que toutes ces richesses se réduisaient à quatre cents talents d''argent et deux cents talents d''or;'),
('2m',3,12,'crampon1923','que d''ailleurs il était tout à fait impossible de dépouiller ceux qui s''étaient confiés à la sainteté de ce lieu, à la majesté inviolable d''un temple vénéré dans tout l''univers.'),
('2m',3,13,'crampon1923','Mais lui, en vertu des ordres qu''il avait reçus du roi, soutenait absolument que cet argent devait être porté dans le trésor royal.'),
('2m',3,14,'crampon1923','Ayant donc fixé un jour, il allait entrer pour inspecter ces richesses avant d''en disposer, ce qui causa dans la ville entière une grande perturbation.'),
('2m',3,15,'crampon1923','Les prêtres se prosternèrent devant l''autel, revêtus de leurs habits sacerdotaux, et, se tournant vers le ciel, ils priaient Celui qui avait fait la loi sur les dépôts de conserver ces biens intacts à ceux qui les avaient déposés.'),
('2m',3,16,'crampon1923','En voyant le visage du grand Prêtre, on se sentait blessé jusqu''au plus intime de l''âme; car sa figure et l''altération de son teint attestaient l''agonie de son âme.'),
('2m',3,17,'crampon1923','La consternation peinte dans toute sa personne et le frisson de son corps révélaient à tous les regards l''affliction de son cœur.'),
('2m',3,18,'crampon1923','Les habitants se précipitaient par troupes hors de leurs maisons et priaient tous ensemble pour que le saint lieu ne fût pas livré à l''opprobre.'),
('2m',3,19,'crampon1923','Les femmes, la poitrine couverte de sacs, remplissaient les rues; celles des jeunes filles qui étaient renfermées, couraient les unes aux portes, les autres vers les murailles; quelques-unes regardaient par les fenêtres;'),
('2m',3,20,'crampon1923','toutes, les mains étendues vers le ciel, faisaient entendre des supplications.'),
('2m',3,21,'crampon1923','L''abattement de cette foule confuse et l''attente pleine d''angoisse du grand prêtre excitaient la pitié.'),
('2m',3,22,'crampon1923','Pendant que les Juifs suppliaient le Seigneur Tout-Puissant de garder intacts, en toute sûreté, les dépôts à ceux qui les avaient confiés,'),
('2m',3,23,'crampon1923','Héliodore exécutait son dessein. Déjà il était là avec ses satellites près du trésor,'),
('2m',3,24,'crampon1923','lorsque le Seigneur des esprits, le Dominateur de toute puissance, fit une grande manifestation, de sorte que tous ceux qui avaient osé venir là, atteints par la force de Dieu, furent frappés d''impuissance et d''épouvante.'),
('2m',3,25,'crampon1923','A leurs yeux apparut un cheval monté par un cavalier terrible, et richement caparaçonné; s''élançant avec impétuosité, il agita sur Héliodore ses pieds de devant; le cavalier paraissait avoir une armure d''or.'),
('2m',3,26,'crampon1923','En même temps, lui apparurent deux autres jeunes hommes, pleins de force, brillants d''un vif éclat et vêtus d''habits magnifiques; s''étant placés l''un d''un côté, l''autre de l''autre, ils le flagellaient sans relâche, lui portant une multitude de coups.'),
('2m',3,27,'crampon1923','Héliodore tomba subitement par terre, environné de profondes ténèbres; on le ramassa, pour le mettre dans une litière;'),
('2m',3,28,'crampon1923','et cet homme qui venait d''entrer dans la chambre du susdit trésor avec une suite nombreuse de coureurs et de satellites armés, on l''emporta incapable de s''aider lui-même et ayant visiblement éprouvé la puissance de Dieu.'),
('2m',3,29,'crampon1923','Pendant qu''il était là, sous le coup de la force divine, étendu muet, privé de toute espérance et de tout secours,'),
('2m',3,30,'crampon1923','les Juifs bénissaient le Seigneur qui avait glorifié son saint lieu, et le temple, qui était un instant auparavant plein d''épouvante et de trouble, fut, grâce à la manifestation du Seigneur tout-puissant, rempli de joie et d''allégresse.'),
('2m',3,31,'crampon1923','Aussitôt quelques-uns des compagnons d''Héliodore demandèrent à Onias de prier le Très-Haut et d''accorder la vie à celui qui gisait n''ayant plus qu''un souffle.'),
('2m',3,32,'crampon1923','Et le grand prêtre, dans la crainte que le roi ne s''imaginât qu''un attentat avait été commis par les Juifs contre Héliodore, offrit pour la vie de cet homme un sacrifice.'),
('2m',3,33,'crampon1923','Pendant que le grand prêtre offrait le sacrifice expiatoire, les mêmes jeunes hommes apparurent de nouveau à Héliodore, revêtus des mêmes habits et, se tenant debout, lui dirent: " Rends de grandes actions de grâces au grand prêtre Onias, car c''est à cause de lui que le Seigneur te donne la vie sauve.'),
('2m',3,34,'crampon1923','Pour toi, ainsi châtié par lui, annonce à tous la grande puissance de Dieu. " Ayant dit ces mots, ils disparurent.'),
('2m',3,35,'crampon1923','Héliodore offrit au Seigneur un sacrifice et fit de grands vœux à Celui qui lui avait accordé la vie; puis, ayant assuré Onias de son amitié, il retourna avec ses troupes vers le roi.'),
('2m',3,36,'crampon1923','Et il rendait témoignage à tous des œuvres du grand Dieu qu''il avait vues de ses yeux.'),
('2m',3,37,'crampon1923','Le roi ayant demandé à Héliodore quel homme lui paraissait propre à être envoyé de nouveau à Jérusalem, celui-ci lui répondit:'),
('2m',3,38,'crampon1923','" Si tu as quelque ennemi ou un adversaire de ton gouvernement, envoie-le là-bas, et il te reviendra déchiré de coups, si toutefois il en réchappe, car il y a vraiment en ce lieu une force divine.'),
('2m',3,39,'crampon1923','Celui qui a sa demeure dans le ciel veille sur ce lieu et le protège; ceux qui y viennent avec de mauvais desseins, il les frappe et les fait périr. "'),
('2m',3,40,'crampon1923','C''est ainsi que se passèrent les choses concernant Héliodore et la conservation du trésor sacré.'),
('2m',4,1,'crampon1923','Le dit Simon, ce délateur du trésor et de sa patrie, parlait mal d''Onias: c''est lui, disait-il, qui avait excité Héliodore et qui était l''auteur de tout le mal.'),
('2m',4,2,'crampon1923','Le bienfaiteur de la ville, le défenseur de ses concitoyens et l''observateur fidèle des lois, il osait le faire passer pour un adversaire de l''Etat.'),
('2m',4,3,'crampon1923','Cette haine alla si loin que des meurtres furent commis par l''un des affidés de Simon.'),
('2m',4,4,'crampon1923','Alors Onias, considérant le danger de ces divisions et les emportements d''Apollonius, le gouverneur militaire de la Cœlé-Syrie et de la Phénicie, qui encourageait la méchanceté de Simon, alla trouver le roi,'),
('2m',4,5,'crampon1923','non pour accuser ses concitoyens, mais ayant en vue l''intérêt général et particulier de tout son peuple.'),
('2m',4,6,'crampon1923','Car il voyait bien que, sans l''intervention du roi, il était impossible de pacifier la situation, et que Simon ne renoncerait pas à ses criminelles entreprises.'),
('2m',4,7,'crampon1923','Mais, après la mort de Séleucus, Antiochus surnommé Epiphane lui ayant succédé, Jason, frère d''Onias, entreprit d''usurper le souverain pontificat.'),
('2m',4,8,'crampon1923','Dans un entretien avec le roi, il lui promit trois cent soixante talents d''argent et quatre-vingts talents pris sur d''autres revenus.'),
('2m',4,9,'crampon1923','Il promettait en outre de s''engager par écrit pour cent cinquante autres talents, si on lui accordait d''établir, de sa propre autorité et selon ses vues, un gymnase avec un éphébée, et d''inscrire les habitants de Jérusalem comme citoyens d''Antioche.'),
('2m',4,10,'crampon1923','Le roi consentit à tout. Dès que Jason eut obtenu le pouvoir, il se mit à introduire les mœurs grecques parmi ses concitoyens.'),
('2m',4,11,'crampon1923','Il abolit les franchises que les rois, par humanité, avaient accordées aux Juifs grâce à l''entreprise de Jean, père d''Eupolème, lequel fut envoyé en ambassade pour conclure un traité d''alliance et d''amitié avec les Romains, et, détruisant les institutions légitimes, il établit des coutumes contraires à la loi.'),
('2m',4,12,'crampon1923','Il se fit un plaisir de fonder un gymnase au pied même de l''Acropole, et il élevait les enfants les plus nobles en les mettant sous le chapeau.'),
('2m',4,13,'crampon1923','L''hellénisme grandit alors à un tel point, et l''on vit un tel entraînement vers les coutumes étrangères, par suite de l''excessive perversité de Jason, homme impie et nullement grand prêtre,'),
('2m',4,14,'crampon1923','que les prêtres ne montraient plus aucun zèle pour le service de l''autel et que, méprisant le temple et négligeant les sacrifices, ils s''empressaient de prendre part, dans la palestre, aux exercices proscrits par la loi, dès que l''appel à lancer le disque s''était fait entendre.'),
('2m',4,15,'crampon1923','Ne faisant aucun cas des fonctions honorifiques de leur pays, ils tenaient en haute estime les distinctions des Grecs.'),
('2m',4,16,'crampon1923','C''est pourquoi de graves calamités les atteignirent, et dans ceux-là même dont ils imitaient le genre de vie et auxquels ils voulaient ressembler en tout, ils trouvèrent des ennemis et des oppresseurs.'),
('2m',4,17,'crampon1923','Car on ne viole pas impunément les lois divines; mais c''est ce que démontrera la suite des événements.'),
('2m',4,18,'crampon1923','Pendant qu''on célébrait à Tyr les jeux quinquennaux, auxquels le roi assistait,'),
('2m',4,19,'crampon1923','le criminel Jason envoya de Jérusalem des spectateurs, qui étaient citoyens d''Antioche, porteurs de trois cents drachmes d''argent pour le sacrifice d''Hercule; mais ceux-là même qui les portaient demandèrent que cet argent fût employé, non à des sacrifices, ce qui ne convenait pas, mais à couvrir d''autres dépenses.'),
('2m',4,20,'crampon1923','Ainsi les trois cents drachmes étaient bien destinées par celui qui les envoyait au sacrifice en l''honneur d''Hercule; mais elles servirent, selon le désir de ceux qui les apportaient, à la construction de trirèmes.'),
('2m',4,21,'crampon1923','Apollonius, fils de Ménesthée, ayant été envoyé en Egypte, à l''occasion de l''intronisation du roi Ptolémée Philométor, Antiochus apprit que ce roi était mal disposé à son égard et, voulant se mettre en sûreté vis-à-vis de lui, il se rendit à Joppé, puis à Jérusalem.'),
('2m',4,22,'crampon1923','Reçu magnifiquement par Jason et par toute la ville, il fit son entrée à la lumière des flambeaux et au milieu des acclamations; puis il conduisit pareillement son armée en Phénicie.'),
('2m',4,23,'crampon1923','Trois ans s''étant écoulés, Jason envoya Ménélas, frère de Simon mentionné plus haut, pour porter l''argent au roi et acquitter les droits d''enregistrement d''affaires importantes.'),
('2m',4,24,'crampon1923','Mais Ménélas se recommanda au roi, lui rendit honneur avec les dehors d''un homme haut placé et se fit adjuger à lui-même le souverain pontificat, en offrant trois cents talents d''argent de plus que n''avait fait Jason.'),
('2m',4,25,'crampon1923','Ayant reçu du roi ses lettres d''investiture, il revint à Jérusalem, n''ayant rien qui fût digne du sacerdoce et n''apportant que les instincts d''un tyran cruel et la fureur d''une bête sauvage.'),
('2m',4,26,'crampon1923','Ainsi Jason, qui avait trompé son propre frère, trompé à son tour par un autre, dut gagner en fugitif le pays des Ammonites.'),
('2m',4,27,'crampon1923','Quant à Ménélas, il obtint le pouvoir; mais, comme il ne s''exécutait pas relativement à la somme promise au roi, malgré les réclamations de Sostrate, commandant de l''Acropole,'),
('2m',4,28,'crampon1923','qui avait dans ses attributions la perception des impôts, tous deux furent mandés auprès du roi.'),
('2m',4,29,'crampon1923','Ménélas laissa pour le remplacer comme grand prêtre son frère Lysimaque, et Sostrate laissa comme remplaçant Cratès, gouverneur de Chypre.'),
('2m',4,30,'crampon1923','Sur ces entrefaites, il arriva que les habitants de Tarse et de Mallas se révoltèrent, parce que ces deux villes avaient été données en présent à Antiochide, concubine du roi.'),
('2m',4,31,'crampon1923','Le roi partit donc en hâte pour apaiser la sédition, ayant laissé comme son lieutenant Andronique, un des grands dignitaires.'),
('2m',4,32,'crampon1923','Ménélas, jugeant les circonstances favorables, enleva du temple quelques vases d''or et les donna à Andronique, et il réussit à en vendre d''autres à Tyr et aux villes voisines.'),
('2m',4,33,'crampon1923','Lorsque Onias eut connu d''une manière certaine ce nouveau crime de Ménélas, il lui en adressa des reproches, après s''être retiré dans un lieu d''asile, a Daphné, près d''Antioche.'),
('2m',4,34,'crampon1923','C''est pourquoi Ménélas, prenant à part Andronique, le pressait de mettre à mort Onias. Andronique vint donc trouver Onias et, usant de ruse, il lui présenta la main droite avec serment; puis, quoique suspect, il le décida à sortir de son asile et le mit aussitôt à mort, sans égard pour la justice.'),
('2m',4,35,'crampon1923','Aussi, non seulement les Juifs, mais beaucoup d''entre les autres nations furent indignés et affligés du meurtre injuste de cet homme.'),
('2m',4,36,'crampon1923','Et lorsque le roi fut revenu de Cilicie, les Juifs d''Antioche, ainsi que des Grecs également ennemis de la violence, vinrent le trouver au sujet du meurtre inique d''Onias.'),
('2m',4,37,'crampon1923','Antiochus fut contristé jusqu''au fond de l''âme et, touché de compassion pour Onias, il versa des larmes au souvenir de la modération et de la conduite si sage du défunt.'),
('2m',4,38,'crampon1923','Rouge de colère, il fit enlever sur le champ la pourpre à Andronique, déchira ses vêtements et, l''ayant fait mener par toute la ville, il dégrada ce scélérat au lieu même où il avait exécuté son attentat impie sur Onias, le Seigneur le frappant ainsi d''un juste châtiment.'),
('2m',4,39,'crampon1923','Or, un grand nombre de vols sacrilèges, ayant été commis dans la ville par Lysimaque, d''accord avec Ménélas, et le bruit s''en étant répandu, le peuple s''ameuta contre Lysimaque, lorsque déjà beaucoup de vases d''or avaient été dispersés.'),
('2m',4,40,'crampon1923','Voyant la multitude soulevée et les esprits enflammés de colère, Lysimaque arma environ trois mille hommes et se mit à exercer des actes de violence, sous le commandement d''un certain Tyran, homme avancé en âge et non moins en perversité.'),
('2m',4,41,'crampon1923','Mais lorsqu''ils connurent l''attaque de Lysimaque, les uns saisissant des pierres, d''autres de gros bâtons, quelques-uns ramassant de la cendre qui se trouvait là, lançaient tumultueusement le tout sur les partisan de Lysimaque.'),
('2m',4,42,'crampon1923','C''est ainsi qu''ils blessèrent un grand nombre de ses gens, en tuèrent plusieurs, mirent tous les autres en fuite et massacrèrent le sacrilège lui-même auprès du trésor du temple.'),
('2m',4,43,'crampon1923','Puis on commença sur ces faits une instruction contre Ménélas.'),
('2m',4,44,'crampon1923','Lorsque le roi vint à Tyr, les trois hommes envoyés par les Anciens lui exposèrent la justice de leur cause.'),
('2m',4,45,'crampon1923','Se voyant convaincu, Ménélas promit à Ptolémée, fils de Dorymène, une grosse somme d''argent pour qu''il lui rendît le roi favorable.'),
('2m',4,46,'crampon1923','Ptolémée, ayant donc emmené le roi sous le péristyle, comme pour prendre le frais, le fit changer de résolution.'),
('2m',4,47,'crampon1923','Le roi déclara Ménélas innocent des accusations portées contre lui, quoiqu''il fût coupable de tous les crimes, et il condamna à mort des malheureux qui, s''ils avaient plaidé leur cause même devant des Scythes, eussent été renvoyés innocents;'),
('2m',4,48,'crampon1923','et des hommes qui avaient pris la défense de la ville, du peuple et des objets sacrés, subirent sans délai cette peine injuste.'),
('2m',4,49,'crampon1923','Les Tyriens eux-mêmes en furent indignés, et ils firent aux victimes de magnifiques funérailles.'),
('2m',4,50,'crampon1923','Quant à Ménélas, grâce à la cupidité des puissants, il se maintint dans sa dignité, grandissant en malice et cruel fléau de ses concitoyens.'),
('2m',5,1,'crampon1923','Vers ce temps-là, Antiochus organisa sa seconde expédition en Egypte.'),
('2m',5,2,'crampon1923','Or il arriva que, dans toute la ville, pendant près de quarante jours, apparurent, courant dans les airs, des cavaliers ayant des vêtements d''or et armés de lances à la manière des cohortes,'),
('2m',5,3,'crampon1923','ainsi que des escadrons de chevaux rangés en ordre de bataille, des attaques et des charges de part et d''autre, des agitations de boucliers et une multitude de piques, des épées tirées du fourreau, des traits lancés, un vif éclat d''armures d''or et de cuirasses de toutes sortes.'),
('2m',5,4,'crampon1923','C''est pourquoi tous priaient pour que ces apparitions leur fussent favorables.'),
('2m',5,5,'crampon1923','Un faux bruit de la mort d''Antiochus s''étant répandu, Jason ne prit pas moins d''un millier d''hommes et vint attaquer la ville à l''improviste. Les citoyens coururent aux murailles, mais la ville finit par être prise, et Ménélas se réfugia dans la citadelle.'),
('2m',5,6,'crampon1923','Jason se livra sans pitié au massacre de ses propres concitoyens, ne réfléchissant pas qu''une journée gagnée sur des compatriotes est la journée la plus tristement perdue, mais s''imaginant remporter des trophées sur des ennemis, et non sur des gens de la même nation.'),
('2m',5,7,'crampon1923','D''une part, il ne réussit pas à s''emparer du pouvoir, et, de l''autre, ses intrigues aboutirent pour lui à la confusion; il dut regagner en fugitif le pays des Ammonites.'),
('2m',5,8,'crampon1923','Comme terme de sa vie criminelle, on le vit serré de près chez Arétas, roi des Arabes, fuyant de ville en ville, poursuivi par tous, détesté comme transgresseur des lois, exécré comme le bourreau de sa patrie et de ses concitoyens, ignominieusement chassé jusqu''en Egypte.'),
('2m',5,9,'crampon1923','Lui qui avait banni tant de personnes de leur patrie, il périt sur la terre étrangère, après s''être rendu à Lacédémone dans l''espoir d''y trouver un refuge, en considération de la commune origine.'),
('2m',5,10,'crampon1923','Lui qui avait jeté tant d''hommes sur le sol sans sépulture, nul ne le pleura et ne lui rendit aucun des derniers devoirs; il ne fut pas enseveli dans le tombeau de ses pères.'),
('2m',5,11,'crampon1923','Ces événements étant arrivés à la connaissance du roi, il crut que la Judée faisait défection. Il partit donc d''Egypte, furieux comme une bête féroce, et s''empara de la ville à main armée.'),
('2m',5,12,'crampon1923','Il ordonna aux soldats de tuer sans pitié ceux qui tomberaient entre leurs mains, et d''égorger ceux qui monteraient sur les toits des maisons.'),
('2m',5,13,'crampon1923','Ainsi furent tués des jeunes gens et des vieillards; ainsi périrent des hommes faits, des femmes et des enfants; ainsi furent égorgés des jeunes filles et des nourrissons.'),
('2m',5,14,'crampon1923','Le nombre des victimes pendant ces trois jours, fut de quatre-vingt mille, dont quarante mille furent massacrés et autant furent vendus comme esclaves.'),
('2m',5,15,'crampon1923','Non content de ces atrocités, il osa pénétrer dans le temple le plus saint de toute la terre, ayant pour guide Ménélas, traître envers les lois et envers sa patrie.'),
('2m',5,16,'crampon1923','Et prenant de ses mains souillées les objets sacrés, et arrachant les offrandes déposées par les autres rois pour rehausser la gloire et la dignité de ce lieu, il les remettait à des mains profanes.'),
('2m',5,17,'crampon1923','Antiochus s''enflait d''orgueil dans son esprit, ne considérant pas que le Seigneur était irrité pour peu de temps à cause des péchés des habitants de la ville, et que c''était pour cela qu''il détournait ses regards de ce lieu.'),
('2m',5,18,'crampon1923','Autrement, s''ils n''avaient pas été coupables d''un grand nombre de péchés, lui aussi, comme Héliodore, envoyé par le roi Séleucus pour inspecter le trésor, il aurait été, dès son arrivée, flagellé et réprimé dans son audace.'),
('2m',5,19,'crampon1923','Mais Dieu n''a pas choisi le peuple à cause de ce lieu; il a choisi ce lieu à cause du peuple.'),
('2m',5,20,'crampon1923','C''est pourquoi ce lieu a participé aux malheurs du peuple, comme il a été ensuite associé aux bienfaits du Seigneur; délaissé dans la colère du Tout-Puissant, il a été de nouveau, quand le souverain Seigneur s''est réconcilié avec son peuple, rétabli en toute sa gloire.'),
('2m',5,21,'crampon1923','Antiochus, ayant donc enlevé au temple dix-huit cents talents, s''en retourna en hâte à Antioche, s''imaginant dans son orgueil, à cause de l''enivrement de son cœur, pouvoir rendre navigable la terre ferme et viable la mer.'),
('2m',5,22,'crampon1923','Mais il laissa des préposés pour tourmenter le peuple: à Jérusalem, Philippe, originaire de Phrygie, plus cruel encore que celui qui l''avait établi;'),
('2m',5,23,'crampon1923','à Garizim, Andronique; et, outre ceux-ci, Ménélas qui, avec plus de méchanceté que les autres, s''élevait insolemment au-dessus de ses concitoyens'),
('2m',5,24,'crampon1923','et nourrissait des sentiments de haine contre les patriotes Juifs. De plus, Antiochus envoya l''infâme Apollonius à la tête d''une armée de vingt-deux mille hommes, avec ordre de mettre à mort tous les hommes dans la force de l''âge et de vendre les femmes et les enfants.'),
('2m',5,25,'crampon1923','Arrivé à Jérusalem, Apollonius, simulant des intentions pacifiques, se tint tranquille jusqu''au saint jour du sabbat et, lorsqu''il vit les Juifs en train de le célébrer, il fit prendre les armes à ses troupes.'),
('2m',5,26,'crampon1923','Et tous ceux qui étaient sortis pour le spectacle, il les fit massacrer et, parcourant la ville avec ses soldats, il mit à mort une multitude de personnes.'),
('2m',5,27,'crampon1923','Or, Judas Machabée, lui dixième, se retira dans le désert, vivant à la manière des bêtes fauves sur les montagnes, avec ses compagnons, ne mangeant jamais que des herbes, pour ne pas se souiller.'),
('2m',6,1,'crampon1923','Peu de temps après, le roi envoya un vieillard d''Athènes pour contraindre les Juifs à abandonner le culte de leurs pères et les empêcher de vivre selon les lois de Dieu,'),
('2m',6,2,'crampon1923','et pour profaner le temple de Jérusalem et le dédier à Jupiter Olympien, et celui de Garizim à Jupiter Hospitalier, conformément au caractère des habitants du lieu.'),
('2m',6,3,'crampon1923','L''invasion de ces maux fut, même pour la masse du peuple, bien pénible et difficile à supporter;'),
('2m',6,4,'crampon1923','car le temple était rempli d''orgies et de débauches par des Gentils dissolus et des courtisanes, des hommes ayant commerce avec des femmes dans les saints parvis et y apportant des choses défendues.'),
('2m',6,5,'crampon1923','L''autel lui-même était couvert de victimes impures que la loi interdisait.'),
('2m',6,6,'crampon1923','Il n''était plus possible de célébrer les sabbats ni les fêtes des pères, ni simplement de confesser que l''on était Juif.'),
('2m',6,7,'crampon1923','Une amère nécessité amenait les Juifs aux sacrifices qui se faisaient chaque mois le jour de la naissance du roi; aux fêtes des Bacchanales, on les contraignait de se promener par les rues couronnés de lierre en l''honneur de Bacchus.'),
('2m',6,8,'crampon1923','Un édit fut rendu, à l''instigation de Ptolémée, pour que, dans les villes grecques du voisinage, on prît les mêmes mesures contre les Juifs et que l''on fît des sacrifices,'),
('2m',6,9,'crampon1923','avec ordre de mettre à mort ceux qui refuseraient d''adopter les coutumes grecques. On avait donc partout sous les yeux des scènes de désolation.'),
('2m',6,10,'crampon1923','Ainsi deux femmes, pour avoir circoncis leurs enfants, furent amenées; on suspendit leurs enfants à leurs mamelles, on les traîna publiquement par la ville, et on les précipita du haut des remparts.'),
('2m',6,11,'crampon1923','D''autres s''étant rendus ensemble dans des cavernes voisines pour célébrer en secret le jour du sabbat, furent dénoncés à Philippe, et on les brûla tous sans qu''ils osassent se défendre, par respect pour la sainteté du jour.'),
('2m',6,12,'crampon1923','Je supplie ceux entre les mains de qui ce livre tombera de ne pas se laisser déconcerter à cause de ces calamités, et de croire que ces persécutions ont eu lieu, non pour la ruine, mais pour la punition de notre race.'),
('2m',6,13,'crampon1923','Quand Dieu ne laisse pas longtemps les pécheurs impunis, mais qu''il fait tomber sur eux un prompt châtiment, c''est une marque de grande bonté.'),
('2m',6,14,'crampon1923','En effet, le souverain Maître, pour punir les autres nations, attend avec patience qu''elles aient comblé la mesure des iniquités; ce n''est pas ainsi qu''il a jugé à propos d''en agir avec nous,'),
('2m',6,15,'crampon1923','afin de n''avoir pas à exercer sur nous sa vengeance, quand nos péchés auraient atteint leur pleine mesure.'),
('2m',6,16,'crampon1923','Aussi ne retire-t-il jamais de nous sa miséricorde; en le châtiant par l''adversité, il n''abandonne pas son peuple.'),
('2m',6,17,'crampon1923','Qu''il nous suffise d''avoir rappelé cette vérité; après ce peu de mots, il faut revenir à notre récit.'),
('2m',6,18,'crampon1923','Eléazar, un des premiers docteurs de la loi, homme déjà avancé en âge et du plus noble extérieur, était contraint, la bouche violemment ouverte, de manger de la chair de porc.'),
('2m',6,19,'crampon1923','Mais lui, préférant une mort glorieuse à une vie criminelle, marchait volontairement au supplice,'),
('2m',6,20,'crampon1923','ayant craché cette viande, comme doivent y marcher ceux qui ont le courage de rejeter ce qu''il n''est pas permis de manger par amour de la vie.'),
('2m',6,21,'crampon1923','Les préposés à ce sacrifice impie, depuis longtemps liés avec Eléazar, le prirent à part et l''engagèrent à faire apporter des viandes dont il était permis de faire usage et préparées par lui, et à feindre de manger des chairs de la victime, comme le roi l''avait ordonné,'),
('2m',6,22,'crampon1923','afin que, cela fait, il fût préservé de la mort et profitât de cette humanité due à sa vieille amitié pour eux.'),
('2m',6,23,'crampon1923','Mais lui, faisant de sages réflexions, dignes de son âge, de la haute considération que lui donnait sa vieillesse et les nobles cheveux blancs qui s''y ajoutaient, de la vie très belle qu''il avait menée depuis l''enfance, et surtout de la législation sainte établie par Dieu même, il répondit en conséquence, disant qu''on l''envoyât sans tarder au séjour des morts.'),
('2m',6,24,'crampon1923','" A notre âge, en effet, il ne convient pas de feindre; de peur que beaucoup de jeunes gens ne soupçonnent Eléazar d''avoir, à quatre-vingt-dix ans, embrassé des mœurs étrangères.'),
('2m',6,25,'crampon1923','Eux-mêmes, alors, à cause de ma dissimulation, et pour un reste de vie périssable, seraient égarés par moi, et j''attirerais sur ma vieillesse la honte et l''opprobre.'),
('2m',6,26,'crampon1923','Et quand j''échapperais pour le présent au châtiment des hommes, je n''éviterais pas, vivant ou mort, les mains du Tout-Puissant.'),
('2m',6,27,'crampon1923','C''est pourquoi, si maintenant je quitte cette vie avec courage, du moins je me montrerai digne de ma vieillesse,'),
('2m',6,28,'crampon1923','et je laisserai aux jeunes gens le noble exemple d''une mort volontaire et généreuse pour les vénérables et saintes lois. " Ayant ainsi parlé, il marcha droit vers l''instrument du supplice.'),
('2m',6,29,'crampon1923','Ceux qui l''y conduisaient changèrent en dureté la bienveillance qu''ils lui avaient montrée un moment auparavant, regardant comme insensées les paroles qu''il venait de prononcer.'),
('2m',6,30,'crampon1923','Lorsqu''il fut près de mourir sous les coups, il poussa un soupir et dit: " Le Seigneur qui a la science sainte voit que, pouvant échapper à la mort, j''endure sous les bâtons des douleurs cruelles selon la chair, mais qu''en mon âme je les souffre avec joie, par respect pour lui. "'),
('2m',6,31,'crampon1923','C''est ainsi qu''il quitta la vie, faisant de sa mort, non seulement pour la jeunesse, mais pour tout le peuple, un exemple de courage et un mémorial de vertu.'),
('2m',7,1,'crampon1923','Il arriva aussi qu''on prit sept frères avec leur mère, et que le roi voulut les contraindre, en les déchirant à coups de fouets et de nerfs de bœuf, à manger de la chair de porc, interdite par la loi.'),
('2m',7,2,'crampon1923','L''un d''eux, prenant la parole au nom de tous, dit: " Que demandes-tu, et que veux-tu apprendre de nous? Nous sommes prêts à mourir plutôt que de transgresser la loi de nos pères. "'),
('2m',7,3,'crampon1923','Le roi, outré de colère, commanda de mettre sur le feu des poêles et des chaudières. Aussitôt qu''elles furent brûlantes,'),
('2m',7,4,'crampon1923','il commanda de couper la langue à celui qui avait parlé au nom de tous, puis de lui enlever la peau de la tête et de lui trancher les extrémités, sous les yeux de ses autres frères et de leur mère.'),
('2m',7,5,'crampon1923','Lorsqu''on l''eut ainsi complètement mutilé, il ordonna qu''on l''approchât du feu, respirant encore, et qu''on le fît rôtir dans la poêle. Pendant que la vapeur de la poêle se répandait au loin, ses frères et leur mère s''exhortaient mutuellement à mourir avec courage:'),
('2m',7,6,'crampon1923','" Le Seigneur Dieu voit, disaient-ils, et il a vraiment compassion de nous, selon que Moïse l''a annoncé, dans le cantique qui proteste en face contre Israël, en disant: Il aura pitié de ses serviteurs. "'),
('2m',7,7,'crampon1923','Le premier étant mort de cette manière, on amena le second pour le supplice, et après lui avoir arraché la peau de la tête avec les cheveux, on lui demanda s''il voulait manger du porc avant d''être torturé dans tous les membres de son corps.'),
('2m',7,8,'crampon1923','Il répondit dans la langue de ses pères: " Non! " C''est pourquoi il subit à son tour les mêmes tourments que le premier.'),
('2m',7,9,'crampon1923','Au moment de rendre le dernier soupir, il dit: " Scélérat que tu es, tu nous ôtes la vie présente, mais le Roi de l''univers nous ressuscitera pour une vie éternelle, nous qui mourons pour être fidèles à ses lois. "'),
('2m',7,10,'crampon1923','Après lui, on tortura le troisième. A la demande du bourreau, il présenta aussitôt sa langue et tendit intrépidement ses mains,'),
('2m',7,11,'crampon1923','et il dit avec un noble courage: " Je tiens ces membres du Ciel, mais à cause de ses lois je les méprise, et c''est de Lui que j''espère les recouvrer un jour. "'),
('2m',7,12,'crampon1923','Le roi lui-même et ceux qui l''accompagnaient furent frappés du courage de ce jeune homme, qui comptait pour rien les tortures.'),
('2m',7,13,'crampon1923','Lui mort, on fit subir au quatrième les mêmes tourments.'),
('2m',7,14,'crampon1923','Sur le point d''expirer, il dit: " Heureux ceux qui meurent de la main des hommes, avec l''espérance qu''ils tiennent de Dieu d''être ressuscités par lui! Pour toi, ta résurrection ne sera point pour la vie. "'),
('2m',7,15,'crampon1923','On amena ensuite le cinquième, et on le tortura. Mais lui, fixant les yeux sur le roi,'),
('2m',7,16,'crampon1923','dit: " Tu as, quoique mortel, pouvoir parmi les hommes, et tu fais ce que tu veux. Mais ne crois pas que notre race soit abandonnée de Dieu.'),
('2m',7,17,'crampon1923','Pour toi, attends, et tu verras sa grande puissance, comme il te tourmentera toi et ta race. "'),
('2m',7,18,'crampon1923','Après lui, on amena le sixième. Près de mourir, il dit: " Ne te fais pas de vaine illusion; c''est nous-mêmes qui nous sommes attiré ces maux, en péchant contre notre Dieu; aussi nous est-il arrivé d''étranges calamités.'),
('2m',7,19,'crampon1923','Mais toi, ne t''imagines pas que tu seras impuni, après avoir osé combattre contre Dieu. "'),
('2m',7,20,'crampon1923','La mère, admirable au-dessus de toute expression et digne d''une illustre mémoire, voyant mourir ses sept fils dans l''espace d''un seul jour, le supporta généreusement, soutenue par son espérance dans le Seigneur.'),
('2m',7,21,'crampon1923','Elle exhortait chacun d''eux en la langue de ses pères et, remplie des plus nobles sentiments, elle raffermissait par un mâle courage sa tendresse de femme.'),
('2m',7,22,'crampon1923','Elle leur disait: " Je ne sais comment vous avez apparu dans mes entrailles; ce n''est pas moi qui vous ai donné l''esprit et la vie; ce n''est pas moi qui ai assemblé les éléments qui composent votre corps.'),
('2m',7,23,'crampon1923','C''est pourquoi le Créateur du monde, qui a formé l''homme à sa naissance et qui préside à l''origine de toutes choses, vous rendra dans sa miséricorde et l''esprit et la vie, parce que maintenant vous vous méprisez vous-mêmes pour l''amour de sa loi. "'),
('2m',7,24,'crampon1923','Antiochus se crut insulté et soupçonna un outrage dans ces paroles. Comme le plus jeune était encore en vie, non seulement il lui adressa des exhortations, mais il lui promit avec serment de le rendre riche et heureux, s''il abandonnait les lois de ses pères, d''en faire son ami et de lui confier de hauts emplois.'),
('2m',7,25,'crampon1923','Le jeune homme ne prêtant à ces offres aucune attention, le roi appela la mère et l''engagea à donner à l''adolescent des conseils de salut.'),
('2m',7,26,'crampon1923','Lorsqu''il l''eut longtemps exhortée, elle accepta de persuader son fils.'),
('2m',7,27,'crampon1923','S''étant donc penchée vers lui et raillant le tyran cruel, elle parla ainsi dans la langue de ses pères: " Mon fils, aie pitié de moi, qui t''ai porté neuf mois dans mon sein, qui t''ai allaité trois ans, qui t''ai entretenu, nourri et élevé jusqu''à l''âge où tu es.'),
('2m',7,28,'crampon1923','Je t''en conjure, mon enfant, regarde le ciel et la terre, vois tout ce qu''ils contiennent, et sache que Dieu les a créés de rien, et que la race des hommes est arrivée ainsi à l''existence.'),
('2m',7,29,'crampon1923','Ne crains pas ce bourreau, mais sois digne de tes frères et accepte la mort, afin que je te retrouve, avec tes frères, au temps de la miséricorde. "'),
('2m',7,30,'crampon1923','Comme elle parlait encore, le jeune homme dit: " Qu''attendez-vous? Je n''obéis pas aux ordres du roi; j''obéis aux prescriptions de la loi qui a été donnée par Moïse à nos pères.'),
('2m',7,31,'crampon1923','Et toi, l''auteur de tous les maux déchaînés sur les Hébreux, tu n''éviteras pas le bras de Dieu.'),
('2m',7,32,'crampon1923','Car c''est à cause de nos péchés que nous souffrons;'),
('2m',7,33,'crampon1923','et si, pour nous châtier et nous corriger, notre Seigneur, qui est vivant, nous a montré un moment sa colère, il se réconciliera avec ses serviteurs.'),
('2m',7,34,'crampon1923','Mais toi, ô impie et le plus scélérat de tous les hommes, ne t''enorgueillis pas follement, te livrant à de vaines espérances, quand tu lèves la main contre les serviteurs de Dieu;'),
('2m',7,35,'crampon1923','car tu n''as pas encore échappé au jugement du Dieu tout-puissant qui surveille toutes choses.'),
('2m',7,36,'crampon1923','Nos frères, après avoir enduré une souffrance passagère, sont échus à l''alliance de Dieu pour une vie éternelle; mais toi, par le jugement de Dieu, tu porteras le juste châtiment de ton orgueil.'),
('2m',7,37,'crampon1923','Quant à moi, ainsi que mes frères, je livre mon corps et ma vie pour les lois de mes pères, suppliant Dieu d''être bientôt propice envers son peuple et de t''amener, par les tourments et la souffrance, à confesser qu''il est le seul Dieu,'),
('2m',7,38,'crampon1923','et puisse, en moi et en mes frères, s''arrêter la colère du Tout-Puissant, justement déchaînée sur toute notre race! "'),
('2m',7,39,'crampon1923','Le roi, transporté de fureur, sévit contre celui-ci plus cruellement encore que contre les autres, ne pouvant supporter qu''on se jouât de lui.'),
('2m',7,40,'crampon1923','Ainsi mourut ce jeune homme, pur de toute idolâtrie et se confiant entièrement au Seigneur.'),
('2m',7,41,'crampon1923','Enfin la mère mourut la dernière, après ses enfants.'),
('2m',7,42,'crampon1923','Mais en voilà assez au sujet des sacrifices et des excessives cruautés d''Antiochus.'),
('2m',8,1,'crampon1923','Cependant Judas Machabée et ses compagnons, s''introduisant secrètement dans les villages, appelaient autour d''eux leurs parents, et, s''adjoignant ceux qui étaient restés fidèles au judaïsme, ils rassemblèrent ainsi une troupe d''environ six mille hommes.'),
('2m',8,2,'crampon1923','Ils conjuraient le Seigneur de regarder son peuple que tout le monde foulait aux pieds, d''avoir aussi pitié de son temple profané par les impies,'),
('2m',8,3,'crampon1923','d''avoir compassion de la ville dévastée qui allait se trouver au niveau du sol, et d''écouter la voix du sang qui criait vers lui,'),
('2m',8,4,'crampon1923','de se souvenir du meurtre criminel des petits enfants innocents et des outrages faits à son nom, et de montrer sa haine contre les méchants.'),
('2m',8,5,'crampon1923','Une fois à la tête d''une troupe nombreuse, Machabée devint invincible aux nations, car la colère du Seigneur s''était changée en miséricorde.'),
('2m',8,6,'crampon1923','Tombant à l''improviste sur les villes et les villages, il les brûlait; occupant les positions les plus favorables, il infligeait des défaites à de nombreux ennemis.'),
('2m',8,7,'crampon1923','C''est surtout la nuit qu''il choisissait pour favoriser le succès de ces sortes d''expéditions. Le bruit de sa valeur se répandit en tous lieux.'),
('2m',8,8,'crampon1923','Philippe ne fut pas longtemps à voir quels progrès faisait cet homme, et les succès de plus en plus fréquents qu''il remportait; il écrivit donc à Ptolémée, chef militaire de la Cœlé-Syrie et de la Phénicie, de venir en aide aux affaires du roi.'),
('2m',8,9,'crampon1923','Ptolémée s''étant mis à l''œuvre sans tarder, fit partir Nicanor, fils de Patrocle, un des principaux favoris du roi, à la tête d''au moins vingt mille hommes de diverses nations, pour qu''il exterminât la race entière des Juifs; il lui adjoignit Gorgias, général fort expérimenté dans les choses de la guerre.'),
('2m',8,10,'crampon1923','Nicanor comptait bien procurer au roi, sur la vente des captifs pris en Judée, le tribut de deux mille talents dû aux Romains.'),
('2m',8,11,'crampon1923','Il s''empressa d''envoyer aux villes maritimes l''invitation à venir acheter des esclaves Juifs, promettant de leur en donner quatre-vingt-dix pour un talent: il ne songeait pas à la vengeance du Tout-Puissant qui allait tomber sur lui.'),
('2m',8,12,'crampon1923','Dès que Judas eut appris la marche de Nicanor, il informa ses compagnons de l''approche de l''armée.'),
('2m',8,13,'crampon1923','Alors les uns, frappés de crainte et manquant de foi en la justice de Dieu, prirent la fuite et passèrent en d''autres lieux;'),
('2m',8,14,'crampon1923','les autres vendirent tout ce qui leur restait et, en même temps, ils priaient le Seigneur de les délivrer de l''impie Nicanor, qui les avait vendus avant même que la bataille fût engagée:'),
('2m',8,15,'crampon1923','sinon à cause d''eux, du moins en considération des alliances faites avec leurs pères, et parce que son nom saint et auguste avait été nommé sur eux.'),
('2m',8,16,'crampon1923','Machabée ayant réuni ceux qui étaient restés avec lui, au nombre de six mille hommes, les exhorta à ne pas craindre les ennemis, et à ne pas se troubler devant la multitude des nations qui marchaient injustement contre eux, mais à combattre vaillamment,'),
('2m',8,17,'crampon1923','ayant devant les yeux l''indigne profanation accomplie par elles contre le lieu saint, l''outrage de la ville ravagée, ainsi que la ruine des institutions des ancêtres.'),
('2m',8,18,'crampon1923','" Eux, dit-il, se confient dans leurs armes et des charges hardies; nous, c''est en Dieu, maître de toutes choses, qui peut d''un signe renverser ceux qui viennent nous attaquer et l''univers même, que nous mettons notre confiance. "'),
('2m',8,19,'crampon1923','Il énuméra aussi devant eux les exemples antiques de la protection de Dieu; et comment, sous Sennachérib, les cent quatre-vingt mille hommes avaient péri;'),
('2m',8,20,'crampon1923','et comment, dans la bataille livrée aux Galates en Babylonie, ceux qui prenaient part à l''action étant en tout huit mille, avec quatre mille Macédoniens, et ceux-ci étant vivement pressés, les huit mille avaient détruit cent vingt mille ennemis, grâce au secours qui leur était venu du ciel, et avaient remporté un grand profit.'),
('2m',8,21,'crampon1923','Après les avoir, par ces souvenirs, remplis de confiance et disposés à mourir pour les lois et pour la patrie, il divisa son armée en quatre corps.'),
('2m',8,22,'crampon1923','A la tête de chaque corps, il mit ses frères Simon, Joseph et Jonathas, leur donnant à chacun quinze cents hommes.'),
('2m',8,23,'crampon1923','En outre, il ordonna à Eléazar de faire la lecture du Livre saint; puis, ayant donné pour mot d''ordre: Secours de Dieu! Judas prit le commandement du premier corps et attaqua Nicanor.'),
('2m',8,24,'crampon1923','Le Tout-Puissant leur étant venu en aide, ils tuèrent plus de neuf mille ennemis, blessèrent et mutilèrent la plus grande partie des soldats de Nicanor et les mirent tous en fuite.'),
('2m',8,25,'crampon1923','Ils prirent aussi l''argent de ceux qui étaient venus pour les acheter. Ayant poursuivi assez loin les fuyards,'),
('2m',8,26,'crampon1923','ils revinrent sur leurs pas, arrêtés par le temps, car c''était la veille du sabbat; c''est pourquoi ils ne continuèrent pas leur poursuite.'),
('2m',8,27,'crampon1923','Ayant donc ramassé les armes des ennemis et recueilli leurs dépouilles, ils célébrèrent le sabbat, bénissant mille fois et louant le Seigneur qui les avait délivrés pour ce jour, ayant résolu de leur montrer un commencement de miséricorde.'),
('2m',8,28,'crampon1923','Après le sabbat, ils distribuèrent une part du butin à ceux qui avaient souffert de la persécution, aux veuves et aux orphelins; eux-mêmes et leurs enfants se partagèrent le reste.'),
('2m',8,29,'crampon1923','Cela fait, ils se mirent à prier tous ensemble, conjurant le Seigneur miséricordieux de se réconcilier entièrement avec ses serviteurs.'),
('2m',8,30,'crampon1923','Ils tuèrent aussi plus de vingt mille hommes des troupes qui combattaient sous les ordres de Timothée et de Bacchidès, et s''emparèrent vaillamment de hautes forteresses. Ils divisèrent leur immense butin, en faisant deux parts égales, l''une pour eux-mêmes, l''autre pour les persécutés, les orphelins et les veuves, ainsi que pour les vieillards.'),
('2m',8,31,'crampon1923','Ils recueillirent les armes et les déposèrent toutes avec soin en des lieux convenables, et transportèrent à Jérusalem le reste du butin.'),
('2m',8,32,'crampon1923','Ils mirent à mort Phylarque, qui accompagnait Timothée; c''était un homme très pervers, qui avait fait beaucoup de mal aux Juifs.'),
('2m',8,33,'crampon1923','Pendant qu''ils fêtaient leur victoire dans leur capitale, Callisthène et quelques autres, qui avaient livré aux flammes les saintes portes du temple, s''étant réfugiés dans une petite maison, ils les y brûlèrent et leur rendirent ainsi le juste salaire de leurs profanations.'),
('2m',8,34,'crampon1923','Le triple scélérat Nicanor, qui avait fait venir les mille marchands pour leur vendre les Juifs,'),
('2m',8,35,'crampon1923','humilié, grâce au secours du Seigneur, par ceux qu''il croyait plus faibles que lui, se dépouilla de ses vêtements d''honneur et, prenant à travers champs comme un fuyard, sans escorte, il rentra seul à Antioche, au désespoir d''avoir perdu son armée.'),
('2m',8,36,'crampon1923','Et lui qui avait promis de parfaire le tribut aux Romains avec le prix des captifs de Jérusalem, il publiait maintenant que les Juifs avaient Dieu pour défenseur et qu''ainsi ils étaient invulnérables, parce qu''ils obéissaient aux lois qu''il leur avait prescrites.'),
('2m',9,1,'crampon1923','Vers ce temps-là, Antiochus était honteusement revenu des contrées de la Perse.'),
('2m',9,2,'crampon1923','Car, étant entré dans la ville nommée Persépolis, il avait tenté de piller le temple et d''opprimer la ville; c''est pourquoi la multitude soulevée eut recours à la force des armes et il arriva qu''Antiochus, mis en fuite par les habitants du pays, fit une retraite humiliante.'),
('2m',9,3,'crampon1923','Comme il était dans la région d''Ecbatane, il apprit ce qui était arrivé à Nicanor et à l''armée de Timothée.'),
('2m',9,4,'crampon1923','Transporté de fureur, il pensait à venger sur les Juifs l''injure de ceux qui l''avaient forcé de fuir; il commanda donc au conducteur de pousser son char sans s''arrêter, pour hâter le voyage. La vengeance du ciel le poursuivait, car il avait dit dans son orgueil: " Aussitôt arrivé à Jérusalem, je ferais de cette ville le tombeau des Juifs. "'),
('2m',9,5,'crampon1923','Mais le Seigneur, Dieu d''Israël, qui voit toutes choses, le frappa d''une plaie incurable et horrible à voir. A peine eut-il proféré cette parole, qu''il fut saisi par une extrême douleur d''entrailles, avec de cruelles tortures à l''intérieur.'),
('2m',9,6,'crampon1923','C''était justice, puisqu''il avait déchiré les entrailles des autres par des tourments nombreux et inouïs. Mais il ne rabattait rien de son arrogance;'),
('2m',9,7,'crampon1923','toujours rempli d''orgueil, il exhalait contre les Juifs le feu de sa colère et ordonnait de hâter la marche, quand soudain il tomba du char qui roulait avec fracas, et sa chute fut si violente que tous les membres de son corps en furent meurtris.'),
('2m',9,8,'crampon1923','Lui qui tout à l''heure croyait commander aux flots de la mer, dans sa jactance surhumaine, lui qui s''imaginait peser dans la balance la hauteur des montagnes, ayant été précipité par terre, il était porté dans une litière, rendant manifeste aux yeux de tous la puissance de Dieu.'),
('2m',9,9,'crampon1923','Du corps de l''impie sortaient des essaims de vers; lui vivant, ses chairs se détachaient par lambeaux avec d''atroces douleurs, et l''odeur de pourriture qui s''en exhalait incommodait toute l''armée;'),
('2m',9,10,'crampon1923','et celui qui naguère semblait toucher aux astres du ciel, personne maintenant ne pouvait le porter, à cause de cette intolérable puanteur.'),
('2m',9,11,'crampon1923','Alors, profondément blessé, il commença à revenir de ce grand orgueil et à se connaître lui-même, sous le fouet divin qui redoublait à chaque moment ses douleurs;'),
('2m',9,12,'crampon1923','et comme lui-même ne pouvait supporter son infection, il dit: " Il est juste de se soumettre à Dieu et, simple mortel, ne pas s''égaler insolemment à la divinité. "'),
('2m',9,13,'crampon1923','Mais ce scélérat priait le Souverain Maître qui ne devait plus avoir pitié de lui,'),
('2m',9,14,'crampon1923','promettant de déclarer libre la ville sainte, vers laquelle il se hâtait pour l''égaler au sol et en faire le tombeau de ses habitants;'),
('2m',9,15,'crampon1923','de rendre semblables aux Athéniens tous les Juifs, qu''il ne jugeait pas dignes de la sépulture, les destinant, eux et leurs enfants, à servir de pâture aux oiseaux de proie et aux bêtes féroces;'),
('2m',9,16,'crampon1923','d''orner des plus belles offrandes le temple saint qu''il avait jadis dépouillé, de lui rendre et au delà tous ses ustensiles sacrés et de subvenir de ses propres revenus aux frais des sacrifices,'),
('2m',9,17,'crampon1923','et en outre de devenir lui-même Juif, et de parcourir tous les lieux habités en y proclamant la puissance de Dieu.'),
('2m',9,18,'crampon1923','Mais ses souffrances ne se calmèrent pas, car le juste jugement de Dieu était venu sur lui; c''est alors que, voyant son état désespéré, il écrivit aux Juifs la lettre ci-dessous transcrite, ayant la forme d''une supplication, et conçue en ces termes:'),
('2m',9,19,'crampon1923','" Aux Juifs, ses excellents citoyens, le roi et général Antiochus: Salut, santé et bonheur parfaits!'),
('2m',9,20,'crampon1923','Si vous vous portez bien, ainsi que vos enfants, si vos affaires vont selon vos désirs, j''en rends à Dieu les plus grandes gloires, mettant mon espoir dans le ciel.'),
('2m',9,21,'crampon1923','Pour moi, je suis étendu sur un lit, sans force, me rappelant avec amour les marques d''honneur et de bienveillance que j''ai reçues de vous. " A mon retour des contrées de la Perse, étant tombé dans une maladie cruelle, j''ai jugé nécessaire de m''occuper du bien-être de tous.'),
('2m',9,22,'crampon1923','Ce n''est pas que je désespère de moi; j''ai au contraire une grande confiance de guérir de cette maladie.'),
('2m',9,23,'crampon1923','Mais considérant que mon père, quand il porta ses armes dans les hautes provinces, désigna son futur successeur,'),
('2m',9,24,'crampon1923','afin que, en cas d''un malheur inattendu ou de bruits fâcheux, ceux du royaume, sachant à qui les affaires étaient remises, ne fussent pas troublés;'),
('2m',9,25,'crampon1923','songeant en outre que les monarques limitrophes et des princes voisins de mes Etats épient les circonstances et attendent ce qui arrivera, j''ai désigné pour roi mon fils Antiochus que, plus d''une fois, lorsque j''ai parcouru mes provinces supérieures, j''ai confié à la plupart d''entre vous en vous le recommandant, et je lui ai écrit la lettre transcrite ci-dessous.'),
('2m',9,26,'crampon1923','Je vous demande donc et vous prie de vous souvenir de mes bienfaits, tant généraux que particuliers, et de conserver chacun la bienveillance que vous avez pour moi et pour mon fils.'),
('2m',9,27,'crampon1923','Car je suis persuadé que, plein de douceur et d''humanité, il réalisera mes intentions et se montrera condescendant à votre égard. "'),
('2m',9,28,'crampon1923','Ainsi ce meurtrier, ce blasphémateur en proie à d''horribles souffrances, comme il en avait fait endurer aux autres, mourut sur la terre étrangère, dans les montagnes, d''une mort misérable.'),
('2m',9,29,'crampon1923','Philippe, son compagnon d''enfance, faisait transporter son corps; mais craignant le jeune Antiochus, il se retira en Egypte, auprès de Ptolémée Philométor.'),
('2m',10,1,'crampon1923','Cependant Machabée et ses compagnons reprirent, avec l''aide du Seigneur, le temple et la ville.'),
('2m',10,2,'crampon1923','Ils détruisirent les autels que les étrangers avaient dressés sur la place publique, ainsi que les bois sacrés.'),
('2m',10,3,'crampon1923','Puis, après avoir purifié le temple, ils élevèrent un autre autel et, ayant tiré du feu des cailloux, ils prirent de ce feu et, après un intervalle de deux ans, ils offrirent un sacrifice, firent de nouveau fumer l''encens, allumèrent les lampes et mirent sur la table les pains de proposition.'),
('2m',10,4,'crampon1923','Cela fait, prosternés par terre, ils prièrent le Seigneur de ne plus faire tomber sur eux de tels maux, demandant, s''ils péchaient encore, d''être châtiés par lui comme il convient, mais de ne plus être livrés à des nations impies et barbares.'),
('2m',10,5,'crampon1923','Le temple avait été profané par les étrangers le vingt-cinquième jour du mois de casleu, et il se rencontra qu''il fut purifié à pareil jour.'),
('2m',10,6,'crampon1923','Et ils firent pendant huit jours une fête à la manière de celle des tabernacles, se souvenant que peu de temps auparavant, ils avaient passé la fête des tabernacles dans les montagnes, dans des cavernes, comme des bêtes sauvages.'),
('2m',10,7,'crampon1923','C''est pourquoi, portant des thyrses, des rameaux verts et des palmes, ils chantèrent des hymnes à la gloire de celui qui les avait heureusement amenés à purifier son temple.'),
('2m',10,8,'crampon1923','Et ils prescrivirent par un édit public et un décret que toute la nation juive solenniserait chaque année ces mêmes jours.'),
('2m',10,9,'crampon1923','Telles furent donc les circonstances de la mort d''Antiochus, surnommé Epiphane;'),
('2m',10,10,'crampon1923','nous allons exposer maintenant ce qui concerne Antiochus Eupator, fils de cet impie, en relatant brièvement les maux causés par les guerres.'),
('2m',10,11,'crampon1923','A son avènement au trône, il mit à la tête des affaires un certain Lysias, nommé aussi commandant en chef de l''armée de Cœlé-Syrie et de Phénicie.'),
('2m',10,12,'crampon1923','Car Ptolémée, surnommé Macron, avait été le premier à observer la justice envers les Juifs, à cause des violences qu''ils avaient subies, et s''était efforcé de les gouverner pacifiquement.'),
('2m',10,13,'crampon1923','Mais pour cela même il fut accusé par des amis du roi devant Eupator et, comme en toute occasion il s''entendait appeler traître, pour avoir abandonné Chypre que lui avait confiée Philométor, et pour avoir passé du côté d''Antiochus Epiphane, n''ayant plus qu''une dignité sans honneur, il perdit courage et se donna la mort par le poison.'),
('2m',10,14,'crampon1923','Or Gorgias, devenu chef militaire de ces provinces, levait des troupes étrangères, et saisissait toutes les occasions de faire la guerre aux Juifs.'),
('2m',10,15,'crampon1923','En même temps que lui, les Iduméens, maîtres de bonnes forteresses, molestaient les Juifs; ils accueillaient ceux qui étaient chassés de Jérusalem, et tentaient d''entretenir la guerre.'),
('2m',10,16,'crampon1923','Machabée et ses compagnons, après avoir prié et demandé à Dieu de leur venir en aide, firent irruption contre les places fortes occupes par les Iduméens.'),
('2m',10,17,'crampon1923','Les ayant attaquées avec vigueur, ils s''en rendirent maîtres, et refoulèrent tous ceux qui combattaient sur les remparts; ils égorgèrent quiconque tombait entre leurs mains; le nombre des tués ne fut pas inférieur à vingt mille.'),
('2m',10,18,'crampon1923','Neuf mille hommes au moins s''étaient réfugiés dans deux tours très fortes, ayant avec eux tout ce qu''il faut pour soutenir un siège.'),
('2m',10,19,'crampon1923','Machabée laissa pour les réduire Simon et Joseph, ainsi que Zachée et ses compagnons, en nombre suffisant, et s''en alla de sa personne où il y avait urgences.'),
('2m',10,20,'crampon1923','Mais les gens de Simon, avides de richesses, se laissèrent gagner à prix d''argent par quelques-uns de ceux qui étaient dans les tours et, ayant reçu soixante-dix mille drachmes, ils en laissèrent échapper un certain nombre.'),
('2m',10,21,'crampon1923','Lorsqu''on eut appris à Machabée ce qui s''était passé, il réunit les princes du peuple et accusa ces hommes d''avoir vendu leurs frères à prix d''argent, en laissant échapper des ennemis armés contre eux.'),
('2m',10,22,'crampon1923','Puis il fit mettre à mort ces traîtres et s''empara aussitôt des deux tours.'),
('2m',10,23,'crampon1923','Et, conduisant à bien toutes ses entreprises militaires, il tua dans ces deux forteresses plus de vingt mille hommes.'),
('2m',10,24,'crampon1923','Mais Timothée, qui précédemment avait été défait par les Juifs, ayant rassemblé une multitude de troupes étrangères et tiré de l''Asie une cavalerie nombreuse, s''avançait pour conquérir la Judée par les armes.'),
('2m',10,25,'crampon1923','A son approche, Machabée et ses compagnons se mirent à prier Dieu, semant la poussière sur leurs têtes et ceignant leurs reins de sacs.'),
('2m',10,26,'crampon1923','Prosternés au pied de l''autel, ils demandèrent au Seigneur de leur être propice, d''être l''ennemi de leurs ennemis, et l''adversaire de leurs adversaires, comme la loi le promet.'),
('2m',10,27,'crampon1923','Leur prière achevée, ils prirent les armes, sortirent de la ville jusqu''à une assez longue distance et, quand ils furent près de l''ennemi ils s''arrêtèrent.'),
('2m',10,28,'crampon1923','Aux premières lueurs du jour, des deux côtés on engagea la bataille, les uns ayant pour gage du succès et de la victoire, outre leur vaillance, leur recours au Seigneur, les autres ne prenant pour guide dans le combat que leur emportement.'),
('2m',10,29,'crampon1923','Au fort du combat, apparurent du ciel aux ennemis, sur des chevaux aux freins d''or, cinq hommes resplendissants, qui se mirent à la tête des Juifs.'),
('2m',10,30,'crampon1923','Deux d''entre eux ayant pris Machabée au milieu d''eux, ils le gardaient invulnérable, en le couvrant de leurs armures; ils lançaient en même temps des traits et la foudre contre les ennemis qui, frappés d''aveuglement et remplis d''épouvante, tombaient en désordre.'),
('2m',10,31,'crampon1923','Vingt mille cinq cents fantassins et six cents cavaliers périrent ainsi.'),
('2m',10,32,'crampon1923','Timothée s''enfuit dans une place très forte, appelée Gazara, où commandait Chéréas.'),
('2m',10,33,'crampon1923','Machabée et ses compagnons, remplis d''une joyeuse ardeur, l''assiégèrent pendant quatre jours.'),
('2m',10,34,'crampon1923','Confiants dans la force de la place, les assiégés ne cessaient de blasphémer et de proférer des paroles impies.'),
('2m',10,35,'crampon1923','Comme le cinquième jour commençait à poindre, vingt jeunes hommes de la troupe de Machabée, dont ces blasphèmes avaient enflammé la colère, s''élancèrent bravement sur la muraille et, avec un courage de lions, massacrèrent tout ce qu''ils trouvèrent devant eux.'),
('2m',10,36,'crampon1923','D''autres montèrent également et attaquèrent les assiégés du côté opposé; ils mirent le feu aux tours et allumèrent des bûchers sur lesquels ils brûlèrent vifs les blasphémateurs; d''autres brisèrent les portes et ouvrirent un passage au reste de l''armée, qui s''empara de la ville.'),
('2m',10,37,'crampon1923','Ayant trouvé Timothée caché dans une citerne, ils le mirent à mort, ainsi que son frère Chéréas et Apollophane.'),
('2m',10,38,'crampon1923','Ces exploits accomplis, ils bénirent, par des hymnes et des chants de louanges, le Seigneur qui avait fait de grandes choses pour Israël et leur avait donné la victoire.'),
('2m',11,1,'crampon1923','Très peu de temps après, Lysias, tuteur et parent du roi, et régent du royaume, supportant avec peine ce qui venait d''arriver,'),
('2m',11,2,'crampon1923','rassembla environ quatre-vingt mille hommes et toute sa cavalerie, et se mit en marche contre les Juifs, comptant bien peupler de Grecs la ville sainte,'),
('2m',11,3,'crampon1923','assujettir le temple à un tribut, comme tous les autres sanctuaires des nations, et vendre chaque année la dignité de grand prêtre;'),
('2m',11,4,'crampon1923','ne considérant nullement en cela la puissance de Dieu, mais fier outre mesure de ses myriades de fantassins, de ses milliers de cavaliers et de ses quatre-vingts éléphants.'),
('2m',11,5,'crampon1923','Etant donc entré en Judée, il s''approcha de Bethsur, place de difficile accès, à environ cinq stades de Jérusalem, et la pressa vivement.'),
('2m',11,6,'crampon1923','Lorsque Machabée et ses compagnons apprirent que Lysias assiégeait les forteresses, ils prièrent le Seigneur avec des gémissements et des larmes, et tout le peuple avec eux, d''envoyer un bon ange pour la délivrance d''Israël.'),
('2m',11,7,'crampon1923','Machabée le premier prit les armes, et il exhorta les autres à s''exposer avec lui au péril pour secourir leurs frères.'),
('2m',11,8,'crampon1923','Tous se mirent en marche avec une généreuse ardeur; et, comme ils étaient encore en vue de Jérusalem, un cavalier vêtu de blanc apparut à leur tête, agitant une armure d''or.'),
('2m',11,9,'crampon1923','Alors tous ensemble bénirent le Dieu miséricordieux, et ils furent fortifiés dans leurs cœurs, prêts à combattre non seulement des hommes, mais les bêtes les plus farouches, et à percer des murailles de fer.'),
('2m',11,10,'crampon1923','Ils s''avancèrent en ordre de bataille, ayant un auxiliaire venu du ciel, et le Seigneur ayant compassion d''eux.'),
('2m',11,11,'crampon1923','S''étant jetés comme des lions sur les ennemis, ils couchèrent par terre onze mille fantassins et seize cents cavaliers,'),
('2m',11,12,'crampon1923','et mirent les autres en fuite. La plupart d''entre eux échappèrent blessés et sans armes; Lysias lui-même ne sauva sa vie que par une fuite honteuse.'),
('2m',11,13,'crampon1923','Mais comme il ne manquait pas de sens, il réfléchit sur sa défaite et, comprenant que les Hébreux étaient invincibles, puisque le Dieu tout-puissant combattait avec eux, il leur envoya'),
('2m',11,14,'crampon1923','proposer la réconciliation sous toutes conditions équitables, s''offrant en conséquence à persuader au roi la nécessité de devenir leur ami.'),
('2m',11,15,'crampon1923','Machabée consentit à tout ce que proposait Lysias, n''ayant en vue que l''intérêt public; car toutes les conditions que Machabée transmit par écrit à Lysias au sujet des Juifs, le roi les consentit.'),
('2m',11,16,'crampon1923','La lettre que Lysias écrivit aux Juifs était conçue en ces termes: " Lysias au peuple Juif, salut.'),
('2m',11,17,'crampon1923','Jean et Absalom, que vous m''avez envoyés, m''ayant remis l''acte signé de vous, m''ont demandé d''en accomplir les clauses.'),
('2m',11,18,'crampon1923','Tout ce qui devait être soumis au roi, je le lui ai fait connaître, et il a accordé ce qui était admissible.'),
('2m',11,19,'crampon1923','Si donc vous persévérez dans votre bon vouloir vis-à-vis du gouvernement, je m''efforcerai aussi désormais de contribuer à votre bonheur.'),
('2m',11,20,'crampon1923','Quant à certains détails, j''ai donné des explications à vos envoyés et aux miens pour en conférer avec vous.'),
('2m',11,21,'crampon1923','Portez-vous bien. L''an cent quarante-huit, le vingt-quatre du mois de Dioscorinthe. "'),
('2m',11,22,'crampon1923','La lettre du roi était ainsi conçue: " Le roi Antiochus à son frère Lysias, salut.'),
('2m',11,23,'crampon1923','Notre père ayant été transféré parmi les dieux, nous, — voulant que ceux de notre royaume se livrent sans trouble au soin de leurs affaires,'),
('2m',11,24,'crampon1923','et ayant appris que les Juifs ne consentent pas, comme le voulait notre père, à adopter les mœurs grecques, mais qu''ils préfèrent leurs coutumes particulières et demandent, en conséquence, qu''il leur soit permis de vivre selon leurs lois,'),
('2m',11,25,'crampon1923','désirant donc que cette nation ne soit pas non plus troublée, — nous ordonnons que le temple leur soit rendu et qu''ils puissent vivre selon les coutumes de leurs ancêtres.'),
('2m',11,26,'crampon1923','Tu feras donc bien d''envoyer vers eux et de leur tendre la main, afin que, connaissant nos intentions, ils aient confiance et se livrent joyeusement au soin de leurs propres affaires. "'),
('2m',11,27,'crampon1923','La lettre du roi à la nation juive était ainsi conçue: " Le roi Antiochus au sénat des Juifs et aux autres Juifs, salut.'),
('2m',11,28,'crampon1923','Si vous vous portez bien, cela répond à nos vœux, et nous-mêmes nous sommes en bonne santé.'),
('2m',11,29,'crampon1923','Ménélas nous a fait connaître votre désir de revenir et d''être à vos propres affaires.'),
('2m',11,30,'crampon1923','Ceux donc qui se mettront en marche jusqu''au trentième jour du mois de Xantique, jouiront de la paix et de la sécurité.'),
('2m',11,31,'crampon1923','Que les Juifs usent de leurs aliments et suivent leurs lois comme auparavant, sans que nul d''entre eux soit aucunement inquiété pour les fautes commises par ignorance.'),
('2m',11,32,'crampon1923','J''ai envoyé Ménélas, qui vous donnera de pacifiques assurances.'),
('2m',11,33,'crampon1923','Portez-vous bien. L''an cent quarante-huit, le quinze du mois de Xantique. "'),
('2m',11,34,'crampon1923','Les Romains adressèrent aussi aux Juifs une lettre ainsi conçue: " Quintus Memmius et Titus Manlius, légats des Romains, au peuple Juif, salut.'),
('2m',11,35,'crampon1923','Les choses que Lysias, parent du roi, vous a accordées, nous vous les accordons aussi.'),
('2m',11,36,'crampon1923','Quant à celles qu''il a jugé devoir soumettre au roi, envoyez-nous quelqu''un sans délai, après les avoir bien examinées, afin que nous les exposions au roi, comme il convient de le faire pour vous, car nous nous rendons à Antioche.'),
('2m',11,37,'crampon1923','Hâtez-vous donc, faites partir vos députés, afin que nous sachions, nous aussi, quelles sont vos intentions.'),
('2m',11,38,'crampon1923','Portez-vous bien. L''an cent quarante-huit, le quinze de Xantique. "'),
('2m',12,1,'crampon1923','Ce traité conclu, Lysias s''en retourna auprès du roi, et les Juifs se mirent à cultiver leurs champs.'),
('2m',12,2,'crampon1923','Or les généraux de la contrée, Timothée et Apollonius, fils de Gennée, ainsi que Hiéronyme et Démophon, auxquels il faut ajouter Nicanor, gouverneur de Chypre, ne les laissaient pas tranquilles ni vivre en paix.'),
('2m',12,3,'crampon1923','Cependant les habitants de Joppé commirent un crime abominable. Ils invitèrent les Juifs qui demeuraient parmi eux à monter avec leurs femmes et leurs enfants sur des barques préparées par eux, comme s''ils n''avaient contre eux aucune inimitié,'),
('2m',12,4,'crampon1923','mais agissaient en vertu d''une décision prise en commun par la ville. Les Juifs acceptèrent, comme des gens qui désirent la paix et n''ont aucune défiance. Mais lorsqu''ils furent au large, on les coula à fond, au nombre de plus de deux cents au moins.'),
('2m',12,5,'crampon1923','Dès que Judas eut appris la cruauté commise contre des hommes de sa nation, il donna des ordres à ses compagnons, et, après avoir invoqué Dieu,'),
('2m',12,6,'crampon1923','le juste juge, il marcha contre les meurtriers de ses frères, mit le feu pendant la nuit aux constructions du port, brûla les navires et passa au fil de l''épée ceux qui y avaient cherché un refuge.'),
('2m',12,7,'crampon1923','Comme la place était fermée, il s''en alla, mais avec le dessein de revenir et de détruire toute la cité des Joppites.'),
('2m',12,8,'crampon1923','Ayant appris que ceux de Jamnia se proposaient aussi de traiter de la même manière les Juifs domiciliés chez eux,'),
('2m',12,9,'crampon1923','Judas attaqua de même pendant la nuit les habitants de Jamnia et brûla le port avec les vaisseaux, en sorte que la lueur de l''incendie fut aperçue jusqu''à Jérusalem, éloignée de deux cent quarante stades.'),
('2m',12,10,'crampon1923','Comme ils s''étaient éloignés de là de neuf stades, marchant contre Timothée, des Arabes tombèrent sur Judas, au nombre d''au moins cinq mille hommes de pied et de cinq cents cavaliers.'),
('2m',12,11,'crampon1923','Le combat fut acharné; mais, avec l''aide de Dieu, Judas et ses compagnons l''emportèrent; vaincus, les nomades demandèrent à Judas de leur tendre la main droite, promettant de lui donner du bétail et de lui être utiles en d''autres choses.'),
('2m',12,12,'crampon1923','Judas, persuadé qu''ils pouvaient en effet lui rendre beaucoup de services, consentit à leur accorder la paix et, après qu''on se fut donné la main, ils se retirèrent sous leurs tentes.'),
('2m',12,13,'crampon1923','Judas attaqua ensuite une ville forte, entourée de remparts avec des ponts-levis, et habitée par des hommes de diverses nations: elle s''appelait Caspin.'),
('2m',12,14,'crampon1923','Les assiégés, confiants dans la force de leurs murailles et bien pourvus de vivres, se montrèrent grossiers, insultant Judas et ses compagnons, et proférant même des blasphèmes et des paroles impies.'),
('2m',12,15,'crampon1923','Judas et les siens, après avoir invoqué le souverain Maître du monde qui, au temps de Josué, renversa les murs de Jéricho sans béliers ni machines, se précipitèrent sur les murailles comme des lions furieux.'),
('2m',12,16,'crampon1923','Ayant pris la ville par la volonté du Seigneur, ils y firent un immense carnage, au point que l''étang voisin, large de deux stades, semblait rempli du sang qui y avait coulé.'),
('2m',12,17,'crampon1923','De là, par une marche de sept cent cinquante stades, ils atteignirent le Charax, où demeurent les Juifs qui sont appelés Tubiens.'),
('2m',12,18,'crampon1923','Ils ne rencontrèrent pas Timothée en ces lieux-là; comme il n''avait rien pu y faire, il s''en était allé, après avoir laissé en un certain endroit une garnison très forte.'),
('2m',12,19,'crampon1923','Mais deux des généraux de Machabée, Dosithée et Sosipater, allèrent attaquer cette forteresse et tuèrent ceux que Timothée y avait laissés, au nombre de plus de dix mille hommes.'),
('2m',12,20,'crampon1923','De son côté, Machabée ayant rangé son armée par cohortes, leur donna le commandement de ces corps et s''avança contre Timothée, qui avait avec lui cent vingt mille fantassins et deux mille cinq cents cavaliers.'),
('2m',12,21,'crampon1923','Informé de l''approche de Judas, Timothée fit diriger les femmes, les enfants et leur avoir vers le lieu nommé Carnion; car c''était un endroit inexpugnable et d''accès difficile, à cause des passes étroites de toute la contrée.'),
('2m',12,22,'crampon1923','Dès que la première cohorte de Judas parut, l''épouvante s''empara des ennemis; car la puissance de Celui qui voit tout se manifestait à eux d''une manière effrayante, et ils prirent la fuite les uns d''un côté, les autres de l''autre, de telle sorte qu''ils se faisaient de mutuelles blessures et se transperçaient de leurs propres épées.'),
('2m',12,23,'crampon1923','Judas les poursuivit avec acharnement, frappant tous ces hommes criminels, et il en fit périr jusqu''à trente mille.'),
('2m',12,24,'crampon1923','Timothée, étant tombé lui-même entre les mains des soldats de Dosithée et de Sosipater, les conjura avec beaucoup d''astuce de le laisser partir sain et sauf, affirmant qu''il tenait en son pouvoir les parents et les frères de beaucoup d''entre eux et, que s''il mourrait, ils ne seraient pas épargnés.'),
('2m',12,25,'crampon1923','Il les assura par de longs discours qu''il était résolu à renvoyer ces hommes sans leur faire aucun mal, si bien que les Juifs le relâchèrent pour sauver leurs frères.'),
('2m',12,26,'crampon1923','Cependant Judas marcha sur Carnion et le sanctuaire d''Atargatis, où il tua vingt-cinq mille hommes.'),
('2m',12,27,'crampon1923','Après avoir mis en déroute et exterminé ces ennemis, Judas conduisit son armée contre Ephron, ville forte où habitait une multitude de diverses nations; de robustes jeunes gens rangés devant les murailles, les défendaient vaillamment, et la ville même était pourvue d''une quantité de machines et de traits.'),
('2m',12,28,'crampon1923','Mais les Juifs, ayant invoqué le Tout-Puissant, Celui qui brise par sa puissance les forces de l''ennemi, se rendirent maîtres de la ville et couchèrent par terre vingt-cinq mille des hommes qui l''occupaient.'),
('2m',12,29,'crampon1923','Partis de là, ils marchèrent contre la ville des Scythes, à six cents stades de Jérusalem.'),
('2m',12,30,'crampon1923','Mais les Juifs qui y résidaient ayant témoigné qu''ils avaient été traités avec bienveillance par les habitants, et que, dans les temps malheureux, ils en avaient reçu de bons offices,'),
('2m',12,31,'crampon1923','Judas et les siens remercièrent les Scythopolitains et les exhortèrent à continuer dans la suite leur bienveillance envers ceux de leur race. Après quoi, ils rentrèrent à Jérusalem, au moment où allait commencer la fête des Semaines.'),
('2m',12,32,'crampon1923','Après la Pentecôte, ils marchèrent contre Gorgias, qui commandait dans l''Idumée.'),
('2m',12,33,'crampon1923','Celui-ci sortit, ayant avec lui trois mille fantassins et quatre cents cavaliers.'),
('2m',12,34,'crampon1923','On en vint aux mains, et il arriva qu''un petit nombre de Juifs tombèrent.'),
('2m',12,35,'crampon1923','Un certain Dosithée, cavalier du corps de Bacénor, homme vaillant, se saisit de Gorgias et, le tirant par sa chlamyde, il l''entraînait vigoureusement, désirant prendre vivant cet homme maudit; mais un des cavaliers Thraces se jetant sur Dosithée, lui trancha l''épaule, et Gorgias put s''enfuir à Marésa.'),
('2m',12,36,'crampon1923','Cependant les hommes d''Esdrin combattaient depuis longtemps et se trouvaient épuisés de fatigue; alors Judas supplia le Seigneur de se montrer leur auxiliaire et leur chef dans le combat.'),
('2m',12,37,'crampon1923','Puis entonnant à haute voix, dans la langue de ses pères, le cri de guerre avec les hymnes, il tomba à l''improviste sur les hommes de Gorgias et les mit en déroute.'),
('2m',12,38,'crampon1923','Ensuite Judas, ayant rallié son armée, la conduisit à la ville d''Odollam, et, le septième jour de la semaine étant arrivé, ils se purifièrent selon la coutume et célébrèrent le sabbat en ce lieu.'),
('2m',12,39,'crampon1923','Le jour suivant, Judas vint avec les siens, selon qu''il était nécessaire, relever les corps de ceux qui avaient été tués, pour les inhumer avec leurs proches dans les tombeaux de leurs pères.'),
('2m',12,40,'crampon1923','Ils trouvèrent, sous les tuniques de chacun des morts, des objets consacrés, provenant des idoles de Jamnia et que la loi interdit aux Juifs; il fut donc évident pour tous que cela avait été la cause de leur mort.'),
('2m',12,41,'crampon1923','Tous bénirent donc le Seigneur, juste juge qui rend manifestes les choses cachées.'),
('2m',12,42,'crampon1923','Puis ils se mirent en prières, demandant que le péché commis fût entièrement pardonné; et le valeureux Judas exhorta le peuple à se garder pur de péché, ayant sous les yeux les conséquences du péché de ceux qui étaient tombés.'),
('2m',12,43,'crampon1923','Puis, ayant fait une collecte où il recueillit la somme de deux mille drachmes, il l''envoya à Jérusalem pour être employée à un sacrifice expiatoire. Belle et noble action, inspirée par la pensée de la résurrection!'),
('2m',12,44,'crampon1923','Car, s''il n''avait pas cru que les soldats tués dans la bataille dussent ressusciter, c''eût été chose inutile et vaine de prier pour des morts.'),
('2m',12,45,'crampon1923','Il considérait en outre qu''une très belle récompense est réservée à ceux qui s''endorment dans la piété,'),
('2m',12,46,'crampon1923','et c''est là une pensée sainte et pieuse. Voilà pourquoi il fit ce sacrifice expiatoire pour les morts, afin qu''ils fussent délivrés de leurs péchés.'),
('2m',13,1,'crampon1923','L''an cent quarante-neuf, Judas et ses compagnons apprirent qu''Antiochus Eupator marchait contre la Judée avec des troupes nombreuses,'),
('2m',13,2,'crampon1923','et que Lysias, son tuteur et son ministre, l''accompagnait, chacun d''eux à la tête d''une armée grecque de cent dix mille fantassins, cinq mille trois cents cavaliers, vingt-deux éléphants et trois cents chars armés de faux.'),
('2m',13,3,'crampon1923','Ménélas aussi se joignit à eux et, avec une grande fourberie, il excitait Antiochus, non pour le salut de sa patrie, mais espérant être rétabli dans sa dignité.'),
('2m',13,4,'crampon1923','Cependant le Roi des rois éveilla contre ce scélérat la colère d''Antiochus, et Lysias ayant démontré au roi que Ménélas était la cause de tous les maux, Antiochus ordonna de le conduire à Bérée, et de l''y mettre à mort selon la coutume du lieu.'),
('2m',13,5,'crampon1923','Or il y avait à Bérée une tour de cinquante coudées, remplie de cendres, et couronnée d''une machine tournante qui de tous côtés fait glisser dans la cendre.'),
('2m',13,6,'crampon1923','C''est là que le peuple de Bérée précipite, pour le faire périr, l''homme coupable de vol sacrilège, ou encore celui qui a commis certains autres grands crimes.'),
('2m',13,7,'crampon1923','Ainsi mourut Ménélas, ce violateur de la loi, et c''est très justement qu''il ne fut pas déposé dans la terre.'),
('2m',13,8,'crampon1923','Car il avait maintes fois péché contre l''autel, dont le feu et la cendre étaient purs, et c''est dans la cendre qu''il trouva la mort.'),
('2m',13,9,'crampon1923','Le roi s''avançait donc, l''esprit tout rempli de pensées barbares, disposé à traiter les Juifs plus cruellement que n''avait fait son père.'),
('2m',13,10,'crampon1923','Dès que Judas le sut, il ordonna au peuple d''invoquer nuit et jour le Seigneur, pour que cette fois encore, il vînt au secours de ceux'),
('2m',13,11,'crampon1923','qui allaient être privés de la loi, de leur patrie et du saint temple, et qu''il ne permît pas que ce peuple qui commençait seulement à respirer, tombât sous la puissance des nations impies.'),
('2m',13,12,'crampon1923','Lorsque tous eurent ainsi prié ensemble et imploré le Seigneur miséricordieux avec larmes et avec jeûnes, se tenant continuellement à genoux pendant trois jours, Judas leur adressa une exhortation et leur commanda de se tenir prêts.'),
('2m',13,13,'crampon1923','Puis, s''étant entretenu à part avec les anciens, il résolut de ne pas attendre que le roi eût fait entrer son armée en Judée et se fût rendu maître de Jérusalem, mais de se mettre incontinent en marche et de tout terminer avec l''aide du Seigneur.'),
('2m',13,14,'crampon1923','Abandonnant donc au Créateur du monde le sort des armes, il exhorta ses compagnons à combattre bravement jusqu''à la mort pour les lois, pour le temple, pour la ville sainte, pour la patrie et les institutions, et il conduisit son armée aux environs de Modin.'),
('2m',13,15,'crampon1923','Après avoir donné aux siens ce mot d''ordre: " Victoire par Dieu! " il choisit les plus braves parmi les jeunes guerriers et attaqua pendant la nuit la tente du roi; il tua dans le camp quatre mille hommes, en y ajoutant le plus grand des éléphants, avec la troupe qu''il portait dans une tour.'),
('2m',13,16,'crampon1923','Enfin ils remplirent le camp d''épouvante et de confusion, et se retirèrent avec un plein succès.'),
('2m',13,17,'crampon1923','Quand le jour commença à poindre, tout était achevé, grâce à la protection dont le Seigneur couvrait Judas.'),
('2m',13,18,'crampon1923','Après avoir ainsi éprouvé l''audace des Juifs, le roi essaya de s''emparer des places par ruse.'),
('2m',13,19,'crampon1923','Il marcha contre Bethsur, forte citadelle des Juifs; mais il était repoussé, il subissait des échecs, il avait le dessous.'),
('2m',13,20,'crampon1923','Or Judas fit passer aux assiégés ce qui leur était nécessaire.'),
('2m',13,21,'crampon1923','Cependant Rhodocus, de l''armée des Juifs, dévoilait à l''ennemi les secrets; on fit une enquête, on le surprit et on le mit en prison.'),
('2m',13,22,'crampon1923','Pour la seconde fois le roi parlementa avec les assiégés, leur tendit la main, prit la leur, se retira,'),
('2m',13,23,'crampon1923','attaqua les guerriers de Judas et fut battu. Mais ayant appris que Philippe, laissé par Epiphane à la tête des affaires, s''était révolté à Antioche, il en fut consterné; il donna aux Juifs de bonnes paroles, se soumit et jura toutes conditions équitables; il se réconcilia et offrit un sacrifice, il honora le temple, traita humainement le saint lieu,'),
('2m',13,24,'crampon1923','et fit bon accueil à Machabée; il le laissa comme gouverneur militaire depuis Ptolémaïs jusqu''aux Gerrhéniens.'),
('2m',13,25,'crampon1923','Mais lorsque le roi vint à Ptolémaïs, les habitants témoignèrent leur mécontentement au sujet du traité, dont ils s''indignaient et ne voulaient point exécuter les conditions.'),
('2m',13,26,'crampon1923','Lysias monta sur le tribunal, défendit les conventions autant que possible, persuada, disposa favorablement les esprits et partit pour Antioche. Ce fut ainsi qu''eurent lieu l''attaque et la retraite du roi.'),
('2m',14,1,'crampon1923','Trois ans s''étant écoulés. Judas et ses compagnons apprirent que Démétrius. fils de Séleucus, ayant fait voile du port de Tripoli avec une armée nombreuse et une flotte,'),
('2m',14,2,'crampon1923','s''était rendu maître du pays et avait mis à mort Antiochus et son tuteur Lysias.'),
('2m',14,3,'crampon1923','Un certain Alcime, précédemment devenu grand prêtre, mais qui s''était volontairement souillé dans les temps de confusion, comprenant qu''il ne lui restait plus aucun espoir de salut ni d''accès à l''autel saint,'),
('2m',14,4,'crampon1923','vint trouver le roi Démétrius en l''an cent cinquante, lui offrant une couronne d''or avec une palme et de plus quelques rameaux d''olivier, tels qu''il est d''usage d''en offrir au temple; et, ce jour-là, il ne fit rien de plus.'),
('2m',14,5,'crampon1923','Mais il trouva une occasion favorable à sa perversité, quand Démétrius, l''ayant appelé dans son conseil, l''interrogea sur les dispositions et les desseins des Juifs.'),
('2m',14,6,'crampon1923','Il répondit: " Les Juifs que l''on nomme Assidéens, dont Judas Machabée est le chef, fomentent la guerre et les séditions, et ne souffrent pas que le royaume soit en paix.'),
('2m',14,7,'crampon1923','Voilà pourquoi, ayant été exclu de mes honneurs héréditaires, je veux dire du souverain pontificat, je suis venu ici,'),
('2m',14,8,'crampon1923','d''abord avec le désir sincère de soutenir les intérêts du roi, ensuite dans le but de procurer aussi le bien-être de mes concitoyens; car la témérité de ces hommes cause à toute notre nation les plus grands maux.'),
('2m',14,9,'crampon1923','Toi donc, ô roi, quand tu auras pris connaissance de toutes ces choses, pourvois au salut de notre pays et de notre nation opprimée, selon cette bonté qui te rend affable envers tous.'),
('2m',14,10,'crampon1923','Car, tant que Judas sera en vie, il sera impossible de ramener la paix dans l''Etat. "'),
('2m',14,11,'crampon1923','Dès qu''il eut parlé de la sorte, les autres amis du roi qui détestaient Judas, enflammèrent encore davantage Démétrius.'),
('2m',14,12,'crampon1923','Il appela aussitôt Nicanor, qui avait commandé l''escadron des éléphants, le nomma général de l''année de Judée et le fit partir,'),
('2m',14,13,'crampon1923','avec ordre écrit de faire périr Judas, de disperser ses compagnons, et d''installer Alcime grand prêtre du temple auguste.'),
('2m',14,14,'crampon1923','Les Gentils, qui s''étaient enfuis de la Judée devant Judas, se rassemblèrent par troupes autour de Nicanor, pensant bien que l''infortune et le malheur des Juifs tourneraient à leur propre avantage.'),
('2m',14,15,'crampon1923','Quand les Juifs apprirent la marche de Nicanor et l''attaque des nations, ils se couvrirent de poussière et ils prièrent Celui qui avait établi son peuple à jamais, et avait sans cesse protégé son héritage par des signes manifestes.'),
('2m',14,16,'crampon1923','Sur l''ordre de leur chef, ils partirent sur-le-champ et en vinrent aux mains avec l''ennemi, au bourg de Dessau.'),
('2m',14,17,'crampon1923','Simon, frère de Judas, avait engagé le combat contre Nicanor, mais, déconcerté par l''apparition subite de l''ennemi, il subit un léger échec.'),
('2m',14,18,'crampon1923','Toutefois Nicanor, apprenant quelle était la valeur de Judas et de ses compagnons, et avec quelle intrépidité ils se battaient pour leur patrie, craignit de s''en remettre au jugement par le sang.'),
('2m',14,19,'crampon1923','Il envoya donc Posidonius, Théodote et Mattathias pour tendre la main aux Juifs et recevoir la leur.'),
('2m',14,20,'crampon1923','Après avoir longtemps examiné ces propositions, le général les communiqua à l''armée, et, quand il fut évident que tous étaient du même avis, on consentit à traiter.'),
('2m',14,21,'crampon1923','On fixa un jour où les deux chefs se réuniraient seul à seul; Judas s''y présenta, et des sièges d''honneur furent placés auprès d''eux.'),
('2m',14,22,'crampon1923','Cependant Judas avait aposté des hommes armés dans des positions avantageuses, dans la crainte de quelque perfidie soudaine de la part de l''ennemi. Ils eurent un entretien convenable.'),
('2m',14,23,'crampon1923','Nicanor passa quelque temps à Jérusalem, sans y faire rien d''injuste, et il congédia les foules qui s''étaient rassemblées par troupeaux.'),
('2m',14,24,'crampon1923','Il avait avec Judas les relations les plus amicales, éprouvant pour lui une inclination de cœur.'),
('2m',14,25,'crampon1923','Il l''engagea à se marier et à avoir des enfants; Judas se maria, vécut heureusement et jouit de la vie.'),
('2m',14,26,'crampon1923','Alcime, voyant l''amitié qui régnait entre eux, prit une copie du traité conclu, et se rendit auprès de Démétrius; il lui dit que Nicanor avait des desseins contraires aux intérêts de l''Etat, puisqu''il avait désigné pour le remplacer, Judas, un ennemi du royaume.'),
('2m',14,27,'crampon1923','Le roi en fut hors de lui; excité par les calomnies de ce scélérat, il écrivit à Nicanor qu''il avait un grand déplaisir des conventions conclues et qu''il lui ordonnait de lui envoyer sans délai à Antioche Machabée, chargé de chaînes.'),
('2m',14,28,'crampon1923','Au reçu de cette lettre, Nicanor fut consterné; il lui en coûtait beaucoup d''avoir à violer des conventions arrêtées, sans que Judas eût rien fait d''injuste.'),
('2m',14,29,'crampon1923','Mais, comme il ne lui était pas permis de résister au roi, il cherchait une occasion favorable pour exécuter son ordre par quelque stratagème.'),
('2m',14,30,'crampon1923','Machabée, de son côté, remarquant que Nicanor se montrait plus réservé à son égard et que leurs relations ordinaires étaient moins amicales, comprit que cette froideur n''annonçait rien de bon; il rassembla un grand nombre des siens et se déroba à Nicanor.'),
('2m',14,31,'crampon1923','Quand Nicanor vit qu''il avait été surpris par l''énergique résolution de Judas, il se rendit au temple auguste et saint, pendant que les prêtres offraient les sacrifices accoutumés, et leur ordonna de lui livrer cet homme.'),
('2m',14,32,'crampon1923','Comme ils assuraient avec serment qu''ils ignoraient où était l''homme qu''il cherchait, Nicanor leva la main vers le temple')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('2m',14,33,'crampon1923','et jura, en disant: " Si vous ne me livrez Judas enchaîné, je raserai au niveau du sol ce sanctuaire de Dieu, je détruirai l''autel et j''élèverai ici un temple magnifique à Bacchus. "'),
('2m',14,34,'crampon1923','Ayant ainsi parlé, il se retira. De leur côté, les prêtres, levant les mains vers le ciel, invoquèrent Celui qui de tout temps a combattu pour notre peuple, en disant:'),
('2m',14,35,'crampon1923','" Vous, Seigneur, qui n''avez besoin de rien, il vous a plu que le temple où vous habitez soit au milieu de nous.'),
('2m',14,36,'crampon1923','Maintenant donc, seigneur, saint de toute sainteté, préservez à jamais de toute souillure cette demeure récemment purifiée. "'),
('2m',14,37,'crampon1923','Or un certain Razis, un des anciens de Jérusalem, fut dénoncé à Nicanor; c''était un homme aimant ses concitoyens, de très bonne renommée, et appelé le père des Juifs, à cause de sa bienfaisance.'),
('2m',14,38,'crampon1923','Car dans les temps antérieurs, où il fallait éviter tout commerce avec les païens, il s''était attiré une accusation de judaïsme et, avec une invincible constance, il avait exposé, pour le judaïsme, son corps et sa vie.'),
('2m',14,39,'crampon1923','Nicanor, voulant donner une preuve de son hostilité contre les Juifs, envoya plus de cinq cents soldats pour le prendre;'),
('2m',14,40,'crampon1923','car il ne doutait pas que son arrestation ne fût un grand coup porté aux Juifs.'),
('2m',14,41,'crampon1923','Cette troupe était sur le point de s''emparer de la tour et de forcer l''entrée du vestibule; déjà l''ordre était donné d''y mettre le feu et de brûler les portes. Mais, au moment où il allait être pris, Razis se jeta sur son épée,'),
('2m',14,42,'crampon1923','aimant mieux mourir noblement que de tomber entre des mains criminelles et de subir des outrages indignes de sa propre noblesse.'),
('2m',14,43,'crampon1923','Mais, comme, dans sa précipitation, il ne s''était pas frappé au bon endroit, voyant la foule se ruer par les portes, il courut avec courage en haut de la muraille et se précipita bravement sur la foule.'),
('2m',14,44,'crampon1923','Tous reculèrent aussitôt, et il se forma un espace vide au milieu duquel il tomba.'),
('2m',14,45,'crampon1923','Respirant encore et l''âme enflammée, il se releva, tout ruisselant de sang, et malgré d''horribles blessures, il traversa la foule en courant et, debout sur une roche qui se dressait là,'),
('2m',14,46,'crampon1923','ayant déjà perdu tout son sang, il s''arracha les entrailles, les jeta de ses deux mains sur la foule, et pria le Maître de la vie et de l''âme de les lui rendre un jour; ce fut ainsi qu''il mourut.'),
('2m',15,1,'crampon1923','Cependant Nicanor apprit que Judas et ses compagnons étaient postés du côté de la Samarie, et il résolut de les attaquer en toute sûreté le jour du sabbat.'),
('2m',15,2,'crampon1923','Les Juifs qui le suivaient par contrainte, lui dirent: " Ne les massacre pas d''une manière si féroce et si barbare, mais rends gloire au jour qui a été honoré et sanctifié par Celui qui gouverne tout. "'),
('2m',15,3,'crampon1923','Alors ce triple scélérat demanda s''il y avait au ciel un souverain qui eût ordonné de célébrer le jour du sabbat.'),
('2m',15,4,'crampon1923','Ils lui répondirent: " C''est le Seigneur, Dieu vivant, lui le souverain Maître au ciel, qui a ordonné de solenniser le septième jour ". —'),
('2m',15,5,'crampon1923','" Et moi aussi, reprit l''autre, je suis souverain sur la terre, et je commande qu''on prenne les armes et qu''on fasse le service du roi. " Pourtant il ne réussit pas à réaliser son mauvais dessein.'),
('2m',15,6,'crampon1923','Pendant que Nicanor, dans son orgueilleuse sécurité, songeait à dresser un trophée commun de Judas et de ses compagnons,'),
('2m',15,7,'crampon1923','Machabée ne cessait d''avoir confiance, avec pleine espérance, qu''il obtiendrait assistance de la part du Seigneur.'),
('2m',15,8,'crampon1923','Il exhortait les siens à ne pas craindre l''attaque des nations, mais, se souvenant des secours que le Ciel leur avait accordés dans le passé, à compter que le Tout-Puissant leur donnerait encore en ce moment aide et victoire.'),
('2m',15,9,'crampon1923','Il les encouragea en citant la loi et les prophètes, et leur rappela en outre les combats qu''ils avaient soutenus, et leur inspira ainsi une grande ardeur.'),
('2m',15,10,'crampon1923','Après avoir relevé leur courage, il leur donna ses ordres, leur représentant en même temps la perfidie des nations et leur violation des serments.'),
('2m',15,11,'crampon1923','Quand il eut armé chacun d''eux, non pas tant de la sécurité que donnent les boucliers et les lances, mais de la confiance qu''inspirent les bonnes paroles, il leur raconta en outre un songe digne de foi, une vision réelle, qui les réjouit tous.'),
('2m',15,12,'crampon1923','Voici ce qu''il avait vu: Le grand prêtre Onias, cet homme de bien, d''un abord modeste et de mœurs douces, distingué dans son langage et adonné dès l''enfance à toutes les pratiques de la vertu, il l''avait vu, les mains étendues, priant pour toute la nation des Juifs.'),
('2m',15,13,'crampon1923','Ensuite lui était apparu, de la même manière, un homme distingué par son grand âge et son air de dignité, d''un aspect admirable, et entouré de la plus imposante majesté.'),
('2m',15,14,'crampon1923','Onias, prenant la parole, lui avait dit: " Celui-ci est l''ami de ses frères, qui prie beaucoup pour le peuple et pour la ville sainte, Jérémie, le prophète de Dieu. "'),
('2m',15,15,'crampon1923','Puis Jérémie, étendant la main droite, avait donné à Judas une épée d''or et, en la lui remettant, il avait dit:'),
('2m',15,16,'crampon1923','" Prends cette sainte épée, c''est un don de Dieu; avec elle tu briseras tes ennemis. "'),
('2m',15,17,'crampon1923','Animés par ces nobles paroles de Judas, bien capables d''exciter à la vaillance et de fortifier les âmes des jeunes gens, ils résolurent de ne pas se retrancher dans un camp, mais de se jeter hardiment sur l''ennemi, et, dans un combat acharné, de décider l''affaire, puisque la ville, la religion et le temple étaient en péril.'),
('2m',15,18,'crampon1923','Car, dans cette lutte, ils songeaient moins à leurs femmes, à leurs enfants, à leurs frères et à leurs proches; leur plus grande crainte, et la première, était pour le temple saint.'),
('2m',15,19,'crampon1923','L''angoisse des citoyens restés dans la ville n''était pas moindre, inquiets qu''ils étaient sur l''issue du combat qui allait se livrer dehors.'),
('2m',15,20,'crampon1923','Pendant que tous attendaient le prochain dénouement, que déjà les ennemis se rassemblaient, en ordre de bataille, que les éléphants étaient disposés à la place convenable et les cavaliers sur les ailes,'),
('2m',15,21,'crampon1923','Machabée, voyant cette immense multitude, l''appareil varié de leurs armes, l''aspect farouche des éléphants, habilement disposés, leva les mains au ciel et invoqua le Seigneur qui fait des prodiges; car il savait que la victoire ne vient pas de la force des armes, mais que c''est Dieu qui en décide et l''accorde à ceux qui en sont dignes.'),
('2m',15,22,'crampon1923','Voici quelle fut sa prière: " Vous, souverain Maître, qui avez envoyé votre ange, sous Ezéchias, roi de Juda, et qui avez exterminé cent quatre-vingt cinq mille hommes du camp de Sennachérib,'),
('2m',15,23,'crampon1923','maintenant encore, ô Souverain des cieux, envoyez votre bon ange devant nous, pour qu''il répande la crainte et l''effroi.'),
('2m',15,24,'crampon1923','Que par la grandeur de votre bras soient frappés ceux qui sont venus, le blasphème à la bouche, contre votre peuple saint! " Telles furent ses paroles.'),
('2m',15,25,'crampon1923','Cependant Nicanor et son armée s''avançaient au son des trompettes et des chants de guerre.'),
('2m',15,26,'crampon1923','Judas et les siens engagèrent le combat en invoquant et en priant.'),
('2m',15,27,'crampon1923','Combattant de leurs bras et priant Dieu dans leurs cœurs, ils couchèrent par terre au moins trente-cinq mille hommes, et ils se réjouirent grandement du secours manifeste de Dieu.'),
('2m',15,28,'crampon1923','L''affaire terminée, pendant qu''ils se débandaient joyeusement, ils reconnurent que Nicanor était tombé, revêtu de son armure.'),
('2m',15,29,'crampon1923','Alors, au milieu des clameurs et de la confusion, ils bénirent le Maître souverain dans la langue de leurs pères.'),
('2m',15,30,'crampon1923','Et celui qui s''était consacré tout entier, corps et âme, à la défense de ses concitoyens, qui avait conservé pour ses compatriotes l''affection de sa jeunesse, Judas ordonna de couper la tête de Nicanor et sa main avec son bras, et de les porter à Jérusalem.'),
('2m',15,31,'crampon1923','Il s''y rendit lui-même, convoqua ses compatriotes et les prêtres, et, s''étant placé devant l''autel, il envoya chercher ceux de la citadelle,'),
('2m',15,32,'crampon1923','et il leur montra la tête du criminel Nicanor et la main que ce blasphémateur avait étendue avec tant d''insolence contre la demeure sainte du Tout-Puissant.'),
('2m',15,33,'crampon1923','Puis, ayant coupé la langue de l''impie Nicanor, il voulut qu''on la donnât par morceaux en pâture aux oiseaux, et qu''on suspendit en face du temple le prix remporté par sa folie.'),
('2m',15,34,'crampon1923','Tous firent monter vers le ciel des bénédictions au Seigneur glorieux, en disant: " Béni soit Celui qui a gardé sa demeure sans souillure! "'),
('2m',15,35,'crampon1923','Judas attacha la tête de Nicanor à la citadelle, comme un signe manifeste et visible à tous du secours du Seigneur.'),
('2m',15,36,'crampon1923','D''un commun accord on rendit un édit public ordonnant de ne pas laisser passer ce jour sans solennité,'),
('2m',15,37,'crampon1923','mais de célébrer le treizième jour du douzième mois, appelé Adar en syriaque, la veille du jour dit de Mardochée.'),
('2m',15,38,'crampon1923','Ainsi se passèrent les choses concernant Nicanor, et, comme à partir de ce temps, la ville demeura en possession des Hébreux, moi aussi je finirai là mon récit.'),
('2m',15,39,'crampon1923','Si la disposition des faits en est heureuse et bien conçue, c''est aussi ce que j''ai voulu; si elle est imparfaite et médiocre, c''est tout ce que j''ai pu faire. Car de même qu''il ne vaut rien de boire seulement du vin ou seulement de l''eau, tandis que le vin mêlé à l''eau est bon et produit une agréable jouissance, de même c''est l''art de disposer le récit qui charme les oreilles de ceux qui lisent l''histoire. C''est donc ici que je termine.'),
('jb',1,1,'crampon1923','Il y avait dans le pays de Hus un homme nommé Job; cet homme était intègre, droit, craignant Dieu et éloigné du mal.'),
('jb',1,2,'crampon1923','Il lui naquit sept fils et trois filles.'),
('jb',1,3,'crampon1923','Il possédait sept mille brebis, trois mille chameaux, cinq cents paires de bœufs, cinq cent ânesses et un très grand nombre de serviteurs; et cet homme était le plus grand de tous les fils de l''Orient.'),
('jb',1,4,'crampon1923','Ses fils avaient coutume d''aller les uns chez les autres et de se donner un festin, chacun à leur tour, et ils envoyaient inviter leurs trois sœurs à venir manger et boire avec eux.'),
('jb',1,5,'crampon1923','Et, quand le cercle des festins était fini, Job envoyait chercher ses fils et les purifiait; puis il se levait de bon matin et offrait un holocauste pour chacun d''eux, car il se disait: « Peut-être mes fils ont-ils péché et offensé Dieu dans leur cœur!... » Et Job faisait ainsi chaque fois.'),
('jb',1,6,'crampon1923','Il arriva un jour que, les fils de Dieu étant venus se présenter devant Yahweh, Satan vint aussi au milieu d''eux.'),
('jb',1,7,'crampon1923','Et Yahweh dit à Satan: « D''où viens-tu? » Satan répondit à Yahweh et dit: « De parcourir le monde et de m''y promener. »'),
('jb',1,8,'crampon1923','Yahweh dit à Satan: « As-tu remarqué mon serviteur Job? Il n''y a pas d''homme comme lui sur la terre, intègre, droit, craignant Dieu et éloigné du mal. »'),
('jb',1,9,'crampon1923','Satan répondit à Yahweh: « Est-ce gratuitement que Job craint Dieu?'),
('jb',1,10,'crampon1923','Ne l''as-tu pas entouré comme d''une clôture, lui, sa maison et tout ce qui lui appartient? Tu as béni l''œuvre de ses mains, et ses troupeaux couvrent le pays.'),
('jb',1,11,'crampon1923','Mais étends la main, touche à tout ce qui lui appartient, et on verra s''il ne te maudit pas en face! »'),
('jb',1,12,'crampon1923','Yahweh dit à Satan: « Voici, tout ce qui lui appartient est en ton pouvoir; seulement ne porte pas la main sur lui. » Et Satan se retira de devant la face de Yahweh.'),
('jb',1,13,'crampon1923','Or un jour que ses fils et ses filles mangeaient et buvaient du vin dans la maison de leur frère aîné,'),
('jb',1,14,'crampon1923','un messager vint dire à Job: « Les bœufs étaient à labourer et les ânesses paissaient autour d''eux;'),
('jb',1,15,'crampon1923','tout à coup les Sabéens sont survenus et les ont enlevés. Ils ont passé les serviteurs au fil de l''épée, et je me suis échappé seul pour te l''annoncer. »'),
('jb',1,16,'crampon1923','Il parlait encore, lorsqu''un autre arriva et dit: « Le feu de Dieu est tombé du ciel; il a embrasé les brebis et les serviteurs et les a dévorés, et je me suis échappé seul pour te l''annoncer. »'),
('jb',1,17,'crampon1923','Il parlait encore, lorsqu''un autre arriva et dit: « Les Chaldéens, partagés en trois bandes, se sont jetés sur les chameaux et les ont enlevés. Ils ont passé les serviteurs au fil de l''épée, et je me suis échappé seul pour te l''annoncer. »'),
('jb',1,18,'crampon1923','Il parlait encore, lorsqu''un autre arriva et dit: « Tes fils et tes filles mangeaient et buvaient du vin chez leur frère aîné,'),
('jb',1,19,'crampon1923','et voilà qu''un grand vent s''est élevé de l''autre côté du désert et a saisi les quatre coins de la maison; elle s''est écroulée sur les jeunes gens, et ils sont morts, et je me suis échappé seul pour te l''annoncer. »'),
('jb',1,20,'crampon1923','Alors Job se leva, il déchira son manteau et se rasa la tête; puis, se jetant par terre, il adora'),
('jb',1,21,'crampon1923','et dit: « Nu je suis sorti du sein de ma mère, et nu j''y retournerai. Yahweh a donné, Yahweh a ôté; que le nom de Yahweh soit béni! »'),
('jb',1,22,'crampon1923','En tout cela, Job ne pécha point et ne dit rien d''insensé contre Dieu.'),
('jb',2,1,'crampon1923','Il arriva un jour que, les fils de Dieu étant venus se présenter devant Yahweh, Satan vint aussi au milieu d''eux se présenter devant Yahweh.'),
('jb',2,2,'crampon1923','Et Yahweh dit à Satan: « D''où viens-tu? » Satan répondit à Yahweh et dit: « De parcourir le monde et de m''y promener. »'),
('jb',2,3,'crampon1923','Yahweh dit à Satan: « As-tu remarqué mon serviteur Job? Il n''y a pas d''homme comme lui sur la terre, intègre, droit, craignant Dieu et éloigné du mal. Il persévère toujours dans son intégrité, quoique tu m''aies provoqué à le perdre sans raison. »'),
('jb',2,4,'crampon1923','Satan répondit à Yahweh et dit: « Peau pour peau! L''homme donne ce qu''il possède pour conserver sa vie.'),
('jb',2,5,'crampon1923','Mais étends ta main, touche ses os et sa chair, et on verra s''il ne te maudit pas en face. »'),
('jb',2,6,'crampon1923','Yahweh dit à Satan: « Voici que je le livre entre tes mains; seulement épargne sa vie! »'),
('jb',2,7,'crampon1923','Et Satan se retira de devant la face de Yahweh. Et il frappa Job d''une lèpre maligne depuis la plante des pieds jusqu''au sommet de la tête.'),
('jb',2,8,'crampon1923','Et Job prit un tesson pour gratter ses plaies et il s''assit sur la cendre.'),
('jb',2,9,'crampon1923','Et sa femme lui dit: « Tu persévère encore dans ton intégrité! Maudis Dieu et meurs! »'),
('jb',2,10,'crampon1923','Il lui dit: « Tu parles comme une femme insensée. Nous recevons de Dieu le bien, et nous n''en recevrions pas aussi le mal? » En tout cela, Job ne pécha point par ses lèvres.'),
('jb',2,11,'crampon1923','Trois amis de Job, Eliphaz de Théman, Baldad de Suhé, et Sophar de Naama, apprirent tous les malheurs qui étaient venus sur lui; ils partirent chacun de leur pays et se concertèrent pour venir le plaindre et le consoler.'),
('jb',2,12,'crampon1923','Ayant de loin levé les yeux, ils ne le reconnurent pas, et ils élevèrent la voix et pleurèrent; ils déchirèrent chacun leur manteau, et jetèrent de la poussière vers le ciel au-dessus de leurs têtes.'),
('jb',2,13,'crampon1923','Et ils se tinrent assis à terre auprès de lui sept jours et sept nuits, sans qu''aucun d''eux lui dit une parole, parce qu''ils voyaient combien sa douleur était excessive.'),
('jb',3,1,'crampon1923','Alors Job ouvrit la bouche et maudit le jour de sa naissance.'),
('jb',3,2,'crampon1923','Job prit la parole et dit:'),
('jb',3,3,'crampon1923','Périsse le jour où je suis né, et la nuit qui a dit: « Un homme est conçu! »'),
('jb',3,4,'crampon1923','Ce jour, qu''il se change en ténèbres, que Dieu d''en haut n''en ait pas souci, que la lumière ne brille pas sur lui!'),
('jb',3,5,'crampon1923','Que les ténèbres et l''ombre de la mort le revendiquent, qu''un nuage épais le couvre, que l''éclipse de sa lumière jette l''épouvante!'),
('jb',3,6,'crampon1923','Cette nuit, que les ténèbres en fassent leur proie, qu''elle ne compte pas dans les jours de l''année, qu''elle n''entre pas dans la supputation des mois!'),
('jb',3,7,'crampon1923','Que cette nuit soit un désert stérile, qu''on n''y entende pas de cri d''allégresse!'),
('jb',3,8,'crampon1923','Que ceux-là la maudissent, qui maudissent les jours, qui savent évoquer Léviathan!'),
('jb',3,9,'crampon1923','Que les étoiles de son crépuscule s''obscurcissent, qu''elle attende la lumière, sans qu''elle vienne, et qu''elle ne voie point les paupières de l''aurore,'),
('jb',3,10,'crampon1923','parce qu''elle ne m''a pas fermé les portes du sein, et n''a pas dérobé la souffrance à mes regards!'),
('jb',3,11,'crampon1923','Que ne suis-je mort dès le ventre de ma mère, au sortir de ses entrailles que n''ai-je expiré!'),
('jb',3,12,'crampon1923','Pourquoi ai-je trouvé deux genoux pour me recevoir, et pourquoi deux mamelles à sucer?'),
('jb',3,13,'crampon1923','Maintenant je serais couché et en paix, je dormirais et je me reposerais'),
('jb',3,14,'crampon1923','avec les rois et les grands de la terre, qui se sont bâti des mausolées;'),
('jb',3,15,'crampon1923','avec les princes qui avaient de l''or, et remplissaient d''argent leur demeures.'),
('jb',3,16,'crampon1923','Ou bien, comme l''avorton ignoré, je n''existerais pas, comme ces enfants qui n''ont pas vu la lumière.'),
('jb',3,17,'crampon1923','Là les méchants n''exercent plus leurs violences, là se repose l''homme épuisé de forces;'),
('jb',3,18,'crampon1923','les captifs y sont tous en paix, ils n''entendent plus la voix de l''exacteur.'),
('jb',3,19,'crampon1923','Là se trouvent le petit et le grand, l''esclave affranchi de son maître.'),
('jb',3,20,'crampon1923','Pourquoi donner la lumière aux malheureux, et la vie à ceux dont l''âme est remplie d''amertume,'),
('jb',3,21,'crampon1923','qui espèrent la mort, et la mort ne vient pas, qui la cherchent plus ardemment que les trésors,'),
('jb',3,22,'crampon1923','qui sont heureux, qui tressaillent d''aise et se réjouissent quand ils ont trouvé le tombeau;'),
('jb',3,23,'crampon1923','à l''homme dont la route est cachée et que Dieu enferme de toutes parts?'),
('jb',3,24,'crampon1923','Mes soupirs sont comme mon pain et mes gémissements se répandent comme l''eau.'),
('jb',3,25,'crampon1923','Ce que je crains, c''est ce qui m''arrive; ce que je redoute fond sur moi.'),
('jb',3,26,'crampon1923','Plus de tranquillité, plus de paix, plus de repos, et le trouble m''a saisi.'),
('jb',4,1,'crampon1923','Alors Eliphaz de Théman prit la parole et dit:'),
('jb',4,2,'crampon1923','Si nous risquons un mot, peut-être en seras-tu affligé; mais qui pourrait retenir ses paroles?'),
('jb',4,3,'crampon1923','Voilà que tu en as instruit plusieurs, que tu as fortifié les mains débiles,'),
('jb',4,4,'crampon1923','que tes paroles ont relevé ceux qui chancelaient, que tu as raffermi les genoux vacillants!...'),
('jb',4,5,'crampon1923','Et maintenant que le malheur vient à toi, tu faiblis; maintenant qu''il t''atteint, tu perds courage!...'),
('jb',4,6,'crampon1923','Ta crainte de Dieu n''était-elle pas ton espoir? Ta confiance n''était-elle pas dans la pureté de ta vie?'),
('jb',4,7,'crampon1923','Cherche dans ton souvenir: quel est l''innocent qui a péri? En quel lieu du monde les justes ont-ils été exterminés?'),
('jb',4,8,'crampon1923','Pour moi, je l''ai vu, ceux qui labourent l''iniquité et qui sèment l''injustice, en moissonnent les fruits.'),
('jb',4,9,'crampon1923','Au souffle de Dieu ils périssent, ils sont consumés par le vent de sa colère.'),
('jb',4,10,'crampon1923','Le rugissement du lion et sa voix tonnante sont étouffés, et les dents du jeune lion sont brisées;'),
('jb',4,11,'crampon1923','le lion périt faute de proie, et les petits de la lionne se dispersent.'),
('jb',4,12,'crampon1923','Une parole est arrivée furtivement jusqu''à moi, et mon oreille en a saisi le léger murmure.'),
('jb',4,13,'crampon1923','Dans le vague des visions de la nuit, à l''heure où un sommeil profond pèse sur les mortels,'),
('jb',4,14,'crampon1923','une frayeur et un tremblement me saisirent, et agitèrent tous mes os.'),
('jb',4,15,'crampon1923','Un esprit passait devant moi... Les poils de ma chair se hérissèrent.'),
('jb',4,16,'crampon1923','Il se dressa, — je ne reconnus pas son visage, — comme un spectre sous mes yeux. Un grand silence, puis j''entendis une voix:'),
('jb',4,17,'crampon1923','L''homme sera-t-il juste vis-à-vis de Dieu? Un mortel sera-t-il pur en face de son Créateur?'),
('jb',4,18,'crampon1923','Voici qu''il ne se fie pas à ses serviteurs, et qu''il découvre des fautes dans ses anges:'),
('jb',4,19,'crampon1923','combien plus en ceux qui habitent des maisons de boue, qui ont leurs fondements dans la poussière, qui seront réduits en poudre, comme par la teigne!'),
('jb',4,20,'crampon1923','Du matin au soir ils sont exterminés, et sans que nul y prenne garde, ils périssent pour jamais.'),
('jb',4,21,'crampon1923','La corde de leur tente est coupée, ils meurent avant d''avoir connu la sagesse.'),
('jb',5,1,'crampon1923','Appelle donc! Y aura-t-il quelqu''un qui te réponde? Vers lequel des saints te tourneras-tu?'),
('jb',5,2,'crampon1923','La colère tue l''insensé, et l''emportement fait mourir le fou.'),
('jb',5,3,'crampon1923','J''ai vu l''insensé étendre ses racines, et soudain j''ai maudit sa demeure.'),
('jb',5,4,'crampon1923','Plus de salut pour ses fils; on les écrase à la porte, et personne ne les défend.'),
('jb',5,5,'crampon1923','L''homme affamé dévore sa moisson, il franchit la haie d''épines et l''emporte; l''homme altéré engloutit ses richesses.'),
('jb',5,6,'crampon1923','Car le malheur ne sort pas de la poussière, et la souffrance ne germe pas du sol,'),
('jb',5,7,'crampon1923','de telle sorte que l''homme naisse pour la peine, comme les fils de la foudre pour élever leur vol.'),
('jb',5,8,'crampon1923','A ta place, je me tournerais vers Dieu, c''est vers lui que je dirigerais ma prière.'),
('jb',5,9,'crampon1923','Il fait des choses grandes, qu''on ne peut sonder; des prodiges qu''on ne saurait compter.'),
('jb',5,10,'crampon1923','Il verse la pluie sur la terre, il envoie les eaux sur les campagnes,'),
('jb',5,11,'crampon1923','il exalte ceux qui sont abaissés, et les affligés retrouvent le bonheur.'),
('jb',5,12,'crampon1923','Il déjoue les projets des perfides, et leurs mains ne peuvent réaliser leurs complots.'),
('jb',5,13,'crampon1923','Il prend les habiles dans leur propre ruse, et renverse les conseils des hommes astucieux.'),
('jb',5,14,'crampon1923','Durant le jour, ils rencontrent les ténèbres; en plein midi, ils tâtonnent comme dans la nuit.'),
('jb',5,15,'crampon1923','Dieu sauve le faible du glaive de leur langue, et de la main du puissant.'),
('jb',5,16,'crampon1923','Alors l''espérance revient au malheureux; et l''iniquité ferme la bouche.'),
('jb',5,17,'crampon1923','Heureux l''homme que Dieu châtie! Ne méprise donc pas la correction du Tout-Puissant.'),
('jb',5,18,'crampon1923','Car il fait la blessure, et il la bande; il frappe, et sa main guérit.'),
('jb',5,19,'crampon1923','Six fois il te délivrera de l''angoisse, et, à la septième, le mal ne t''atteindra pas.'),
('jb',5,20,'crampon1923','Dans la famine, il te sauvera de la mort; dans le combat, des coups de l''épée.'),
('jb',5,21,'crampon1923','Tu seras à l''abri du fouet de la langue, tu seras sans crainte quand viendra la dévastation.'),
('jb',5,22,'crampon1923','Tu te riras de la dévastation et de la famine, tu ne redouteras pas les bêtes de la terre.'),
('jb',5,23,'crampon1923','Car tu auras une alliance avec les pierres des champs, et les bêtes de la terre seront en paix avec toi.'),
('jb',5,24,'crampon1923','Tu verras le bonheur régner sous ta tente; tu visiteras tes pâturages, et rien n''y manquera.'),
('jb',5,25,'crampon1923','Tu verras ta postérité s''accroître, et tes rejetons se multiplier comme l''herbe des champs.'),
('jb',5,26,'crampon1923','Tu entreras mûr dans le tombeau, comme une gerbe qu''on enlève en son temps.'),
('jb',5,27,'crampon1923','Voilà ce que nous avons observé: c''est la vérité! Ecoute-le, et fais-en ton profit.'),
('jb',6,1,'crampon1923','Alors Job prit la parole et dit:'),
('jb',6,2,'crampon1923','Oh! S''il était possible de peser mon affliction, et de mettre toutes ensemble mes calamités dans la balance!...'),
('jb',6,3,'crampon1923','Elles seraient plus pesantes que le sable de la mer: voilà pourquoi mes paroles vont jusqu''à la folie.'),
('jb',6,4,'crampon1923','Car les flèches du Tout-Puissant me transpercent, et mon âme en boit le venin; les terreurs de Dieu sont rangées en bataille contre moi.'),
('jb',6,5,'crampon1923','Est-ce que l''onagre rugit auprès de l''herbe tendre? Est-ce que le bœuf mugit devant sa pâture?'),
('jb',6,6,'crampon1923','Comment se nourrir d''un mets fade et sans sel, ou bien trouver du goût au jus d''une herbe insipide?'),
('jb',6,7,'crampon1923','Ce que mon âme se refuse à toucher, c''est là mon pain, tout couvert de souillures.'),
('jb',6,8,'crampon1923','Qui me donnera que mon vœu s''accomplisse, et que Dieu réalise mon attente!'),
('jb',6,9,'crampon1923','Que Dieu daigne me briser, qu''il laisse aller sa main et qu''il tranche mes jours!'),
('jb',6,10,'crampon1923','Et qu''il me reste du moins cette consolation, que j''en tressaille dans les maux dont il m''accable: de n''avoir jamais transgressé les commandements du Saint!'),
('jb',6,11,'crampon1923','Quelle est ma force, pour que j''attende? Quelle est la durée de mes jours, pour que j''aie patience?'),
('jb',6,12,'crampon1923','Ma force est-elle la force des pierres, et ma chair est-elle d''airain?'),
('jb',6,13,'crampon1923','Ne suis-je pas dénué de tout secours, et tout espoir de salut ne m''est-il pas enlevé?'),
('jb',6,14,'crampon1923','Le malheureux a droit à la pitié de son ami, eût-il même abandonné la crainte du Tout-Puissant.'),
('jb',6,15,'crampon1923','Mes frères ont été perfides comme le torrent, comme l''eau des torrents qui s''écoulent.'),
('jb',6,16,'crampon1923','Les glaçons en troublent le cours, la neige disparaît dans leurs flots.'),
('jb',6,17,'crampon1923','Au temps de la sécheresse, ils s''évanouissent; aux premières chaleurs, leur lit est desséché.'),
('jb',6,18,'crampon1923','Dans des sentiers divers leurs eaux se perdent, elles s''évaporent dans les airs, et ils tarissent.'),
('jb',6,19,'crampon1923','Les caravanes de Théma comptaient sur eux; les voyageurs de Saba espéraient en eux;'),
('jb',6,20,'crampon1923','ils sont frustrés dans leur attente; arrivés sur leurs bords, ils restent confondus.'),
('jb',6,21,'crampon1923','Ainsi vous me manquez à cette heure; à la vue de l''infortune, vous fuyez épouvantés.'),
('jb',6,22,'crampon1923','Vous ai-je dit: « Donnez-moi quelque chose, faites-moi part de vos biens,'),
('jb',6,23,'crampon1923','délivrez-moi de la main de l''ennemi, arrachez-moi de la main des brigands? »'),
('jb',6,24,'crampon1923','Instruisez-moi, et je vous écouterai en silence; faites-moi voir en quoi j''ai failli.'),
('jb',6,25,'crampon1923','Qu''elles ont de force les paroles équitables! Mais sur quoi tombe votre blâme?'),
('jb',6,26,'crampon1923','Voulez-vous donc censurer des mots? Les discours échappés au désespoir sont la proie du vent.'),
('jb',6,27,'crampon1923','Ah! Vous jetez le filet sur un orphelin, vous creusez un piège à votre ami!'),
('jb',6,28,'crampon1923','Maintenant, daignez vous retourner vers moi, et vous verrez si je vous mens en face.'),
('jb',6,29,'crampon1923','Revenez, ne soyez pas injustes; revenez, et mon innocence apparaîtra.'),
('jb',6,30,'crampon1923','Y a-t-il de l''iniquité sur ma langue, ou bien mon palais ne sait-il pas discerner le mal?'),
('jb',7,1,'crampon1923','La vie de l''homme sur la terre est un temps de service, et ses jours sont comme ceux du mercenaire.'),
('jb',7,2,'crampon1923','Comme l''esclave soupire après l''ombre, comme l''ouvrier attend son salaire,'),
('jb',7,3,'crampon1923','ainsi j''ai eu en partage des mois de douleur, pour mon lot, des nuits de souffrance.'),
('jb',7,4,'crampon1923','Si je me couche, je dis: « Quand me lèverai-je? Quand finira la nuit? » et je suis rassasié d''angoisses jusqu''au jour.'),
('jb',7,5,'crampon1923','Ma chair se couvre de vers et d''une croûte terreuse, ma peau se gerce et coule.'),
('jb',7,6,'crampon1923','Mes jours passent plus rapides que la navette, ils s''évanouissent: plus d''espérance!'),
('jb',7,7,'crampon1923','O Dieu, souviens-toi que ma vie n''est qu''un souffle! Mes yeux ne reverront pas le bonheur.'),
('jb',7,8,'crampon1923','L''œil qui me regarde ne m''apercevra plus; ton œil me cherchera, et je ne serai plus.'),
('jb',7,9,'crampon1923','Le nuage se dissipe et passe; ainsi celui qui descend au schéol ne remontera plus;'),
('jb',7,10,'crampon1923','il ne retournera plus dans sa maison; le lieu qu''il habitait ne le reconnaîtra plus.'),
('jb',7,11,'crampon1923','C''est pourquoi je ne retiendrai pas ma langue, je parlerai dans l''angoisse de mon esprit, j''exhalerai mes plaintes dans l''amertume de mon âme.'),
('jb',7,12,'crampon1923','Suis-je la mer ou un monstre marin, pour que tu poses une barrière autour de moi?'),
('jb',7,13,'crampon1923','Quand je dis: « Mon lit me soulagera, ma couche calmera mes soupirs, »'),
('jb',7,14,'crampon1923','alors tu m''effraies par des songes, tu m''épouvantes par des visions.'),
('jb',7,15,'crampon1923','Ah! Mon âme préfère la mort violente, mes os appellent le trépas.'),
('jb',7,16,'crampon1923','Je suis en proie à la dissolution, la vie m''échappe pour jamais; laisse-moi, car mes jours ne sont qu''un souffle.'),
('jb',7,17,'crampon1923','Qu''est-ce que l''homme, pour que tu en fasses tant d''estime, que tu daignes t''occuper de lui,'),
('jb',7,18,'crampon1923','que tu le visites chaque matin, et qu''à chaque instant tu l''éprouves?'),
('jb',7,19,'crampon1923','Quand cesseras-ru d''avoir le regard sur moi? Quand me laisseras-tu le temps d''avaler ma salive?'),
('jb',7,20,'crampon1923','Si j''ai péché, que puis-je te faire, ô Gardien des hommes? Pourquoi me mettre en butte à tes traits, et me rendre à charge à moi-même?'),
('jb',7,21,'crampon1923','Que ne pardonnes-tu mon offense? Que n''oublies-tu mon iniquité? Car bientôt je dormirai dans la poussière; tu me chercheras, et je ne serai plus.'),
('jb',8,1,'crampon1923','Alors Baldad de Suhé prit la parole et dit:'),
('jb',8,2,'crampon1923','Jusques à quand tiendras-tu ces discours, et tes paroles seront-elles comme un souffle de tempête?'),
('jb',8,3,'crampon1923','Est-ce que Dieu fait fléchir le droit, ou bien le Tout-Puissant renverse-t-il la justice?'),
('jb',8,4,'crampon1923','Si tes fils ont péché contre lui, il les a livrés aux mains de leur iniquité.'),
('jb',8,5,'crampon1923','Pour toi, si tu as recours à Dieu, si tu implores le Tout-Puissant,'),
('jb',8,6,'crampon1923','si tu es droit et pur, alors il veillera sur toi, il rendra le bonheur à la demeure de ta justice;'),
('jb',8,7,'crampon1923','ton premier état semblera peu de chose, tant le second sera florissant.'),
('jb',8,8,'crampon1923','Interroge les générations passées, sois attentif à l''expérience des pères: —'),
('jb',8,9,'crampon1923','car nous sommes d''hier, et nous ne savons rien, nos jours sur la terre passent comme l''ombre; —'),
('jb',8,10,'crampon1923','ne vont-ils pas t''enseigner, te parler, et de leur cœur tirer des sentences:'),
('jb',8,11,'crampon1923','« Le papyrus croît-il en dehors des marais? Le jonc s''élève-t-il sans eau?'),
('jb',8,12,'crampon1923','Encore tendre, sans qu''on le coupe, il sèche avant toute herbe.'),
('jb',8,13,'crampon1923','Telles sont les voies de tous ceux qui oublient Dieu; l''espérance de l''impie périra.'),
('jb',8,14,'crampon1923','Sa confiance sera brisée; son assurance ressemble à la toile de l''araignée.'),
('jb',8,15,'crampon1923','Il s''appuie sur sa maison, et elle ne tient pas; il s''y attache, et elle ne reste pas debout.'),
('jb',8,16,'crampon1923','Il est plein de vigueur, au soleil, ses rameaux s''étendent sur son jardin,'),
('jb',8,17,'crampon1923','ses racines s''entrelacent parmi les pierres, il plonge jusqu''aux profondeurs du roc.'),
('jb',8,18,'crampon1923','Si Dieu l''arrache de sa place, sa place le renie: Je ne t''ai jamais vu.'),
('jb',8,19,'crampon1923','C''est là que sa joie se termine, et du même sol d''autres s''élèveront après lui. »'),
('jb',8,20,'crampon1923','Non, Dieu ne rejette pas l''innocent, il ne prend pas la main des malfaiteurs.'),
('jb',8,21,'crampon1923','Il remplira ta bouche d''éclats de rire, et mettra sur tes lèvres des chants d''allégresse.'),
('jb',8,22,'crampon1923','Tes ennemis seront couverts de honte, et la tente des méchants disparaîtra.'),
('jb',9,1,'crampon1923','Alors Job prit la parole et dit:'),
('jb',9,2,'crampon1923','Je sais bien qu''il en est ainsi: comment l''homme serait-il juste vis-à-vis de Dieu?'),
('jb',9,3,'crampon1923','S''il voulait contester avec lui, sur mille choses il ne pourrait répondre à une seule.'),
('jb',9,4,'crampon1923','Dieu est sage en son cœur, et puissant en force: qui lui a résisté, et est demeuré en paix?'),
('jb',9,5,'crampon1923','Il transporte les montagnes, sans qu''elles le sachent, il les renverse dans sa colère;'),
('jb',9,6,'crampon1923','il secoue la terre sur sa base, et ses colonnes sont ébranlées.'),
('jb',9,7,'crampon1923','Il commande au soleil, et le soleil ne se lève pas; il met un sceau sur les étoiles.'),
('jb',9,8,'crampon1923','Seul, il étend les cieux, il marche sur les hauteurs de la mer.'),
('jb',9,9,'crampon1923','Il a créé la Grande Ourse, Orion, les Pléiades, et les régions du ciel austral.'),
('jb',9,10,'crampon1923','Il fait des merveilles qu''on ne peut sonder, des prodiges qu''on ne saurait compter.'),
('jb',9,11,'crampon1923','Voici qu''il passe près de moi, et je ne le vois pas; il s''éloigne, sans que je l''aperçoive.'),
('jb',9,12,'crampon1923','S''il ravit une proie, qui s''y opposera, qui lui dira: « Que fais-tu? »'),
('jb',9,13,'crampon1923','Dieu! Rien ne fléchit sa colère; devant lui s''inclinent les légions d''orgueil.'),
('jb',9,14,'crampon1923','Et moi je songerais à lui répondre, à choisir mes paroles pour discuter avec lui!'),
('jb',9,15,'crampon1923','Aurais-je pour moi la justice, je ne répondrais pas; j''implorerais la clémence de mon juge.'),
('jb',9,16,'crampon1923','Même s''il se rendait à mon appel, je ne croirais pas qu''il eût écouté ma voix:'),
('jb',9,17,'crampon1923','lui qui me brise comme dans un tourbillon, et multiplie mes blessures sans motif;'),
('jb',9,18,'crampon1923','qui ne me laisse point respirer, et me rassasie d''amertume.'),
('jb',9,19,'crampon1923','S''agit-il de force, voici qu''il est fort, s''agit-il de droit, il dit: « Qui m''assigne? »'),
('jb',9,20,'crampon1923','Serais-je irréprochable, ma bouche même me condamnerait; serais-je innocent, elle me déclarerait pervers.'),
('jb',9,21,'crampon1923','Innocent! Je le suis; je ne tiens pas à l''existence, et la vie m''est à charge.'),
('jb',9,22,'crampon1923','Il m''importe après tout; c''est pourquoi j''ai dit: « Il fait périr également le juste et l''impie. »'),
('jb',9,23,'crampon1923','Si du moins le fléau tuait d''un seul coup! Hélas! il se rit des épreuves de l''innocent!'),
('jb',9,24,'crampon1923','La terre est livrée aux mains du méchant, Dieu voile la face de ses juges: si ce n''est pas lui, qui est-ce donc?'),
('jb',9,25,'crampon1923','Mes jours sont plus rapides qu''un courrier, ils fuient sans avoir vu le bonheur;'),
('jb',9,26,'crampon1923','ils passent comme la barque de jonc, comme l''aigle qui fond sur sa proie.'),
('jb',9,27,'crampon1923','Si je dis: « Je veux oublier ma plainte, quitter mon air triste, prendre un air joyeux, »'),
('jb',9,28,'crampon1923','je tremble pour toutes mes douleurs, je sais que tu ne me tiendras pas pour innocent.'),
('jb',9,29,'crampon1923','Je serai jugé coupable: pourquoi prendre une peine inutile?'),
('jb',9,30,'crampon1923','Quand je me laverais dans la neige, quand je purifierais mes mains avec le bor,'),
('jb',9,31,'crampon1923','tu me plongerais dans la fange, et mes vêtements m''auraient en horreur.'),
('jb',9,32,'crampon1923','Dieu n''est pas un homme comme moi, pour que je lui réponde, pour que nous comparaissions ensemble en justice.'),
('jb',9,33,'crampon1923','Il n''y a pas entre nous d''arbitre qui pose sa main sur nous deux.'),
('jb',9,34,'crampon1923','Qu''il retire sa verge de dessus moi, que ses terreurs cessent de m''épouvanter:'),
('jb',9,35,'crampon1923','alors je parlerai sans le craindre; autrement, je ne suis point à moi-même.'),
('jb',10,1,'crampon1923','Mon âme est lasse de la vie; je donnerai libre cours à ma plainte, je parlerai dans l''amertume de mon cœur.'),
('jb',10,2,'crampon1923','Je dis à Dieu: Ne me condamne point; apprends-moi sur quoi tu me prends à partie.'),
('jb',10,3,'crampon1923','Trouves-tu du plaisir à opprimer, à repousser l''œuvre de tes mains, à faire luire ta faveur sur le conseil des méchants?'),
('jb',10,4,'crampon1923','As-tu des yeux de chair, ou bien vois-tu comme voient les hommes?'),
('jb',10,5,'crampon1923','Tes jours sont-ils comme les jours de l''homme, ou bien tes années comme les années d''un mortel,'),
('jb',10,6,'crampon1923','pour que tu recherches mon iniquité, pour que tu poursuives mon péché,'),
('jb',10,7,'crampon1923','quand tu sais que je ne suis pas coupable, et que nul ne peut me délivrer de ta main?'),
('jb',10,8,'crampon1923','Tes mains m''ont formé et façonné, tout entier, et tu voudrais me détruire!'),
('jb',10,9,'crampon1923','Souviens-toi que tu m''as pétri comme l''argile: et tu me ramènerais à la poussière!'),
('jb',10,10,'crampon1923','Ne m''as-tu pas coulé comme le lait, et coagulé comme le fromage?'),
('jb',10,11,'crampon1923','Tu m''as revêtu de peau et de chair, tu m''as tissé d''os et de nerfs.'),
('jb',10,12,'crampon1923','Avec la vie, tu m''as accordé ta faveur, et ta providence a gardé mon âme.'),
('jb',10,13,'crampon1923','Et pourtant, voilà ce que tu cachais dans ton cœur: Je vois bien ce que tu méditais.'),
('jb',10,14,'crampon1923','Si je pèche, tu m''observes, tu ne me pardonnes pas mon iniquité.'),
('jb',10,15,'crampon1923','Suis-je coupable, malheur à moi! Suis-je innocent, je n''ose lever la tête, rassasié de honte, et voyant ma misère.'),
('jb',10,16,'crampon1923','Si je me relève, tu me poursuis comme un lion, tu recommences à me tourmenter étrangement,'),
('jb',10,17,'crampon1923','tu m''opposes de nouveaux témoins; tu redoubles de fureur contre moi, des troupes de rechange viennent m''assaillir.'),
('jb',10,18,'crampon1923','Pourquoi m''as-tu tiré du sein de ma mère? Je serais mort, et aucun œil ne m''aurait vu.'),
('jb',10,19,'crampon1923','Je serais comme si je n''eusse jamais été, du sein maternel j''aurais été porté au sépulcre.'),
('jb',10,20,'crampon1923','Mes jours ne sont-ils pas bien courts? Qu''il me laisse! Qu''il se retire et que je respire un instant,'),
('jb',10,21,'crampon1923','avant que je m''en aille, pour ne plus revenir, dans la région des ténèbres et de l''ombre de la mort,'),
('jb',10,22,'crampon1923','morne et sombre région, où règnent l''ombre de la mort et le chaos, où la clarté est pareille aux ténèbres.'),
('jb',11,1,'crampon1923','Alors Sophar de Naama prit la parole et dit:'),
('jb',11,2,'crampon1923','La multitude des paroles restera-t-elle sans réponse, et le bavard aura-t-il raison?'),
('jb',11,3,'crampon1923','Tes vains propos feront-ils taire les gens? Te moqueras-tu, sans que personne te confonde?'),
('jb',11,4,'crampon1923','Tu as dit à Dieu: « Ma pensée est la vraie, et je suis irréprochable devant toi. »'),
('jb',11,5,'crampon1923','Oh! Si Dieu voulait parler, s''il ouvrait les lèvres pour te répondre;'),
('jb',11,6,'crampon1923','s''il te révélait les secrets de sa sagesse, les replis cachés de ses desseins, tu verrais alors qu''il oublie une part de tes crimes.'),
('jb',11,7,'crampon1923','Prétends-tu sonder les profondeurs de Dieu, atteindre la perfection du Tout-Puissant?'),
('jb',11,8,'crampon1923','Elle est haute comme les cieux: que feras-tu? Plus profonde que le séjour des morts: que sauras-tu?'),
('jb',11,9,'crampon1923','Sa mesure est plus longue que la terre, elle est plus large que la mer.'),
('jb',11,10,'crampon1923','S''il fond sur le coupable, s''il l''arrête, s''il convoque le tribunal, qui s''y opposera?'),
('jb',11,11,'crampon1923','Car il connaît les pervers, il découvre l''iniquité avant qu''elle s''en doute.'),
('jb',11,12,'crampon1923','A cette vue, le fou même comprendrait, et le petit de l''onagre deviendrait raisonnable.'),
('jb',11,13,'crampon1923','Pour toi, si tu diriges ton cœur vers Dieu, et que tu étendes vers lui tes bras,'),
('jb',11,14,'crampon1923','si tu éloignes l''iniquité qui est dans tes mains, et que tu ne laisses pas l''injustice habiter sous ta tente,'),
('jb',11,15,'crampon1923','alors tu lèveras ton front sans tache, tu seras inébranlable et tu ne craindras plus.'),
('jb',11,16,'crampon1923','Tu oublieras alors tes souffrances, tu t''en souviendras comme des eaux écoulées;'),
('jb',11,17,'crampon1923','L''avenir se lèvera pour toi plus brillant que le midi, les ténèbres se changeront en aurore.'),
('jb',11,18,'crampon1923','Tu seras plein de confiance, et ton attente ne sera pas veine; tu regarderas autour de toi, et tu te coucheras tranquille.'),
('jb',11,19,'crampon1923','Tu reposeras, sans que personne t''inquiète, et plusieurs caresseront ton visage.'),
('jb',11,20,'crampon1923','Mais les yeux des méchants se consumeront: pour eux, point de refuge; leur espérance est le souffle d''un mourant.'),
('jb',12,1,'crampon1923','Alors Job prit la parole et dit:'),
('jb',12,2,'crampon1923','Vraiment vous êtes aussi sages que tout un peuple, et avec vous mourra la sagesse!'),
('jb',12,3,'crampon1923','Moi aussi, j''ai de l''intelligence comme vous, je ne vous le cède en rien, et qui ne sait les choses que vous dites?'),
('jb',12,4,'crampon1923','Je suis la risée de mes amis, moi qui invoquais Dieu et à qui Dieu répondait; leur risée, moi le juste, l''innocent!...'),
('jb',12,5,'crampon1923','Honte au malheur! C''est la devise des heureux; le mépris attend celui dont le pied chancelle.'),
('jb',12,6,'crampon1923','La paix cependant règne sous la tente des brigands, la sécurité pour ceux qui provoquent Dieu, et qui n''ont d''autre dieu que leur bras.'),
('jb',12,7,'crampon1923','Mais, de grâce, interroge les bêtes, et elles t''instruiront, les oiseaux du ciel, et ils te l''apprendront;'),
('jb',12,8,'crampon1923','ou bien parle à la terre, et elle t''enseignera; les poissons même de la mer te le raconteront.'),
('jb',12,9,'crampon1923','Qui ne sait, parmi tous ces êtres, que la main de Yahweh a fait ces choses,'),
('jb',12,10,'crampon1923','qu''il tient dans sa main l''âme de tout ce qui vit, et le souffle de tous les humains?'),
('jb',12,11,'crampon1923','L''oreille ne discerne-t-elle pas les paroles, comme le palais savoure les aliments?'),
('jb',12,12,'crampon1923','Aux cheveux blancs appartient la sagesse, la prudence est le fruit des longs jours.'),
('jb',12,13,'crampon1923','En Dieu résident la sagesse et la puissance, à lui le conseil et l''intelligence.'),
('jb',12,14,'crampon1923','Voici qu''il renverse et l''on ne rebâtit pas; il ferme la porte sur l''homme, et on ne lui ouvre pas.'),
('jb',12,15,'crampon1923','Voici qu''il arrête les eaux, elles tarissent; il les lâche, elles bouleversent la terre.'),
('jb',12,16,'crampon1923','A lui la force et la prudence, à lui celui qui est égaré et celui qui égare.'),
('jb',12,17,'crampon1923','Il emmène captifs les conseillers des peuples, et il ôte le sens aux juges.'),
('jb',12,18,'crampon1923','Il délie la ceinture des rois, et ceint leurs reins d''une corde.'),
('jb',12,19,'crampon1923','Il traîne les prêtres en captivité, et renverse les puissants.'),
('jb',12,20,'crampon1923','Il ôte la parole aux hommes les plus habiles, et il enlève le jugement aux vieillards.'),
('jb',12,21,'crampon1923','Il verse le mépris sur les nobles, et il relâche la ceinture des forts.'),
('jb',12,22,'crampon1923','Il met à découvert les choses cachées dans les ténèbres, et produit à la lumière l''ombre de la mort.'),
('jb',12,23,'crampon1923','Il fait croître les nations, et il les anéantit; il les étend et il les resserre.'),
('jb',12,24,'crampon1923','Il ôte l''intelligence aux chefs des peuples de la terre, et les égare dans des déserts sans chemin;'),
('jb',12,25,'crampon1923','ils tâtonnent dans les ténèbres, loin de la lumière; il les fait errer comme un homme ivre.'),
('jb',13,1,'crampon1923','Voilà que mon œil a vu tout cela, mon oreille l''a entendu et compris.'),
('jb',13,2,'crampon1923','Ce que vous savez, moi aussi je le sais, je ne vous suis en rien inférieur.'),
('jb',13,3,'crampon1923','Mais je veux parler au Tout-Puissant, je veux plaider ma cause avec Dieu.'),
('jb',13,4,'crampon1923','Car vous n''êtes que des charlatans, vous êtes tous des médecins inutiles.'),
('jb',13,5,'crampon1923','Que ne gardiez-vous le silence! Il vous eût tenu lieu de sagesse.'),
('jb',13,6,'crampon1923','Ecoutez, je vous prie, ma défense, soyez attentifs au plaidoyer de mes lèvres.'),
('jb',13,7,'crampon1923','Parlerez-vous mensonge en faveur de Dieu, pour lui, parlerez-vous tromperie?'),
('jb',13,8,'crampon1923','Ferez-vous pour Dieu acception de personnes, vous constituerez-vous avocats?'),
('jb',13,9,'crampon1923','Vous en saura-t-il gré, s''il sonde vos cœurs? Le tromperez-vous comme on trompe un homme?'),
('jb',13,10,'crampon1923','Certainement il vous condamnera, si vous faites en secret acception de personnes.'),
('jb',13,11,'crampon1923','Oui, sa majesté vous épouvantera, ses terreurs tomberont sur vous.'),
('jb',13,12,'crampon1923','Vos arguments sont des raisons de poussière, vos forteresses sont des forteresses d''argile.'),
('jb',13,13,'crampon1923','Taisez-vous, laissez-moi, je veux parler; il m''en arrivera ce qu''il pourra.'),
('jb',13,14,'crampon1923','Je veux prendre ma chair entre les dents, je veux mettre mon âme dans ma main.'),
('jb',13,15,'crampon1923','Quand il me tuerait, que je n''aurais rien à espérer, je défendrai devant lui ma conduite.'),
('jb',13,16,'crampon1923','Mais il sera mon salut, car l''impie ne saurait paraître en sa présence.'),
('jb',13,17,'crampon1923','Ecoutez donc mes paroles, prêtez l''oreille à mon discours.'),
('jb',13,18,'crampon1923','Voici que j''ai préparé ma cause, je sais que je serai justifié.'),
('jb',13,19,'crampon1923','Est-il quelqu''un qui veuille plaider contre moi? A l''instant même je veux me taire et mourir.'),
('jb',13,20,'crampon1923','Seulement épargne-moi deux choses, ô Dieu, et je ne me cacherai pas devant ta face:'),
('jb',13,21,'crampon1923','éloigne ta main de dessus moi, et que tes terreurs ne m''épouvantent plus.'),
('jb',13,22,'crampon1923','Après cela, appelle, et je répondrai; ou bien je parlerai d''abord, et tu me répondras.'),
('jb',13,23,'crampon1923','Quel est le nombre de mes iniquités et de mes péchés? Fais-moi connaître mes transgressions et mes offenses.'),
('jb',13,24,'crampon1923','Pourquoi cacher ainsi ton visage, et me regarder comme ton ennemi!'),
('jb',13,25,'crampon1923','Veux-tu donc effrayer une feuille agitée par le vent, poursuivre une paille desséchée,'),
('jb',13,26,'crampon1923','pour que tu écrives contre moi des choses amères, pour que tu m''imputes les fautes de ma jeunesse,'),
('jb',13,27,'crampon1923','pour que tu mettes mes pieds dans les ceps, que tu observes toutes mes démarches, que tu traces une limite à la plante de mes pieds,'),
('jb',13,28,'crampon1923','alors que mon corps se consume comme un bois vermoulu, comme un vêtement que dévore la teigne.'),
('jb',14,1,'crampon1923','L''homme né de la femme vit peu de jours, et il est rassasié de misères.'),
('jb',14,2,'crampon1923','Comme la fleur, il naît, et on le coupe; il fuit comme l''ombre, sans s''arrêter.'),
('jb',14,3,'crampon1923','Et c''est sur lui que tu as l''œil ouvert, lui que tu amènes en justice avec toi!'),
('jb',14,4,'crampon1923','Qui peut tirer le pur de l''impur? Personne.'),
('jb',14,5,'crampon1923','Si les jours de l''homme sont comptés, si tu as fixé le nombre de ses mois, si tu as posé un terme qu''il ne doit pas franchir,'),
('jb',14,6,'crampon1923','détourne de lui tes yeux pour qu''il se repose, jusqu''à ce qu''il goûte, comme le mercenaire, la fin de sa journée.'),
('jb',14,7,'crampon1923','Un arbre a de l''espérance: coupé, il peut verdir encore, il ne cesse pas d''avoir des rejetons.'),
('jb',14,8,'crampon1923','Que sa racine ait vieilli dans la terre, que son tronc soit mort dans la poussière,'),
('jb',14,9,'crampon1923','dès qu''il sent l''eau, il reverdit, il pousse des branches comme un jeune plant.'),
('jb',14,10,'crampon1923','Mais l''homme meurt, et il reste étendu; quand il a expiré, où est-il?'),
('jb',14,11,'crampon1923','Les eaux du lac disparaissent, le fleuve tarit et se dessèche:'),
('jb',14,12,'crampon1923','ainsi l''homme se couche et ne se relève plus, il ne se réveillera pas tant que subsistera le ciel, on ne le fera pas sortir de son sommeil.'),
('jb',14,13,'crampon1923','Oh! Si tu voulais me cacher dans le séjour des morts, m''y tenir à couvert jusqu''à ce que ta colère ait passé, me fixer un terme où tu te souviendrais de moi!'),
('jb',14,14,'crampon1923','Si l''homme une fois mort pouvait revivre! Tout le temps de mon service j''attendrais qu''on vînt me relever.'),
('jb',14,15,'crampon1923','Tu m''appellerais alors, et moi je te répondrais; tu languirais après l''ouvrage de tes mains.'),
('jb',14,16,'crampon1923','Mais hélas! Maintenant, tu comptes mes pas, tu as l''œil ouvert sur mes péchés;'),
('jb',14,17,'crampon1923','mes transgressions sont scellées dans une bourse, et tu mets un enduit sur mes iniquités.'),
('jb',14,18,'crampon1923','La montagne s''écroule et s''efface; le rocher est transporté hors de sa place;'),
('jb',14,19,'crampon1923','les eaux creusent la pierre, leurs flots débordés entraînent la poussière du sol: ainsi tu anéantis l''espérance de l''homme.'),
('jb',14,20,'crampon1923','Tu l''abats sans retour, et il s''en va; tu flétris son visage, et tu le congédies.'),
('jb',14,21,'crampon1923','Que ses enfants soient honorés, il n''en sait rien; qu''ils soient dans l''abaissement, il l''ignore.'),
('jb',14,22,'crampon1923','Sa chair ne sent que ses propres souffrances, son âme ne gémit que sur elle-même.'),
('jb',15,1,'crampon1923','Alors Eliphaz de Théman prit la parole et dit:'),
('jb',15,2,'crampon1923','Le sage répond-il par une science vaine? Se gonfle-t-il la poitrine de vent?'),
('jb',15,3,'crampon1923','Se défend-il par de futiles propos, par des discours qui ne servent à rien?'),
('jb',15,4,'crampon1923','Toi, tu détruis même la crainte de Dieu, tu anéantis toute piété envers Dieu.'),
('jb',15,5,'crampon1923','Ta bouche révèle ton iniquité, et tu prends le langage les fourbes.'),
('jb',15,6,'crampon1923','Ce n''est pas moi, c''est ta bouche qui te condamne, ce sont tes lèvres qui déposent contre toi.'),
('jb',15,7,'crampon1923','Es-tu né le premier des hommes? As-tu été enfanté avant les collines?'),
('jb',15,8,'crampon1923','As-tu assisté au conseil de Dieu? As-tu dérobé pour toi seul la sagesse?'),
('jb',15,9,'crampon1923','Que sais-tu, que nous ne sachions? Qu''as-tu appris, qui ne nous soit familier?'),
('jb',15,10,'crampon1923','Nous avons aussi parmi nous des cheveux blancs, des vieillards plus riches de jours que ton père.'),
('jb',15,11,'crampon1923','Tiens-tu pour peu de chose les consolations de Dieu et les douces paroles que nous t''adressons?'),
('jb',15,12,'crampon1923','Où ton cœur t''emporte-t-il, et que signifie ce roulement de tes yeux?'),
('jb',15,13,'crampon1923','Quoi! C''est contre Dieu que tu tournes ta colère, et que de ta bouche tu fais sortir de tels discours?'),
('jb',15,14,'crampon1923','Qu''est-ce que l''homme, pour qu''il soit pur, le fils de la femme, pour qu''il soit juste?'),
('jb',15,15,'crampon1923','Voici que Dieu ne se fie pas même à ses saints, et les cieux ne sont pas purs devant lui:'),
('jb',15,16,'crampon1923','combien moins cet être abominable et pervers, l''homme qui boit l''iniquité comme l''eau!'),
('jb',15,17,'crampon1923','Je vais t''instruire, écoute-moi; je raconterai ce que j''ai vu,'),
('jb',15,18,'crampon1923','ce que les sages enseignent, — ils ne le cachent pas, l''ayant appris de leurs pères;'),
('jb',15,19,'crampon1923','à eux seuls avait été donné le pays, et parmi eux jamais ne passa l''étranger. —'),
('jb',15,20,'crampon1923','« Le méchant, durant tous ses jours, est rongé par l''angoisse; un petit nombre d''années sont réservées à l''oppresseur.'),
('jb',15,21,'crampon1923','Des bruits effrayants retentissent à ses oreilles; au sein de la paix, le dévastateur fond sur lui.'),
('jb',15,22,'crampon1923','Il n''espère pas échapper aux ténèbres, il sent qu''il est guetté pour le glaive.'),
('jb',15,23,'crampon1923','Il erre pour chercher son pain; il sait que le jour des ténèbres est prêt, à ses côtés.'),
('jb',15,24,'crampon1923','La détresse et l''angoisse tombent sur lui; elles l''assaillent comme un roi armé pour le combat.'),
('jb',15,25,'crampon1923','Car il a levé sa main contre Dieu, il a bravé le Tout-Puissant,'),
('jb',15,26,'crampon1923','il a couru sur lui le cou raide, sous le dos épais de ses boucliers.'),
('jb',15,27,'crampon1923','Il avait le visage couvert de graisse, et les flancs chargés d''embonpoint.'),
('jb',15,28,'crampon1923','Il occupait des villes qui ne sont plus, des maisons qui n''ont plus d''habitants, vouées à devenir des monceaux de pierre.'),
('jb',15,29,'crampon1923','Il ne s''enrichira plus, sa fortune ne tiendra pas, ses possessions ne s''étendront plus sur la terre.'),
('jb',15,30,'crampon1923','Il n''échappera pas aux ténèbres; la flamme desséchera ses rejetons, et il sera emporté par le souffle de la bouche de Dieu.'),
('jb',15,31,'crampon1923','Qu''il n''espère rien du mensonge, il y sera pris; le mensonge sera sa récompense.'),
('jb',15,32,'crampon1923','Elle arrivera avant que ses jours soient pleins, et son rameau ne verdira plus.'),
('jb',15,33,'crampon1923','Il secouera, comme la vigne, son fruit à peine éclos; il laissera tomber sa fleur, comme l''olivier.'),
('jb',15,34,'crampon1923','Car la maison de l''impie est stérile, et le feu dévore la tente du juge corrompu.'),
('jb',15,35,'crampon1923','Il a conçu le mal, et il enfante le malheur, dans son sein mûrit un fruit de déception. »'),
('jb',16,1,'crampon1923','Alors Job prit la parole et dit:'),
('jb',16,2,'crampon1923','J''ai souvent entendu de semblables harangues; vous êtes tous d''insupportables consolateurs.'),
('jb',16,3,'crampon1923','Quand finiront ces vains discours? Quel aiguillon t''excite à répliquer?'),
('jb',16,4,'crampon1923','Moi aussi, je saurais parler comme vous, si vous étiez à ma place; j''arrangerais de beaux discours à votre adresse, je secouerais la tête sur vous;'),
('jb',16,5,'crampon1923','je vous encouragerais de la bouche, et vous auriez pour soulagement l''agitation de mes lèvres.'),
('jb',16,6,'crampon1923','Si je parle, ma douleur n''est pas adoucie; si je me tais, en est-elle soulagée?'),
('jb',16,7,'crampon1923','Aujourd''hui, hélas! Dieu a épuisé mes forces... ô Dieu, tu as moissonné tous mes proches.'),
('jb',16,8,'crampon1923','Tu me garrottes... c''est un témoignage contre moi!... ma maigreur se lève contre moi, en face elle m''accuse.'),
('jb',16,9,'crampon1923','Sa colère me déchire et me poursuit, il grince des dents contre moi; mon ennemi darde sur moi ses regards.'),
('jb',16,10,'crampon1923','Ils ouvrent leur bouche pour me dévorer, ils me frappent la joue avec outrage, ils se liguent tous ensemble pour me perdre.'),
('jb',16,11,'crampon1923','Dieu m''a livré au pervers, il m''a jeté entre les mains des méchants.'),
('jb',16,12,'crampon1923','J''étais en paix, et il m''a secoué, il m''a saisi par la nuque, et il m''a brisé. Il m''a posé en but à ses traits,'),
('jb',16,13,'crampon1923','ses flèches volent autour de moi; il perce mes flancs sans pitié, il répand mes entrailles sur la terre;'),
('jb',16,14,'crampon1923','il me fait brèche sur brèche, il fond sur moi comme un géant.'),
('jb',16,15,'crampon1923','J''ai cousu un sac sur ma peau, et j''ai roulé mon front dans la poussière.'),
('jb',16,16,'crampon1923','Mon visage est tout rouge de larmes, et l''ombre de la mort s''étend sur mes paupières,'),
('jb',16,17,'crampon1923','quoiqu''il n''y ait pas d''iniquités dans mes mains, et que ma prière soit pure.'),
('jb',16,18,'crampon1923','O terre, ne couvre point mon sang, et que mes cris s''élèvent librement!'),
('jb',16,19,'crampon1923','A cette heure même, voici que j''ai mon témoin dans le ciel, mon défenseur dans les hauts lieux.'),
('jb',16,20,'crampon1923','Mes amis se moquent de moi, c''est vers Dieu que pleurent mes yeux.'),
('jb',16,21,'crampon1923','Qu''il juge lui-même entre Dieu et l''homme, entre le fils de l''homme et son semblable!'),
('jb',16,22,'crampon1923','Car les années qui me sont comptés s''écoulent, et j''entre dans un sentier d''où je ne reviendrai pas.'),
('jb',17,1,'crampon1923','Mon souffle s''épuise, mes jours s''éteignent, il ne me reste plus que le tombeau.'),
('jb',17,2,'crampon1923','Je suis environné de moqueurs, mon œil veille au milieu de leurs outrages.'),
('jb',17,3,'crampon1923','O Dieu, fais-toi auprès de toi-même ma caution: quel autre voudrait me frapper dans la main?'),
('jb',17,4,'crampon1923','Car tu as fermé leur cœur à la sagesse; ne permets donc pas qu''ils s''élèvent.'),
('jb',17,5,'crampon1923','Tel invite ses amis au partage, quand défaillent les yeux de ses enfants.'),
('jb',17,6,'crampon1923','Il a fait de moi la risée des peuples; je suis l''homme à qui l''on crache au visage.'),
('jb',17,7,'crampon1923','Mon œil est voilé par le chagrin, et tous mes membres ne sont plus qu''une ombre.'),
('jb',17,8,'crampon1923','Les hommes droits en sont stupéfaits, et l''innocent s''irrite contre l''impie.'),
('jb',17,9,'crampon1923','Le juste néanmoins demeure ferme dans sa voie, et qui a les mains pures redouble de courage.'),
('jb',17,10,'crampon1923','Mais vous tous, revenez, venez donc; ne trouverai-je pas un sage parmi vous?'),
('jb',17,11,'crampon1923','Mes jours sont écoulés, mes projets anéantis, ces projets que caressait mon cœur.'),
('jb',17,12,'crampon1923','De la nuit ils font le jour; en face des ténèbres, ils disent que la lumière est proche!'),
('jb',17,13,'crampon1923','J''ai beau attendre, le schéol est ma demeure; dans les ténèbres j''ai disposé ma couche.'),
('jb',17,14,'crampon1923','J''ai dit à la fosse: « Tu es mon père; » aux vers: « Vous êtes ma mère et ma sœur! »'),
('jb',17,15,'crampon1923','Où est donc mon espérance? Mon espérance, qui peut la voir?'),
('jb',17,16,'crampon1923','Elle est descendue aux portes du schéol, si du moins dans la poussière on trouve du repos!...'),
('jb',18,1,'crampon1923','Alors Baldad de Suhé prit la parole et dit:'),
('jb',18,2,'crampon1923','Quand donc mettrez-vous un terme à ces discours? Ayez de l''intelligence, puis nous parlerons.'),
('jb',18,3,'crampon1923','Pourquoi nous regardez-vous comme des brutes, et sommes-nous stupides à vos yeux?'),
('jb',18,4,'crampon1923','Toi qui te déchires dans ta fureur, veux-tu qu''à cause de toi la terre devienne déserte, que le rocher soit transporté hors de sa place?'),
('jb',18,5,'crampon1923','Oui, la lumière du méchant s''éteindra, et la flamme de son foyer cessera de briller.'),
('jb',18,6,'crampon1923','Le jour s''obscurcira sous sa tente, sa lampe s''éteindra au-dessus de lui.'),
('jb',18,7,'crampon1923','Ses pas si fermes seront à l''étroit, son propre conseil précipite sa chute.'),
('jb',18,8,'crampon1923','Ses pieds le jettent dans les rets, il marche sur le piège.'),
('jb',18,9,'crampon1923','Le filet saisit ses talons; il est serré dans ses nœuds.'),
('jb',18,10,'crampon1923','Pour lui les lacs sont cachés sous terre, et la trappe est sur son sentier.'),
('jb',18,11,'crampon1923','De tous côtés des terreurs l''assiègent, et le poursuivent pas à pas.'),
('jb',18,12,'crampon1923','La disette est son châtiment, et la ruine est prête pour sa chute.'),
('jb',18,13,'crampon1923','La peau de ses membres est dévorée; ses membres sont dévorés par le premier-né de la mort.'),
('jb',18,14,'crampon1923','Il est arraché de sa tente, où il se croyait en sûreté; on le traîne vers le Roi des frayeurs.'),
('jb',18,15,'crampon1923','Nul des siens n''habite dans sa tente, le soufre est semé sur sa demeure.'),
('jb',18,16,'crampon1923','En bas, ses racines se dessèchent, en haut, ses rameaux sont coupés.'),
('jb',18,17,'crampon1923','Sa mémoire a disparu de la terre, il n''a plus de nom dans la contrée.'),
('jb',18,18,'crampon1923','On le chasse de la lumière dans les ténèbres, on le bannit de l''univers.'),
('jb',18,19,'crampon1923','Il ne laisse ni descendance ni postérité dans sa tribu; aucun survivant dans son séjour.'),
('jb',18,20,'crampon1923','Les peuples de l''Occident sont stupéfaits de sa ruine, et ceux de l''Orient en sont saisis d''horreur.'),
('jb',18,21,'crampon1923','Telle est la demeure de l''impie, telle est la place de l''homme qui ne connaît pas Dieu.'),
('jb',19,1,'crampon1923','Alors Job prit la parole et dit:'),
('jb',19,2,'crampon1923','Jusques à quand affligerez-vous mon âme, et m''accablerez-vous de vos discours?'),
('jb',19,3,'crampon1923','Voilà dix fois que vous m''insultez, que vous m''outragez sans pudeur.'),
('jb',19,4,'crampon1923','Quand même j''aurais failli, c''est avec moi que demeure ma faute.'),
('jb',19,5,'crampon1923','Mais vous, qui vous élevez contre moi, qui invoquez mon opprobre pour me convaincre,'),
('jb',19,6,'crampon1923','sachez enfin que c''est Dieu qui m''opprime, et qui m''enveloppe de son filet.'),
('jb',19,7,'crampon1923','Voici que je crie à la violence, et nul ne me répond! J''en appelle, et point de justice!'),
('jb',19,8,'crampon1923','Il m''a barré le chemin, et je ne puis passer: il a répandu les ténèbres sur mes sentiers.'),
('jb',19,9,'crampon1923','Il m''a dépouillé de ma gloire, il a enlevé la couronne de ma tête.'),
('jb',19,10,'crampon1923','Il m''a sapé tout à l''entour, et je tombe; il a déraciné, comme un arbre, mon espérance.'),
('jb',19,11,'crampon1923','Sa colère s''est allumée contre moi; il m''a traité comme ses ennemis.'),
('jb',19,12,'crampon1923','Ses bataillons sont venus ensemble, ils se sont frayés un chemin jusqu''à moi, ils font le siège de ma tente.'),
('jb',19,13,'crampon1923','Il a éloigné de moi mes frères; mes amis se sont détournés de moi.'),
('jb',19,14,'crampon1923','Mes proches m''ont abandonné, mes intimes m''ont oublié.'),
('jb',19,15,'crampon1923','Les hôtes de ma maison et mes servantes me traitent comme un étranger; je suis un inconnu à leurs yeux.'),
('jb',19,16,'crampon1923','J''appelle mon serviteur, et il ne me répond pas; je suis réduit à le supplier de ma bouche.'),
('jb',19,17,'crampon1923','Ma femme a horreur de mon haleine, je demande grâce aux fils de mon sein.'),
('jb',19,18,'crampon1923','Les enfants eux-mêmes me méprisent; si je me lève, ils me raillent.'),
('jb',19,19,'crampon1923','Tous ceux qui étaient mes confidents m''ont en horreur, ceux que j''aimais se tournent contre moi.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('jb',19,20,'crampon1923','Mes os sont attachés à ma peau et à ma chair, je me suis échappé avec la peau de mes dents.'),
('jb',19,21,'crampon1923','Ayez pitié, ayez pitié de moi, vous du moins, mes amis, car la main de Dieu m''a frappé!'),
('jb',19,22,'crampon1923','Pourquoi me poursuivez-vous, comme Dieu me poursuit? Pourquoi êtes-vous insatiables de ma chair?'),
('jb',19,23,'crampon1923','Oh! Qui me donnera que mes paroles soient écrites! Qui me donnera qu''elles soient consignées dans un livre,'),
('jb',19,24,'crampon1923','qu''avec un burin de fer et du plomb, elles soient pour toujours gravées dans le roc!'),
('jb',19,25,'crampon1923','Je sais que mon vengeur est vivant, et qu''il se lèvera le dernier sur la poussière.'),
('jb',19,26,'crampon1923','Alors de ce squelette, revêtu de sa peau, de ma chair je verrai Dieu.'),
('jb',19,27,'crampon1923','Moi-même je le verrai; mes yeux le verront, et non un autre; mes reins se consument d''attente au-dedans de moi.'),
('jb',19,28,'crampon1923','Vous direz alors: « Pourquoi le poursuivions-nous? » et la justice de ma cause sera reconnue.'),
('jb',19,29,'crampon1923','Ce jour-là, craignez pour vous le glaive: terribles sont les vengeances du glaive! Et vous saurez qu''il y a une justice.'),
('jb',20,1,'crampon1923','Alors Sophar de Naama prit la parole et dit:'),
('jb',20,2,'crampon1923','C''est pourquoi mes pensées me suggèrent une réponse, et, à cause de mon agitation, j''ai hâte de la donner.'),
('jb',20,3,'crampon1923','J''ai entendu des reproches qui m''outragent; dans mon intelligence, mon esprit trouvera la réplique.'),
('jb',20,4,'crampon1923','Sais-tu bien que, de tout temps, depuis que l''homme a été placé sur la terre,'),
('jb',20,5,'crampon1923','le triomphe des méchants a été court, et la joie de l''impie d''un moment?'),
('jb',20,6,'crampon1923','Quand il porterait son orgueil jusqu''au ciel, et que sa tête toucherait aux nues,'),
('jb',20,7,'crampon1923','comme son ordure, il périt pour toujours; ceux qui le voyaient disent: « Où est-il? »'),
('jb',20,8,'crampon1923','Il s''envole comme un songe, et on ne le trouve plus; il s''efface comme une vision de la nuit.'),
('jb',20,9,'crampon1923','L''œil qui le voyait ne le découvre plus; sa demeure ne l''apercevra plus.'),
('jb',20,10,'crampon1923','Ses enfants imploreront les pauvres, de ses propres mains il restituera ses rapines.'),
('jb',20,11,'crampon1923','Ses os étaient pleins de ses iniquités cachées; elles dormiront avec lui dans la poussière.'),
('jb',20,12,'crampon1923','Parce que le mal a été doux à sa bouche, qu''il l''a caché sous sa langue,'),
('jb',20,13,'crampon1923','qu''il l''a savouré sans l''abandonner, et l''a retenu au milieu de son palais:'),
('jb',20,14,'crampon1923','sa nourriture tournera en poison dans ses entrailles, elle deviendra dans son sein le venin de l''aspic.'),
('jb',20,15,'crampon1923','Il a englouti des richesses, il les vomira; Dieu les retirera de son ventre.'),
('jb',20,16,'crampon1923','Il a sucé le venin de l''aspic, la langue de la vipère le tuera.'),
('jb',20,17,'crampon1923','Il ne verra jamais couler les fleuves, les torrents de miel et de lait.'),
('jb',20,18,'crampon1923','Il rendra ce qu''il a gagné et ne s''en gorgera pas, dans la mesure de ses profits, et il n''en jouira pas.'),
('jb',20,19,'crampon1923','Car il a opprimé et délaissé les pauvres, il a saccagé leur maison, et ne l''a point rétablie:'),
('jb',20,20,'crampon1923','son avidité n''a pu être rassasiée, il n''emportera pas ce qu''il a de plus cher.'),
('jb',20,21,'crampon1923','Rien n''échappait à sa voracité; aussi son bonheur ne subsistera pas.'),
('jb',20,22,'crampon1923','Au sein de l''abondance, il tombe dans la disette; tous les coups du malheur viennent sur lui.'),
('jb',20,23,'crampon1923','Voici pour lui remplir le ventre: Dieu enverra sur lui le feu de sa colère, elle pleuvra sur lui jusqu''en ses entrailles.'),
('jb',20,24,'crampon1923','S''il échappe aux armes de fer, l''arc d''airain le transperce.'),
('jb',20,25,'crampon1923','Il arrache le trait, il sort de son corps, l''acier sort étincelant de son foie; les terreurs de la mort tombent sur lui.'),
('jb',20,26,'crampon1923','Une nuit profonde engloutit ses trésors; un feu que l''homme n''a pas allumé le dévore, et consume tout ce qui restait dans sa tente.'),
('jb',20,27,'crampon1923','Les cieux révéleront son iniquité, et la terre s''élèvera contre lui.'),
('jb',20,28,'crampon1923','L''abondance de sa maison sera dispersée, elle disparaîtra au jour de la colère.'),
('jb',20,29,'crampon1923','Telle est la part que Dieu réserve au méchant, et l''héritage que lui destine Dieu.'),
('jb',21,1,'crampon1923','Alors Job prit la parole et dit:'),
('jb',21,2,'crampon1923','Ecoutez, écoutez mes paroles, que j''aie, du moins, cette consolation de vous.'),
('jb',21,3,'crampon1923','Permettez-moi de parler à mon tour, et, quand j''aurai parlé, vous pourrez vous moquer.'),
('jb',21,4,'crampon1923','Est-ce contre un homme que se porte ma plainte? Comment donc la patience ne m''échapperait elle pas?'),
('jb',21,5,'crampon1923','Regardez-moi et soyez dans la stupeur, et mettez la main sur votre bouche.'),
('jb',21,6,'crampon1923','Quand j''y pense, je frémis; et un frissonnement saisit ma chair.'),
('jb',21,7,'crampon1923','Pourquoi les méchants vivent-ils, et vieillissent-ils, accroissant leur force?'),
('jb',21,8,'crampon1923','Leur postérité s''affermit autour d''eux, leurs rejetons fleurissent à leurs yeux.'),
('jb',21,9,'crampon1923','Leur maison est en paix, à l''abri de la crainte; la verge de Dieu ne les touche pas.'),
('jb',21,10,'crampon1923','Leur taureau est toujours fécond, leur génisse enfante et n''avorte pas.'),
('jb',21,11,'crampon1923','Ils laissent courir leurs enfants comme un troupeau, leurs nouveau-nés bondissent autour d''eux.'),
('jb',21,12,'crampon1923','Ils chantent au son du tambourin et de la cithare, ils se divertissent au son du chalumeau.'),
('jb',21,13,'crampon1923','Ils passent leurs jours dans le bonheur, et ils descendent en un instant au schéol.'),
('jb',21,14,'crampon1923','Pourtant ils disaient à Dieu: « Retire-toi de nous; nous ne désirons pas connaître tes voies.'),
('jb',21,15,'crampon1923','Qu''est-ce que le Tout-Puissant, pour que nous le servions? Que gagnerions-nous à le prier? »'),
('jb',21,16,'crampon1923','Leur prospérité n''est-elle pas dans leur main? — Toutefois, loin de moi le conseil de l''impie! —'),
('jb',21,17,'crampon1923','Voit-on souvent s''éteindre la lampe des impies, la ruine fondre sur eux, et Dieu leur assigner un lot dans sa colère?'),
('jb',21,18,'crampon1923','Les voit-on comme la paille emportée par le vent, comme la glume enlevée par le tourbillon?'),
('jb',21,19,'crampon1923','« Dieu, dites-vous, réserve à ses enfants son châtiment!... » Mais que Dieu le punisse lui-même pour qu''il le sente,'),
('jb',21,20,'crampon1923','qu''il voie de ses yeux sa ruine, qu''il boive lui-même la colère du Tout-Puissant!'),
('jb',21,21,'crampon1923','Que lui importe, en effet, sa maison après lui, une fois que le nombre de ses mois est tranché?'),
('jb',21,22,'crampon1923','Est-ce à Dieu qu''on apprendra la sagesse, à lui qui juge les êtres les plus élevés?'),
('jb',21,23,'crampon1923','L''un meurt au sein de sa prospérité, parfaitement heureux et tranquille,'),
('jb',21,24,'crampon1923','les flancs chargés de graisse, et la moelle des os remplie de sève.'),
('jb',21,25,'crampon1923','L''autre meurt, l''amertume dans l''âme, sans avoir goûté le bonheur.'),
('jb',21,26,'crampon1923','Tous deux se couchent également dans la poussière, et les vers les couvrent tous deux.'),
('jb',21,27,'crampon1923','Ah! Je sais bien quelles sont vos pensées, quels jugements iniques vous portez sur moi.'),
('jb',21,28,'crampon1923','Vous dites: « Où est la maison de l''oppresseur! Qu''est devenue la tente qu''habitaient les impies? »'),
('jb',21,29,'crampon1923','N''avez-vous donc jamais interrogé les voyageurs, et ignorez-vous leurs remarques?'),
('jb',21,30,'crampon1923','Au jour du malheur, le méchant est épargné; au jour de la colère, il échappe au châtiment.'),
('jb',21,31,'crampon1923','Qui blâme devant lui sa conduite? Qui lui demande compte de ce qu''il a fait?'),
('jb',21,32,'crampon1923','On le porte honorablement au tombeau; et on veille sur son mausolée.'),
('jb',21,33,'crampon1923','les glèbes de la vallée lui sont légères, et tous les hommes y vont à sa suite, comme des générations sans nombre l''y ont précédé.'),
('jb',21,34,'crampon1923','Que signifient donc vos vaines consolations? De vos réponses il ne reste que perfidie.'),
('jb',22,1,'crampon1923','Alors Eliphaz prit la parole et dit:'),
('jb',22,2,'crampon1923','L''homme peut-il être utile à Dieu? Le sage n''est utile qu''à lui-même.'),
('jb',22,3,'crampon1923','Qu''importe au Tout-Puissant que tu sois juste? Si tu es intègre dans tes voies, qu''y gagne-t-il?'),
('jb',22,4,'crampon1923','Est-ce à cause de ta piété qu''il te châtie, qu''il entre en jugement avec toi?'),
('jb',22,5,'crampon1923','Ta malice n''est-elle pas immense, tes iniquités sans mesure?'),
('jb',22,6,'crampon1923','Tu prenais sans motif des gages à tes frères, tu enlevais les vêtements à ceux qui étaient nus.'),
('jb',22,7,'crampon1923','Tu ne donnais point d''eau à l''homme épuisé, à l''affamé tu refusais le pain.'),
('jb',22,8,'crampon1923','La terre était au bras le plus fort, et le protégé y établissait sa demeure.'),
('jb',22,9,'crampon1923','Tu renvoyais les veuves les mains vides, et les bras des orphelins étaient brisés.'),
('jb',22,10,'crampon1923','Voilà pourquoi tu es entouré de pièges, et troublé par des terreurs soudaines,'),
('jb',22,11,'crampon1923','au sein des ténèbres, sans voir, et submergé par le déluge des eaux.'),
('jb',22,12,'crampon1923','Dieu n''est-il pas dans les hauteurs du ciel? Vois le front des étoiles: comme il est élevé!'),
('jb',22,13,'crampon1923','Et tu disais: « Qu''en sait Dieu? Pourra-t-il juger à travers les nues profondes?'),
('jb',22,14,'crampon1923','Les nues lui forment un voile, et il ne voit pas; il se promène sur le cercle du ciel. »'),
('jb',22,15,'crampon1923','Gardes-tu donc les voies anciennes, où marchèrent les hommes d''iniquité,'),
('jb',22,16,'crampon1923','qui furent emportés avant le temps, dont les fondements ont été arrachés par les eaux.'),
('jb',22,17,'crampon1923','Eux qui disaient à Dieu: « Retire-toi de nous! Que pourrait nous faire le Tout-Puissant? »'),
('jb',22,18,'crampon1923','C''était lui pourtant qui avait rempli leurs maisons de richesses. — Loin de moi le conseil des méchants! —'),
('jb',22,19,'crampon1923','Les justes voient leur chute et s''en réjouissent; les innocents se moquent d''eux:'),
('jb',22,20,'crampon1923','« Voilà nos ennemis anéantis! Le feu a dévoré leurs richesses! »'),
('jb',22,21,'crampon1923','Réconcilie-toi donc avec Dieu et apaise-toi; ainsi le bonheur te sera rendu.'),
('jb',22,22,'crampon1923','Reçois de sa bouche l''enseignement, et mets ses paroles dans ton cœur.'),
('jb',22,23,'crampon1923','Tu te relèveras, si tu reviens au Tout-Puissant, si tu éloignes l''iniquité de ta tente.'),
('jb',22,24,'crampon1923','Jette les lingots d''or dans la poussière, et l''or d''Ophir parmi les cailloux du torrent.'),
('jb',22,25,'crampon1923','Et le Tout-Puissant sera ton or, il sera pour toi un monceau d''argent.'),
('jb',22,26,'crampon1923','Alors tu mettras tes délices dans le Tout-Puissant, et tu lèveras vers lui ta face.'),
('jb',22,27,'crampon1923','Tu le prieras, et il t''écoutera, et tu t''acquitteras de tes vœux.'),
('jb',22,28,'crampon1923','Si tu formes un dessein, il te réussira, sur tes sentiers brillera la lumière.'),
('jb',22,29,'crampon1923','A des fronts abattus tu crieras: « En haut! » et Dieu secourra celui dont les yeux sont abaissés.'),
('jb',22,30,'crampon1923','Il délivrera même le coupable, sauvé par la pureté de tes mains.'),
('jb',23,1,'crampon1923','Alors Job prit la parole et dit:'),
('jb',23,2,'crampon1923','Oui, aujourd''hui ma plainte est amère, et pourtant ma main retient mes soupirs.'),
('jb',23,3,'crampon1923','Oh! Qui me donnera de savoir où le trouver, d''arriver jusqu''à son trône!'),
('jb',23,4,'crampon1923','Je plaiderais ma cause devant lui, et je remplirais ma bouche d''arguments.'),
('jb',23,5,'crampon1923','Je saurais les raisons qu''il peut m''opposer, je verrais ce qu''il peut avoir à me dire.'),
('jb',23,6,'crampon1923','M''opposerait-il la grandeur de sa puissance? Ne jetterait-il pas au moins les yeux sur moi?'),
('jb',23,7,'crampon1923','Alors l''innocent discuterait avec lui, et je m''en irais absous pour toujours par mon juge.'),
('jb',23,8,'crampon1923','Mais si je vais à l''orient, il n''y est pas; à l''occident, je ne l''aperçois pas.'),
('jb',23,9,'crampon1923','Est-il occupé au septentrion, je ne le vois pas; se cache-t-il au midi, je ne puis le découvrir.'),
('jb',23,10,'crampon1923','Cependant il connaît les sentiers où je marche; qu''il m''examine, je sortirai pur comme l''or.'),
('jb',23,11,'crampon1923','Mon pied a toujours foulé ses traces; je me suis tenu dans sa voie sans dévier.'),
('jb',23,12,'crampon1923','Je ne me suis pas écarté des préceptes de ses lèvres; j''ai fait plier ma volonté aux paroles de sa bouche.'),
('jb',23,13,'crampon1923','Mais il a une pensée: qui l''en fera revenir? Ce qu''il désire, il l''exécute.'),
('jb',23,14,'crampon1923','Il accomplira donc ce qu''il a décrété à mon sujet, et de pareils desseins, il en a beaucoup.'),
('jb',23,15,'crampon1923','Voilà pourquoi je me trouble en sa présence; quand j''y pense, j''ai peur de lui.'),
('jb',23,16,'crampon1923','Dieu fait fondre mon cœur; le Tout-Puissant me remplit d''effroi.'),
('jb',23,17,'crampon1923','Car ce ne sont pas les ténèbres qui me consument, ni l''obscurité dont ma face est voilée.'),
('jb',24,1,'crampon1923','Pourquoi n''y a-t-il pas de temps réservés par le Tout-Puissant, et ceux qui le servent ne voient-ils pas son jour?'),
('jb',24,2,'crampon1923','On voit des hommes qui déplacent les bornes, qui font paître le troupeau qu''ils ont volé.'),
('jb',24,3,'crampon1923','Ils poussent devant eux l''âne de l''orphelin, et retiennent en gage le bœuf de la veuve.'),
('jb',24,4,'crampon1923','Ils forcent les pauvres à se détourner du chemin; tous les humbles du pays sont réduits à se cacher.'),
('jb',24,5,'crampon1923','Comme l''onagre dans la solitude, ils sortent pour leur travail, dès le matin, cherchant leur nourriture. Le désert leur fournit la subsistance de leurs enfants;'),
('jb',24,6,'crampon1923','ils coupent les épis dans les champs, ils maraudent dans la vigne de leur oppresseur.'),
('jb',24,7,'crampon1923','Nus, ils passent la nuit, faute de vêtements, sans couverture contre le froid.'),
('jb',24,8,'crampon1923','La pluie des montagnes les pénètre; à défaut d''abri, ils se blottissent contre le rocher.'),
('jb',24,9,'crampon1923','Ils arrachent l''orphelin à la mamelle, ils prennent des gages sur les pauvres.'),
('jb',24,10,'crampon1923','Ceux-ci, tout nus, sans vêtements, portent, affamés, les gerbes du maître;'),
('jb',24,11,'crampon1923','Ils expriment l''huile dans ses celliers; ils foulent la vendange, et ils ont soif.'),
('jb',24,12,'crampon1923','Du sein des villes s''élèvent les gémissements des hommes, et l''âme des blessés crie; et Dieu ne prend pas garde à ces forfaits!'),
('jb',24,13,'crampon1923','D''autres sont parmi les ennemis de la lumière, ils n''en connaissent pas les voies, ils ne se tiennent pas dans ses sentiers.'),
('jb',24,14,'crampon1923','L''assassin se lève au point du jour; il tue le pauvre et l''indigent, il rôde la nuit comme un voleur.'),
('jb',24,15,'crampon1923','L''œil de l''adultère épie le crépuscule; « Personne ne me voit, » dit-il, et il jette un voile sur son visage.'),
('jb',24,16,'crampon1923','La nuit, d''autres forcent les maisons, le jour, ils se tiennent cachés: ils ne connaissent pas la lumière.'),
('jb',24,17,'crampon1923','Pour eux, le matin est comme l''ombre de la mort, car les horreurs de la nuit leur sont familières.'),
('jb',24,18,'crampon1923','Ah! l''impie glisse comme un corps léger sur la face des eaux, il n''a sur la terre qu''une part maudite, il ne se dirige pas sur le chemin des vignes!'),
('jb',24,19,'crampon1923','Comme la sécheresse et la chaleur absorbent l''eau des neiges, ainsi le schéol engloutit les pécheurs!'),
('jb',24,20,'crampon1923','Ah! Le sein maternel l''oublie, les vers en font leurs délices; on ne se souvient plus de lui, et l''iniquité est brisée comme un arbre.'),
('jb',24,21,'crampon1923','Il dévorait la femme stérile et sans enfants, il ne faisait pas de bien à la veuve!...'),
('jb',24,22,'crampon1923','Mais Dieu par sa force ébranle les puissants, il se lève, et ils ne comptent plus sur la vie;'),
('jb',24,23,'crampon1923','il leur donne la sécurité et la confiance, et ses yeux veillent sur leurs voies.'),
('jb',24,24,'crampon1923','Ils se sont élevés, et en un instant ils ne sont plus; ils tombent, ils sont moissonnés comme tous les hommes; ils sont coupés comme la tête des épis.'),
('jb',24,25,'crampon1923','S''il n''en est pas ainsi, qui me convaincra de mensonge? Qui réduira mes paroles à néant?'),
('jb',25,1,'crampon1923','Alors Baldad de Suhé prit la parole et dit:'),
('jb',25,2,'crampon1923','A lui appartiennent la domination et la terreur; il fait régner la paix dans ses hautes demeures.'),
('jb',25,3,'crampon1923','Ses légions ne sont-elles pas innombrables? Sur qui ne se lève pas sa lumière?'),
('jb',25,4,'crampon1923','Comment l''homme serait-il juste devant Dieu? Comment le fils de la femme serait-il pur?'),
('jb',25,5,'crampon1923','Voici que la lune même est sans clarté, les étoiles ne sont pas pures à ses yeux:'),
('jb',25,6,'crampon1923','combien moins l''homme, ce vermisseau, le fils de l''homme, ce vil insecte!'),
('jb',25,7,'crampon1923',''),
('jb',25,8,'crampon1923',''),
('jb',25,9,'crampon1923',''),
('jb',25,10,'crampon1923',''),
('jb',25,11,'crampon1923',''),
('jb',25,12,'crampon1923',''),
('jb',25,13,'crampon1923',''),
('jb',25,14,'crampon1923',''),
('jb',26,1,'crampon1923','Alors Job prit la parole et dit:'),
('jb',26,2,'crampon1923','Comme tu sais venir en aide à la faiblesse, prêter secours au bras sans force!'),
('jb',26,3,'crampon1923','Comme tu conseilles bien l''ignorant! Quelle abondance de sagesse tu fais paraître!'),
('jb',26,4,'crampon1923','A qui adresses-tu des paroles? Et de qui est l''esprit qui sort de ta bouche?'),
('jb',26,5,'crampon1923','Devant Dieu, les ombres tremblent sous les eaux et leurs habitants.'),
('jb',26,6,'crampon1923','Le schéol est à nu devant lui, et l''abîme n''a point de voile.'),
('jb',26,7,'crampon1923','Il étend le septentrion sur le vide, il suspend la terre sur le néant.'),
('jb',26,8,'crampon1923','Il renferme les eaux dans ses nuages, et les nues ne se déchirent pas sous leur poids.'),
('jb',26,9,'crampon1923','Il voile la face de son trône, il étend sur lui ses nuées.'),
('jb',26,10,'crampon1923','Il a tracé un cercle à la surface des eaux, au point de division de la lumière et des ténèbres.'),
('jb',26,11,'crampon1923','Les colonnes du ciel s''ébranlent, et s''épouvantent à sa menace.'),
('jb',26,12,'crampon1923','Par sa puissance il soulève la mer, par sa sagesse il brise l''orgueil.'),
('jb',26,13,'crampon1923','Par son souffle le ciel devient serein, sa main a formé le serpent fuyard.'),
('jb',26,14,'crampon1923','Tels sont les bords de ses voies, le léger murmure que nous en percevons; mais le tonnerre de sa puissance, qui pourra l''entendre?'),
('jb',27,1,'crampon1923','Job reprit son discours et dit:'),
('jb',27,2,'crampon1923','Par le Dieu vivant qui me refuse justice, par le Tout-Puissant qui remplit mon âme d''amertume:'),
('jb',27,3,'crampon1923','aussi longtemps que j''aurai la respiration, que le souffle de Dieu sera dans mes narines,'),
('jb',27,4,'crampon1923','mes lèvres ne prononceront rien d''inique, ma langue ne proférera pas le mensonge.'),
('jb',27,5,'crampon1923','Loin de moi la pensée de vous donner raison! Jusqu''à ce que j''expire, je défendrai mon innocence.'),
('jb',27,6,'crampon1923','J''ai entrepris ma justification, je ne l''abandonnerai pas; mon cœur ne condamne aucun de mes jours.'),
('jb',27,7,'crampon1923','Que mon ennemi soit traité comme le méchant! Que mon adversaire ait le sort de l''impie!'),
('jb',27,8,'crampon1923','Quel sera l''espoir de l''impie quand Dieu le retranchera, quand il retirera son âme?'),
('jb',27,9,'crampon1923','Est-ce que Dieu écoutera ses cris, au jour où l''angoisse viendra sur lui?'),
('jb',27,10,'crampon1923','Trouve-t-il ses délices dans le Tout-Puissant? Adresse-t-il en tout temps ses prières à Dieu?'),
('jb',27,11,'crampon1923','Je vous enseignerai la conduite de Dieu, et je ne vous cacherai pas les desseins du Tout-Puissant.'),
('jb',27,12,'crampon1923','Voici que vous-mêmes, vous avez tous vu; pourquoi donc discourez-vous en vain?'),
('jb',27,13,'crampon1923','Voici la part que Dieu réserve au méchant, l''héritage que les violents reçoivent du Tout-Puissant.'),
('jb',27,14,'crampon1923','S''il a des fils en grand nombre, c''est pour le glaive; ses rejetons ne seront pas rassasiés de pain.'),
('jb',27,15,'crampon1923','Ses survivants seront ensevelis dans la mort, leurs veuves ne les pleureront pas.'),
('jb',27,16,'crampon1923','S''il amasse l''argent comme la poussière, s''il entasse les vêtements comme la boue,'),
('jb',27,17,'crampon1923','c''est lui qui entasse, mais c''est le juste qui les porte, c''est le juste qui hérite de ton argent.'),
('jb',27,18,'crampon1923','Sa maison est comme celle que bâtit la teigne, comme la hutte que se construit le gardien des vignes.'),
('jb',27,19,'crampon1923','Le riche se couche, c''est pour la dernière fois; il ouvre les yeux, il n''est plus.'),
('jb',27,20,'crampon1923','Les terreurs fondent sur lui comme des eaux, un tourbillon l''enlève au milieu de la nuit.'),
('jb',27,21,'crampon1923','Le vent d''orient l''emporte, et il disparaît; il l''arrache violemment de sa demeure.'),
('jb',27,22,'crampon1923','Dieu lance sur lui ses traits sans pitié, il fuit éperdu loin de sa main;'),
('jb',27,23,'crampon1923','on bat des mains à son sujet, de sa demeure on siffle sur lui.'),
('jb',27,24,'crampon1923',''),
('jb',28,1,'crampon1923','Il y a pour l''argent un lieu d''où on l''extrait, pour l''or un lieu où on l''épure.'),
('jb',28,2,'crampon1923','Le fer se tire de la terre, et la pierre fondue donne le cuivre.'),
('jb',28,3,'crampon1923','L''homme met fin aux ténèbres, il explore, jusqu''au fond des abîmes, la pierre cachée dans les ténèbres et l''ombre de la mort.'),
('jb',28,4,'crampon1923','Il creuse, loin des lieux habités, des galeries, qu''ignore le pied des vivants; suspendu, il vacille, loin des humains.'),
('jb',28,5,'crampon1923','La terre, d''où sort le pain, est bouleversée dans ses entrailles comme par le feu.'),
('jb',28,6,'crampon1923','Ses roches sont le lieu du saphir, et l''on y trouve de la poudre d''or.'),
('jb',28,7,'crampon1923','L''oiseau de proie n''en connaît pas le sentier, l''œil du vautour ne l''a point aperçu.'),
('jb',28,8,'crampon1923','Les animaux sauvages ne l''ont point foulé, le lion n''y a jamais passé.'),
('jb',28,9,'crampon1923','L''homme porte sa main sur le granit, il ébranle les montagnes dans leurs racines.'),
('jb',28,10,'crampon1923','Il perce des galeries dans les rochers; rien de précieux n''échappe à son regard.'),
('jb',28,11,'crampon1923','Il sait arrêter le suintement des eaux, il amène à la lumière tout ce qui était caché.'),
('jb',28,12,'crampon1923','Mais la Sagesse, où la trouver? Où est le lieu de l''Intelligence?'),
('jb',28,13,'crampon1923','L''homme n''en connaît pas le prix, on ne la rencontre pas sur la terre des vivants.'),
('jb',28,14,'crampon1923','L''abîme dit: « Elle n''est pas dans mon sein; » la mer dit: « Elle n''est pas avec moi. »'),
('jb',28,15,'crampon1923','Elle ne se donne pas contre de l''or pur, elle ne s''achète pas au poids de l''argent.'),
('jb',28,16,'crampon1923','On ne la met pas en balance avec de l''or d''Ophir, avec l''onyx précieux et avec le saphir.'),
('jb',28,17,'crampon1923','L''or et le verre ne peuvent lui être comparés, on ne l''échange pas pour un vase d''or fin.'),
('jb',28,18,'crampon1923','Qu''on ne fasse pas mention du corail et du cristal: la possession de la sagesse vaut mieux que les perles.'),
('jb',28,19,'crampon1923','La topaze d''Ethiopie ne l''égale pas, et l''or pur n''atteint pas sa valeur.'),
('jb',28,20,'crampon1923','D''où vient donc la sagesse? Où est lieu de l''Intelligence?'),
('jb',28,21,'crampon1923','Elle est cachée aux yeux de tous les vivants, elle se dérobe aux oiseaux du ciel.'),
('jb',28,22,'crampon1923','L''enfer et la mort disent: « Nous en avons entendu parler. »'),
('jb',28,23,'crampon1923','C''est Dieu qui connaît son chemin, c''est lui qui sait où elle réside.'),
('jb',28,24,'crampon1923','Car il voit jusqu''aux extrémités de la terre, il aperçoit tout ce qui est sous le ciel.'),
('jb',28,25,'crampon1923','Quand il réglait le poids des vents, qu''il mettait les eaux dans la balance,'),
('jb',28,26,'crampon1923','quand il donnait des lois à la pluie, qu''il traçait la route aux éclairs de la foudre,'),
('jb',28,27,'crampon1923','alors il l''a vue et l''a décrite, il l''a établie et en a sondé les secrets.'),
('jb',28,28,'crampon1923','Puis il a dit à l''homme: La crainte du Seigneur, voilà la sagesse; fuir le mal, voilà l''intelligence.'),
('jb',29,1,'crampon1923','Job reprit encore son discours et dit:'),
('jb',29,2,'crampon1923','Oh! Qui me rendra les mois d''autrefois, les jours où Dieu veillait à ma garde;'),
('jb',29,3,'crampon1923','quand sa lampe brillait sur ma tête, et que sa lumière me guidait dans les ténèbres!'),
('jb',29,4,'crampon1923','Tel que j''étais aux jours de mon âge mûr, quand Dieu me visitait familièrement dans ma tente,'),
('jb',29,5,'crampon1923','quand le Tout-Puissant était encore avec moi, et que mes fils m''entouraient;'),
('jb',29,6,'crampon1923','quand je lavais mes pieds dans le lait, et que le rocher me versait des flots d''huile!'),
('jb',29,7,'crampon1923','Lorsque je sortais pour me rendre à la porte de la ville, et que j''établissais mon siège sur la place publique,'),
('jb',29,8,'crampon1923','en me voyant, les jeunes gens se cachaient, les vieillards se levaient et se tenaient debout.'),
('jb',29,9,'crampon1923','Les princes retenaient leurs paroles, et mettaient leur main sur la bouche.'),
('jb',29,10,'crampon1923','La voix des chefs restait muette, leur langue s''attachait à leur palais.'),
('jb',29,11,'crampon1923','L''oreille qui m''entendait me proclamait heureux, l''œil qui me voyait me rendait témoignage.'),
('jb',29,12,'crampon1923','Car je sauvais le pauvre qui implorait du secours, et l''orphelin dénué de tout appui.'),
('jb',29,13,'crampon1923','La bénédiction de celui qui allait périr venait sur moi, je remplissais de joie le cœur de la veuve.'),
('jb',29,14,'crampon1923','Je me revêtais de la justice comme d''un vêtement, mon équité était mon manteau et mon turban.'),
('jb',29,15,'crampon1923','J''étais l''œil de l''aveugle, et le pied du boiteux.'),
('jb',29,16,'crampon1923','J''étais le père des pauvres, j''examinais avec soin la cause de l''inconnu.'),
('jb',29,17,'crampon1923','Je brisais la mâchoire de l''injuste, et j''arrachais sa proie d''entre les dents.'),
('jb',29,18,'crampon1923','Je disais: « Je mourrai dans mon nid, j''aurai des jours nombreux comme le sable.'),
('jb',29,19,'crampon1923','Mes racines s''étendent vers les eaux, la rosée passe la nuit dans mon feuillage.'),
('jb',29,20,'crampon1923','Ma gloire reverdira sans cesse, et mon arc reprendra sa vigueur dans ma main. »'),
('jb',29,21,'crampon1923','On m''écoutait et l''on attendait, on recueillait en silence mon avis.'),
('jb',29,22,'crampon1923','Après que j''avais parlé, personne n''ajoutait rien; ma parole coulait sur eux comme la rosée.'),
('jb',29,23,'crampon1923','Ils m''attendaient comme on attend la pluie; ils ouvraient la bouche comme aux ondées du printemps.'),
('jb',29,24,'crampon1923','Si je leur souriais, ils ne pouvaient le croire; ils recueillaient avidement ce signe de faveur.'),
('jb',29,25,'crampon1923','Quand j''allais vers eux, j''avais la première place, je siégeais comme un roi entouré de sa troupe, comme un consolateur au milieu des affligés.'),
('jb',30,1,'crampon1923','Et maintenant, je suis la risée d''hommes plus jeunes que moi, dont je n''aurais pas daigné mettre les pères parmi les chiens de mon troupeau.'),
('jb',30,2,'crampon1923','Qu''aurais-je fait de la force de leurs bras? Ils sont privés de toute vigueur.'),
('jb',30,3,'crampon1923','Desséchés par la misère et la faim, ils broutent le désert, un sol depuis longtemps aride et désolé.'),
('jb',30,4,'crampon1923','Ils cueillent sur les buissons des bourgeons amers, ils n''ont pour pain que la racine des genêts.'),
('jb',30,5,'crampon1923','On les écarte de la société des hommes, on crie après eux comme après le voleur.'),
('jb',30,6,'crampon1923','Ils habitent dans d''affreuses vallées, dans les cavernes de la terre et les rochers.'),
('jb',30,7,'crampon1923','On entend leurs cris sauvages parmi les broussailles, ils se couchent ensemble sous les ronces:'),
('jb',30,8,'crampon1923','gens insensés, race sans nom, bannis avec mépris de la terre habitée!'),
('jb',30,9,'crampon1923','Et maintenant je suis l''objet de leurs chansons, je suis en butte à leurs propos.'),
('jb',30,10,'crampon1923','Ils ont horreur de moi, ils me fuient, ils ne détournent pas leur crachat de mon visage.'),
('jb',30,11,'crampon1923','Ils se donnent libre carrière pour m''outrager, ils rejettent tout frein devant moi.'),
('jb',30,12,'crampon1923','Des misérables se lèvent à ma droite, ils cherchent à ébranler mes pieds, ils frayent jusqu''à moi leurs routes meurtrières.'),
('jb',30,13,'crampon1923','Ils ont bouleversé mes sentiers, ils travaillent à ma ruine, eux à qui personne ne porterait secours.'),
('jb',30,14,'crampon1923','Ils fondent sur moi, comme par une large brèche, ils se précipitent parmi les décombres.'),
('jb',30,15,'crampon1923','Les terreurs m''assiègent, ma prospérité est emportée comme un souffle, mon bonheur a passé comme un nuage.'),
('jb',30,16,'crampon1923','Et maintenant, mon âme s''épanche en moi, les jours d''affliction m''ont saisi.'),
('jb',30,17,'crampon1923','La nuit perce mes os, les consume, le mal qui me ronge ne dort pas.'),
('jb',30,18,'crampon1923','Par sa violence, mon vêtement a perdu sa forme, il me serre comme une tunique.'),
('jb',30,19,'crampon1923','Dieu m''a jeté dans la fange, je suis comme la poussière et la cendre.'),
('jb',30,20,'crampon1923','Je crie vers toi, et tu ne me réponds pas; je me tiens debout, et tu me regardes avec indifférence.'),
('jb',30,21,'crampon1923','Tu deviens cruel à mon égard, tu m''attaques avec toute la force de ton bras.'),
('jb',30,22,'crampon1923','Tu m''enlèves, tu me fais voler au gré du vent, et tu m''anéantis dans le fracas de la tempête.'),
('jb',30,23,'crampon1923','Car, je le sais, tu me mènes à la mort, au rendez-vous de tous les vivants.'),
('jb',30,24,'crampon1923','Cependant celui qui va périr n''étendra-t-il pas les mains et, dans sa détresse, ne poussera-t-il pas un cri?'),
('jb',30,25,'crampon1923','N''avais-je pas des larmes pour l''infortuné? Mon cœur ne s''est-il pas attendri sur l''indigent?'),
('jb',30,26,'crampon1923','J''attendais le bonheur, et le malheur est arrivé; j''espérais la lumière, et les ténèbres sont venues.'),
('jb',30,27,'crampon1923','Mes entrailles bouillonnent sans relâche, les jours d''affliction ont fondu sur moi.'),
('jb',30,28,'crampon1923','Je marche dans le deuil, sans soleil; si je me lève dans l''assemblée, c''est pour pousser des cris.'),
('jb',30,29,'crampon1923','Je suis devenu le frère des chacals, le compagnon des filles de l''autruche.'),
('jb',30,30,'crampon1923','Ma peau livide tombe en lambeaux, mes os sont brûlés par un feu intérieur.'),
('jb',30,31,'crampon1923','Ma cithare ne rend plus que des accords lugubres, mon chalumeau que des sons plaintifs.'),
('jb',31,1,'crampon1923','J''avais fait un pacte avec mes yeux, et comment aurais-je arrêté mes regards sur une vierge. —'),
('jb',31,2,'crampon1923','Quelle part, me disais-je, Dieu me réserverait-il d''en haut? Quel sort le Tout-Puissant me ferait-il de son ciel?'),
('jb',31,3,'crampon1923','La ruine n''est-elle pas pour le méchant, et le malheur pour les artisans d''iniquité?'),
('jb',31,4,'crampon1923','Dieu ne connaît-il pas mes voies, ne compte-t-il pas tous mes pas?'),
('jb',31,5,'crampon1923','Si j''ai marché dans le sentier du mensonge, si mon pied a couru après la fraude, —'),
('jb',31,6,'crampon1923','que Dieu me pèse dans de justes balances, et il reconnaîtra mon innocence!'),
('jb',31,7,'crampon1923','Si mes pas se sont écartés du droit chemin, si mon cœur a suivi mes yeux, si quelque souillure s''est attachée à mes mains, —'),
('jb',31,8,'crampon1923','que je sème, et qu''un autre mange, que mes rejetons soient déracinés!'),
('jb',31,9,'crampon1923','Si mon cœur a été séduit par une femme, si j''ai fait le guet à la porte de mon prochain, —'),
('jb',31,10,'crampon1923','que ma femme tourne la meule pour un autre, que des étrangers la déshonorent!'),
('jb',31,11,'crampon1923','Car c''est là un crime horrible, un forfait que punissent les juges;'),
('jb',31,12,'crampon1923','un feu qui dévore jusqu''à la ruine, qui aurait détruit tous mes biens.'),
('jb',31,13,'crampon1923','Si j''ai méconnu le droit de mon serviteur ou de ma servante, quand ils étaient en contestation avec moi: —'),
('jb',31,14,'crampon1923','Que faire, quand Dieu se lèvera? Au jour de sa visite, que lui répondrai-je?'),
('jb',31,15,'crampon1923','Celui qui m''a fait dans le sein de ma mère ne l''a-t-il pas fait aussi? Un même Créateur ne nous a-t-il pas formés?'),
('jb',31,16,'crampon1923','Si j''ai refusé aux pauvres ce qu''ils désiraient, si j''ai fait languir les yeux de la veuve,'),
('jb',31,17,'crampon1923','si j''ai mangé seul mon morceau de pain, sans que l''orphelin en ait eu sa part: —'),
('jb',31,18,'crampon1923','dès mon enfance il m''a gardé comme un père; dès ma naissance il a guidé mes pas.'),
('jb',31,19,'crampon1923','Si j''ai vu le malheureux périr sans vêtements, l''indigent manquer de couverture,'),
('jb',31,20,'crampon1923','sans que ses reins m''aient béni, sans que la toison de mes agneaux l''ait réchauffé;'),
('jb',31,21,'crampon1923','si j''ai levé la main contre l''orphelin, parce que je me voyais un appui dans les juges, —'),
('jb',31,22,'crampon1923','que mon épaule se détache du tronc, que mon bras soit arraché de l''humérus.'),
('jb',31,23,'crampon1923','Car je crains la vengeance de Dieu, et devant sa majesté je ne puis subsister.'),
('jb',31,24,'crampon1923','Si j''ai mis dans l''or mon assurance, si j''ai dit à l''or pur: « Tu es mon espoir; »'),
('jb',31,25,'crampon1923','si je me suis réjoui de l''abondance de mes biens, des trésors amassés par mes mains;'),
('jb',31,26,'crampon1923','si, en voyant le soleil jeter ses feux, et la lune s''avancer dans sa splendeur,'),
('jb',31,27,'crampon1923','mon cœur s''est laissé séduire en secret, si ma main s''est portée à ma bouche, —'),
('jb',31,28,'crampon1923','c''est là encore un crime que punit le juge; j''aurais renié le Dieu très-haut.'),
('jb',31,29,'crampon1923','Si j''ai été joyeux de la ruine de mon ennemi, si j''ai tressailli d''allégresse quand le malheur l''a frappé: —'),
('jb',31,30,'crampon1923','Non, je n''ai pas permis à ma langue de pécher, en demandant sa mort avec imprécation!...'),
('jb',31,31,'crampon1923','Si les gens de ma tente ne disaient pas: « Où trouver quelqu''un qui ne soit pas rassasiés de sa table? »'),
('jb',31,32,'crampon1923','si l''étranger passait la nuit en dehors, si je n''ouvrais pas la porte au voyageur!...'),
('jb',31,33,'crampon1923','Si j''ai, comme font les hommes, déguisé mes fautes, et renfermé mes iniquités dans mon sein,'),
('jb',31,34,'crampon1923','par peur de la grande assemblée, par crainte du mépris des familles, au point de me taire, et de n''oser franchir le seuil de ma porte!...'),
('jb',31,35,'crampon1923','Oh! Qui me fera trouver quelqu''un qui m''écoute? Voilà ma signature: que le Tout-Puissant me réponde! Que mon adversaire écrive aussi sa cédule!'),
('jb',31,36,'crampon1923','On verra si je ne la mets pas sur mon épaule, si je n''en ceins pas mon front comme d''un diadème!'),
('jb',31,37,'crampon1923','Je rendrai compte à mon juge de tous mes pas, je m''approcherai de lui comme un prince.'),
('jb',31,38,'crampon1923','Si ma terre crie contre moi, si j''ai fait pleurer ses sillons;'),
('jb',31,39,'crampon1923','si j''ai mangé ses produits sans l''avoir payée, si je l''ai arrachée à ses légitimes possesseurs, —'),
('jb',31,40,'crampon1923','qu''au lieu de froment il y naisse des épines, et de l''ivraie au lieu d''orge! Ici finissent les discours de Job.'),
('jb',32,1,'crampon1923','Ces trois hommes cessèrent de répondre à Job, parce qu''il persistait à se regarder comme juste.'),
('jb',32,2,'crampon1923','Alors s''alluma la colère d''Eliu, fils de Barachel le Bouzite, de la famille de Ram. Sa colère s''alluma contre Job, parce qu''il se prétendait plus juste que Dieu.'),
('jb',32,3,'crampon1923','Elle s''alluma aussi contre ses trois amis, parce qu''ils n''avaient pas trouvé de bonnes réponse à lui faire et que néanmoins ils condamnaient Job.'),
('jb',32,4,'crampon1923','Comme ils étaient plus âgés que lui, Eliu avait attendu pour parler à Job.'),
('jb',32,5,'crampon1923','Mais voyant qu''il n''y avait plus de réponse dans la bouche de ces trois hommes, il s''enflamma de colère.'),
('jb',32,6,'crampon1923','Alors Eliu, fils de Barachel le Bouzite, prit la parole et dit: Je suis jeune et vous êtes des vieillards; c''est pourquoi j''étais effrayé et je redoutais de vous faire connaître mon sentiment.'),
('jb',32,7,'crampon1923','Je me disais: « Les jours parleront, les nombreuses années révéleront la sagesse. »'),
('jb',32,8,'crampon1923','Mais c''est l''esprit mis dans l''homme, le souffle du Tout-Puissant qui lui donne l''intelligence.'),
('jb',32,9,'crampon1923','Ce n''est pas l''âge qui donne la sagesse, ce n''est pas la vieillesse qui discerne la justice.'),
('jb',32,10,'crampon1923','Voilà pourquoi je dis: « Écoutez-moi; je vais, moi aussi, exposer ma pensée. »'),
('jb',32,11,'crampon1923','J''ai attendu tant que vous parliez, j''ai prêté l''oreille à vos raisonnements, jusqu''à la fin de vos débats.'),
('jb',32,12,'crampon1923','Je vous ai suivis attentivement, et nul n''a convaincu Job, nul d''entre vous n''a réfuté ses paroles.'),
('jb',32,13,'crampon1923','Ne dites pas: « Nous avons trouvé la sagesse; c''est Dieu qui le frappe, et non pas l''homme. »'),
('jb',32,14,'crampon1923','Il n''a pas dirigé contre moi ses discours, mais ce n''est pas avec vos paroles que je lui répondrai.'),
('jb',32,15,'crampon1923','Les voilà interdits; ils ne répondent rien; la parole leur fait défaut.'),
('jb',32,16,'crampon1923','J''ai attendu qu''ils eussent fini de parler, qu''ils restassent muets et sans réponse.'),
('jb',32,17,'crampon1923','C''est à mon tour de parler à présent; je veux dire aussi ce que je pense.'),
('jb',32,18,'crampon1923','Car je suis plein de discours, l''esprit qui est en moi m''oppresse.'),
('jb',32,19,'crampon1923','Mon cœur est comme un vin renfermé, comme une outre remplie de vin nouveau qui va éclater.'),
('jb',32,20,'crampon1923','Que je parle donc, afin de respirer à l''aise, que mes lèvres s''ouvrent pour répondre!'),
('jb',32,21,'crampon1923','Je ne veux faire acception de personne, je ne flatterai qui que ce soit.'),
('jb',32,22,'crampon1923','Car je ne sais pas flatter; autrement mon Créateur m''enlèverait sur-le-champ.'),
('jb',33,1,'crampon1923','Maintenant donc, Job, écoute mes paroles, prête l''oreille à tous mes discours.'),
('jb',33,2,'crampon1923','Voilà que j''ouvre la bouche, ma langue forme des mots dans mon palais,'),
('jb',33,3,'crampon1923','mes paroles partiront d''un cœur droit, c''est la vérité pure qu''exprimeront mes lèvres.'),
('jb',33,4,'crampon1923','L''esprit de Dieu m''a créé, le souffle du Tout-Puissant me donne la vie.'),
('jb',33,5,'crampon1923','Si tu le peux, réponds-moi; dispose tes arguments devant moi, tiens-toi ferme.'),
('jb',33,6,'crampon1923','Devant Dieu je suis ton égal, comme toi j''ai été formé du limon.'),
('jb',33,7,'crampon1923','Ainsi ma crainte ne t''épouvantera pas, et le poids de ma majesté ne peut t''accabler.'),
('jb',33,8,'crampon1923','Oui, tu as dit à mes oreilles, et j''ai bien entendu le son de tes paroles;'),
('jb',33,9,'crampon1923','« Je suis pur, exempt de tout péché; je suis irréprochable, il n''y a point d''iniquité en moi.'),
('jb',33,10,'crampon1923','Et Dieu invente contre moi des motifs de haine, il me traite comme son ennemi.'),
('jb',33,11,'crampon1923','Il a mis mes pieds dans les ceps, il surveille tous mes pas. »'),
('jb',33,12,'crampon1923','Je te répondrai qu''en cela tu n''as pas été juste, car Dieu est plus grand que l''homme.'),
('jb',33,13,'crampon1923','Pourquoi disputer contre lui, parce qu''il ne rend compte de ses actes à personne?'),
('jb',33,14,'crampon1923','Pourtant Dieu parle tantôt d''une manière, tantôt d''une autre, et l''on n''y fait pas attention.'),
('jb',33,15,'crampon1923','Il parle par des songes, par des visions nocturnes, quand un profond sommeil pèse sur les mortels, quand ils dorment sur leur couche.'),
('jb',33,16,'crampon1923','A ce moment, il ouvre l''oreille des hommes, et y scelle ses avertissements,'),
('jb',33,17,'crampon1923','afin de détourner l''homme de ses œuvres mauvaises, et d''écarter de lui l''orgueil,'),
('jb',33,18,'crampon1923','afin de sauver son âme de la mort, sa vie des atteintes du dard.'),
('jb',33,19,'crampon1923','Par la douleur aussi l''homme est repris sur sa couche, quand une lutte continue agite ses os.'),
('jb',33,20,'crampon1923','Alors il prend en dégoût le pain, et il a horreur des mets exquis,'),
('jb',33,21,'crampon1923','Sa chair s''évanouit aux regards, ses os qu''on ne voyait pas sont mis à nu.'),
('jb',33,22,'crampon1923','Il s''approche de la fosse, sa vie est en proie aux horreurs du trépas.'),
('jb',33,23,'crampon1923','Mais s''il trouve pour intercesseur, un ange entre mille, qui fasse connaître à l''homme son devoir,'),
('jb',33,24,'crampon1923','Dieu a pitié de lui et dit à l''ange: « Epargne-lui de descendre dans la fosse, j''ai trouvé la rançon de sa vie. »'),
('jb',33,25,'crampon1923','Sa chair alors a plus de fraîcheur qu''au premier âge, il revient aux jours de sa jeunesse.'),
('jb',33,26,'crampon1923','Il prie Dieu, et Dieu lui est propice; il contemple sa face avec allégresse, et le Très-Haut lui rend son innocence.'),
('jb',33,27,'crampon1923','Il chante parmi les hommes, il dit: « J''ai péché, j''ai violé la justice, et Dieu ne m''a pas traité selon mes fautes.'),
('jb',33,28,'crampon1923','Il a épargné à mon âme de descendre dans la fosse, et ma vie s''épanouit à la lumière! »'),
('jb',33,29,'crampon1923','Voilà, Dieu fait tout cela, deux fois, trois fois, pour l''homme,'),
('jb',33,30,'crampon1923','afin de le ramener de la mort, de l''éclairer de la lumière des vivants.'),
('jb',33,31,'crampon1923','Sois attentif, Job, écoute-moi; garde le silence, que je parle.'),
('jb',33,32,'crampon1923','Si tu as quelque chose à dire, réponds-moi; parle, car je voudrais te trouver juste.'),
('jb',33,33,'crampon1923','Si tu n''as rien à dire, écoute-moi; fais silence, et je t''enseignerai la sagesse.'),
('jb',34,1,'crampon1923','Eliu reprit et dit:'),
('jb',34,2,'crampon1923','Sages, écoutez mes discours; hommes intelligents, prêtez-moi l''oreille.'),
('jb',34,3,'crampon1923','Car l''oreille juge les paroles, comme le palais discerne les aliments.'),
('jb',34,4,'crampon1923','Tâchons de discerner ce qui est juste; cherchons entre nous ce qui est bon.'),
('jb',34,5,'crampon1923','Job a dit: « Je suis innocent, et Dieu me refuse justice.'),
('jb',34,6,'crampon1923','Quand je soutiens mon droit, je passe pour menteur; ma plaie est douloureuse, sans que j''aie péché. »'),
('jb',34,7,'crampon1923','Y a-t-il un homme semblable à Job? Il boit le blasphème comme l''eau!'),
('jb',34,8,'crampon1923','Il s''associe aux artisans d''iniquité, il marche avec les hommes pervers.'),
('jb',34,9,'crampon1923','Car il a dit: « Il ne sert de rien à l''homme de chercher la faveur de Dieu. »'),
('jb',34,10,'crampon1923','Ecoutez-moi donc, hommes sensés: Loin de Dieu l''iniquité! Loin du Tout-Puissant l''injustice!'),
('jb',34,11,'crampon1923','Il rend à l''homme selon ses œuvres, il rétribue chacun selon ses voies.'),
('jb',34,12,'crampon1923','Non, certes, Dieu ne commet pas l''iniquité, le Tout-Puissant ne viole pas la justice.'),
('jb',34,13,'crampon1923','Qui lui a remis le gouvernement de la terre? Qui lui a confié l''univers?'),
('jb',34,14,'crampon1923','S''il ne pensait qu''à lui-même, s''il retirait à lui son esprit et son souffle,'),
('jb',34,15,'crampon1923','toute chair expirerait à l''instant, et l''homme retournerait à la poussière.'),
('jb',34,16,'crampon1923','Si tu as de l''intelligence, écoute ceci; prête l''oreille au son de mes paroles:'),
('jb',34,17,'crampon1923','Un ennemi de la justice aurait-il le suprême pouvoir? Oses-tu condamner le Juste, le Puissant,'),
('jb',34,18,'crampon1923','qui dit à un roi: « Vaurien! » aux princes: « Pervers! »'),
('jb',34,19,'crampon1923','qui ne fait point acception de la personne des grands, qui ne regarde pas le riche plus que le pauvre, parce que tous sont l''ouvrage de ses mains?'),
('jb',34,20,'crampon1923','En un instant ils périssent, au milieu de la nuit, les peuples chancellent et disparaissent; le puissant est emporté sans main d''homme.'),
('jb',34,21,'crampon1923','Car les yeux de Dieu sont ouverts sur les voies de l''homme, il voit distinctement tous ses pas.'),
('jb',34,22,'crampon1923','Il n''y a ni ténèbres ni ombre de la mort, où puissent se cacher ceux qui commettent l''iniquité.'),
('jb',34,23,'crampon1923','Il n''a pas besoin de regarder un homme deux fois, pour l''amener au jugement avec lui.'),
('jb',34,24,'crampon1923','Il brise les puissants sans enquête, et il en met d''autres à leur place.'),
('jb',34,25,'crampon1923','Il connaît donc leurs œuvres; il les renverse de nuit, et ils sont écrasés.'),
('jb',34,26,'crampon1923','Il les frappe comme des impies, en un lieu où on les regarde,'),
('jb',34,27,'crampon1923','parce qu''en se détournant de lui, en refusant de connaître toutes ses voies,'),
('jb',34,28,'crampon1923','ils ont fait monter vers lui le cri du pauvre, ils l''ont rendu attentif au cri des malheureux.'),
('jb',34,29,'crampon1923','S''il accorde la paix, qui le trouvera mauvais; s''il cache son visage, qui pourra le contempler, qu''il soit peuple ou homme celui qu''il traite ainsi,'),
('jb',34,30,'crampon1923','pour mettre fin au règne de l''impie, pour qu''il ne soit plus un piège pour le peuple?'),
('jb',34,31,'crampon1923','Or avait-il dit à Dieu: « J''ai été châtié, je ne pécherai plus;'),
('jb',34,32,'crampon1923','montre-moi ce que j''ignore; si j''ai commis l''iniquité, je ne le ferai plus? »'),
('jb',34,33,'crampon1923','Est-ce d''après ton avis que Dieu doit rendre la justice de sorte que tu puisses rejeter son jugement? Choisis à ton gré, et non pas moi; ce que tu sais, expose-le.'),
('jb',34,34,'crampon1923','Les gens sensés me diront, ainsi que l''homme sage qui m''écoute:'),
('jb',34,35,'crampon1923','« Job a parlé sans intelligence, et ses discours sont dépourvus de sagesse.'),
('jb',34,36,'crampon1923','Eh bien, que Job soit éprouvé jusqu''au bout, puisque ses réponses sont celles d''un impie!'),
('jb',34,37,'crampon1923','Car à l''offense il ajoute la révolte; il bat des mains au milieu de nous, il multiplie ses propos contre Dieu. »'),
('jb',35,1,'crampon1923','Eliu prit de nouveau la parole et dit:'),
('jb',35,2,'crampon1923','Crois-tu que ce soit là de la justice, de dire: « J''ai raison contre Dieu? »'),
('jb',35,3,'crampon1923','Car tu as dit: « Que me sert mon innocence, qu''ai-je de plus que si j''avais péché? »'),
('jb',35,4,'crampon1923','Moi, je vais te répondre, et à tes amis en même temps.'),
('jb',35,5,'crampon1923','Considère les cieux et regarde; vois les nuées: elles sont plus hautes que toi!...'),
('jb',35,6,'crampon1923','Si tu pèches, quel tort lui causes-tu? Si tes offenses se multiplient, que lui fais-tu?'),
('jb',35,7,'crampon1923','Si tu es juste, que lui donnes-tu? Que reçoit-il de ta main?'),
('jb',35,8,'crampon1923','Ton iniquité ne peut nuire qu''à tes semblables, ta justice n''est utile qu''au fils de l''homme.'),
('jb',35,9,'crampon1923','Des malheureux gémissent sous la violence des vexations, et crient sous la main des puissants.'),
('jb',35,10,'crampon1923','Mais nul ne dit: « Où est Dieu, mon Créateur, qui donne à la nuit des chants de joie,'),
('jb',35,11,'crampon1923','qui nous a faits plus intelligents que les animaux de la terre, plus sages que les oiseaux du ciel. »'),
('jb',35,12,'crampon1923','Ils crient alors, sans être exaucés, sous l''orgueilleuse tyrannie des méchants.'),
('jb',35,13,'crampon1923','Dieu n''exauce pas les discours insensés, le Tout-Puissant ne les regarde pas.'),
('jb',35,14,'crampon1923','Quand tu lui dis: « Tu ne vois pas ce qui se passe, » ta cause est devant lui; attends son jugement.'),
('jb',35,15,'crampon1923','Mais, parce que sa colère ne sévit pas encore, et qu''il semble ignorer sa folie,'),
('jb',35,16,'crampon1923','Job prête sa bouche à de vaines paroles, et se répand en discours insensés.'),
('jb',36,1,'crampon1923','Eliu reprit encore une fois et dit:'),
('jb',36,2,'crampon1923','Attends un peu, et je t''instruirai, car j''ai des paroles encore pour la cause de Dieu;'),
('jb',36,3,'crampon1923','je prendrai mes raisons de haut, et je montrerai la justice de mon Créateur.'),
('jb',36,4,'crampon1923','Sois-en sûr, mes discours sont exempts de mensonge; devant toi est un homme sincère en ses jugements.'),
('jb',36,5,'crampon1923','Voici que Dieu est puissant, mais il ne dédaigne personne; il est puissant par la force de son intelligence.'),
('jb',36,6,'crampon1923','Il ne laisse pas vivre le méchant, et il fait justice aux malheureux.'),
('jb',36,7,'crampon1923','Il ne détourne pas ses yeux des justes; il les fait asseoir sur le trône avec les rois, il les établit pour toujours, et ils sont exaltés.'),
('jb',36,8,'crampon1923','Viennent-ils à tomber dans les fers, sont-ils pris dans les liens du malheur,'),
('jb',36,9,'crampon1923','il leur dénonce leurs œuvres, leurs fautes causées par l''orgueil.'),
('jb',36,10,'crampon1923','Il ouvre leur oreille à la réprimande, il les exhorte à se détourner du mal.'),
('jb',36,11,'crampon1923','S''ils écoutent et se soumettent, ils achèvent leurs jours dans le bonheur, et leurs années dans les délices.'),
('jb',36,12,'crampon1923','Mais s''ils n''écoutent pas, ils périssent par le glaive, ils meurent dans leur aveuglement.'),
('jb',36,13,'crampon1923','Les cœurs impies se livrent à la colère, ils ne crient pas vers Dieu quand il les met dans les chaînes.'),
('jb',36,14,'crampon1923','Aussi meurent-ils dans leur jeunesse, et leur vie se flétrit comme celle des infâmes.'),
('jb',36,15,'crampon1923','Mais Dieu sauve le malheureux dans sa misère, il l''instruit par la souffrance.'),
('jb',36,16,'crampon1923','Toi aussi, il te retirera de la détresse, pour te mettre au large, en pleine liberté, et ta table sera dressée et chargée de mets succulents.'),
('jb',36,17,'crampon1923','Mais si tu combles la mesure de l''impie, tu en porteras la sentence et la peine.'),
('jb',36,18,'crampon1923','Crains que Dieu irrité ne t''inflige un châtiment, et que tes riches offrandes ne t''égarent.'),
('jb',36,19,'crampon1923','Tes cris te tireront-ils de la détresse, et même toutes les ressources de la force?'),
('jb',36,20,'crampon1923','Ne soupire pas après la nuit, durant laquelle les peuples sont anéantis sur place.'),
('jb',36,21,'crampon1923','Prends garde de te tourner vers l''iniquité, car tu la préfères à l''affliction.'),
('jb',36,22,'crampon1923','Vois: Dieu est sublime dans sa puissance! Quel maître est semblable à lui?'),
('jb',36,23,'crampon1923','Qui lui trace la voie qu''il doit suivre? Qui peut lui dire: « Tu as mal fait? »'),
('jb',36,24,'crampon1923','Songe plutôt à glorifier ses œuvres, que les hommes célèbrent dans leurs chants.'),
('jb',36,25,'crampon1923','Tout homme les admire, le mortel les contemple de loin.'),
('jb',36,26,'crampon1923','Dieu est grand au-dessus de toute science, le nombre de ses années est impénétrable.'),
('jb',36,27,'crampon1923','Il attire les gouttes d''eau, qui se répandent en pluie sous leur poids.'),
('jb',36,28,'crampon1923','Les nuées la laissent couler, et tomber sur la masse des hommes.'),
('jb',36,29,'crampon1923','Qui comprendra l''expansion des nuages, et le fracas de la tente du Très-Haut?'),
('jb',36,30,'crampon1923','Tantôt il étend autour de lui sa lumière, tantôt il se cache comme au fond de la mer.'),
('jb',36,31,'crampon1923','C''est ainsi qu''il exerce sa justice sur les peuples, et qu''il donne la nourriture avec abondance.'),
('jb',36,32,'crampon1923','Il prend la lumière dans ses mains, et lui marque le but à atteindre.'),
('jb',36,33,'crampon1923','Son tonnerre l''annonce, l''effroi des troupeaux annonce son approche.'),
('jb',37,1,'crampon1923','A ce spectacle, mon cœur est tout tremblant, il bondit hors de sa place.'),
('jb',37,2,'crampon1923','Ecoutez, écoutez le fracas de sa voix, le grondement qui sort de sa bouche!'),
('jb',37,3,'crampon1923','Il lui donne libre carrière sous l''immensité des cieux, et son éclair brille jusqu''aux extrémités de la terre.'),
('jb',37,4,'crampon1923','Puis éclate un rugissement, il tonne de sa voix majestueuse; il ne retient plus les éclairs, quand on entend sa voix;'),
('jb',37,5,'crampon1923','Dieu tonne de sa voix, d''une manière merveilleuse. Il fait de grandes choses que nous ne comprenons pas.'),
('jb',37,6,'crampon1923','Il dit à la neige: « Tombe sur la terre; » il commande aux ondées et aux pluies torrentielles.'),
('jb',37,7,'crampon1923','Il met un sceau sur la main de tous les hommes, afin que tout mortel reconnaisse son Créateur.'),
('jb',37,8,'crampon1923','Alors l''animal sauvage rentre dans son repaire, et demeure dans sa tanière.'),
('jb',37,9,'crampon1923','L''ouragan sort de ses retraites cachées, l''aquilon amène les frimas.'),
('jb',37,10,'crampon1923','Au souffle de Dieu se forme la glace, et la masse des eaux est emprisonnée.'),
('jb',37,11,'crampon1923','Il charge de vapeurs les nuages, il disperse ses nuées lumineuses.'),
('jb',37,12,'crampon1923','On les voit, selon ses décrets, errer en tous sens, pour exécuter tout ce qu''il leur commande, sur la face de la terre habitée.'),
('jb',37,13,'crampon1923','C''est tantôt pour le châtiment de sa terre, et tantôt en signe de faveur qu''il les envoie.'),
('jb',37,14,'crampon1923','Job, sois attentif à ces choses; arrête-toi, et considère les merveilles de Dieu.'),
('jb',37,15,'crampon1923','Sais-tu comment il les opère, et fait briller l''éclair dans la nue?'),
('jb',37,16,'crampon1923','Comprends-tu le balancement des nuages, les merveilles de celui dont la science est parfaite,'),
('jb',37,17,'crampon1923','toi dont les vêtements sont chauds, quand la terre se repose au souffle du midi?'),
('jb',37,18,'crampon1923','Peux-tu, comme lui, étendre les nuées, et les rendre solides comme un miroir d''airain?'),
('jb',37,19,'crampon1923','Fais-nous connaître ce que nous devons lui dire: nous ne saurions lui parler, ignorants que nous sommes.'),
('jb',37,20,'crampon1923','Ah! qu''on ne lui rapporte pas mes discours! Un homme a-t-il jamais dit qu''il désirait sa perte?'),
('jb',37,21,'crampon1923','On ne peut voir maintenant la lumière du soleil, qui luit derrière les nuages; qu''un vent passe, il les dissipe.'),
('jb',37,22,'crampon1923','L''or vient du septentrion; mais Dieu, que sa majesté est redoutable!'),
('jb',37,23,'crampon1923','Le Tout-Puissant, nous ne pouvons l''atteindre: il est grand en force, et en droit, et en justice, il ne répond à personne!'),
('jb',37,24,'crampon1923','Que les hommes donc le révèrent! Il ne regarde pas ceux qui se croient sages.'),
('jb',38,1,'crampon1923','Alors Yahweh répondit à Job du sein de la tempête, et dit:'),
('jb',38,2,'crampon1923','Quel est celui qui obscurcit ainsi le plan divin, par des discours sans intelligence?'),
('jb',38,3,'crampon1923','Ceins tes reins, comme un homme: je vais t''interroger, et tu m''instruiras.'),
('jb',38,4,'crampon1923','Où étais-tu quand je posais les fondements de la terre? Dis-le, si tu as l''intelligence.'),
('jb',38,5,'crampon1923','Qui en a fixé les dimensions? Le sais-tu? Qui a tendu sur elle cordeau?'),
('jb',38,6,'crampon1923','Sur quoi ses bases reposent-elles, ou qui en a posé la pierre angulaire,'),
('jb',38,7,'crampon1923','quand les astres du matin chantaient en chœur, et que tous les fils de Dieu poussaient des cris d''allégresse?'),
('jb',38,8,'crampon1923','Qui a fermé la mer avec des portes, lorsqu''elle sortit impétueuse du sein maternel;'),
('jb',38,9,'crampon1923','quand je lui donnai les nuages pour vêtements, et pour langes d''épais brouillards;'),
('jb',38,10,'crampon1923','quand je lui imposai ma loi, que je lui mis des portes et des verrous,'),
('jb',38,11,'crampon1923','et que je lui dis: « Tu viendras jusqu''ici, non au delà; ici s''arrêtera l''orgueil de tes flots »?'),
('jb',38,12,'crampon1923','As-tu, depuis que tu existes, commandé au matin? As-tu indiqué sa place à l''aurore,'),
('jb',38,13,'crampon1923','pour qu''elle saisisse les extrémités de la terre et qu''elle en secoue les méchants;'),
('jb',38,14,'crampon1923','pour que la terre prenne forme, comme l''argile sous le cachet, et qu''elle se montre parée comme d''un vêtement;')
